The Defender strategy we propose in the next section monitors the proximity of the Attacker to the primary goal, $g^1$, using the \emph{progress function} defined below.
% We use $d_i(s) \triangleq d(s,g_i)$ to denote weighted graph-distance from node $s$ to $g_i$.
\begin{definition}[Progress function] \label{def. c(t)}
Let $s_\tau$ be the \Mover{}'s position at  time $\tau$. We define $c_t$ as the minimum distance to the primary goal $g^1$ the \Mover{} has reached by $t$:
\begin{equation}
    c_t=\min_{\tau \leq t} d(s_\tau,g^1).
\end{equation}
%where $s_\tau$ is \Mover{}'s position at  time $\tau$, and $ d(s,g^1)$ denotes weighted distance between node $s$ and goal $g^1$.
\end{definition}

