\paragraph*{\textbf{Phase I}} This is the initial phase during which the \Eater{} deterministically allocates to $g^1$, i.e., $\sigma^{*}_t(g^1|\xi^{2}_{[0:t]})=1, \forall t\in[1,t_{\x{1}}]$. 
The end of this phase can be found as
\begin{equation}\label{eq: t_1}
     t_{\x{1}}\triangleq
     \max \{t|\sigma^*_t(g^1|\xi^{2}_{[0:\tau]})=1,\forall \tau \leq t\}.
 \end{equation}
Phase I exists, i.e., has non-zero duration, if and only if $\sigma^{*}_t(g^1|\xi^{2}_{[0:1]})=1$; otherwise, $t_\x{1}=0$ if $\sigma^{*}_t(g^1|\xi^{2}_{[0:1]})<1$.

\paragraph*{\textbf{Phase II}}
This phase is the duration between the first time step the \Eater{} allocates to $g^2$ with non-zero probability, and the last time step at which the \Eater{} allocates to $g^1$ with non-zero probability.
The end of phase~II can be found as
\begin{equation}\label{eq: t_2}
    t_{\x{2}}\triangleq
        \begin{cases}
        T^{\xi^2},&\text{ if } \sigma^{*}_t(g^1|\xi^{2})>0,\\
        \min \{t| \sigma^{*}_t(g^1|\xi^{2}_{[0:\tau]})=0,\forall \tau > t \},&\text{ otherwise}.
        \end{cases}
\end{equation}
Phase II exists if and only if $t_{\x{1}}<t_{\x{2}}$.

\paragraph*{\textbf{Phase~\Romannum{3}}} During this final phase, the \Eater{} deterministically allocates to $g^2$, i.e., $\sigma^*_t(g^1|\xi^{2}_{[0:t]})=0,\forall t\in[t_\x{2}+1,T^{\xi^2}]$. 
Phase~\Romannum{3} exists if and only if $t_{\text{\Romannum{2}}} < T^{\xi^2}$. 


