\section{Preliminaries}
\label{sec:preliminary}
%


Before proceeding to the description of our algorithm, let us start by gathering several preliminary facts.





\paragraph{The forward process.}
%
Recall the forward process~\eqref{eq:forward-process}. By taking 
%
\begin{align}
\label{eq:overline-alpha}
\alpha_t \coloneqq 1- \beta_t 
\qquad \text{and}\qquad 
\overline{\alpha}_t \coloneqq \prod_{i=1}^t \alpha_i, 
%\qquad \text{and} \qquad  
\end{align}
%
we see that \eqref{eq:forward-process} admits the following distributional characterization:  
%
\begin{equation}
    \label{eq:forward-alt}
    X_t = \sqrt{\overline{\alpha}_t}X_0 + \sqrt{1 - \overline{\alpha}_t}\,\overline{W}_t 
    \qquad \text{  with  } \overline{W}_t \sim \mathcal{N}(0,I_d).
\end{equation}
%

Moreover, we find it useful to introduce a continuous-time generalization $(\overline{X}_{\tau})$ of the above process. 
Specifically, for every $\tau \in [0,1]$, construct $\overline{X}_{\tau}$ such that 
%
\begin{align}
\label{defn:X-tau-process}
    \overline{X}_\tau = \sqrt{1-\tau}X_0 + \sqrt{\tau}Z
    \qquad \text{with }~ X_0 \sim \Pdata ~\text{ and }~Z\sim \mathcal{N}(0,I_d), 
\end{align}
%
where $X_0$ and $Z$ are independently generated. Clearly, with this construction we have 
%
\begin{align}
\overline{X}_{1-\overline{\alpha}_t} \overset{\mathrm{d}}{=} X_t.
\label{eq:X-alphat-Xt}
\end{align}
%
In the sequel, 
we will often refer to $\tau$ as the time variable too as long as it is clear from the context, and 
 will develop and describe our algorithm mainly based on this continuous-time forward process~\eqref{defn:X-tau-process}. 


\paragraph{The score function and Tweedie's formula.} 
%
As mentioned previously, a key object that plays a pivotal role in the sampling procedure is the (Stein) score function, defined as the gradient of the log marginal density of the forward process.  To be precise, the score function associated with $(\overline{X}_{\tau})$ is defined and denoted by
%
\begin{align}
    \label{eq:defn-score}
    s^\star_{\tau}(X) \coloneqq \nabla \log p_{\overline{X}_{\tau}}(X)
\end{align}
%
for each $\tau \in [0,1]$. 
The celebrated Tweedie formula \citep{efron2011tweedie} tells us that 
%
\begin{align} %s_{\tau}^{\star}(x)=\frac{\sqrt{1-\tau}}{\tau}\mathbb{E}\big[X_{0}\mid\overline{X}_{\tau}=x\big]-x
s_{\tau}^{\star}(x)=-\frac{1}{\tau}\Big\{x-\sqrt{1-\tau}\,\mathbb{E}\big[X_{0}\mid\overline{X}_{\tau}=x\big]\Big\}
\end{align}
%
for any $x\in \mathbb{R}^d$, 
which implies that
% 
\begin{align}
\label{eq:score_form}
s_{\tau}^{\star}(\sqrt{1-\tau}x) &= -\frac{\sqrt{1-\tau}}{\tau}\int_{x_0} p_{X_0 \mymid \overline{X}_\tau}(x_0 \mymid \sqrt{1-\tau}x)(x - x_0)\mathrm{d}x_0. 
\end{align}
%



\paragraph{The probability flow ODE.}
%
As has been shown by \citet{song2020score}, 
there exists an ordinary differential equation (ODE), called the probability flow ODE, that is able to reverse the forward process \eqref{defn:X-tau-process} (in the sense of yielding matching marginal distributions). Note that the precise form of the probability flow ODE depends on the parameterization of the forward process (e.g., $(X_t)$ and $(\overline{X}_{\tau})$ are associated with different, although related, ODEs). In particular,  the probability flow ODE associated with process \eqref{defn:X-tau-process} takes the following form: 
%
\begin{align} \label{eq:ODE}
	\mathrm{d} \frac{Y_\tau^{\mathsf{ode}}}{\sqrt{1-\tau}} = -\frac{1}{2(1-\tau)^{3/2}}s_{\tau}^{\star}(Y_\tau^{\mathsf{ode}}) \mathrm{d} \tau; 
\end{align}
%
