&= \frac{x_{\tau_{t, 0}}}{\sqrt{1-\tau_{t, 0}}} + \sum_{0 \le j \leq K-1} \gamma_{t, j}(\tau')(1-\tau_{t, j})^{-3/2}s_{\tau_{t, j}}(x_{\tau_{t, j}}^{(n)}).\label{eq:update_rule}
\end{align}
Here, $\tau'$ denotes $\tau_{t, i}$ and
\begin{align}
    \gamma_{t, i}(\tau') := \int_{\tau'}^{\tau_{t, 0}}\psi_i(\tau)\mathrm{d}\tau.\label{def:gamma}
\end{align}


