			\frac{1}{2}\frac{1-\alpha_{t}}{1 - \overline{\alpha}_t} \leq \frac{1}{2}\frac{1-\alpha_{t}}{\alpha_{t} - \overline{\alpha}_t} &\leq \frac{1-\alpha_{t}}{1 - \overline{\alpha}_{t-1}} \leq \frac{4c_1\log T}{T},\quad~2 \leq t \leq T\label{ineq:learning_rate_b}\\
			1 &\leq \frac{1 - \overline{\alpha}_{t}}{1 - \overline{\alpha}_{t-1}} \leq 1 + \frac{4c_1\log T}{T},\quad~2 \leq t \leq T\label{ineq:learning_rate_c}\\
			\overline{\alpha}_T &\leq \frac{1}{T^{c_2}},\label{ineq:learning_rate_d}\\
			\frac{\overline{\alpha}_{t+1}}{1-\overline{\alpha}_{t+1}} &\leq \frac{\overline{\alpha}_{t}}{1-\overline{\alpha}_{t}} \leq \frac{4\overline{\alpha}_{t+1}}{1-\overline{\alpha}_{t+1}},\quad~1 \leq t < T\label{ineq:learning_rate_e}\\
				\Big|\frac{\tau_{t, i_1} - \tau_{t, i_2}}{\tau_{t, i_3}(1-\tau_{t, i_4})}\Big| &\leq 8c_1\frac{\log T}{T},\quad~2 \leq t \leq T, 0 \leq i_1, i_2, i_3, i_4 \leq K-1,\label{ineq:learning_rate_f}\\
				|\gamma_{t, i}(\tau_{t,j})| &\le 2^K (\tau_{t, 0} - \tau_{t,j}),\quad~\forall 0 \leq i, j \leq K-1\label{ineq:learning_rate_g}\\
	        1 - \tau_{t,i}& \asymp 1 - \tau_{t,j},~\quad~\tau_{t, i} \asymp \tau_{t, j},~\quad~\forall 0 \leq i, j \leq K-1, 2 \leq t \leq T.\label{ineq:learning_rate_h}
		\end{align}
	Here, $c_2$ is a sufficiently large constant.
	\end{subequations}
\end{lemma}
For notational convenience, we define
\begin{align}\label{def:theta}
	\theta_{\tau}(x) := \max\left\{-\frac{\log p_{\overline{X}_\tau}(x)}{d\log T}, c_6\right\} 
\end{align}
for some large enough constant $c_6 > 0$. The second lemma establishes the tail bounds of $X_0$ conditioned on the continuous-time forward process $\overline{X}_{\tau}$ (cf.~\eqref{defn:X-tau-process}).
\begin{lemma}[Lemma 1 in \cite{li2024sharp}]\label{lemma:tail_bound}
	Suppose that Assumption \ref{assump:data_distribution} holds and $\tau \leq 1 - \frac{1}{T^{c_0}}$. Then for any $c_5 \geq 2$, conditioned on $\overline{X}_{\tau} = y$, we have
	\begin{align}\label{ineq6}
		\left\|\sqrt{1 - \tau}X_0 - y\right\|_2 \leq 5c_5\sqrt{\theta_{\tau}(y)d\tau\log T}
	\end{align}
with probability exceeding $1 - \exp(-c_5^2\theta_{\tau}(y)d\log T)$. Furthermore, one has
\begin{subequations}
	\begin{align}
		\mathbb{E}\left[\left\|\sqrt{1 - \tau}X_0 - y\right\|_2\ |\ \overline{X}_{\tau} = y\right] &\leq 12\sqrt{\theta_{\tau}(y)d\tau\log T},\label{ineq7a}\\
		\mathbb{E}\left[\left\|\sqrt{1 - \tau}X_0 - y\right\|_2^2\ |\ \overline{X}_{\tau} = y\right] &\leq 120\theta_{\tau}(y)d\tau\log T,\label{ineq7b}\\
		\mathbb{E}\left[\left\|\sqrt{1 - \tau}X_0 - y\right\|_2^3\ |\ \overline{X}_{\tau} = y\right] &\leq 1040\left(\theta_{\tau}(y)d\tau\log T\right)^{3/2},\label{ineq7c}\\
		\mathbb{E}\left[\left\|\sqrt{1 - \tau}X_0 - y\right\|_2^4\ |\ \overline{X}_{\tau} = y\right] &\leq 10080\left(\theta_{\tau}(y)d\tau\log T\right)^{2},\label{ineq7d}.
	\end{align}
\end{subequations}
\end{lemma}
The next lemma provides key properties of the score function $s_{\tau}^\star(\cdot)$.
\begin{lemma}\label{lemma:Hessian}
	One has
	\begin{subequations}
		\begin{align}
			\left\|s_{\tau}^\star(x)\right\|_2 &\lesssim \sqrt{\frac{d\theta_{\tau}(x)\log T}{\tau}},\label{score_1}\\
			\left\|\frac{\partial s_{\tau}^\star(x)}{\partial x}\right\| &\lesssim \frac{d\theta_{\tau}(x)\log T}{\tau}.\label{score_2}
		\end{align}
	\end{subequations}
Furthermore, if $-\log p_{\overline{X}_\tau}(\lambda x_1 + (1 - \lambda)x_2) \lesssim d\log T$ for all $\lambda \in [0,1]$, then
\begin{align}\label{score_derivative_difference}
	\left\|\frac{\partial s_{\tau}^\star(x_1)}{\partial x} - \frac{\partial s_{\tau}^\star(x_2)}{\partial x}\right\| &\lesssim \sqrt{\frac{d^3\log^3 T}{\tau^3}}\|x_1 - x_2\|_2.
\end{align}
\end{lemma}
The proofs of Lemma \ref{lemma:learning_rate} and Lemma \ref{lemma:Hessian} are deferred to Sections \ref{sec:proof_lemma_learning_rate} and \ref{sec:proof_lemma_Hessian}, respectively.

The following lemma shows that if $-\log p_{\overline{X}_{\tau}}(x_{\tau}^\star)$ is not too large, then $-\log p_{\overline{X}_{\tau'}}(x_{\tau'}^\star)$ can be well-controlled for all $\tau'$ sufficiently close to $\tau$.
\begin{lemma}\label{lemma:log_density}
	Suppose that $-\log p_{\overline{X}_{\widetilde\tau}}(x_{\widetilde\tau}^\star) \leq \theta d\log T$ for some $\theta > 1$. Then for all $|\tau' - \widetilde\tau| \leq c_0\widetilde\tau(1 - \widetilde\tau)$ for some sufficiently small constant $c_0 > 0$, one has
	\begin{align}
		-\log p_{\overline{X}_{\tau'}}(x_{\tau'}^\star) \leq 2\theta d\log T.
	\end{align}
\end{lemma}
The proof of Lemma \ref{lemma:log_density} can be found in Section \ref{proof:Lemma_log_density}. The last lemma reveals that the the distributions of $X_T$ and $Y_T$ are close.
\begin{lemma}[Lemma 3 in \cite{li2024sharp}]\label{lemma:distance_y_T}
	Suppose that $T$ is large enough. Then
	\begin{align}
		\big(\mathsf{TV}(p_{X_T}~||~p_{Y_T})\big)^2 \leq \frac{1}{2}\mathsf{KL}(p_{X_T}~||~p_{Y_T}) \lesssim \frac{1}{T^{200}}.\label{ineq:distance_y_T}
	\end{align}
\end{lemma}

%For any $x_{T} = x_{\tau_{T},0} \in \mathbb{R}^d$, we let $\{x_{\tau_{t,i}}^{(n)}\}$ denote the deterministic sequence generated by \eqref{eq:update_rule}, and define $x_t = x_{\tau_t, 0} = x_{\tau_{t-1},K-1}^{(N)}$. 

%We mainly focus on the case that $\max\{-\log p_{\tau}(x_{\tau}^\star), -\log p_{X_{\tau_{t,i}}}(x_{t,i}^{(n)})\} \lesssim d\log T$, where the remaining case can be bounded easily and is omitted here due to the overwhelming probability.
\subsection{Main steps for proving Theorem \ref{theorem:main}}
We now proceed to present the proof ideas, which comprises multiple steps as detailed below. 
\paragraph{Step 1: controlling the density ratio.} To establish the convergence rate \eqref{eq:ratio}, a pivotal step is to control the density ratio $\frac{p_{Y_{t-1}}(x_{t-1})}{p_{X_{t-1}}(x_{t-1})}/\frac{p_{Y_{t}}(x_{t})}{p_{X_{t}}(x_{t})}$. Our starting point is the following observation: 
%
	\begin{align}\label{eq5}
		&\frac{p_{Y_{t-1}}(x_{t-1})}{p_{X_{t-1}}(x_{t-1})}= \frac{p_{\sqrt{\alpha_t}Y_{t-1}}(\sqrt{\alpha_t}x_{t-1})}{p_{\sqrt{\alpha_t}X_{t-1}}(\sqrt{\alpha_t}x_{t-1})}=\frac{p_{\sqrt{\alpha_t}Y_{t-1}}(\sqrt{\alpha_t}x_{t-1})}{p_{Y_{t}}(x_{t})}\left(\frac{p_{\sqrt{\alpha_t}X_{t-1}}(\sqrt{\alpha_t}x_{t-1})}{p_{X_{t}}(x_{t})}\right)^{-1}\frac{p_{Y_{t}}(x_{t})}{p_{X_{t}}(x_{t})}\notag\\
		&= \frac{p_{\sqrt{\alpha_t}Y_{t-1}}(\sqrt{\alpha_t}x_{t-1})}{p_{\sqrt{\alpha_t}Y_{t-1}^{\star}}(\sqrt{\alpha_t}x_{t-1}^{\star})}\cdot\frac{p_{\sqrt{\alpha_t}Y_{t-1}^{\star}}(\sqrt{\alpha_t}x_{t-1}^{\star})}{p_{Y_{t}}(x_{t})}\left(\frac{p_{\sqrt{\alpha_t}X_{t-1}}(\sqrt{\alpha_t}x_{t-1})}{p_{\sqrt{\alpha_t}X_{t-1}}(\sqrt{\alpha_t}x_{t-1}^{\star})}
		\cdot\frac{p_{\sqrt{\alpha_t}X_{t-1}}(\sqrt{\alpha_t}x_{t-1}^{\star})}{p_{X_{t}}(x_{t})}\right)^{-1}\frac{p_{Y_{t}}(x_{t})}{p_{X_{t}}(x_{t})}. 
	\end{align}
By virtue of the defition of $Y_{t-1}^\star$ and the fact that we can transport the distribution of $X_{t}$ to the one of $X_{t-1}$ via \eqref{eq:ODE}, one has
\begin{align}\label{eq6}
	\frac{p_{\sqrt{\alpha_t}Y_{t-1}^{\star}}(\sqrt{\alpha_t}x_{t-1}^{\star})}{p_{Y_{t}}(x_{t})} = \frac{p_{\sqrt{\alpha_t}X_{t-1}}(\sqrt{\alpha_t}x_{t-1}^{\star})}{p_{X_{t}}(x_{t})}.
\end{align}
In addition, the following lemma provides upper bounds for $\frac{p_{\sqrt{\alpha_t}X_{t-1}}(\sqrt{\alpha_t}x_{t-1})}{p_{\sqrt{\alpha_t}X_{t-1}}(\sqrt{\alpha_t}x_{t-1}^{\star})}$ and $\frac{p_{\sqrt{\alpha_t}Y_{t-1}}(\sqrt{\alpha_t}x_{t-1})}{p_{\sqrt{\alpha_t}Y_{t-1}^{\star}}(\sqrt{\alpha_t}x_{t-1}^{\star})}$, respectively.
\begin{lemma}\label{lemma:density_ratio_1}
    We have
    \begin{align}\label{ineq18}
        \frac{p_{\sqrt{\alpha_t}X_{t-1}}(\sqrt{\alpha_t}x_{t-1})}{p_{\sqrt{\alpha_t}X_{t-1}}(\sqrt{\alpha_t}x_{t-1}^{\star})} = \exp\bigg(O\bigg(\frac{\|x_{t-1} - x_{t-1}^{\star}\|_2^2}{1 - \overline{\alpha}_{t-1}} + \sqrt{\frac{d\|x_{t-1} - x_{t-1}^{\star}\|_2^2\log T}{1 - \overline{\alpha}_{t-1}}}\bigg)\bigg).
    \end{align}
    If, furthermore, $\bigg\|\frac{\partial x_{\tau_{t, K-1}}^{(N)}/\sqrt{1-\tau_{t, K-1}}}{\partial x_{\tau_{t, 0}}/\sqrt{1-\tau_{t, 0}}}\bigg\|^{-1} \lesssim 1$, then
    \begin{align}
	\frac{p_{\sqrt{\alpha_t}Y_{t-1}}(\sqrt{\alpha_t}x_{t-1})}{p_{\sqrt{\alpha_t}Y_{t-1}^{\star}}(\sqrt{\alpha_t}x_{t-1}^{\star})}
	&= \exp\bigg(O\bigg(d\bigg\|\frac{\partial x_{\tau_{t, K-1}}^{\star}/\sqrt{1-\tau_{t, K-1}}}{\partial x_{\tau_{t, 0}}^{\star}/\sqrt{1-\tau_{t, 0}}} - \frac{\partial x_{\tau_{t, K-1}}^{(N)}/\sqrt{1-\tau_{t, K-1}}}{\partial x_{\tau_{t, 0}}/\sqrt{1-\tau_{t, 0}}}\bigg\|\bigg)\bigg).\label{ineq39}
\end{align}
\end{lemma}

The proof of Lemma \ref{lemma:density_ratio_1} is postponed to Section \ref{sec:proof_lemma_density_ratio_1}. Combining \eqref{eq5}, \eqref{eq6}, \eqref{ineq18} and \eqref{ineq39}, we know that if $\bigg\|\frac{\partial x_{\tau_{t, K-1}}^{(N)}/\sqrt{1-\tau_{t, K-1}}}{\partial x_{\tau_{t, 0}}/\sqrt{1-\tau_{t, 0}}}\bigg\|^{-1} \lesssim 1$, then
we have
\begin{align}
	\frac{p_{Y_{t-1}}(x_{t-1})}{p_{X_{t-1}}(x_{t-1})}
	= \frac{p_{\sqrt{\alpha_t}Y_{t-1}}(\sqrt{\alpha_t}x_{t-1})}{p_{\sqrt{\alpha_t}X_{t-1}}(\sqrt{\alpha_t}x_{t-1})}
	= \exp(O(\zeta_t(x_t)))\frac{p_{Y_{t}}(x_{t})}{p_{X_{t}}(x_{t})},
\end{align}
where
\begin{align}\label{ineq41}
	\zeta_t(x_t) := d\bigg\|\frac{\partial x_{\tau_{t, K-1}}^{\star}/\sqrt{1-\tau_{t, K-1}}}{\partial x_{\tau_{t, 0}}^{\star}/\sqrt{1-\tau_{t, 0}}} - \frac{\partial x_{\tau_{t, K-1}}^{(N)}/\sqrt{1-\tau_{t, K-1}}}{\partial x_{\tau_{t, 0}}/\sqrt{1-\tau_{t, 0}}}\bigg\|
	+ \frac{\|x_{\tau_{t, K-1}}^{\star} - x_{\tau_{t, K-1}}^{(N)}\|_2^2}{1 - \overline{\alpha}_{t-1}} + \sqrt{\frac{d\|x_{\tau_{t, K-1}}^{\star} - x_{\tau_{t, K-1}}^{(N)}\|_2^2\log T}{1 - \overline{\alpha}_{t-1}}}.
\end{align}
The next lemma reveals that $\zeta_t(x_t)$ is small for ``typical'' points.
\begin{lemma}\label{lemma:main}
	We define the events
	\begin{align*}
		\mathcal{E}_t' := \big\{\varepsilon_{\mathsf{Jacob}, t, i}^{(n)}\big(x_{\tau_{t, i}}^{(n)}\big)\log T \le T, \text{ for all }i, n\big\}
	\end{align*}
	and
	\begin{align}
		\mathcal{E}_t &:= \mathcal{E}_t' \cap \{-\log p_{X_{\tau_{t, i}}}\big(\lambda x_{\tau_{t, i}}^{(n)} + (1 - \lambda)x_{\tau_{t, i}}^\star\big) \leq C_4d\log T, \text{ for all }i, n\}\notag\\ &\qquad \cap \{-\log p_{X_{\tau}}(x_{\tau}^{\star}) \leq C_4d\log T\text{ for all }\tau_{t,K-1} \leq \tau \leq \tau_{t, 0}\},\label{def:event_E}
	\end{align}
	where $C_4 > 0$ is a sufficiently large constant.
	Then on the event $\mathcal{E}_t$, for any $0 \leq i \leq K-1$, one has
    \begin{subequations}
    	\begin{align}
    		&\bigg\|\frac{\partial x_{\tau_{t, K-1}}^{(N)}/\sqrt{1-\tau_{t, K-1}}}{\partial x_{\tau_{t, 0}}/\sqrt{1-\tau_{t, 0}}}\bigg\|^{-1} \lesssim 1,\label{ineq40a}\\
    		&\big\|x_{\tau_{t,i}}^{(N)} - x_{\tau_{t,i}}^{\star}\big\|_2^2 \leq C\tau'^{2}\frac{\log^2 T}{T^2}\sum_{0 \leq n \leq N}\sum_{0 \le i < k}\big(\varepsilon_{\mathsf{score}, t, i}^{(n)}(x_{\tau_{t, i}}^{(n)})\big)^2 + 3C\frac{d\tau'\log^3 T}{T^2}\bigg(\frac{d\log^2 T}{T}\bigg)^{2K},\label{ineq40b}\\
    		&\bigg\|\frac{\partial x_{\tau_{t,i}}^{(N)}/\sqrt{1-\tau_{t,i}}}{\partial x_{\tau_{t, 0}}/\sqrt{1-\tau_{t, 0}}} - \frac{\partial x_{\tau_{t,i}}^{\star}/\sqrt{1-\tau_{t,i}}}{\partial x_{\tau_{t, 0}}^{\star}/\sqrt{1-\tau_{t, 0}}}\bigg\|^2\notag\\ &\quad\lesssim \frac{d^3\log^7 T}{T^4}\sum_{i,n}\big(\varepsilon_{\mathsf{score}, t, i}^{(n)}(x_{\tau_{t, i}}^{(n)})\big)^2 + \frac{\log^2 T}{T^2}\tau'^{2}\sum_{i,n}\big(\varepsilon_{\mathsf{Jacobi}, t, i}^{(n)}(x_{\tau_{t, i}}^{(n)})\big)^2 + \Big(\frac{d\log^2 T}{T}\Big)^{2K+2}.\label{ineq40c}
    	\end{align}
    \end{subequations}
\end{lemma}
The proof of Lemma \ref{lemma:main} is deferred to Section \ref{sec:proof_lemma_main}. By virtue of Lemma \ref{lemma:main} and \eqref{ineq41}, one can show that on the event $\mathcal{E}_t \cap \{\xi_t(x_t) \leq c\}$, one has
\begin{align}\label{ineq42}
		&\frac{p_{Y_{t-1}}(x_{t-1})}{p_{X_{t-1}}(x_{t-1})}\notag\\
	&\quad= \exp\left(O\left(\frac{d\log T}{T}\sqrt{\sum_{i,n}\big(\varepsilon_{\mathsf{Jacobi}, t, i}^{(n)}(x_{\tau_{t, i}}^{(n)})\big)^2} + \frac{\sqrt{d\log^3 T}}{T}\sqrt{\sum_{i,n}\big(\varepsilon_{\mathsf{score}, t, i}^{(n)}(x_{\tau_{t, i}}^{(n)})\big)^2} + d\bigg(\frac{d\log^2 T}{T}\bigg)^{K+1}\right)\right)\frac{p_{Y_{t}}(x_{t})}{p_{X_{t}}(x_{t})}\notag\\
	&\quad= \exp\left(O\left(\xi_t(x_t) + d\bigg(\frac{d\log^2 T}{T}\bigg)^{K+1}\right)\right)\frac{p_{Y_{t}}(x_{t})}{p_{X_{t}}(x_{t})},
\end{align}
provided that $T \gtrsim d^2\log^2 T$. Here, $\xi_t(\cdot)$ is defined in \eqref{eq9a}. Furthermore, the following lemma shows that the log densities $\{-\log p_{X_{\tau_{t,i}}}\big(\lambda x_{\tau_{t,i}}^{(n+1)} + (1-\lambda)x_{\tau_{t,i}}^\star\big)\}_{i,n, \lambda \in [0,1]}$ can be well-controlled as long as $x_{\tau_{t,0}}$ is ``typical" and the score estimation errors are not extremely large.
\begin{lemma}\label{lemma:log_density_ratio_1}
	If $C_{10}\frac{\theta_{\tau_{t,0}}(x_{\tau_{t,0}})d\log^2 T + \sqrt{\theta_{\tau_{t,0}}(x_{\tau_{t,0}})\sum_{i,n}\big(\varepsilon_{\mathsf{score}, t, i}^{(n)}(x_{\tau_{t, i}}^{(n)})\big)^2d\log^3 T}}{T} \leq 1$ for some large enough constant $C_{10} > 0$, then for all $0 \leq i \leq K - 1, 0 \leq n \leq N - 1$, one has
	\begin{subequations}
		\begin{align}
			-\log p_{X_{\tau_{t,i}}}\big(\lambda x_{\tau_{t,i}}^{(n+1)} + (1-\lambda)x_{\tau_{t,i}}^\star\big) &\leq 2.1d\theta_t\log T,\label{ineq38a}\\
			\log\frac{p_{\sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}X_{\tau_{t,i}}}\left(\sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}x_{\tau_{t,i}}^{(n+1)}\right)}{p_{X_{\tau_{t,0}}}(x_{\tau_{t,0}})} &\leq \frac{4c_1d\log T}{T} + C_{10}\left\{\frac{d^2\theta_t^2\log^4 T}{T^2} + \frac{\sqrt{d\theta_t\log^3 T}}{T}\sqrt{\sum_{i}\big(\varepsilon_{\mathsf{score}, t, i}^{(n)}(x_{\tau_{t, i}}^{(n)})\big)^2}\right\}.\label{ineq38b}
		\end{align}
	\end{subequations}
\end{lemma}
\paragraph{Step 2: decomposing the TV distance of interest.}
Next, let us  define the sets
\begin{align}\label{event:typical}
	\mathcal{E} = \{x: q_1(x) > \max\{p_1(x), \exp(-c_6d\log T)\}\},
\end{align}
and
\begin{align}\label{set:typical_1}
	\mathcal{I}_1 := \{x_T\ | \ S_T(x_T) \leq c_3\}
\end{align}
for some small enough constant $c_3 > 0$.
Then we learn from \citet[Eqn. (51) and (53)]{li2024sharp} that 
\begin{align}\label{ineq43}
	\mathsf{TV}(q_1, p_1) &\leq \mathbb{E}_{Y_1 \in p_1}\left[\Big(\frac{q_1(Y_1)}{p_1(Y_1)} - 1\Big)\ind\{Y_1 \in \mathcal{E}\}\right] + \exp(-c_6d\log T)\notag\\
	&= \underbrace{\mathbb{E}_{Y_T \in p_T}\left[\Big(\frac{q_1(Y_1)}{p_1(Y_1)} - 1\Big)\ind\{Y_1 \in \mathcal{E}, Y_T \in \mathcal{I}_1\}\right]}_{=:\alpha_1} + \underbrace{\mathbb{E}_{Y_T \in p_T}\left[\Big(\frac{q_1(Y_1)}{p_1(Y_1)} - 1\Big)\ind\{Y_1 \in \mathcal{E}, Y_T \notin \mathcal{I}_1\}\right]}_{=:\alpha_2}\notag\\
	&\quad + \exp(-c_6d\log T).
\end{align}
provided that $c_6 \geq 4(c_R + 2)$. This motivates us to bound $\alpha_1$ and $\alpha_2$ separately.

\paragraph{Step 3: bounding $\alpha_1$.}
We let $\tau(x_T)$ denote the following quantity:
\begin{align}\label{def:tau}
	\tau(x_T) := \max\{2 \leq t \leq T + 1: S_{t-1}(x_T) \leq c_{3}\}.
\end{align}
Then for any $x_T \in \mathcal{I}_1$, one has
\begin{align}\label{ineq44}
	\tau(x_T) = T + 1.
\end{align}
In addition, we have the following two important properties regarding $\tau(x_T)$:
\begin{lemma}\label{lemma:log_density_bound}
	If $-\log q_1(x_1) \leq c_6d\log T$, then for all $1 \leq \ell < \tau(x_T)$, one has
	\begin{align}\label{ineq:log_density_bound}
		-\log q_{\ell}(x_{\ell}) \leq 2c_6d\log T
	\end{align}
	as long as $c_6 > 5c_1$.
\end{lemma}
\begin{lemma}\label{lemma:log_density_ratio_2}
    For $\tau = \tau(x_{T})$, We have
    \begin{align}
    	\frac{q_1(x_{1})}{p_1(x_{1})}
    	&= \left(1 + O\left(\sum_{t < \tau}\xi_t(x_t) + d^2\log^2 T\bigg(\frac{d\log^2 T}{T}\bigg)^{K}\right)\right)\frac{q_{\tau-1}(x_{\tau-1})}{p_{\tau-1}(x_{\tau-1})},\label{ineq45a}\\
    	&\qquad\frac{q_{\ell}(x_{\ell})}{2p_{\ell}(x_{\ell})} \leq \frac{q_1(x_{1})}{p_1(x_{1})} \leq \frac{2q_{\ell}(x_{\ell})}{p_{\ell}(x_{\ell})}, \quad \forall \ell < \tau.\label{ineq45b}
    \end{align}
\end{lemma}
The proofs of Lemma \ref{lemma:log_density_bound} and Lemma \ref{lemma:log_density_ratio_2} are postponed to Sections \ref{sec:proof_lemma_log_density_bound} and \ref{sec:proof_lemma_log_density_ratio_2}, respectively.
By virtue of \eqref{ineq44} and Lemma \ref{lemma:log_density_ratio_2}, one can show that
\begin{align}
	&\mathbb{E}_{Y_T \in p_T}\left[\Big(\frac{q_1(Y_1)}{p_1(Y_1)} - 1\Big)\ind\{Y_1 \in \mathcal{E}, Y_T \in \mathcal{I}_1\}\right]\notag\\
	&\quad = \mathbb{E}_{Y_T \in p_T}\left[\left(\left(1 + \sum_{t}\xi_t(Y_t) + d^2\log^2 T\bigg(\frac{d\log^2 T}{T}\bigg)^{K}\right)\frac{q_T(Y_T)}{p_T(Y_T)} - 1\right)\ind\{Y_1 \in \mathcal{E}, Y_T \in \mathcal{I}_1\}\right]\notag\\
	&\quad = \int\left\{\left(\left(1 + \sum_{t}\xi_t(x_t) + d^2\log^2 T\bigg(\frac{d\log^2 T}{T}\bigg)^{K}\right)q_T(x_T) - p_T(x_T)\right)\ind\{x_1 \in \mathcal{E}, x_T \in \mathcal{I}_1\}\right\}{\rm d}x_T\notag\\
	&\quad \leq \int|q_T(x_T) - p_T(x_T)|{\rm d}x_T + d^2\log^2 T\bigg(\frac{d\log^2 T}{T}\bigg)^{K} +  \int S_T(x_T)q_T(x_T)\ind\{x_1 \in \mathcal{E}, x_T \in \mathcal{I}_1\}{\rm d}x_T.\label{ineq46}
\end{align}
Additionally, we make the observation that 
\begin{align}
	&\int S_T(x_T)q_T(x_T)\ind\{x_1 \in \mathcal{E}, x_T \in \mathcal{I}_1\}{\rm d}x_T\notag\\
	&\quad = \sum_{t=2}^{T}\int \frac{\log T}{T}\left(d\sqrt{\sum_{i,n}\big(\varepsilon_{\mathsf{Jacobi}, t, i}^{(n)}(x_{\tau_{t, i}}^{(n)})\big)^2} + \sqrt{d\log T}\sqrt{\sum_{i,n}\big(\varepsilon_{\mathsf{score}, t, i}^{(n)}(x_{\tau_{t, i}}^{(n)})\big)^2}\right)\ind\{x_1 \in \mathcal{E}, x_T \in \mathcal{I}_1\}{\rm d}x_T\notag\\
	&\quad = \sum_{t=2}^{T}\mathbb{E}_{Y_T \sim p_T}\left[\frac{\log T}{T}\left(d\varepsilon_{\mathsf{Jacobi}, t}(Y_t) + \sqrt{d\log T}\varepsilon_{\mathsf{score}, t}(Y_t)\right)\frac{q_t(Y_T)}{p_t(Y_T)}\ind\{x_1 \in \mathcal{E}, x_T \in \mathcal{I}_1\}\right]\notag\\
	&\quad \stackrel{\eqref{ineq45b}}{\leq} 4\sum_{t=2}^{T}\mathbb{E}_{Y_T \sim p_T}\left[\frac{\log T}{T}\left(d\varepsilon_{\mathsf{Jacobi}, t}(Y_t) + \sqrt{d\log T}\varepsilon_{\mathsf{score}, t}(Y_t)\right)\frac{q_t(Y_t)}{p_t(Y_t)}\ind\{x_1 \in \mathcal{E}, x_T \in \mathcal{I}_1\}\right]\notag\\
	&\quad \leq 4\sum_{t=2}^{T}\mathbb{E}_{Y_t \sim p_t}\left[\frac{\log T}{T}\left(d\varepsilon_{\mathsf{Jacobi}, t}(Y_t) + \sqrt{d\log T}\varepsilon_{\mathsf{score}, t}(Y_t)\right)\frac{q_t(Y_t)}{p_t(Y_t)}\right]\notag\\
	&\quad = 4\sum_{t=2}^{T}\mathbb{E}_{Y_t \sim q_t}\left[\frac{\log T}{T}\left(d\varepsilon_{\mathsf{Jacobi}, t}(Y_t) + \sqrt{d\log T}\varepsilon_{\mathsf{score}, t}(Y_t)\right)\right]\notag\\
	&\quad \stackrel{\eqref{ineq47a}~\text{and}~\eqref{ineq47b}}{\lesssim} d\log^{3/2}T\varepsilon_{\mathsf{Jacobi}} + \sqrt{d\log^4 T}\varepsilon_{\mathsf{score}}.
\end{align}
Putting the previous two inequalities together, one arrives at
\begin{align}
	\alpha_1 &= \mathbb{E}_{Y_T \in p_T}\left[\Big(\frac{q_1(Y_1)}{p_1(Y_1)} - 1\Big)\ind\{Y_1 \in \mathcal{E}, Y_T \in \mathcal{I}_1\}\right]\notag\\ &\lesssim d^2\log^2 T\bigg(\frac{d\log^2 T}{T}\bigg)^{K} + d\log^{3/2}T\varepsilon_{\mathsf{Jacobi}} + \sqrt{d\log^4 T}\varepsilon_{\mathsf{score}}.\label{ineq:alpha_1}
\end{align}

\paragraph{Step 4: bounding $\alpha_2$.} Now, we turn to bounding $\alpha_2$. We let $\tau = \tau(x_T)$ define the following sets:
\begin{align}
    \mathcal{I}_2 &:= \{x_T~|~c_3 \leq S_{\tau}(x_T) \leq 2c_3\},\label{set_I_2}\\
    \mathcal{I}_3 &:= \left\{x_T~|~S_{\tau-1}(x_T) \leq c_3, \xi_{\tau}(x_T) \geq c_3, \frac{q_{\tau-1}(x_{\tau-1})}{p_{\tau-1}(x_{\tau-1})} \leq 8\frac{q_{\tau}(x_{\tau})}{p_{\tau}(x_{\tau})}\right\},\label{set_I_3}\\
    \mathcal{I}_4 &:= \left\{x_T~|~S_{\tau-1}(x_T) \leq c_3, \xi_{\tau}(x_T) \geq c_3, \frac{q_{\tau-1}(x_{\tau-1})}{p_{\tau-1}(x_{\tau-1})} > 8\frac{q_{\tau}(x_{\tau})}{p_{\tau}(x_{\tau})}\right\},\label{set_I_4}
\end{align}
It is straightforward to verify that $\mathcal{I}_1 \cup \mathcal{I}_2 \cup \mathcal{I}_3 \cup \mathcal{I}_4 = \mathbb{R}^d$. The following lemma indicates that $\alpha_2$ can be well-controlled.
\begin{lemma}\label{lemma:other_set}
    The following inequality holds:
    \begin{align}
        \mathbb{E}_{Y_T \sim p_T}\left[\Big(\frac{q_1(Y_1)}{p_1(Y_1)} - 1\Big)\ind\{Y_1 \in \mathcal{E}, Y_T \in \mathcal{I}_2 \cup \mathcal{I}_3 \cup \mathcal{I}_4\}\right] \lesssim d^2\log^2 T\bigg(\frac{d\log^2 T}{T}\bigg)^{K} + d\log^{3/2}T\varepsilon_{\mathsf{Jacobi}} + \sqrt{d\log^4 T}\varepsilon_{\mathsf{score}}.\label{ineq48}
    \end{align}
\end{lemma}
An immediate consequence of Lemma \ref{lemma:other_set} is
\begin{align}
    \alpha_2 &= \mathbb{E}_{Y_T \in p_T}\left[\Big(\frac{q_1(Y_1)}{p_1(Y_1)} - 1\Big)\ind\{Y_1 \in \mathcal{E}, Y_T \notin \mathcal{I}_1\}\right]\notag\\
    &\leq \mathbb{E}_{Y_T \in p_T}\left[\Big(\frac{q_1(Y_1)}{p_1(Y_1)} - 1\Big)\ind\{Y_1 \in \mathcal{E}, Y_T \in \mathcal{I}_2 \cup \mathcal{I}_3 \cup \mathcal{I}_4\}\right]\notag\\
    &\lesssim d^2\log^2 T\bigg(\frac{d\log^2 T}{T}\bigg)^{K} + d\log^{3/2}T\varepsilon_{\mathsf{Jacobi}} + \sqrt{d\log^4 T}\varepsilon_{\mathsf{score}}.\label{ineq:alpha_2}
\end{align}
Here, the second line comes from the facts $q_1(x) \geq p_1(x)$ for any $x \in \mathcal{E}$ and $\mathcal{I}_1^c \subseteq \mathcal{I}_2 \cup \mathcal{I}_3 \cup \mathcal{I}_4$.

\paragraph{Step 5: bounding ${\sf TV}(p_1, q_1)$ } Combining \eqref{ineq43}, \eqref{ineq:alpha_1} and \eqref{ineq:alpha_2}, one arrives at the advertised result: 
\begin{align}
    {\sf TV}(p_1, q_1) &\lesssim d^2\log^2 T\bigg(\frac{d\log^2 T}{T}\bigg)^{K} + d\log^{3/2}T\varepsilon_{\mathsf{Jacobi}} + \sqrt{d\log^4 T}\varepsilon_{\mathsf{score}} + \exp(-c_6d\log T)\notag\\
    &\asymp d^2\log^2 T\bigg(\frac{d\log^2 T}{T}\bigg)^{K} + d\log^{3/2}T\varepsilon_{\mathsf{Jacobi}} + \sqrt{d\log^4 T}\varepsilon_{\mathsf{score}}.\label{ineq49}
\end{align}




\section{Discussion and future directions}

In this work, we have proposed an algorithm to speed up data generation in diffusion models. The proposed algorithm exploits $K$-th order ODE approximation combined with a successive refining scheme, which provably yields  $\varepsilon$-precision (measured by the TV distance between the output distribution and the target distribution) within $\widetilde{O}\big(d^{1+2/K}/\varepsilon^{1/K}\big)$ iterations. Our theoretical guarantees hold under fairly mild assumptions on the target distribution, with no restrictions on smoothness and log-concavity, and are capable of accommodating imperfect score estimation.
Our findings leave open several interesting questions for future investigation.  
For instance, while our theory allows the order $K$ to be an arbitrary large constant,  it is worth exploring whether $K$ can be allowed to scale with $T$ (e.g., whether $K$ can reach the order of $\log T$), as accomplishing this might potentially lead to further acceleration. 
Additionally, our method is a deterministic sampler designed to speed up diffusion ODE, 
and it remains unclear whether a similar iteration complexity can be achieved with an accelerated stochastic sampler (i.e., the SDE counterpart). Furthermore, 
while this work focuses on the iteration complexity of the sampling phase,  how to develop an end-to-end theory that also incorporates the score matching phase forms another direction for future study.  
Finally, if the target data distribution exhibits intrinsic low dimensionality, it would be interesting to examine whether the sampling process be further expedited.  




