	&= \sum_{0 \le i < K} \gamma_{t, i}(\tau')(1-\tau_{t, i})^{-3/2}\big[s_{\tau_{t, i}}(x_{\tau_{t, i}}^{(n)}) - s_{\tau_{t, i}}^{\star}(x_{\tau_{t, i}}^{(n)})\big].
\end{align*}
Then one can derive
\begin{align}
	&\frac{x_{\tau'}^{(n+1)}}{\sqrt{1-\tau'}} - \frac{x_{\tau'}^{\star}}{\sqrt{1-\tau'}}\notag\\ &\quad= \Big(\frac{x_{\tau'}^{(n+1)}}{\sqrt{1-\tau'}} - \frac{x_{\tau_{t, 0}}}{\sqrt{1-\tau_{t, 0}}}\Big) - \Big(\frac{x_{\tau'}^{\star}}{\sqrt{1-\tau'}}-\frac{x_{\tau_{t, 0}}^{\star}}{\sqrt{1-\tau_{t, 0}}}\Big)\notag\\
	&\quad=\sum_{0 \le i < K} \gamma_{t, i}(\tau')(1-\tau_{t, i})^{-3/2}s_{\tau_{t, i}}(x_{\tau_{t, i}}^{(n)}) + \int_{\tau_{t, 0}}^{\tau'} \frac{1}{2(1-\tau)^{3/2}}s_{\tau}^{\star}\mathrm{d}\tau\notag\\
	&\quad= \sum_{0 \le i < K} \gamma_{t, i}(\tau')(1-\tau_{t, i})^{-3/2}\big[s_{\tau_{t, i}}(x_{\tau_{t, i}}^{(n)}) - s_{\tau_{t, i}}^{\star}(x_{\tau_{t, i}}^{(n)})\big]\notag\\&\qquad + \left[\sum_{0 \le i < K} \gamma_{t, i}(\tau')(1-\tau_{t, i})^{-3/2} s_{\tau_{t, i}}^{\star}(x_{\tau_{t, i}}^{(n)}) - \left(-\int_{\tau_{t, 0}}^{\tau'} \frac{1}{2(1-\tau)^{3/2}}s_{\tau}^{\star}(x_{\tau}^\star)\mathrm{d}\tau\right)\right]\notag\\
	&\quad= \xi_{\mathsf{score}, \tau'}^{(n)} + \sum_{0 \le i < K} \gamma_{t, i}(\tau')(1-\tau_{t, i})^{-3/2}\big(s_{\tau_{t, i}}^{\star}(x_{\tau_{t, i}}^{\star}) - s_{\tau_{t, i}}^{\star}(x_{\tau_{t, i}}^{(n)})\big)\notag\\&\qquad + \left[\sum_{0 \le i < K} \gamma_{t, i}(\tau')(1-\tau_{t, i})^{-3/2} s_{\tau_{t, i}}^{\star}(x_{\tau_{t, i}}^{\star}) - \left(-\int_{\tau_{t, 0}}^{\tau'} \frac{1}{2(1-\tau)^{3/2}}s_{\tau}^{\star}(x_{\tau}^\star)\mathrm{d}\tau\right)\right].\label{eq:decomposition_1}
\end{align}
Furthermore, we make the observation that
\begin{align}
	\frac{\partial x_{\tau'}^{(n+1)}/\sqrt{1-\tau'}}{\partial x_{\tau_{t, 0}}/\sqrt{1-\tau_{t, 0}}}
	&= I + \sum_{0 \le i < K} \gamma_{t, i}(\tau')(1-\tau_{t, i})^{-3/2}\frac{\partial s_{\tau_{t, i}}(x_{\tau_{t, i}}^{(n)})}{\partial x_{\tau_{t, i}}^{(n)}/\sqrt{1-\tau_{t, i}}}\frac{\partial x_{\tau_{t, i}}^{(n)}/\sqrt{1-\tau_{t, i}}}{\partial x_{\tau_{t, 0}}/\sqrt{1-\tau_{t, 0}}} \notag\\
	&=: I + \sum_{0 \le i < K} \gamma_{t, i}(\tau')(1-\tau_{t, i})^{-3/2}\frac{\partial s_{\tau_{t, i}}^{\star}(x_{\tau_{t, i}}^{(n)})}{\partial x_{\tau_{t, i}}^{(n)}/\sqrt{1-\tau_{t, i}}}\frac{\partial x_{\tau_{t, i}}^{(n)}/\sqrt{1-\tau_{t, i}}}{\partial x_{\tau_{t, 0}}/\sqrt{1-\tau_{t, 0}}} + \xi_{\mathsf{Jacob}, \tau'}^{(n)}.\label{ineq5}
