\end{align}
and
\begin{align}
	&\frac{\partial x_{\tau'}^{\star}/\sqrt{1-\tau'}}{\partial x_{\tau_{t, 0}}^{\star}/\sqrt{1-\tau_{t, 0}}}\notag\\
	&\quad= I - \int_{\tau_{t, 0}}^{\tau'} \frac{1}{2(1-\tau)^{3/2}}\frac{\partial s_{\tau}^{\star}(x_{\tau}^{\star})}{\partial x_{\tau}^{\star}/\sqrt{1-\tau}}\frac{\partial x_{\tau}^{\star}/\sqrt{1-\tau}}{\partial x_{\tau_{t, 0}}^{\star}/\sqrt{1-\tau_{t, 0}}}\mathrm{d}\tau\notag\\ 
