\end{align}


\paragraph{Putting everything together.}
Combing \eqref{eq:decomposition_1}, \eqref{eq:taylor_1} and Lemma \ref{lemma:Hessian}, one has
\begin{align*}
	&\bigg\|\frac{x_{\tau'}^{(n+1)}}{\sqrt{1-\tau'}} - \frac{x_{\tau'}^{\star}}{\sqrt{1-\tau'}}\bigg\|_2\\
	&\quad\lesssim\|\xi_{\mathsf{score}, \tau'}^{(n)}\|_2 + \sum_{0 \le i < K} |\gamma_{t, i}(\tau')|(1-\tau_{t, i})^{-3/2}\big\|s_{\tau_{t, i}}^{\star}(x_{\tau_{t, i}}^{\star}) - s_{\tau_{t, i}}^{\star}(x_{\tau_{t, i}}^{(n)})\big\|_2\\&\qquad + \left\|\sum_{0 \le i < K} \gamma_{t, i}(\tau')(1-\tau_{t, i})^{-3/2} s_{\tau_{t, i}}^{\star}(x_{\tau_{t, i}}^{(n)}) - \left(-\int_{\tau_{t, 0}}^{\tau'} \frac{1}{2(1-\tau)^{3/2}}s_{\tau}^{\star}(x_{\tau}^\star)\mathrm{d}\tau\right)\right\|_2\\
	&\quad \lesssim\|\xi_{\mathsf{score}, \tau'}^{(n)}\|_2 + \sum_{0 \le i < K}2^K(\tau_{t, 0} - \tau')(1-\tau_{t, i})^{-3/2}\big\|s_{\tau_{t, i}}^{\star}(x_{\tau_{t, i}}^{\star}) - s_{\tau_{t, i}}^{\star}(x_{\tau_{t, i}}^{(n)})\big\|_2\\
