	&\quad\lesssim \sum_{0 \le i < K} \frac{d(\tau_{t, 0}-\tau')\log T}{\tau_{t, i}(1-\tau_{t, i})} \bigg\|\frac{x_{\tau_{t, i}}^{(n)}}{\sqrt{1-\tau'}} - \frac{x_{\tau_{t, i}}^{\star}}{\sqrt{1-\tau'}}\bigg\|_2 \\
	&\qquad+ \|\xi_{\mathsf{score}, \tau'}^{(n)}\|_2 + O\Bigg(\sqrt{\frac{d(\tau'-\tau_{t, 0})^2\log T}{\tau'(1-\tau')^3}}\bigg(\frac{d(\tau_{t, 0}-\tau')\log T}{\tau'(1-\tau')}\bigg)^{K}\Bigg) \\
	&\quad\lesssim \frac{d\log^2 T}{T} \sum_{0 \le i < K} \bigg\|\frac{x_{\tau_{t, i}}^{(n)}}{\sqrt{1-\tau'}} - \frac{x_{\tau_{t, i}}^{\star}}{\sqrt{1-\tau'}}\bigg\|_2 
	+ \|\xi_{\mathsf{score}, \tau'}^{(n)}\|_2 + O\Bigg(\sqrt{\frac{d\tau'\log^3 T}{T^2(1-\tau')}}\bigg(\frac{d\log^2 T}{T}\bigg)^{K}\Bigg),
\end{align*}
Here, the second inequality makes use of \eqref{ineq:learning_rate_g} and Lemma \ref{lemma:learning_rate}; the third inequality is valid due to Lemma \ref{lemma:Hessian}; the last line holds because of Lemma \ref{lemma:learning_rate}. Recalling that $K$ is a constant, we know there exists constants $C > 0$ such that
\begin{align*}
	\big\|x_{\tau'}^{(n+1)} - x_{\tau'}^{\star}\big\|_2^2 &\leq C\left[\left(\frac{d\log^2 T}{T}\right)^2 \sum_{0 \le i < K} \big\|x_{\tau_{t, i}}^{(n)} - x_{\tau_{t, i}}^{\star}\big\|_2^2 + (1 - \tau')\|\xi_{\mathsf{score}, \tau'}^{(n)}\|_2^2 + \frac{d\tau'\log^3 T}{T^2}\bigg(\frac{d\log^2 T}{T}\bigg)^{2K}\right]\\
	&\stackrel{\eqref{ineq:score_estimation_1}}{\leq} \frac{1}{3}\max_{0 \leq i \leq K}\big\|x_{\tau_{t, i}}^{(n)} - x_{\tau_{t, i}}^{\star}\big\|_2^2 + C\tau'^{2}\frac{\log^2 T}{T^2}\sum_{0 \le i < K}\big(\varepsilon_{\mathsf{score}, t, i}^{(n)}(x_{\tau_{t, i}}^{(n)})\big)^2 + C\frac{d\tau'\log^3 T}{T^2}\bigg(\frac{d\log^2 T}{T}\bigg)^{2K},
\end{align*}
Then it follows by induction that, for all $N' \geq 1$,
\begin{align}
	\big\|x_{\tau'}^{(N')} - x_{\tau'}^{\star}\big\|_2^2 &\leq \frac{1}{3^{N'}}\max_{0 \leq i \leq K}\big\|x_{\tau_{t, i}}^{(0)} - x_{\tau_{t, i}}^{\star}\big\|_2^2 + C\tau'^{2}\frac{\log^2 T}{T^2}\sum_{0 \leq n \leq N'}\sum_{0 \le i < K}\big(\varepsilon_{\mathsf{score}, t, i}^{(n)}(x_{\tau_{t, i}}^{(n)})\big)^2\notag\\&\quad+ 2C\frac{d\tau'\log^3 T}{T^2}\bigg(\frac{d\log^2 T}{T}\bigg)^{2K}.\label{ineq:induction_1}
\end{align}
Recalling the definition of $x_{\tau_{t, i}}^{\star}$ and $x_{\tau_{t, i}}^{(0)}$, we invoke Lemma \ref{lemma:Hessian} to obtain
\begin{align}
	\big\|x_{\tau_{t, i}}^{\star} - x_{\tau_{t, i}}^{(0)}\big\|_2 &= \big\|x_{\tau_{t, i}}^{\star} - x_{\tau_{t, 0}}\big\|_2 = \bigg\|\int_{\tau_{t, 0}}^{\tau_{t, i}}s_{\tau}^\star(x_{\tau}^\star){\rm d}\tau\bigg\|_2 \leq (\tau_{t, 0}-\tau_{t, i})\sup_{\tau_{t, i}\leq\tau\leq\tau_{t, 0}}\left\|s_{\tau}^\star(x_{\tau}^\star)\right\|_2\notag\\
	&\lesssim (\tau_{t, 0}-\tau_{t, K-1})\sqrt{\frac{d\log T}{\tau_{t, K-1}}} = (\overline{\alpha}_{t-1} - \overline{\alpha}_t)\sqrt{\frac{d\log T}{1-\overline{\alpha}_{t-1}}} =\overline{\alpha}_{t-1}\sqrt{1-\alpha_t}\sqrt{\frac{1-\alpha_t}{1-\overline{\alpha}_{t-1}}}\sqrt{d\log T}\notag\\
	&\stackrel{\text{Lemma }\ref{lemma:learning_rate}}{\leq} 2c_1\frac{\log T}{T}\sqrt{d\log T}\label{ineq13}
\end{align}
for all $0 \leq i \leq k-1$, provided that $-\log p_{\tau}(x_{\tau}^\star) \lesssim d\log T$ for all $\tau_{t,k-1} \leq \tau \leq \tau_{t, 0}$. As a consequence, as long as $N \geq C_0\log T$ for some large enough constant $C_0 > 0$, one has
\begin{align}\label{ineq12}
	\big\|x_{\tau'}^{(N)} - x_{\tau'}^{\star}\big\|_2^2 &\leq C\tau'^{2}\frac{\log^2 T}{T^2}\sum_{0 \leq n \leq N}\sum_{0 \le i < K}\big(\varepsilon_{\mathsf{score}, t, i}^{(n)}(x_{\tau_{t, i}}^{(n)})\big)^2 + 3C\frac{d\tau'\log^3 T}{T^2}\bigg(\frac{d\log^2 T}{T}\bigg)^{2K}.
\end{align}


Similarly, \eqref{eq:decomposition_2}, \eqref{ineq3a}, \eqref{eq:taylor_2}, Lemma \ref{lemma:learning_rate} and Lemma \ref{lemma:Hessian} together imply that on $\mathcal{E}_t$,
\begin{align*}
