	\le 1 + 2^K\sum_{0 \le i < K} (\tau_{t, 0} - \tau')\frac{d\log T}{\tau_{t, i}(1-\tau_{t, i})}\bigg\|\frac{\partial x_{\tau_{t, i}}^{(n)}/\sqrt{1-\tau_{t, i}}}{\partial x_{\tau_{t, 0}}/\sqrt{1-\tau_{t, 0}}}\bigg\| + \|\xi_{\mathsf{Jacob}, \tau'}^{(n)}\| \lesssim 1,
\end{align*}
provided that $-p_{\overline{X}_{\tau_{t, i}}}(x_{\tau_{t, i}}^{(n)}) \lesssim d\log T$. Here, the first inequality makes use of Lemma \ref{lemma:Hessian} and the second inequality holds due to the induction hypotheses \eqref{ineq3a} and \eqref{ineq3b} for $n$. Similarly, one has
\begin{align*}
	\bigg\|\frac{\partial x_{\tau'}^{(n+1)}/\sqrt{1-\tau'}}{\partial x_{\tau_{t, 0}}/\sqrt{1-\tau_{t, 0}}}\bigg\|
	\geq 1 - 2^K\sum_{0 \le i < K} (\tau_{t, 0} - \tau')\frac{d\log T}{\tau_{t, i}(1-\tau_{t, i})}\bigg\|\frac{\partial x_{\tau_{t, i}}^{(n)}/\sqrt{1-\tau_{t, i}}}{\partial x_{\tau_{t, 0}}/\sqrt{1-\tau_{t, 0}}}\bigg\| - \|\xi_{\mathsf{Jacob}, \tau'}^{(n)}\| \gtrsim 1
\end{align*}
In addition, repeating a similar argument as in \eqref{ineq4} yields
\begin{align*}
	\|\xi_{\mathsf{Jacob}, \tau'}^{(n+1)}\| \leq \frac{1}{2}.
\end{align*}
Therefore, \eqref{ineq3a} and \eqref{ineq3b} hold for $n+1$, and consequently we have finished the proof.
\paragraph{Proof of Claims~\eqref{eq:derivative_1} and \eqref{eq:derivative_2}.}
It remains to verify \eqref{eq:derivative_1} and \eqref{eq:derivative_2}. We let $$u_k := \frac{\partial^k}{\partial \tau^k} \frac{s_{\tau}^{\star}(x_{\tau}^{\star})}{(1-\tau)^{3/2}}.$$
The score function can be expressed as
\begin{align}\label{eq2}
	\frac{s_{\tau}^{\star}(\sqrt{1-\tau}x)}{(1-\tau)^{3/2}}
	&= -\frac{1}{\tau(1-\tau)}\int_{x_0} p_{X_0 \mymid \overline{X}_\tau}(x_0 \mymid \sqrt{1-\tau}x)(x - x_0)\mathrm{d}x_0 \notag\\
	&= -\frac{1}{\tau(1-\tau)}\cdot\frac{\int_{x_0} p_{X_0}(x_0)p_{\overline{X}_\tau \mymid X_0}(\sqrt{1-\tau}x \mymid x_0)(x - x_0)\mathrm{d}x_0}{\int_{x_0} p_{X_0}(x_0)p_{\overline{X}_\tau \mymid X_0}(\sqrt{1-\tau}x \mymid x_0)\mathrm{d}x_0},
\end{align}
where
\begin{align*}
	(2\pi\tau)^{d/2}p_{\overline{X}_\tau \mymid X_0}(\sqrt{1-\tau}x \mymid x_0)
	= \exp\Big(-\frac{(1-\tau)\|x - x_0\|_2^2}{2\tau}\Big).
\end{align*}
Then for sufficiently small $\delta$, we have
\begin{align}
	&\frac{s_{\tau+\delta}^{\star}(x_{\tau+\delta}^{\star})}{(1-\tau-\delta)^{3/2}}\notag\\
	&\quad= -\frac{1}{(\tau+\delta)(1-\tau-\delta)}\int_{x_0} p_{X_0 \mymid \overline{X}_{\tau+\delta}}(x_0 \mymid x_{\tau+\delta}^{\star})\bigg(\frac{x_{\tau+\delta}^{\star}}{\sqrt{1-\tau-\delta}} - x_0\bigg)\mathrm{d}x_0 \notag\\
	&\quad= -\frac{1}{(\tau+\delta)(1-\tau-\delta)}\bigg(\frac{x_{\tau+\delta}^{\star}}{\sqrt{1-\tau-\delta}} - \frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} + \int_{x_0} p_{X_0 \mymid \overline{X}_{\tau+\delta}}(x_0 \mymid x_{\tau+\delta}^{\star})\bigg(\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\bigg)\mathrm{d}x_0\bigg)\notag\\
	&\quad= -\frac{1}{(\tau+\delta)(1-\tau-\delta)}\left(\frac{x_{\tau+\delta}^{\star}}{\sqrt{1-\tau-\delta}} - \frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} + \frac{\int_{x_0} p_{X_0}(x_0)p_{\overline{X}_{\tau+\delta} \mymid X_0}(x_{\tau+\delta}^{\star} \mymid x_0)\left(\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\right)\mathrm{d}x_0}{\int_{x_0} p_{X_0}(x_0)p_{\overline{X}_{\tau+\delta} \mymid X_0}(x_{\tau+\delta}^{\star} \mymid x_0)\mathrm{d}x_0}\right)\notag\\
	&\quad= -\frac{1}{(\tau+\delta)(1-\tau-\delta)}\left(\frac{x_{\tau+\delta}^{\star}}{\sqrt{1-\tau-\delta}} - \frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} + \frac{\int_{x_0} p_{X_0}(x_0)p_{\overline{X}_{\tau} \mymid X_0}(x_{\tau}^{\star} \mymid x_0)\exp(\Delta)\left(\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\right)\mathrm{d}x_0}{\int_{x_0} p_{X_0}(x_0)p_{\overline{X}_{\tau} \mymid X_0}(x_{\tau}^{\star} \mymid x_0)\exp(\Delta)\mathrm{d}x_0}\right)\notag\\
	&\quad= -\frac{1}{(\tau+\delta)(1-\tau-\delta)}\left(\frac{x_{\tau+\delta}^{\star}}{\sqrt{1-\tau-\delta}} - \frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} + \frac{\int_{x_0} p_{X_0 \mymid \overline{X}_\tau}(x_0 \mymid x_{\tau}^{\star})\exp(\Delta)\big(\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\big)\mathrm{d}x_0}
	{\int_{x_0} p_{X_0 \mymid \overline{X}_\tau}(x_0 \mymid x_{\tau}^{\star})\exp(\Delta)\mathrm{d}x_0}\right),\label{eq1}
\end{align}
%\begin{align*}
%\frac{s_{\tau+\delta}^{\star}(x_{\tau+\delta}^{\star})}{(1-\tau-\delta)^{3/2}}
%&= \frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - \frac{x_{\tau+\delta}^{\star}}{\sqrt{1-\tau-\delta}} 
%-\frac{1}{(\tau+\delta)(1-\tau-\delta)}
%\frac{\int_{x_0} p_{X_0 \mymid X_\tau}(x_0 \mymid x_{\tau}^{\star})\exp(\Delta)\big(\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\big)\mathrm{d}x_0}
%{\int_{x_0} p_{X_0 \mymid X_\tau}(x_0 \mymid x_{\tau}^{\star})\exp(\Delta)\mathrm{d}x_0},
%\end{align*}
where
\begin{align*}
	\Delta := \frac{(1-\tau)\|x_{\tau}^{\star}/\sqrt{1-\tau} - x_0\|_2^2}{\tau} - \frac{(1-\tau-\delta)\|x_{\tau+\delta}^{\star}/\sqrt{1-\tau-\delta} - x_0\|_2^2}{\tau+\delta}
	=: \sum_{k = 1}^{\infty} \frac{\delta^k}{k!}v_k.
\end{align*}
Here, the last equation of \eqref{eq1} makes use of the Bayes rule.
We prove by induction that for any quantity $\overline{C} \geq 2$,
\begin{subequations}
	\begin{align}
		\|u_k\|_2 &\le c_k \sqrt{\frac{d\theta\log T}{\tau(1-\tau)^3}}\bigg(\frac{d\theta\log T}{\tau(1-\tau)}\bigg)^k, \quad\text{for }k = 0, 1, \ldots, K,\label{ineq9a}\\
		|v_k| &\le C_k\overline{C}^2\bigg(\frac{d\theta\log T}{\tau(1-\tau)}\bigg)^k,
		\quad\text{for }k = 1, \ldots, K, \quad\text{provided that }\Big\|\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\Big\|_2 \leq 5\overline{C}\sqrt{\frac{d\theta\tau\log T}{1-\tau}}.\label{ineq9b}
	\end{align}
\end{subequations}
For $k = 0$, we have 
\begin{align*}
	\|u_0\|_2 &= \left\|\frac{s_{\tau}^{\star}(x_{\tau}^\star)}{(1-\tau)^{3/2}}\right\|_2\\ &= \frac{1}{\tau(1 - \tau)}\left\|\int_{x_0} p_{X_0 \mymid \overline{X}_\tau}(x_0 \mymid x_{\tau}^{\star})\left(\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\right)\mathrm{d}x_0\right\|_2\\
	&= \frac{1}{\tau(1 - \tau)}\int_{x_0} p_{X_0 \mymid \overline{X}_\tau}(x_0 \mymid x_{\tau}^{\star})\left\|\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\right\|\mathrm{d}x_0\\
	&= \frac{1}{\tau(1 - \tau)}\mathbb{E}\left[\left\|\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - X_0\right\|_2\ \bigg|\ \overline{X}_{\tau} = x_{\tau}^{\star}\right]\\
	&\stackrel{\text{Lemma \ref{lemma:tail_bound}}}{\lesssim} \frac{1}{\tau(1 - \tau)}\frac{1}{\sqrt{1-\tau}}\sqrt{d\theta\tau\log T}\\
	&\asymp \sqrt{\frac{d\theta\log T}{\tau(1-\tau)^3}}.
\end{align*}
Suppose that \eqref{ineq9a} and \eqref{ineq9b} hold for $k \leq k_0$. We would like to prove \eqref{ineq9a} and \eqref{ineq9b} for $k = k_0 + 1$. Recalling that
\begin{align*}
	\frac{\partial}{\partial \tau} \frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} = -\frac{1}{2(1-\tau)^{3/2}}s_{\tau}^{\star}(x_{\tau}^{\star}),
\end{align*}
we have
\begin{align*}
	\frac{\partial^k}{\partial \tau^k} \frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} = -\frac{\partial^{k-1}}{\partial \tau^{k-1}}\frac{1}{2(1-\tau)^{3/2}}s_{\tau}^{\star}(x_{\tau}^{\star}).
\end{align*}
Then we know from Taylor expansion that 
\begin{align*}
	\frac{x_{\tau+\delta}^{\star}}{\sqrt{1-\tau-\delta}}-\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}}
	= -\frac{1}{2}\sum_{k = 1}^{\infty} \frac{\delta^k}{k!}u_{k-1}.
\end{align*}
Furthermore, it is straightforward to verify that
\begin{align}\label{eq3}
	\frac{1}{(\tau+\delta)(1-\tau-\delta)}-\frac{1}{\tau(1-\tau)}
	= \sum_{k = 1}^{\infty} \delta^k\big[(1-\tau)^{-k-1} - (-\tau)^{-k-1}\big],
\end{align}
and
\begin{align}\label{eq4}
	&\frac{(1-\tau-\delta)\|x_{\tau+\delta}^{\star}/\sqrt{1-\tau-\delta} - x_0\|_2^2}{\tau+\delta}\notag\\
	&\quad= \Big(\frac{1-\tau}{\tau} - \sum_{k = 1}^{\infty} \delta^k(-\tau)^{-k-1}\Big)\Big\|\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0 + \frac{x_{\tau+\delta}^{\star}}{\sqrt{1-\tau-\delta}}-\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}}\Big\|_2^2\notag\\
	&\quad= \Big(\frac{1-\tau}{\tau} - \sum_{k = 1}^{\infty} \delta^k(-\tau)^{-k-1}\Big)\bigg(\Big\|\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\Big\|_2^2 - \Big(\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\Big)^{\top}\sum_{k = 1}^{\infty} \frac{\delta^k}{k!}u_{k-1} + \frac{1}{4}\Big\|\sum_{k = 1}^{\infty} \frac{\delta^k}{k!}u_{k-1}\Big\|_2^2\bigg).
\end{align}
Then we immediately have
\begin{align*}
	\sum_{k = 1}^{\infty} \frac{\delta^k}{k!}v_k &= \sum_{k=1}^{\infty}\bigg[-(-\tau)^{-k-1}\Big\|\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\Big\|_2^2 - \frac{1}{k!}\frac{1 - \tau}{\tau}\Big(\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\Big)^{\top}u_{k-1}\\ &\hspace{1cm}+ \Big(\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\Big)^{\top}\sum_{\ell = 1}^{k-1}(-\tau)^{-\ell-1}\frac{1}{(k-\ell)!}u_{k - \ell - 1} + \frac{1}{4}\frac{1-\tau}{\tau}\sum_{\ell = 1}^{k - 1}\frac{1}{\ell!(k - \ell)!}u_{\ell - 1}u_{k - \ell - 1}\\&\hspace{1cm} - \sum_{\ell = 1}^{k - 2}\sum_{j = 1}^{k - 1 - \ell}\frac{1}{j!(k-\ell-j)!}(-\tau)^{-\ell - 1}u_{j - 1}u_{k - \ell - j - 1}\bigg]\delta^k 
\end{align*}
for sufficiently small $\delta > 0$.
Comparing the coefficients of $\delta^{k_0 + 1}$ on both sides and making use of the induction assumption, one has 
\begin{align*}
	|v_{k_0 + 1}| &\leq \tau^{-k_0}\Big\|\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\Big\|_2^2 + \frac{1}{(k_0 + 1)!}\frac{1 - \tau}{\tau}\Big\|\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\Big\|_2\|u_{k_0}\|_2\\
	&\quad + \Big\|\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\Big\|_2\sum_{\ell = 1}^{k_0}\tau^{-\ell-1}\frac{1}{(k_0+1-\ell)!}u_{k_0 - \ell}\\
	&\quad + \frac{1}{4}\sum_{\ell = 1}^{k_0}\frac{1}{\ell!(k_0+1 - \ell)!}u_{\ell-1}u_{k_0 - \ell} + \sum_{\ell = 1}^{k_0 - 1}\sum_{j = 1}^{k_0 - \ell}\frac{1}{j!(k_0+1-\ell-j)!}\tau^{-\ell - 1}u_{j - 1}u_{k_0 - \ell - j}\\
	&\lesssim \tau^{k_0}\overline{C}^2\frac{d\theta\tau\log T}{1 - \tau} + \frac{1 - \tau}{\tau}\overline{C}\sqrt{\frac{d\theta\tau\log T}{1-\tau}}\sqrt{\frac{d\theta\log T}{\tau(1-\tau)^3}}\bigg(\frac{d\theta\log T}{\tau(1-\tau)}\bigg)^{k_0}\\&\quad + \overline{C}\sqrt{\frac{d\theta\tau\log T}{1-\tau}}\sum_{\ell = 1}^{k_0}\tau^{-\ell-1}\sqrt{\frac{d\theta\log T}{\tau(1-\tau)^3}}\bigg(\frac{d\theta\log T}{\tau(1-\tau)}\bigg)^{k_0 - \ell}\\&\quad + \frac{1-\tau}{\tau}\sum_{\ell = 1}^{k_0}\sqrt{\frac{d\theta\log T}{\tau(1-\tau)^3}}\bigg(\frac{d\theta\log T}{\tau(1-\tau)}\bigg)^{\ell - 1}\sqrt{\frac{d\theta\log T}{\tau(1-\tau)^3}}\bigg(\frac{d\theta\log T}{\tau(1-\tau)}\bigg)^{k_0 - \ell}\\
	&\quad + \sum_{\ell = 1}^{k_0 - 1}\sum_{j = 1}^{k_0 - \ell}\tau^{-\ell - 1}\sqrt{\frac{d\theta\log T}{\tau(1-\tau)^3}}\bigg(\frac{d\theta\log T}{\tau(1-\tau)}\bigg)^{j - 1}\sqrt{\frac{d\theta\log T}{\tau(1-\tau)^3}}\bigg(\frac{d\theta\log T}{\tau(1-\tau)}\bigg)^{k_0-\ell-j}\\
	&\lesssim \overline{C}^2\bigg(\frac{d\theta\log T}{\tau(1-\tau)}\bigg)^{k_0+1},
\end{align*}
provided that $\|\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\|_2 \leq 5\overline{C}\sqrt{\frac{d\theta\tau\log T}{1-\tau}}$. Therefore, we have verified \eqref{ineq9b} for $k = k_0 + 1$.

Then, we prove that \eqref{ineq9a} holds for $k = k_0 + 1$. We let $e^\Delta =: \sum_{k = 0}^{\infty}\frac{\delta^k}{k!}w_k = \sum_{k = 0}^{\infty}\frac{\delta^k}{k!}w_k(x_0)$ denote the Taylor expansion of $e^\Delta$. Then one can show that $w_0 = 1$ and for all $1 \leq k \leq k_0+1$,
\begin{align}\label{ineq10}
	|w_k| = \bigg|\sum_{\ell = 1}^{k}\sum_{j_1 + \cdots + j_{\ell} = k}\frac{k!}{j_1!\cdots j_\ell!}v_{j_1}\cdots v_{j_\ell}\bigg| \lesssim \overline{C}^{2k}\bigg(\frac{d\theta\log T}{\tau(1-\tau)}\bigg)^{k},
\end{align}
provided that $\|\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\|_2 \leq 5\overline{C}\sqrt{\frac{d\theta\tau\log T}{1-\tau}}$.

We define
\begin{align*}
	\mathcal{C}_0 &= \left\{x_0 \in \mathbb{R}^d: \Big\|\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\Big\|_2 \leq 5c_7\sqrt{\frac{d\theta\tau\log T}{1-\tau}}\right\},\\
	\mathcal{C}_\ell &= \left\{x_0 \in \mathbb{R}^d: 5\cdot 2^{\ell-1}c_7\sqrt{\frac{d\tau\log T}{1-\tau}} < \Big\|\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\Big\|_2 \leq 5\cdot 2^{\ell}c_7\sqrt{\frac{d\theta\tau\log T}{1-\tau}}\right\},\quad k \geq 1.
\end{align*}
where $c_7$ is a sufficiently large constant.
Let $a_k$ (resp.~$b_k$) denote the $k$-th order derivative\\$\frac{\partial^k}{\partial \tau^k}\int_{x_0} p_{X_0 \mymid \overline{X}_\tau}(x_0 \mymid x_{\tau}^{\star})\exp(\Delta)\big(\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\big)\mathrm{d}x_0$ (resp.~$\frac{\partial^k}{\partial \tau^k}\int_{x_0} p_{X_0 \mymid \overline{X}_\tau}(x_0 \mymid x_{\tau}^{\star})\exp(\Delta)\mathrm{d}x_0$). Then for $0 \leq k \leq k_0 + 1$,
\begin{align*}
	\|a_k\|_2&= \Big\|\int_{x_0} p_{X_0 \mymid \overline{X}_\tau}(x_0 \mymid x_{\tau}^{\star})\Big(\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\Big)w_k\mathrm{d}x_0\Big\|_2\\
	&= \Big\|\sum_{\ell=0}^{\infty}\int_{x_0 \in \mathcal{C}_\ell} p_{X_0 \mymid \overline{X}_\tau}(x_0 \mymid x_{\tau}^{\star})\Big(\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\Big)w_k\mathrm{d}x_0\Big\|_2\\
	&\leq \Big\|\int_{x_0 \in \mathcal{C}_0} p_{X_0 \mymid \overline{X}_\tau}(x_0 \mymid x_{\tau}^{\star})\Big(\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\Big)w_k\mathrm{d}x_0\Big\|_2\\
	&\quad + \sum_{\ell=1}^{\infty}\Big\|\int_{x_0 \in \mathcal{C}_\ell} p_{X_0 \mymid \overline{X}_\tau}(x_0 \mymid x_{\tau}^{\star})\Big(\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\Big)w_k\mathrm{d}x_0\Big\|_2\\
	&\leq \sup_{x_0 \in \mathcal{C}_0}\Big\|\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\Big\|_2\|w_k\|_2\\&\quad + \sum_{\ell=1}^{\infty}\mathbb{P}\left(\Big\|\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - X_0\Big\|_2 \leq 5\cdot 2^\ell c_7\sqrt{\frac{d\theta\tau\log T}{1-\tau}}\ \Big|\ \overline{X}_{\tau} = x_{\tau}^\star\right)\sup_{x_0 \in \mathcal{C}_\ell}\Big\|\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\Big\|_2\|w_k\|_2\\
	&\stackrel{(*)}{\lesssim} 5c_7\sqrt{\frac{d\theta\tau\log T}{1-\tau}}\cdot c_7^{2k}\bigg(\frac{d\theta\log T}{\tau(1-\tau)}\bigg)^{k}\\&\quad + \sum_{\ell=1}^{\infty}\exp\left(-2^{2\ell}c_7^2d\theta\log T\right)\cdot 2^{\ell}c_7\sqrt{\frac{d\theta\tau\log T}{1-\tau}}\cdot (5\cdot2^\ell c_7)^{2k}\bigg(\frac{d\theta\log T}{\tau(1-\tau)}\bigg)^{k}\\
	&\lesssim \sqrt{\frac{d\theta\tau\log T}{1-\tau}}\bigg(\frac{d\theta\log T}{\tau(1-\tau)}\bigg)^{k} + \sum_{\ell = 1}^\infty\exp\left(-2^{\ell}c_7^2d\theta\log T\right)\sqrt{\frac{d\theta\tau\log T}{1-\tau}}\bigg(\frac{d\theta\log T}{\tau(1-\tau)}\bigg)^{k}\\
	&\asymp \sqrt{\frac{d\theta\tau\log T}{1-\tau}}\bigg(\frac{d\theta\log T}{\tau(1-\tau)}\bigg)^{k},
\end{align*}
and more specifically,
\begin{align*}
	a_0 = \int_{x_0} p_{X_0 \mymid \overline{X}_\tau}(x_0 \mymid x_{\tau}^{\star})\Big(\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\Big)w_0\mathrm{d}x_0 = \int_{x_0} p_{X_0 \mymid \overline{X}_\tau}(x_0 \mymid x_{\tau}^{\star})\Big(\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\Big)\mathrm{d}x_0.
\end{align*}
Here, $(*)$ is valid due to Lemma \ref{lemma:tail_bound} and \eqref{ineq10}.
Similarly, for all $1 \leq k \leq k_0+1$, one can show that
\begin{align*}
	b_0 = 1,~\quad~\text{and}~\quad~|b_k| \lesssim \bigg(\frac{d\theta\log T}{\tau(1-\tau)}\bigg)^{k},\quad \forall 1 \leq k \leq k_0 + 1.
\end{align*}
We denote by $$d_k:= \frac{\partial^k}{\partial \tau^k}\frac{\int_{x_0} p_{X_0 \mymid \overline{X}_\tau}(x_0 \mymid x_{\tau}^{\star})\exp(\Delta)\big(\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\big)\mathrm{d}x_0}
{\int_{x_0} p_{X_0 \mymid \overline{X}_\tau}(x_0 \mymid x_{\tau}^{\star})\exp(\Delta)\mathrm{d}x_0}$$ the $k$-th derivative of $\frac{\int_{x_0} p_{X_0 \mymid \overline{X}_\tau}(x_0 \mymid x_{\tau}^{\star})\exp(\Delta)\big(\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\big)\mathrm{d}x_0}
{\int_{x_0} p_{X_0 \mymid \overline{X}_\tau}(x_0 \mymid x_{\tau}^{\star})\exp(\Delta)\mathrm{d}x_0}$. Then one can easily verify that
\begin{subequations}
	\begin{align}
		d_0 &= \int_{x_0} p_{X_0 \mymid \overline{X}_\tau}(x_0 \mymid x_{\tau}^{\star})\Big(\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\Big)\mathrm{d}x_0,\label{ineq11a}\\
		|d_k| &= |a_k - \sum_{\ell = 0}^{k-1}d_\ell b_{k-\ell}| \lesssim \sqrt{\frac{d\theta\tau\log T}{1-\tau}}\bigg(\frac{d\theta\log T}{\tau(1-\tau)}\bigg)^{k},\quad\text{for all}~0 \leq k \leq k_0+1.\label{ineq11b}
	\end{align}
\end{subequations}
Now, we are ready to prove \eqref{ineq9b} for $t = t_0 + 1$. In view of \eqref{eq1} and \eqref{eq2}, one has
\begin{align}
	\sum_{k = 1}^{\infty}\frac{\delta^k}{k!}u_k &=\frac{s_{\tau+\delta}^{\star}(x_{\tau+\delta}^{\star})}{(1-\tau-\delta)^{3/2}} - \frac{s_{\tau}^{\star}(x_{\tau}^{\star})}{(1-\tau)^{3/2}}\notag\\
	&= -\frac{1}{(\tau+\delta)(1-\tau-\delta)}\left(\frac{x_{\tau+\delta}^{\star}}{\sqrt{1-\tau-\delta}} - \frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} + \frac{\int_{x_0} p_{X_0 \mymid \overline{X}_\tau}(x_0 \mymid x_{\tau}^{\star})\exp(\Delta)\big(\frac{x_{\tau}^{\star}}{\sqrt{1-\tau}} - x_0\big)\mathrm{d}x_0}
	{\int_{x_0} p_{X_0 \mymid \overline{X}_\tau}(x_0 \mymid x_{\tau}^{\star})\exp(\Delta)\mathrm{d}x_0}\right)\notag\\&\quad + \frac{1}{\tau(1-\tau)}\int_{x_0} p_{X_0 \mymid \overline{X}_\tau}(x_0 \mymid \sqrt{1-\tau}x)(x - x_0)\mathrm{d}x_0\notag\\
	&=-\left(\frac{1}{\tau(1-\tau)} + \sum_{k = 1}^{\infty} \delta^k\big[(1-\tau)^{-k-1} - (-\tau)^{-k-1}\big]\right)\left(-\frac{1}{2}\sum_{k = 1}^{\infty} \frac{\delta^k}{k!}u_{k-1} + \sum_{k = 0}^{\infty} \frac{\delta^k}{k!}d_{k}\right) + \frac{1}{\tau(1-\tau)}d_0\notag\\
	&= \sum_{k=1}^{\infty}\left(\frac{1}{\tau(1-\tau)}\frac{u_{k-1}-2d_k}{2k!} + \sum_{\ell=1}^{k}\big[(-\tau)^{-\ell-1}-(1-\tau)^{-\ell-1}\big]\frac{2d_{k-\ell}-u_{k-1-\ell}}{2(k-\ell)!}\right)\delta^k.
\end{align}
By virtue of the induction hypothesis \eqref{ineq9a} for $1 \leq k \leq k_0$ and \eqref{ineq11b}, we have
\begin{align*}
	|u_{k_0+1}| &= \left|\frac{1}{\tau(1-\tau)}\left(\frac{u_{k_0}}{2} - d_{k_0+1}\right) + \sum_{\ell=1}^{k_0+1}\big[(-\tau)^{-\ell-1}-(1-\tau)^{-\ell-1}\big]\frac{(k_0+1)!}{2(k_0+1-\ell)!}\left(2d_{k_0+1-\ell}-u_{k_0-\ell}\right)\right|\\
	&\lesssim \frac{1}{\tau(1-\tau)}\left(\sqrt{\frac{d\theta\log T}{\tau(1-\tau)^3}}\bigg(\frac{d\theta\log T}{\tau(1-\tau)}\bigg)^{k_0} + \sqrt{\frac{d\theta\tau\log T}{1-\tau}}\bigg(\frac{d\theta\log T}{\tau(1-\tau)}\bigg)^{k_0+1}\right)\\&\quad + \sum_{\ell = 1}^{k_0+1}\frac{1}{[\tau(1-\tau)]^{\ell+1}}\left[\sqrt{\frac{d\theta\tau\log T}{1-\tau}}\bigg(\frac{d\theta\log T}{\tau(1-\tau)}\bigg)^{k_0+1-\ell}+\sqrt{\frac{d\theta\log T}{\tau(1-\tau)^3}}\bigg(\frac{d\theta\log T}{\tau(1-\tau)}\bigg)^{k_0-\ell}\right]\\
	&\asymp \sqrt{\frac{d\theta\log T}{\tau(1-\tau)^3}}\bigg(\frac{d\theta\log T}{\tau(1-\tau)}\bigg)^{k_0+1},
\end{align*}
which has finished the proof of the induction step. Therefore, we have verified Claim \eqref{eq:derivative_1}. 

Claim \eqref{eq:derivative_2} can be proved by using similar arguments. We omit the details here for the sake of brevity.

