\section{Proofs of technical lemmas}
\subsection{Proof of Lemma \ref{lemma:learning_rate}}\label{sec:proof_lemma_learning_rate}
Equations \eqref{ineq:learning_rate_a} - \eqref{ineq:learning_rate_e} follow directly from \citet[(26a) - (26e)]{li2024sharp}.
\paragraph{Proof of \eqref{ineq:learning_rate_f}.} For any $2 \leq t \leq T, 0 \leq i_1, i_2, i_3, i_4 \leq K - 1$, one has
\begin{align*}
	\Big|\frac{\tau_{t, i_1} - \tau_{t, i_2}}{\tau_{t, i_3}(1-\tau_{t, i_4})}\Big| \leq \frac{\tau_{t,0} - \tau_{t,k-1}}{\tau_{t,k-1}\left(1 - \tau_{t,0}\right)} = \frac{\overline{\alpha}_{t-1} - \overline{\alpha}_{t}}{\overline{\alpha}_{t}\left(1 - \overline{\alpha}_{t-1}\right)} = \frac{1}{\alpha_t}\frac{1 - \alpha_t}{1 - \overline{\alpha}_{t-1}} \stackrel{\eqref{ineq:learning_rate_a}~\text{and}~\eqref{ineq:learning_rate_b}}{\leq} 2\cdot\frac{4c_1\log T}{T} = \frac{8c_1\log T}{T}.
\end{align*}
\paragraph{Proof of \eqref{ineq:learning_rate_g}.} By virtue of \eqref{def:gamma}, one has 
\begin{align*}
	\left|\gamma_{t, i}(\tau_{t,j})\right| \leq \left(\tau_{t,0} - \tau_{t,j}\right)\sup_{\tau \in [\tau_{t,K-1}, \tau_{t,0}]}\left|\psi_i(\tau)\right|.
\end{align*}
We observe that 
\begin{align*}
	\sup_{\tau \in [\tau_{t,K-1}, \tau_{t,0}]}\left|\psi_i(\tau)\right| = \sup_{\eta \in [0,K-1]}\left|\frac{\prod_{i' \neq i}(K-1-i'-\eta)}{\prod_{i' \neq i}(i-i')}\right| \leq \frac{(K-1)!}{\left(\lfloor\frac{K-1}{2}\rfloor\right)!\left(\lfloor\frac{K-1}{2}\rfloor\right)!} = \binom{K-1}{\lfloor\frac{K-1}{2}\rfloor} \leq 2^{K}.
\end{align*}
Putting the previous two inequalities together, we have completed the proof of \eqref{ineq:learning_rate_g}.
\paragraph{Proof of \eqref{ineq:learning_rate_h}.} For all $0 \leq i \leq K-1, 2 \leq t \leq T$, one has
\begin{align*}
	\overline{\alpha}_{t} = 1 - \tau_{t,0} \leq 1 - \tau_{t,i} \leq 1 - \tau_{t,K-1} = \overline{\alpha}_{t-1}~\quad~\text{and}~\quad~1 - \overline{\alpha}_{t-1} = \tau_{t,K-1} \leq \tau_{t,i} \leq \tau_{t,0} = 1 - \overline{\alpha}_{t}.
\end{align*}
Therefore, it suffices to show that 
\begin{align*}
	\overline{\alpha}_{t} \asymp \overline{\alpha}_{t-1}~\quad~\text{and}~\quad~1 - \overline{\alpha}_{t-1} \asymp 1 - \overline{\alpha}_{t},
\end{align*}
which are direct consequences of \eqref{ineq:learning_rate_a} and \eqref{ineq:learning_rate_c}, respectively.

\subsection{Proof of Lemma \ref{lemma:Hessian}}\label{sec:proof_lemma_Hessian}
Elementary calculations reveal that
\begin{align*}
	\left\|s_{\tau}^{\star}(x)\right\|_2 &= \frac{\sqrt{1 - \tau}}{\tau}\left\|\int_{x_0} p_{X_0 \mymid \overline{X}_\tau}(x_0 \mymid x)\left(\frac{x}{\sqrt{1-\tau}} - x_0\right)\mathrm{d}x_0\right\|_2\\
	&= \frac{\sqrt{1 - \tau}}{\tau}\int_{x_0} p_{X_0 \mymid \overline{X}_\tau}(x_0 \mymid x)\left\|\frac{x}{\sqrt{1-\tau}} - x_0\right\|\mathrm{d}x_0\\
	&= \frac{\sqrt{1 - \tau}}{\tau}\mathbb{E}\left[\left\|\frac{x}{\sqrt{1-\tau}} - X_0\right\|_2\ \bigg|\ \overline{X}_{\tau} = x\right]\\
	&\stackrel{\text{Lemma \ref{lemma:tail_bound}}}{\lesssim} \frac{\sqrt{1 - \tau}}{\tau}\frac{1}{\sqrt{1-\tau}}\sqrt{d\theta_{\tau}(x)\tau\log T}\\
	&\asymp \sqrt{\frac{d\theta_{\tau}(x)\log T}{\tau}},
\end{align*}
which has finished the proof of \eqref{score_1}.

Turning to \eqref{score_2}, by virtue of (24) and (25b) in \cite{li2024sharp}, we have
\begin{align}\label{ineq8}
	\frac{\partial s_{\tau}^\star(x_{\tau})}{\partial x} = -\frac{1}{\tau}I_d + \frac{1}{\tau^2}{\sf Cov}\left(\overline{X}_{\tau} - \sqrt{1 - \tau}X_0\ |\ \overline{X}_{\tau} = x\right).
\end{align}
We make the observation that
\begin{align*}
	\left\|{\sf Cov}\left(\overline{X}_{\tau} - \sqrt{1 - \tau}X_0\ |\ \overline{X}_{\tau} = x\right)\right\|
	&\quad \leq \left\|\mathbb{E}\left[\left(x - \sqrt{1 - \tau}X_0\right)\left(x - \sqrt{1 - \tau}X_0\right)^\top\ |\ \overline{X}_{\tau} = x\right]\right\|\\
	&\quad \leq \mathbb{E}\left[\left\|x - \sqrt{1 - \tau}X_0\right\|_2^2\ |\ \overline{X}_{\tau} = x\right]\\
	&\quad \lesssim d\theta_{\tau}(x)\tau\log T.
\end{align*}
Here, the last line holds due to Lemma \ref{lemma:tail_bound}. Then we immediately have
\begin{align*}
	\left\|\frac{\partial s_{\tau}^\star(x_{\tau})}{\partial x}\right\| \lesssim \frac{1}{\tau} + \frac{1}{\tau^2}d\theta_{\tau}(x)\tau\log T \asymp \frac{d\theta_{\tau}(x)\log T}{\tau}.
\end{align*}

Eqn. \eqref{score_derivative_difference} follows by an argument similar to that of \citet[Claim (89)]{li2024provable}; we omit the details for brevity.

\subsection{Proof of Lemma \ref{lemma:log_density}}\label{proof:Lemma_log_density}
We let $J_{\tau}$ denote the Jacobian matrix
\begin{align}
	J_{\tau}(\sqrt{1-\tau}x) &:= \frac{\partial}{\partial x}\frac{s_{\tau}^\star(\sqrt{1-\tau}x)}{(1-\tau)^{3/2}}\notag\\
	&= -\frac{1}{\tau(1-\tau)}I_d + \frac{1}{\tau^2}\Big(\mathbb{E}\big[(x-X_0)(x-X_0)^\top~\big |~\overline{X}_{\tau} = \sqrt{1-\tau}x\big]\notag\\&\hspace{3.5cm}- \mathbb{E}\big[x-X_0~\big |~\overline{X}_{\tau} = -\sqrt{1-\tau}x\big]\mathbb{E}\big[x-X_0~\big |~\overline{X}_{\tau} = \sqrt{1-\tau}x\big]^\top\Big).\label{def:Jacobian}
\end{align}
We define
\begin{align*}
	\theta' = \sup_{\tau': |\tau'-\widetilde\tau| \leq c_0\widetilde\tau(1-\widetilde\tau)}\frac{-\log p_{\overline{X}_{\tau'}}(x_{\tau'}^\star)}{d\log T} < \infty.
\end{align*}
By virtue of Lemma \ref{lemma:tail_bound}, we have
\begin{align}\label{ineq19}
	\mathsf{tr}\left(J_{\tau}(x_{\tau}^\star)\right) &\leq -\frac{d}{\tau(1-\tau)} + \frac{1}{\tau^2(1-\tau)}\mathsf{tr}\left(\mathbb{E}\big[(x_{\tau}^\star-\sqrt{1-\tau}X_0)(x_{\tau}^\star-\sqrt{1-\tau}X_0)^\top~\big |~\overline{X}_{\tau} = x_{\tau}^\star\big]\right)\notag\\
	&= -\frac{d}{\tau(1-\tau)} + \frac{1}{\tau^2(1-\tau)}\mathbb{E}\left[\left\|x_{\tau}^\star-\sqrt{1-\tau}X_0\right\|_2^2~\big |~\overline{X}_{\tau} = x_{\tau}^\star\right]\notag\\
	&\leq -\frac{d}{\tau(1-\tau)} + \frac{120}{\tau^2(1-\tau)}\theta'd\tau\log T \leq \frac{120}{\tau(1-\tau)}\theta'd\log T.
\end{align}
In addition, \eqref{eq:ODE}tells us that 
\begin{align}\label{eq:relation_initial}
	\frac{\partial}{\partial\tau}\frac{\partial x_{\tau}^\star/\sqrt{1-\tau}}{\partial x_{\tau'}^\star/\sqrt{1-\tau'}} &= \frac{\partial}{\partial x_{\tau'}^\star/\sqrt{1-\tau'}}\frac{\partial x_{\tau}^\star/\sqrt{1-\tau}}{\partial\tau}\notag\\
	&= \frac{\partial}{\partial x_{\tau}^\star/\sqrt{1-\tau}}\left(-\frac{1}{2(1-\tau)^{3/2}}s_{\tau}^{\star}(x_\tau^{\star})\right)\notag\\
	&= \frac{\partial}{\partial x_{\tau'}^\star/\sqrt{1-\tau'}}\left(-\frac{1}{2(1-\tau)^{3/2}}s_{\tau}^{\star}(x_\tau^{\star})\right)\frac{\partial x_{\tau}^\star/\sqrt{1-\tau}}{\partial x_{\tau'}^\star/\sqrt{1-\tau'}}\notag\\
	&= -\frac{1}{2}J_{\tau}\left(x_{\tau}^\star\right)\frac{\partial x_{\tau}^\star/\sqrt{1-\tau}}{\partial x_{\tau'}^\star/\sqrt{1-\tau'}}.
\end{align}
Applying Jacobi's formula
\begin{align*}
	\frac{{\rm d}}{{\rm d}t}\det A(t) = (\det A(t))\cdot{\rm tr}\left(A(t)^{-1}\cdot \frac{{\rm d}A(t)}{{\rm d}t}\right)
\end{align*}
yields
\begin{align}\label{eq7}
	\frac{\partial}{\partial\tau}\det\left(\frac{\partial x_{\tau}^\star/\sqrt{1-\tau}}{\partial x_{\tau'}^\star/\sqrt{1-\tau'}}\right) &= \det \left(\frac{\partial x_{\tau}^\star/\sqrt{1-\tau}}{\partial x_{\tau'}^\star/\sqrt{1-\tau'}}\right)\cdot{\rm tr}\left(\left(\frac{\partial x_{\tau}^\star/\sqrt{1-\tau}}{\partial x_{\tau'}^\star/\sqrt{1-\tau'}}\right)^{-1}\cdot	\frac{\partial}{\partial\tau}\frac{\partial x_{\tau}^\star/\sqrt{1-\tau}}{\partial x_{\tau'}^\star/\sqrt{1-\tau'}}\right)\notag\\
	&= -\frac{1}{2}{\rm tr}\left(J_{\tau}\left(x_{\tau}^\star\right)\right)\det \left(\frac{\partial x_{\tau}^\star/\sqrt{1-\tau}}{\partial x_{\tau'}^\star/\sqrt{1-\tau'}}\right).
\end{align}
By solving this equation, we know that
\begin{align}\label{eq8}
	\det\left(\frac{\partial x_{\tau''}^\star/\sqrt{1-\tau''}}{\partial x_{\tau'}^\star/\sqrt{1-\tau'}}\right) = \exp\left(-\frac{1}{2}\int_{\tau'}^{\tau''}{\rm tr}\left(J_{\tau}\left(x_{\tau}^\star\right)\right){\rm d}\tau\right)
\end{align} 
for all $\tau', \tau''$. In view of \eqref{ineq19} and \eqref{eq7}, one has
\begin{align}\label{ineq20}
	%\frac{{\rm d}}{{\rm d}\tau'}\log p_{X_{\tau'}/\sqrt{1-\tau'}}\left(x_{\tau'}^\star/\sqrt{1-\tau'}\right) &= 
	\frac{{\rm d}}{{\rm d}\tau'}\bigg(\log \frac{p_{\overline{X}_{\tau'}/\sqrt{1-\tau'}}\left(x_{\tau'}^\star/\sqrt{1-\tau'}\right)}{p_{\overline{X}_{\widetilde\tau}/\sqrt{1-\widetilde\tau}}\left(x_{\widetilde\tau}^\star/\sqrt{1-\widetilde\tau}\right)}\bigg) = -\frac{{\rm d}}{{\rm d}\tau'}\log \det\left(\frac{\partial x_{\tau'}^\star/\sqrt{1-\tau'}}{\partial x_{\widetilde\tau}^\star/\sqrt{1-\widetilde\tau}}\right) = \frac{1}{2}{\rm tr}\left(J_{\tau'}\left(x_{\tau'}^\star\right)\right).
\end{align}
Moreover, recognizing that for all $|\tau'-\widetilde{\tau}| \leq c_0\widetilde{\tau}(1-\widetilde{\tau})$,
\begin{align*}
	\left|\frac{1}{\tau'(1-\tau')} - \frac{1}{\widetilde{\tau}(1-\widetilde{\tau})}\right| = \frac{\left|(\tau'-\widetilde{\tau})(1-\tau'-\widetilde{\tau})\right|}{\tau'(1-\tau')\widetilde{\tau}(1-\widetilde{\tau})} \leq \frac{c_0\widetilde{\tau}(1-\widetilde{\tau})}{\tau'(1-\tau')\widetilde{\tau}(1-\widetilde{\tau})} = \frac{c_0}{\tau'(1-\tau')},
\end{align*}
we have
\begin{align*}
	\frac{1}{\tau'(1-\tau')} \leq \frac{1}{1-c_0}\frac{1}{\widetilde{\tau}(1-\widetilde{\tau})} \leq \frac{2}{\widetilde{\tau}(1-\widetilde{\tau})}.
\end{align*}
Combining \eqref{ineq19}, \eqref{ineq20} and the previous inequality gives us 
\begin{align*}
	-\log p_{\overline{X}_{\tau'}/\sqrt{1-\tau'}}\big(x_{\tau'}^\star/\sqrt{1-\tau'}\big) \leq -\log p_{\overline{X}_{\widetilde\tau}/\sqrt{1-\widetilde\tau}}\big(x_{\widetilde\tau}^\star/\sqrt{1-\widetilde\tau}\big) + |\tau' - \widetilde{\tau}|\frac{120}{\tau(1-\tau)}\theta'd\log T.
\end{align*}
Furthermore, by noting that $p_{\overline{X}_{\tau}/\sqrt{1-\tau}}(x_{\tau}^\star/\sqrt{1-\tau}) = (1-\tau)^{d/2}p_{\overline{X}_{\tau}}(x_{\tau}^\star)$, we have
\begin{align*}
	-\log p_{\overline{X}_{\tau'}}(x_{\tau'}^\star) &\leq -\log p_{\overline{X}_{\widetilde\tau}}(x_{\widetilde\tau}^\star) + d\log\left(\frac{1-\tau'}{1-\widetilde{\tau}}\right) + |\tau' - \widetilde{\tau}|\frac{120}{\tau(1-\tau)}\theta'd\log T\\
	&\leq -\log p_{\overline{X}_{\widetilde\tau}}(x_{\widetilde\tau}^\star) + d\frac{|\tau'-\widetilde{\tau}|}{1-\widetilde{\tau}} + 60c_0\theta'd\log T\\
	&\leq \theta d\log T + c_0d\tau + 60c_0\theta'd\log T\\
	&\leq \theta d\log T + \frac{1}{2}\theta'd\log T,
\end{align*}
provided that $|\tau'-\widetilde{\tau}| \leq c_0\widetilde{\tau}(1-\widetilde{\tau})$. Here, the second inequality makes use of $\log(1+x) \leq x$. Recalling the definition of $\theta'$, we know that
\begin{align*}
	\theta'd\log T = \sup_{\tau': |\tau'-\widetilde\tau| \leq c_0\widetilde\tau(1-\widetilde\tau)}-\log p_{\overline{X}_{\tau'}}(x_{\tau'}^\star) \leq \theta d\log T + \frac{1}{2}\theta'd\log T,
\end{align*}
which implies
\begin{align*}
	\theta' \leq 2\theta.
\end{align*}
Therefore, for all $|\tau'-\widetilde{\tau}| \leq c_0\widetilde{\tau}(1-\widetilde{\tau})$, we have
\begin{align*}
	-\log p_{\overline{X}_{\tau'}}(x_{\tau'}^\star) \leq 2\theta d\log T,
\end{align*}
which has finished the proof of Lemma \ref{lemma:log_density}.

\subsection{Proof of Lemma \ref{lemma:density_ratio_1}}\label{sec:proof_lemma_density_ratio_1}
In addition, elementary calculations show that
\begin{align*}
	\frac{p_{\sqrt{\alpha_t}X_{t-1}}(\sqrt{\alpha_t}x_{t-1})}{p_{\sqrt{\alpha_t}X_{t-1}}(\sqrt{\alpha_t}x_{t-1}^{\star})}
	&= \int_{x_0} p_{X_0\mymid \sqrt{\alpha_t}X_{t-1}}(x_0 | \sqrt{\alpha_t}x_{t-1}^{\star})
	\exp\Big(-\frac{\|x_{t-1} - \sqrt{\overline{\alpha}_{t-1}}x_0\|_2^2 - \|x_{t-1}^{\star} - \sqrt{\overline{\alpha}_{t-1}}x_0\|_2^2}{2(1 - \overline{\alpha}_{t-1})}\Big)
	\mathrm{d}x_0.
\end{align*}
We define $u := x_{t-1} - x_{t-1}^{\star}$. Then we have
\begin{align}\label{ineq17}
	\frac{p_{\sqrt{\alpha_t}X_{t-1}}(\sqrt{\alpha_t}x_{t-1})}{p_{\sqrt{\alpha_t}X_{t-1}}(\sqrt{\alpha_t}x_{t-1}^{\star})}
	&= \int_{x_0} p_{X_0\mymid \sqrt{\alpha_t}X_{t-1}}(x_0 | \sqrt{\alpha_t}x_{t-1}^{\star})\exp\Big(-\frac{\|u\|_2^2 + 2u^\top(x_{t-1}^{\star} - \sqrt{\overline{\alpha}_{t-1}}x_0)}{2(1 - \overline{\alpha}_{t-1})}\Big)\mathrm{d}x_0\notag\\
	&= \exp\Big(-\frac{\|u\|_2^2}{2(1 - \overline{\alpha}_{t-1})}\Big)\int_{x_0} p_{X_0\mymid \sqrt{\alpha_t}X_{t-1}}(x_0 | \sqrt{\alpha_t}x_{t-1}^{\star})\exp\Big(-\frac{u^\top(x_{t-1}^{\star} - \sqrt{\overline{\alpha}_{t-1}}x_0)}{1 - \overline{\alpha}_{t-1}}\Big)\mathrm{d}x_0\notag\\
	&\leq \exp\Big(-\frac{\|u\|_2^2}{2(1 - \overline{\alpha}_{t-1})}\Big)\mathbb{E}\left[\exp\Big(-\frac{u^\top(x_{t-1}^{\star} - \sqrt{\overline{\alpha}_{t-1}}X_0)}{1 - \overline{\alpha}_{t-1}}\Big)~\Big |~X_{t-1} = x_{t-1}^{\star}\right]\notag\\
	&\leq \exp\Big(-\frac{\|u\|_2^2}{2(1 - \overline{\alpha}_{t-1})}\Big)\mathbb{E}\left[\exp\Big(\frac{\|u\|_2\|x_{t-1}^{\star} - \sqrt{\overline{\alpha}_{t-1}}X_0\|_2}{1 - \overline{\alpha}_{t-1}}\Big)~\Big |~X_{t-1} = x_{t-1}^{\star}\right].
\end{align}
By virtue of Lemma \ref{lemma:tail_bound}, one has
\begin{align}\label{ineq21}
	&\mathbb{E}\left[\exp\Big(\frac{\|u\|_2\|x_{t-1}^{\star} - \sqrt{\overline{\alpha}_{t-1}}X_0\|_2}{1 - \overline{\alpha}_{t-1}}\Big)~\Big |~X_{t-1} = x_{t-1}^{\star}\right]\notag\\
	&\quad=\int_{0}^{\infty}\mathbb{P}\left(\exp\Big(\frac{\|u\|_2\|x_{t-1}^{\star} - \sqrt{\overline{\alpha}_{t-1}}X_0\|_2}{1 - \overline{\alpha}_{t-1}}\Big) > w~\Big |~X_{t-1} = x_{t-1}^{\star}\right){\rm d}w\notag\\
	&\quad=1 + \int_{1}^{\infty}\mathbb{P}\left(\exp\Big(\frac{\|u\|_2\|x_{t-1}^{\star} - \sqrt{\overline{\alpha}_{t-1}}X_0\|_2}{1 - \overline{\alpha}_{t-1}}\Big) > w~\Big |~X_{t-1} = x_{t-1}^{\star}\right){\rm d}w\notag\\
	&\quad\stackrel{v = \frac{\sqrt{1 - \overline{\alpha}_{t-1}}\log w}{\|u\|_2}}{=}1 + \int_{0}^{\infty}e^{\frac{\|u\|_2v}{\sqrt{1 - \overline{\alpha}_{t-1}}}}\frac{\|u\|_2}{\sqrt{1 - \overline{\alpha}_{t-1}}}\mathbb{P}\left(\|x_{t-1}^{\star} - \sqrt{\overline{\alpha}_{t-1}}X_0\|_2 > \sqrt{1 - \overline{\alpha}_{t-1}}v~\Big |~X_{t-1} = x_{t-1}^{\star}\right){\rm d}v\notag\\
	&\quad\leq 1 + 5c_5\sqrt{c_6d\log T}\cdot \frac{\|u\|_2}{\sqrt{1 - \overline{\alpha}_{t-1}}}\exp\left(\frac{\|u\|_2\cdot 5c_5\sqrt{c_6d\log T}}{\sqrt{1 - \overline{\alpha}_{t-1}}}\right) + \int_{5c_5\sqrt{c_6d\log T}}^{\infty}e^{\frac{\|u\|_2v}{\sqrt{1 - \overline{\alpha}_{t-1}}}}\frac{\|u\|_2}{\sqrt{1 - \overline{\alpha}_{t-1}}}e^{-\frac{v^2}{25}}{\rm d}v\notag\\
	&\quad\leq 1 + 5c_5\sqrt{c_6d\log T}\cdot \frac{\|u\|_2}{\sqrt{1 - \overline{\alpha}_{t-1}}}\exp\left(\frac{\|u\|_2\cdot 5c_5\sqrt{c_6d\log T}}{\sqrt{1 - \overline{\alpha}_{t-1}}}\right)\notag\\&\qquad + \frac{\|u\|_2}{\sqrt{1 - \overline{\alpha}_{t-1}}}\exp\left(\frac{25\|u\|_2^2}{4(1-\overline{\alpha}_{t-1})}\right)\int_{-\infty}^{\infty}\exp\bigg(-\frac{(v - \frac{25\|u\|_2}{2\sqrt{1 - \overline{\alpha}_{t-1}}})^2}{25}\bigg){\rm d}v\notag\\
	&\quad= 1 + 5c_5\sqrt{c_6d\log T}\cdot \frac{\|u\|_2}{\sqrt{1 - \overline{\alpha}_{t-1}}}\exp\left(\frac{\|u\|_2\cdot 5c_5\sqrt{c_6d\log T}}{\sqrt{1 - \overline{\alpha}_{t-1}}}\right) + 5\sqrt{2\pi}\frac{\|u\|_2}{\sqrt{1 - \overline{\alpha}_{t-1}}}\exp\left(\frac{25\|u\|_2^2}{4(1-\overline{\alpha}_{t-1})}\right)\notag\\
	&\quad\leq \exp\bigg(O\bigg(\frac{\|x_{t-1} - x_{t-1}^{\star}\|_2^2}{1 - \overline{\alpha}_{t-1}} + \sqrt{\frac{d\|x_{t-1} - x_{t-1}^{\star}\|_2^2\log T}{1 - \overline{\alpha}_{t-1}}}\bigg)\bigg).
\end{align}
where the last line holds since $1 + a\exp(b) + c\exp(d) \leq (1+a+c)\exp(\max\{b,d\}) \leq \exp(a+b+c+d)$ for all $a, b , c, d \geq 0$. Combining \eqref{ineq17} and the previous inequality, we have finished the proof of \eqref{ineq18}.

