	&= \frac{p_{\frac{1}{\sqrt{\overline{\alpha}_{t-1}}}Y_{t-1}}\big(\frac{1}{\sqrt{\overline{\alpha}_{t-1}}}x_{t-1}\big)}{p_{\frac{1}{\sqrt{\overline{\alpha}_{t-1}}}Y_{t-1}^\star}\big(\frac{1}{\sqrt{\overline{\alpha}_{t-1}}}x_{t-1}^\star\big)}\\
	&\stackrel{x_{\tau_t,0}=x_{\tau_t,0}^\star}{=} \frac{p_{\frac{1}{\sqrt{1-\tau_{t,K-1}}}Y_{t-1}}\big(\frac{1}{\sqrt{1-\tau_{t,K-1}}}x_{\tau_{t, K-1}^{(N)}}\big)/p_{\frac{1}{\sqrt{1-\tau_{t,0}}}Y_{t}}\big(\frac{1}{1-\tau_{t, 0}}x_{\tau_{t,0}}\big)}{p_{\frac{1}{\sqrt{\overline{\alpha}_{t-1}}}Y_{t-1}^\star}\big(\frac{1}{\sqrt{\overline{\alpha}_{t-1}}}x_{t-1}^\star\big)/p_{\frac{1}{\sqrt{1-\tau_{t,0}}}Y_{t}}\big(\frac{1}{1-\tau_{t, 0}}x_{\tau_{t,0}}^\star\big)}\\
	&= \mathsf{det}\bigg(\frac{\partial x_{\tau_{t, K-1}}^{\star}/\sqrt{1-\tau_{t, K-1}}}{\partial x_{\tau_{t, 0}}^{\star}/\sqrt{1-\tau_{t, 0}}}\bigg) / \mathsf{det}\bigg(\frac{\partial x_{\tau_{t, K-1}}^{(N)}/\sqrt{1-\tau_{t, K-1}}}{\partial x_{\tau_{t, 0}}/\sqrt{1-\tau_{t, 0}}}\bigg)\\
	&= 1 + \frac{\mathsf{det}\bigg(\frac{\partial x_{\tau_{t, K-1}}^{\star}/\sqrt{1-\tau_{t, K-1}}}{\partial x_{\tau_{t, 0}}^{\star}/\sqrt{1-\tau_{t, 0}}}\bigg) - \mathsf{det}\bigg(\frac{\partial x_{\tau_{t, K-1}}^{(N)}/\sqrt{1-\tau_{t, K-1}}}{\partial x_{\tau_{t, 0}}/\sqrt{1-\tau_{t, 0}}}\bigg)}{\mathsf{det}\bigg(\frac{\partial x_{\tau_{t, K-1}}^{(N)}/\sqrt{1-\tau_{t, K-1}}}{\partial x_{\tau_{t, 0}}/\sqrt{1-\tau_{t, 0}}}\bigg)}.
\end{align*}
We know from \citet[Corollary 2.14]{ipsen2008perturbation} that
\begin{align*}
	&\left|\frac{\mathsf{det}\bigg(\frac{\partial x_{\tau_{t, K-1}}^{\star}/\sqrt{1-\tau_{t, K-1}}}{\partial x_{\tau_{t, 0}}^{\star}/\sqrt{1-\tau_{t, 0}}}\bigg) - \mathsf{det}\bigg(\frac{\partial x_{\tau_{t, K-1}}^{(N)}/\sqrt{1-\tau_{t, K-1}}}{\partial x_{\tau_{t, 0}}/\sqrt{1-\tau_{t, 0}}}\bigg)}{\mathsf{det}\bigg(\frac{\partial x_{\tau_{t, K-1}}^{(N)}/\sqrt{1-\tau_{t, K-1}}}{\partial x_{\tau_{t, 0}}/\sqrt{1-\tau_{t, 0}}}\bigg)}\right|\\ &\quad\leq \bigg(\bigg\|\frac{\partial x_{\tau_{t, K-1}}^{(N)}/\sqrt{1-\tau_{t, K-1}}}{\partial x_{\tau_{t, 0}}/\sqrt{1-\tau_{t, 0}}}\bigg\|^{-1}\bigg\|\frac{\partial x_{\tau_{t, K-1}}^{\star}/\sqrt{1-\tau_{t, K-1}}}{\partial x_{\tau_{t, 0}}^{\star}/\sqrt{1-\tau_{t, 0}}}-\frac{\partial x_{\tau_{t, K-1}}^{(N)}/\sqrt{1-\tau_{t, K-1}}}{\partial x_{\tau_{t, 0}}/\sqrt{1-\tau_{t, 0}}}\bigg\| + 1\bigg)^d - 1\\
	&\quad\leq \exp\bigg(d\bigg\|\frac{\partial x_{\tau_{t, K-1}}^{(N)}/\sqrt{1-\tau_{t, K-1}}}{\partial x_{\tau_{t, 0}}/\sqrt{1-\tau_{t, 0}}}\bigg\|^{-1}\bigg\|\frac{\partial x_{\tau_{t, K-1}}^{\star}/\sqrt{1-\tau_{t, K-1}}}{\partial x_{\tau_{t, 0}}^{\star}/\sqrt{1-\tau_{t, 0}}}-\frac{\partial x_{\tau_{t, K-1}}^{(N)}/\sqrt{1-\tau_{t, K-1}}}{\partial x_{\tau_{t, 0}}/\sqrt{1-\tau_{t, 0}}}\bigg\|\bigg) - 1.
\end{align*}
The previous two inequalities together tell us that \eqref{ineq39} holds if $\bigg\|\frac{\partial x_{\tau_{t, K-1}}^{(N)}/\sqrt{1-\tau_{t, K-1}}}{\partial x_{\tau_{t, 0}}/\sqrt{1-\tau_{t, 0}}}\bigg\|^{-1} \lesssim 1$.

\subsection{Proof of Lemma \ref{lemma:log_density_ratio_1}}
We prove Lemma \ref{lemma:log_density_ratio_1} by induction. For notational convenience, we let $\theta_t := \theta_{\tau_{t,0}}(x_{\tau_{t,i}}^{(0)})$. Recalling that $x_{\tau}^\star$ is the solution of ODE \eqref{eq:ODE} at $\tau$ with the initial condition $x_{\tau_{t,0}}^\star = x_{\tau_{t,0}}$, we know from Lemma \ref{lemma:log_density} that $-\log p_{\overline{X}_\tau}(x_{\tau}^\star) \leq 2\theta_td\log T$ for all $\tau_{t,K-1} \leq \tau \leq \tau_{t, 0}$. 
For all $\lambda \in [0,1]$, one can derive
\begin{align*}
	\frac{p_{\overline{X}_{\tau_{t,i}}}\big(\lambda x_{\tau_{t,i}}^{(0)} + (1-\lambda)x_{\tau_{t,i}}^\star\big)}{p_{\overline{X}_{\tau_{t,i}}}(x_{\tau_{t,i}}^\star)}
	&= \exp\Big(-\frac{\|u\|_2^2}{2\tau_{t, i}}\Big)\int_{x_0} p_{X_0 \mymid \overline{X}_{\tau_{t,i}}}\left(x_0 \mymid x_{\tau_{t,i}}^{\star}\right)\exp\Big(-\frac{u^\top(x_{\tau_{t,i}}^\star - \sqrt{1-\tau_{t, i}}x_0)}{\tau_{t, i}}\Big)\mathrm{d}x_0\\
	&\geq \exp\Big(-\frac{\|u\|_2^2}{2\tau_{t, i}}\Big)\mathbb{E}\left[\exp\Big(-\frac{\|u\|_2\|x_{\tau_{t,i}}^\star - \sqrt{1-\tau_{t, i}}X_0\|_2}{\tau_{t, i}}\Big)~\Big |~\overline{X}_{\tau_{t,i}} = x_{\tau_{t,i}}^{\star}\right],
	%\\\quad&= \frac{p_{\sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}X_{\tau_{t,i}}}\Big(\sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}x_{\tau_{t,i}}^{(0)}\Big)}{p_{\sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}X_{\tau_{t,i}}}\Big(\sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}x_{\tau_{t,i}}^\star\Big)}\\
	%\quad&= \exp\Big(-\frac{\|u\|_2^2}{2\tau_{t, i}}\Big)\int_{x_0} p_{X_0~\big |~ \sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}X_{\tau_{t,i}}}\bigg(x_0~\bigg |~ \sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}x_{\tau_{t,i}}^{\star}\bigg)\exp\Big(-\frac{u^\top(x_{t-1}^{\star} - \sqrt{\overline{\alpha}_{t-1}}x_0)}{\tau_{t, i}}\Big)\mathrm{d}x_0
\end{align*}
where $u = \lambda(x_{\tau_{t,i}}^{(0)} - x_{\tau_{t,i}}^\star)$.
In view of \eqref{ineq21} and Jensen's inequality, we know that
\begin{align*}
	&\mathbb{E}\left[\exp\Big(-\frac{\|u\|_2\|x_{\tau_{t,i}}^\star - \sqrt{1-\tau_{t, i}}X_0\|_2}{\tau_{t, i}}\Big)~\Big |~\overline{X}_{\tau_{t,i}} = x_{\tau_{t,i}}^{\star}\right]\\ &\quad \geq \left(\mathbb{E}\left[\exp\Big(\frac{\|u\|_2\|x_{\tau_{t,i}}^\star - \sqrt{1-\tau_{t, i}}X_0\|_2}{\tau_{t, i}}\Big)~\Big |~\overline{X}_{\tau_{t,i}} = x_{\tau_{t,i}}^{\star}\right]\right)^{-1}\\
	&\quad \geq \exp\left(-O\left(\frac{\big\|x_{\tau_{t,i}}^{(0)} - x_{\tau_{t,i}}^\star\big\|_2^2}{\tau_{t,i}} + \sqrt{\frac{d\big\|x_{\tau_{t,i}}^{(0)} - x_{\tau_{t,i}}^\star\big\|_2^2\log T}{\tau_{t,i}}}\right)\right)\\
	&\quad \geq \exp\left(-O\left(\frac{\big\|x_{\tau_{t,i}}^{(0)} - x_{\tau_{t,i}}^\star\big\|_2^2}{1-\overline{\alpha}_{t-1}} + \sqrt{\frac{d\big\|x_{\tau_{t,i}}^{(0)} - x_{\tau_{t,i}}^\star\big\|_2^2\log T}{1 - \overline{\alpha}_{t-1}}}\right)\right).
\end{align*}
where the last line makes use of $1 - \overline{\alpha}_{t-1} \asymp \tau_{t,i}$.
%Repeating similar arguments as in \eqref{ineq18}, one has
%\begin{align}
%	\frac{p_{X_{\tau_{t,i}}}(x_{\tau_{t,i}}^{(0)})}{p_{X_{\tau_{t,i}}}(x_{\tau_{t,i}}^\star)} = \exp\left(O\left(\frac{\big\|x_{\tau_{t,i}}^{(0)} - x_{\tau_{t,i}}^\star\big\|_2^2}{1-\overline{\alpha}_{t-1}} + \sqrt{\frac{d\big\|x_{\tau_{t,i}}^{(0)} - x_{\tau_{t,i}}^\star\big\|_2^2\log T}{1 - \overline{\alpha}_{t-1}}}\right)\right).
%\end{align}
By virtue of \eqref{ineq13}, one has
\begin{align}\label{ineq22}
	\big\|x_{\tau_{t,i}}^{(0)} - x_{\tau_{t,i}}^\star\big\|_2 \lesssim \overline{\alpha}_{t-1}(1-\alpha_t)\frac{1}{\sqrt{1-\overline{\alpha}_{t-1}}}\sqrt{\theta_t d\log T}.
\end{align}
The previous two inequalities together with Lemma \ref{lemma:learning_rate} and \eqref{ineq18} imply that
\begin{align*}
	\left|\log\frac{p_{\overline{X}_{\tau_{t,i}}}\big(\lambda x_{\tau_{t,i}}^{(0)} + (1-\lambda)x_{\tau_{t,i}}^\star\big)}{p_{\overline{X}_{\tau_{t,i}}}(x_{\tau_{t,i}}^\star)}\right| = O\left(\frac{\theta_td\log^3 T}{T^2} + \frac{\sqrt{\theta_t}d\log^2 T}{T}\right) = O\left(\frac{\sqrt{\theta_t}d\log^2 T}{T}\right).
\end{align*}
Therefore, for any $i$ and $\lambda \in [0,1]$, we have
\begin{align}\label{ineq23}
	-\log p_{\overline{X}_{\tau_{t,i}}}\big(\lambda x_{\tau_{t,i}}^{(0)} + (1-\lambda)x_{\tau_{t,i}}^\star\big) \leq 2.1d\theta_t\log T.
\end{align}
Then Lemma \ref{lemma:Hessian} tells us that
\begin{align}\label{ineq24}
	\big\|s_{\tau_{t,i}}^\star\big(\lambda x_{\tau_{t,i}}^{(0)} + (1-\lambda)x_{\tau_{t,i}}^\star\big)\big\| \lesssim \sqrt{\frac{d\theta_t\log T}{\tau_{t,i}}},~\quad~\forall 0 \leq i \leq K-1.
\end{align}
We define
\begin{align*}
	u_{t,i}^{(n)} &:= \sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}x_{\tau_{t,i}}^{(n)} - x_{\tau_{t,0}}\\
	&= \sqrt{1-\tau_{t, 0}}\sum_{0 \le j < K}\gamma_{t, j}(\tau_{t,i})(1-\tau_{t, j})^{-3/2}s_{\tau_{t, j}}(x_{\tau_{t, j}}^{(n-1)}).
\end{align*}
For $n = 1$, recognizing that 
\begin{align*}
	\sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}\overline{X}_{\tau_{t,i}} \stackrel{{\rm d.}}{=} \sqrt{1-\tau_{t,0}}X_0 + \sqrt{\frac{(1-\tau_{t,0})\tau_{t,i}}{1-\tau_{t,i}}}Z,~\quad~\text{where}~Z \sim N(0, I_d),
\end{align*}
one can apply the Bayesian rule to derive
\begin{align*}
	&p_{\sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}\overline{X}_{\tau_{t,i}}}\left(\sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}x_{\tau_{t,i}}^{(1)}\right)\\&\quad = \int_{x_0}p_{X_0}(x_0)p_{\sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}\overline{X}_{\tau_{t,i}}\mymid X_0}\left(\sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}x_{\tau_{t,i}}^{(1)}~\Big |~x_0\right){\rm  d}x_0\\
	&\quad= \int_{x_0}p_{X_0}(x_0)\frac{1}{\left(2\pi\frac{(1-\tau_{t,0})\tau_{t,i}}{1-\tau_{t,i}} \right)^{d/2}}\exp\left(-\frac{\left\|\sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}x_{\tau_{t,i}}^{(1)} - \sqrt{1-\tau_{t,0}}x_0\right\|_2^2}{2\frac{(1-\tau_{t,0})\tau_{t,i}}{1-\tau_{t,i}}}\right){\rm  d}x_0\\
	&\quad= \int_{x_0}p_{X_0}(x_0)\frac{1}{\left(2\pi\frac{(1-\tau_{t,0})\tau_{t,i}}{1-\tau_{t,i}} \right)^{d/2}}\exp\left(-\frac{\left\|\sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}x_{\tau_{t,i}}^{(1)} - \sqrt{1-\tau_{t,0}}x_0\right\|_2^2}{2\frac{(1-\tau_{t,0})\tau_{t,i}}{1-\tau_{t,i}}}\right){\rm  d}x_0\\
	&\quad= \int_{x_0}p_{X_0}(x_0)\frac{1}{\left(2\pi\frac{(1-\tau_{t,0})\tau_{t,i}}{1-\tau_{t,i}} \right)^{d/2}}\exp\left(-\frac{\left\|x_{\tau_{t,0}} - \sqrt{1-\tau_{t,0}}x_0\right\|_2^2}{2\tau_{t,0}}\right)\\
	&\qquad \cdot\exp\left(-\frac{(\tau_{t,0} - \tau_{t, i})\left\|x_{\tau_{t,0}} - \sqrt{1-\tau_{t,0}}x_0\right\|_2^2}{2(1-\tau_{t,0})\tau_{t,0}\tau_{t,i}} -\frac{\big\|u_{t,i}^{(1)}\big\|_2^2 + 2\big<u_{t,i}^{(1)}, x_{\tau_{t,0}} - \sqrt{1-\tau_{t,0}}x_0\big>}{2\frac{(1-\tau_{t,0})\tau_{t,i}}{1-\tau_{t,i}}}\right){\rm  d}x_0.
\end{align*}
Therefore, we can rewrite
\begin{align}\label{ineq25}
	&\frac{p_{\sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}\overline{X}_{\tau_{t,i}}}\left(\sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}x_{\tau_{t,i}}^{(1)}\right)}{p_{\overline{X}_{\tau_{t,0}}}(x_{\tau_{t,0}})}\notag\\ &\quad = \frac{1}{p_{\overline{X}_{\tau_{t,0}}}(x_{\tau_{t,0}})}\int_{x_0}p_{X_0}(x_0)p_{\sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}\overline{X}_{\tau_{t,i}}\mymid X_0}\left(\sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}x_{\tau_{t,i}}^{(1)}~\Big |~x_0\right){\rm  d}x_0\notag\\
	&\quad= \left(\frac{(1-\tau_{t,i})\tau_{t,0}}{(1-\tau_{t,0})\tau_{t,i}}\right)^{d/2}\int_{x_0}p_{X_0\mymid \overline{X}_{\tau_{t, 0}}}(x_0\mymid x_{\tau_{t,0}})\notag\\
	&\qquad \cdot\exp\left(-\frac{(\tau_{t,i} - \tau_{t, 0})\left\|x_{\tau_{t,0}} - \sqrt{1-\tau_{t,0}}x_0\right\|_2^2}{2(1-\tau_{t,0})\tau_{t,0}\tau_{t,i}} -\frac{\big\|u_{t,i}^{(1)}\big\|_2^2 + 2\big<u_{t,i}^{(1)}, x_{\tau_{t,0}} - \sqrt{1-\tau_{t,0}}x_0\big>}{2\frac{(1-\tau_{t,0})\tau_{t,i}}{1-\tau_{t,i}}}\right){\rm  d}x_0\notag\\
	&\quad = \left(1 + \frac{d}{2}\frac{\tau_{t, 0} - \tau_{t, i}}{(1-\tau_{t,0})\tau_{t,i}} + O\left(d^2\left(\frac{\tau_{t, 0} - \tau_{t, i}}{(1-\tau_{t,0})\tau_{t,i}}\right)^2\right)\right)\notag\\
	&\qquad \cdot\int_{x_0}p_{X_0\mymid \overline{X}_{\tau_{t, 0}}}(x_0\mymid x_{\tau_{t,0}})\notag\\&\hspace{2cm}\cdot\exp\left(-\frac{(\tau_{t,0} - \tau_{t, i})\left\|x_{\tau_{t,0}} - \sqrt{1-\tau_{t,0}}x_0\right\|_2^2}{2(1-\tau_{t,0})\tau_{t,0}\tau_{t,i}} -\frac{\big\|u_{t,i}^{(1)}\big\|_2^2 + 2\big<u_{t,i}^{(1)}, x_{\tau_{t,0}} - \sqrt{1-\tau_{t,0}}x_0\big>}{2\frac{(1-\tau_{t,0})\tau_{t,i}}{1-\tau_{t,i}}}\right){\rm  d}x_0.
\end{align}
By virtue of \eqref{ineq24}, we can derive
\begin{align}\label{ineq30}
	&\bigg\|u_{t,i}^{(1)} - \bigg(-\sqrt{1-\tau_{t, 0}}\int_{\tau_{t, 0}}^{\tau_{t,i}} \frac{1}{2(1-\tau)^{3/2}}s_{\tau}^{\star}(x_{\tau}^\star)\mathrm{d}\tau\bigg)\bigg\|_2\notag\\
	&\quad= \sqrt{1-\tau_{t, 0}}\Bigg\|\sum_{0 \le j < K} \gamma_{t, j}(\tau_{t,i})(1-\tau_{t, j})^{-3/2}\big(s_{\tau_{t, j}}(x_{\tau_{t, j}}^{(0)}) - s_{\tau_{t, j}}^\star(x_{\tau_{t, j}}^{(0)})\big)\notag\\&\hspace{2.5cm} + \bigg[\sum_{0 \le j < k} \gamma_{t, j}(\tau_{t,i})(1-\tau_{t, j})^{-3/2} s_{\tau_{t, j}}^{\star}(x_{\tau_{t, j}}^{\star}) - \bigg(-\int_{\tau_{t, 0}}^{\tau'} \frac{1}{2(1-\tau)^{3/2}}s_{\tau}^{\star}(x_{\tau}^\star)\mathrm{d}\tau\bigg)\bigg]\Bigg\|_2\notag\\
	&\quad\leq\sqrt{1-\tau_{t, 0}}\sum_{0 \le j < K} \left|\gamma_{t, j}(\tau_{t,i})\right|(1-\tau_{t, j})^{-3/2}\big\|s_{\tau_{t, j}}(x_{\tau_{t, j}}^{(0)}) - s_{\tau_{t, j}}^\star(x_{\tau_{t, j}}^{(0)})\big\|\notag\\
	&\qquad + \sqrt{1-\tau_{t, 0}}\bigg\|\sum_{0 \le j < K} \gamma_{t, j}(\tau_{t,i})(1-\tau_{t, j})^{-3/2} s_{\tau_{t, j}}^{\star}(x_{\tau_{t, j}}^{\star}) - \bigg(-\int_{\tau_{t, 0}}^{\tau'} \frac{1}{2(1-\tau)^{3/2}}s_{\tau}^{\star}(x_{\tau}^\star)\mathrm{d}\tau\bigg)\bigg\|\notag\\
	&\quad\asymp \sum_{0 \le j < K}(\tau_{t,0} - \tau_{t,i})(1-\tau_{t, 0})^{-1}\big\|s_{\tau_{t, j}}(x_{\tau_{t, j}}^{(0)}) - s_{\tau_{t, j}}^\star(x_{\tau_{t, j}}^{(0)})\big\|_2\notag\\&\qquad + \sqrt{1-\tau_{t, 0}}\sqrt{\frac{d\theta_t(\tau_{t,i}-\tau_{t, 0})^2\log T}{\tau_{t,0}(1-\tau_{t,0})^3}}\bigg(\frac{d\theta_t(\tau_{t, 0}-\tau_{t,i})\log T}{\tau_{t,0}(1-\tau_{t,0})}\bigg)^{K}\notag\\
	&\quad\lesssim \frac{\tau_{t, 0}\log T}{T}\sum_{0 \le j < K}\big\|s_{\tau_{t, j}}(x_{\tau_{t, j}}^{(0)}) - s_{\tau_{t, j}}^\star(x_{\tau_{t, j}}^{(0)})\big\|_2 +  \sqrt{\frac{d\theta_t\tau_{t, 0}\log^3 T}{T^2}}\left(\frac{d\theta_t\log^2T}{T}\right)^K\notag\\
	&\quad\lesssim \frac{\tau_{t, 0}\log T}{T}\sqrt{K\sum_{i}\big(\varepsilon_{\mathsf{score}, t, i}^{(n)}(x_{\tau_{t, i}}^{(0)})\big)^2} +  \sqrt{\frac{d\theta_t\tau_{t, 0}\log^3 T}{T^2}}\left(\frac{d\theta_t\log^2T}{T}\right)^K\notag\\
	&\quad\asymp \frac{\tau_{t, 0}\log T}{T}\sqrt{\sum_{i}\big(\varepsilon_{\mathsf{score}, t, i}^{(0)}(x_{\tau_{t, i}}^{(0)})\big)^2} +  \sqrt{\frac{d\theta_t\tau_{t, 0}\log^3 T}{T^2}}\left(\frac{d\theta_t\log^2T}{T}\right)^K.
\end{align}
Here, the fourth line makes use of \eqref{ineq:learning_rate_g}, \eqref{ineq:learning_rate_h}, \eqref{eq:derivative_1} and Taylor's Theorem; the fifth line holds due to \eqref{ineq:learning_rate_f}; the fifth line comes from Cauchy-Schwarz inequality and the last line is valid since $K$ is a constant. By virtue of Lemmas \ref{lemma:learning_rate}, \ref{lemma:Hessian} and \ref{lemma:log_density}, one has
\begin{align}
	\bigg\|-\sqrt{1-\tau_{t, 0}}\int_{\tau_{t, 0}}^{\tau_{t,i}} \frac{1}{2(1-\tau)^{3/2}}s_{\tau}^{\star}(x_{\tau}^\star)\mathrm{d}\tau\bigg\|_2 &\lesssim \sqrt{1-\tau_{t, 0}}\int_{\tau_{t, i}}^{\tau_{t,0}}\frac{1}{2(1-\tau)^{3/2}}\sqrt{\frac{d\theta_t\log T}{\tau}}d\tau\notag\\
	&\lesssim \sqrt{1-\tau_{t, 0}}\frac{\tau_{t, 0}-\tau_{t, i}}{2(1-\tau_{t,0})^{3/2}}\sqrt{\frac{d\theta_t\log T}{\tau_{t,0}}}\notag\\
	&=\frac{\tau_{t, 0}-\tau_{t, i}}{2(1-\tau_{t,0})\tau_{t,0}}\sqrt{\tau_{t, 0}d\theta_t\log T}\\
	&\lesssim \frac{\sqrt{\tau_{t, 0}d\theta_t\log^3 T}}{T}.\label{ineq34}
\end{align}
Combining the previous two inequalities, we obtain
\begin{align}\label{ineq26}
