	&\lesssim \frac{\sqrt{\tau_{t, 0}d
			\theta_t\log^3 T}}{T} + \frac{\tau_{t, 0}\log T}{T}\sqrt{\sum_{i}\big(\varepsilon_{\mathsf{score}, t, i}^{(0)}(x_{\tau_{t, i}}^{(0)})\big)^2}.
\end{align}

