	&\qquad + O\left(\frac{d^2\theta_t^2\log^4 T}{T^2} + \frac{\sqrt{d\theta_t\tau_{t, 0}\log^3 T}}{T}\sqrt{\sum_{i}\big(\varepsilon_{\mathsf{score}, t, i}^{(0)}(x_{\tau_{t, i}}^{(0)})\big)^2}\right)\\
	&\quad \stackrel{\eqref{eq:score_form}}{=} 1 - \frac{\tau_{t,0} - \tau_{t, i}}{2(1-\tau_{t,0})\tau_{t,0}\tau_{t,i}}\bigg[\int_{x_0}p_{X_0\mymid \overline{X}_{\tau_{t, 0}}}(x_0\mymid x_{\tau_{t,0}})\left\|x_{\tau_{t,0}} - \sqrt{1-\tau_{t,0}}x_0\right\|_2^2{\rm  d}x_0\\&\hspace{4.5cm} - \big\|\int_{x_0}p_{X_0\mymid \overline{X}_{\tau_{t, 0}}}(x_0\mymid x_{\tau_{t,0}})(x_{\tau_{t,0}} - \sqrt{1-\tau_{t,0}}x_0){\rm  d}x_0\big\|_2^2\bigg]\\&\qquad + O\left(\frac{d^2\theta_t^2\log^4 T}{T^2} + \frac{\sqrt{d\theta_t\tau_{t, 0}\log^3 T}}{T}\sqrt{\sum_{i}\big(\varepsilon_{\mathsf{score}, t, i}^{(0)}(x_{\tau_{t, i}}^{(0)})\big)^2}\right)\\
	&\quad \stackrel{\text{Jensen's inequality}}{\leq} 1 + O\left(\frac{d^2\theta_t^2\log^4 T}{T^2} + \frac{\sqrt{d\theta_t\tau_{t, 0}\log^3 T}}{T}\sqrt{\sum_{i}\big(\varepsilon_{\mathsf{score}, t, i}^{(0)}(x_{\tau_{t, i}}^{(0)})\big)^2}\right).
\end{align*}
Equation \eqref{ineq25} together with the previous inequality and Lemma \ref{lemma:learning_rate} implies that
\begin{align}\label{ineq28}
	\log\frac{p_{\sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}\overline{X}_{\tau_{t,i}}}\left(\sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}x_{\tau_{t,i}}^{(1)}\right)}{p_{\overline{X}_{\tau_{t,0}}}(x_{\tau_{t,0}})} \leq \frac{4c_1d\log T}{T} + C_{10}\left\{\frac{d^2\theta_t^2\log^4 T}{T^2} + \frac{\sqrt{d\theta_t\log^3 T}}{T}\sqrt{\sum_{i}\big(\varepsilon_{\mathsf{score}, t, i}^{(0)}(x_{\tau_{t, i}}^{(0)})\big)^2}\right\}.
\end{align}
Similarly, for any $\lambda \in [0,1]$, one has
\begin{align}\label{ineq29}
	&\left|\log\frac{p_{\sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}\overline{X}_{\tau_{t,i}}}\left(\sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}\left(\lambda x_{\tau_{t,i}}^\star + (1-\lambda)x_{\tau_{t,i}}^{(1)}\right)\right)}{p_{\overline{X}_{\tau_{t,0}}}(x_{\tau_{t,0}})}\right|\notag\\ \quad &\leq C_{10}\left\{\frac{d\theta_t\log^2 T}{T} + \frac{\ell\sqrt{d\theta_t\log^3 T}}{T}\sqrt{\sum_{i}\big(\varepsilon_{\mathsf{score}, t, i}^{(0)}(x_{\tau_{t, i}}^{(0)})\big)^2}\right\}
\end{align}
Repeating similar arguments and using induction yields that for all $0 \leq n \leq N-1$, $0 \leq i \leq K-1$,
\begin{subequations}
	\begin{align}
		-\log p_{\overline{X}_{\tau_{t,i}}}\big(\lambda x_{\tau_{t,i}}^{(n+1)} + (1-\lambda)x_{\tau_{t,i}}^\star\big) &\leq 2.1d\theta_t\log T,\label{ineq37a}\\
		\log\frac{p_{\sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}\overline{X}_{\tau_{t,i}}}\left(\sqrt{\frac{1-\tau_{t,0}}{1-\tau_{t,i}}}x_{\tau_{t,i}}^{(n+1)}\right)}{p_{\overline{X}_{\tau_{t,0}}}(x_{\tau_{t,0}})} &\leq \frac{4c_1d\log T}{T} + C_{10}\left\{\frac{d^2\theta_t^2\log^4 T}{T^2} + \frac{\sqrt{d\theta_t\log^3 T}}{T}\sqrt{\sum_{i}\big(\varepsilon_{\mathsf{score}, t, i}^{(n)}(x_{\tau_{t, i}}^{(n)})\big)^2}\right\}.\label{ineq37b}
	\end{align}
\end{subequations}

\subsection{Proof of Lemma \ref{lemma:log_density_bound}}\label{sec:proof_lemma_log_density_bound}
We prove Lemma \ref{lemma:log_density_bound} by contradiction. Suppose that there exists $\ell \in [1, \tau(x_T))$ such that $-\log q_{\ell}(x_{\ell}) > 2c_6d\log T$. We let $1 < t \leq \ell$ denote the smallest time step satisfying
\begin{align}
	\theta_t(x_t) = \max\left\{-\frac{\log q_t(x_t)}{d\log T}, c_6\right\} > 2c_6.\label{ineq53}
\end{align}
Since $-\log q_t(x_t) \leq c_6d\log T$, we have 
\begin{align}
	\theta_t(x_t) \geq 2\theta_1(x_1).\label{ineq51}
\end{align}
Morevoer, by repeating similar arguments as in \citet[Eqn. (129)]{li2024sharp}, one can derive
\begin{align}\label{ineq50}
	\theta_1(x_1), \dots, \theta_t(x_t) \in [c_6, 4c_6]. 
\end{align}
By virtue of Lemma \ref{lemma:log_density_ratio_1}, for any $2 \leq j \leq t$, one has
\begin{align}
	&\log q_{j-1}(x_{j-1}) - \log q_j(x_j)\notag\\ &\quad= \log\frac{p_{\overline{X}_{\tau_{j, K-1}}}\big(x_{\tau_{j, K-1}}^{(n)}\big)}{p_{\overline{X}_{\tau_{j, 0}}}\big(x_{\tau_{j, 0}}\big)}\notag\\ &\quad= \log\frac{p_{\sqrt{\frac{1 - \tau_{j,0}}{1 - \tau_{j,K-1}}}\overline{X}_{\tau_{j, K-1}}}\big(\sqrt{\frac{1 - \tau_{j,0}}{1 - \tau_{j,K-1}}}x_{\tau_{j, K-1}}^{(n)}\big)}{p_{\overline{X}_{\tau_{j, 0}}}\big(x_{\tau_{j, 0}}\big)} + \log\left[\left(\frac{1 - \tau_{j,0}}{1 - \tau_{j,K-1}}\right)^{d/2}\right]\notag\\
	&\quad\leq \frac{4c_1d\log T}{T} + C_{10}\left\{\frac{d^2\theta_t^2\log^4 T}{T^2} + \frac{\sqrt{d\theta_t\log^3 T}}{T}\sqrt{\sum_{i}\big(\varepsilon_{\mathsf{score}, t, i}^{(n)}(x_{\tau_{t, i}}^{(n)})\big)^2}\right\} + \frac{d}{2}\log\alpha_j\notag\\
	&\quad\leq \frac{4c_1d\log T}{T} + C_{10}\left\{\frac{d^2\theta_t^2\log^4 T}{T^2} + \frac{\sqrt{d\theta_t\log^3 T}}{T}\sqrt{\sum_{i}\big(\varepsilon_{\mathsf{score}, t, i}^{(n)}(x_{\tau_{t, i}}^{(n)})\big)^2}\right\},\label{ineq52}
\end{align}
where we makes use of the fact $p_{\overline{X}_{\tau_{j, K-1}}}\big(x_{\tau_{j, K-1}}^{(n)}\big)  = \left(\frac{1 - \tau_{j,0}}{1 - \tau_{j,K-1}}\right)^{d/2}p_{\sqrt{\frac{1 - \tau_{j,0}}{1 - \tau_{j,K-1}}}\overline{X}_{\tau_{j, K-1}}}\big(\sqrt{\frac{1 - \tau_{j,0}}{1 - \tau_{j,K-1}}}x_{\tau_{j, K-1}}^{(n)}\big)$ in the second line.
Putting \eqref{ineq53}, \eqref{ineq51}, \eqref{ineq50} and \eqref{ineq52} together leads to
\begin{align}
	c_6 = \theta_1(x_1) &\leq \theta_t(x_t) - \theta_1(x_1) = -\frac{\log q_t(x_t)}{d\log T} - \theta_1(x_1) \leq \frac{-\log q_t(x_t) + \log q_1(x_1)}{d\log T}\notag\\
	&= \frac{1}{d\log T}\sum_{j = 2}^{t}\left(\log q_{j-1}(x_{j-1}) - \log q_{j}(x_j)\right)\notag\\
	&\leq 4c_1 + C_{11}\left(\frac{d\log^3 T}{T} + \frac{S_{\tau(x_T)-1}(x_T)}{d\log T}\right)\notag\\ &\leq 5c_1.
\end{align}
Here, the last inequality holds due to \eqref{def:tau}. This contradicts our assumption $c_6 > 5c_1$. Therefore, we know that \eqref{ineq:log_density_bound} holds for all $1 \leq \ell < \tau(x_T)$.

\subsection{Proof of Lemma \ref{lemma:log_density_ratio_2}}\label{sec:proof_lemma_log_density_ratio_2}
First, we prove that the event $\{S_t(x_T) \leq c_3\}$ implies $\mathcal{E}_t \cap \{\xi_t(x_t) \leq c_3\}$ for all $t < \tau$. We know from Lemma \ref{lemma:log_density_bound} that 
\begin{align}
	-\log q_{\ell}(x_\ell) \leq 2c_6d\log T,~\quad~\forall 1 \leq \ell \leq t.\label{ineq61}
\end{align}
Then Lemma \ref{lemma:log_density} and Lemma \ref{lemma:learning_rate} (more precisely, \eqref{ineq:learning_rate_f}) together imply that for any $\tau \in [\tau_{t,K-1}, \tau_{t,0}]$, one has
\begin{align}
	-\log p_{\overline{X}_{\tau}}(x_{\tau}^\star) \leq 4c_6d\log T.\label{ineq54}
\end{align}
Furthermore, it is straightforward to verify that
\begin{align}
	&C_{10}\frac{\theta_{\tau_{t,0}}(x_{\tau_{t,0}})d\log^2 T + \sqrt{\theta_{\tau_{t,0}}(x_{\tau_{t,0}})\sum_{i,n}\big(\varepsilon_{\mathsf{score}, t, i}^{(n)}(x_{\tau_{t, i}}^{(n)})\big)^2d\log^3 T}}{T}\notag\\
	&\quad \asymp \frac{d\log^2 T + \sqrt{\sum_{i,n}\big(\varepsilon_{\mathsf{score}, t, i}^{(n)}(x_{\tau_{t, i}}^{(n)})\big)^2d\log^3 T}}{T}\notag\\
	&\quad \leq \frac{d\log^2 T}{T} + \xi_t(x_t)\notag\\
	&\quad \leq \frac{d\log^2 T}{T} + S_t(x_T)\notag\\
	&\quad \ll 1.\label{ineq55}
\end{align}
By virtue of Lemma \ref{lemma:log_density_ratio_1}, we know that for all $0 \leq i \leq K-1, 0 \leq n \leq N$,
\begin{align}
	-\log p_{\overline{X}_{\tau_{t,i}}}\big(\lambda x_{\tau_{t,i}}^{(n)} + (1-\lambda)x_{\tau_{t,i}}^\star\big) &\leq 2.1d\theta_t\log T.\label{ineq56}
\end{align}
In addition, for all $0 \leq i \leq K-1, 0 \leq n \leq N$, we have
\begin{align}
	\frac{\varepsilon_{\mathsf{Jacob}, t, i}^{(n)}\big(x_{\tau_{t, i}}^{(n)}\big)\log T}{T} \leq \xi_t(x_t) \leq S_t(x_T) \leq c_3 \ll 1. \label{ineq57}
\end{align}
Combining \eqref{ineq54}, \eqref{ineq56} and \eqref{ineq57} together yields
\begin{align}
	\{S_t(x_T) \leq c_3\} \subseteq \mathcal{E}_t \cap \{\xi_t(x_t) \leq c_3\}.\label{ineq58}
\end{align}
Observing that $S_t(x_T) \leq c_3$ for all $t < \tau$, \eqref{ineq42} tells us that 
\begin{align}
	\frac{p_{Y_{t-1}}(x_{t-1})}{p_{X_{t-1}}(x_{t-1})} = \exp\left(O\left(\xi_t(x_t) + d\bigg(\frac{d\log^2 T}{T}\bigg)^{K+1}\right)\right)\frac{p_{Y_{t}}(x_{t})}{p_{X_{t}}(x_{t})},~\quad~\forall 2 \leq t < \tau(x_T).\label{ineq59}
\end{align}
As a result, one has
\begin{align}
	\frac{q_1(x_1)}{p_1(x_1)} = \prod_{t=2}^{\tau-1}\exp\left(O\left(\xi_t(x_t) + d\bigg(\frac{d\log^2 T}{T}\bigg)^{K+1}\right)\right)\cdot \frac{q_{\tau-1}(x_{\tau-1})}{p_{\tau-1}(x_{\tau-1})}\notag\\
	= \exp\left(O\left(\sum_{t < \tau}\xi_t(x_t) + d^2\log^2 T\bigg(\frac{d\log^2 T}{T}\bigg)^{K}\right)\right)\frac{q_{\tau-1}(x_{\tau-1})}{p_{\tau-1}(x_{\tau-1})}\notag\\
	= \left(1 + O\left(\sum_{t < \tau}\xi_t(x_t) + d^2\log^2 T\bigg(\frac{d\log^2 T}{T}\bigg)^{K}\right)\right)\frac{q_{\tau-1}(x_{\tau-1})}{p_{\tau-1}(x_{\tau-1})},\label{ineq60}
\end{align}
which has finished the proof of \eqref{ineq45a}. Here, the last equation holds since $\sum_{t < \tau}\xi_t(x_t) + d^2\log^2 T\bigg(\frac{d\log^2 T}{T}\bigg)^{K} \leq c_3 + d^2\log^2 T\bigg(\frac{d\log^2 T}{T}\bigg)^{K} \ll 1$ and $\exp(z) = 1 + O(z)$ for all $|z| < 1$. Similarly, we can also prove \eqref{ineq45b}.

\subsection{Proof of Lemma \ref{lemma:other_set}}\label{sec:proof_Lemma_other_set}
We can prove Lemma \ref{lemma:other_set} by using same arguments in the proof of \citet[Lemma 8]{li2024sharp} and we omit the details here for the sake of brevity. 
