  \item For each $\Ubf_i$, compute  $\widehat{\ebf}_{\text{int}}(\Ubf_i, r) = \Pbf \mathcal{F}\brackets{\Psihatbf(r) \Ibf(\Ubf_i, S, \mubf )}$ such that 
  $$
\Ibf(\Ubf_i, S, \mubf ) = \Ubf_i|_0^T + \sum_{s=1}^{S} \dt^{2s} \frac{B_{2s}}{(2s)!} \sum_{l=0}^{2s} \binom{2s}{l} \dbf^{2s-l} \mathcal{D}^{l}_{\mu_l}[\Ubf_i]|_0^T.
$$
Concatenate over $i$ to form  $\widehat{\ebf}_{\text{int}}(r)$.
\item Compute $\widehat{\ebf}(r) := \frac{1}{\sqrt{K(r)}} \norm{\widehat{\ebf}_{\text{int}}(r) }_2$.
\end{itemize}
\vspace{0.5em}
%\STATE Identify the critical radius $\rchat := m^\star \dt$ where $m^\star := \text{change point}(\widehat{\ebf}(m\dt))$
\STATE Identify the critical radius $\rchat := \text{change\_point}(log(\widehat{\ebf}(r))$.
\RETURN $\Phibf(\rchat), \Phidotbf(\rchat)$
\end{algorithmic}
\end{algorithm}   
\end{comment}



\section{Results}

\label{sec:results}
In this section, we evaluate the effectiveness of our algorithm for selecting test function hyperparameters by analyzing how the WENDy framework performs as a function of the test function radius and polynomial (see \cref{sec:result_Sl}). In addition, in \cref{sec:compareMG},  we compare two strategies for constructing the test function set $\Kcalbf$: the Single-scale-Local (SL) approach described in \cref{alg:SL}, and  Multi-scale-Global (MG) approach from \cref{alg:MG}.

Both objectives are explored in two regression settings: Ordinary Least Squares (WENDy-OLS) (see \cref{sec:weakform}) and Iteratively Reweighted Least Squares (WENDy - IRLS) (see \cref{sec:WENDy}).  Results are demonstrated on four canonical ODE systems: logistic growth, Duffing oscillator, Lorenz system, and FitzHugh–Nagumo. The governing equations and parameter values used in these experiments are summarized in \cref{table:eq}.

To assess performance, we perform $100$ independent trials for each setting. In each trial, Gaussian noise with standard deviation $\sigma = \sigma_{NR}\norm{ \Ubfstar}_F$ is added to the data, where $\sigma_{NR}$ denotes the noise ratio. We evaluate two error metrics: the relative coefficient error of the IRLS estimate $E_2(\widehat{\wbf})$ and the relative coefficient error of the OLS estimate $E_2(\wbf_0)$.
%, and the forward simulation error $ E_{FS}(\widehat{\wbf})$, computed by simulating the learned model from the true initial condition $\ubf^{\star}(0)$. Unless otherwise noted, all forward simulations are performed using the RK45 scheme with absolute and relative tolerances set to $10^{-15}$.
These error metrics are defined as follows:
\begin{equation}
\begin{aligned}
    E_2(\widehat{\wbf}) := \frac{\norm{\widehat{\wbf} - \wbf^{\star}}_2}{\norm{\wbf^{\star}}_2}, \quad   E_2(\wbf_0) := \frac{\norm{\wbf_0 - \wbf^{\star}}_2}{\norm{\wbf^{\star}}_2}, 
    %\quad E_{FS}(\widehat{\wbf}) := \frac{\norm{\Ubfstar - \widehat{\Ubf}}_F}{\norm{\Ubfstar}_F},
\end{aligned}
\label{eq:metric}
\end{equation}
where $\wstar$ denotes the true parameter vector: $\wstar:= \textsf{vec}(\Wbfstar)$.

