\section{Proof of \propositionref{prop_approx_call}}
\label{section_appendix_ouCall}

    We calculate the price of a call option on an underlying modelled by a OU-process with constant speed and vola and time-dependent level. Its dynamics and solution thus are:
    \begin{align*}
	    dX_t &= \kappa (\mu(t) - X_t) dt + \sigma dW_t \\
	    X_s &= X_t e^{-\kappa(s-t)} + \int^s_t e^{-\kappa(s-u)} \kappa \mu(u) du + \int^s_t e^{-\kappa(s-u)} \sigma dW_u
    \end{align*}

    The variance of the OU process is:
    \begin{align*}
    	\bar{\sigma}(t,T) = \Var(X_T | \mathcal{F}_t) = \sigma^2 \Ef\left[\int^T_t e^{-2\kappa(T-u)} du | \mathcal{F}_t\right] = \sigma^2 \frac{1}{2 \kappa} \left(1 - e^{-2\kappa(T-t)}\right)
    \end{align*}

    The call at time $t$ on $X_t$ with strike $K$ and expiry $T$ has fair value:
    \begin{align*}
    	C(t,T) = \Ef[(X_T - K)^+ | \mathcal{F}_t] &= 	\Ef[(X_T - K) \mathbbmss{1}_{X_T > K} | \mathcal{F}_t]
    \end{align*}

    The event of the above indicator function can be written as:
    \begin{align*}
    	X_T > K &\Rightarrow K <  X_t e^{-\kappa(T-t)} + \int^T_t e^{-\kappa(T-u)} \kappa \mu(u) du + \int^T_t e^{-\kappa(T-u)} \sigma dW_u \\
    	&\Rightarrow \bar{\sigma}(t,T) Z > K - X_t e^{-\kappa(T-t)} - \int^T_t e^{-\kappa(T-u)} \kappa \mu(u) du \\
    	&\Rightarrow Z > \frac{-\left(X_t e^{-\kappa(T-t)} + \int^T_t e^{-\kappa(T-u)} \kappa \mu(u) du  - K\right)}{\bar{\sigma}(t,T)} = -d
    \end{align*}
    where $Z \sim \mathcal{N}(0,1)$ and we used Ito's isometry. Going back to the payoff function, we now split the expectation into two parts:
    \begin{align*}
    	C(t,T) &= \underbrace{\Ef[X_T \mathbbmss{1}_{X_T > K} | \mathcal{F}_t]}_A - \underbrace{\Ef[K \mathbbmss{1}_{X_T > K} | \mathcal{F}_t]}_B
    \end{align*}

    We calculate both parts in turn. The second part is straightforward:
    \begin{align*}
	    B = K ~ \Pf(Z \geq -d) = K \Phi(d)
    \end{align*}
    For the first part we introduce another helper variable 
    \begin{align*}
        g(t,T) = X_t e^{-\kappa(T-t)} + \int^T_t e^{-\kappa(T-u)} \kappa \mu(u) du
    \end{align*}
    We then calculate:
    \begin{align*}
    	A &= \Ef\left[\left(g(t,T) + \bar{\sigma} Z\right) \mathbbmss{1}_{X_T > K} | \mathcal{F}_t\right] \\
    	&= g(t,T) \Phi(d) + \bar{\sigma} ~ \Ef\left[Z \mathbbmss{1}_{Z > -d} | \mathcal{F}_t\right]\\
    	&= g(t,T) \Phi(d) + \bar{\sigma} ~  \int^\infty_{-d} x \phi(x) dx \\
    	&= g(t,T) \Phi(d) + \bar{\sigma} ~ \phi(-d) \\
    	&= g(t,T) \Phi(d) + \bar{\sigma} ~ \phi(d)
    \end{align*}

    Collecting terms, we arrive at:
    \begin{align*}
        C(t,T) &= (g(t,T) - K) ~ \Phi(d) + \bar{\sigma} ~ \phi(d)
    \end{align*}
    which is the desired result.

