		\frac{-\alpha_{1x}\cos\mu_{1}-(1-u)\sin\mu_{1}}{\sqrt{\beta_{1x}}} \\
		\sqrt{\beta_{1y}}\cos(\mu_{1}-\nu_{1}) \\
		\frac{-\alpha_{1y}\cos(\mu_{1}-\nu_{1})-u\sin(\mu_{1}-\nu_{1})}{\sqrt{\beta_{1y}}}
	\end{pmatrix}, \qquad \vec{z}_{2}= \begin{pmatrix}
	    x_{2}\\
        x'_{2}\\
        y_{2}\\
        y'_{2}
	\end{pmatrix}=\begin{pmatrix}
		\sqrt{\beta_{1x}}\sin\mu_{x} \\
		\frac{(1-u)\cos\mu_{1} - \alpha_{1x}\sin\mu_{1}}{\sqrt{\beta_{1x}}} \\
		\sqrt{\beta_{1y}}\sin(\mu_{1}-\nu_{1})\\
		\frac{u\cos(\mu_{1}-\nu_{1})-\alpha_{1y}\sin(\mu_{1}-\nu_{1})}{\sqrt{\beta_{1y}}}
	\end{pmatrix}, \\
		\vec{z}_{3}&= \begin{pmatrix}
		    x_{3}\\
            x'_{3}\\
            y_{3}\\
            y'_{3}
		\end{pmatrix}=\begin{pmatrix}
		\sqrt{\beta_{2x}}\cos(\mu_{2}-\nu_{2}) \\
		\frac{-\alpha_{2x}\cos(\mu_{2}-\nu_{2})-u\sin(\mu_{2}-\nu_{2})}{\sqrt{\beta_{2x}}} \\
		\sqrt{\beta_{2y}}\cos\mu_{2} \\
		\frac{-\alpha_{2y}\cos\mu_{2}-(1-u)\sin\mu_{2}}{\sqrt{\beta_{2y}}}
	\end{pmatrix}, \qquad \vec{z}_{4}= \begin{pmatrix}
	    x_{4}\\
        x'_{4}\\
        y_{4}\\
        y'_{4}
	\end{pmatrix}=\begin{pmatrix}
		\sqrt{\beta_{2x}}\sin(\mu_{2}-\nu_{2}) \\
		\frac{u\cos(\mu_{2}-\nu_{2})-\alpha_{2x}\sin(\mu_{2}-\nu_{2})}{\sqrt{\beta_{2x}}} \\
		\sqrt{\beta_{2y}}\sin\mu_{2} \\
		\frac{(1-u)\cos\mu_{2}-\alpha_{2y}\sin\mu_{2}}{\sqrt{\beta_{2y}}}
	\end{pmatrix}.
	\end{split}
\end{equation}
The phase advances can be extracted from the generating vectors as:
\begin{equation}
	\begin{split}
		\mu_{1} &= \arctan(x_{2}/x_{1}), \qquad \mu_{2}= \arctan(y_{4}/y_{3}), \\
		\mu_{1}-\nu_{1} &= \arctan(y_{2}/y_{1}), \qquad \mu_{2}-\nu_{2}= \arctan(x_{4}/x_{3}). 
	\end{split}
\end{equation}
Thus, the propagation of the phase advances depends on the propagation of the generating vectors. The change in phase advance is $\Delta\mu_{1}=\mu_{1f}- \mu_{1i}$, and can be written as:
\begin{equation}
	\begin{split}
		\tan(\Delta\mu_{1}) &= \frac{\tan\mu_{f}-\tan\mu_{i}}{1 + \tan\mu_{f}\tan\mu_{i}} = \frac{\frac{x_{2f}}{x_{1f}} - \frac{x_{2i}}{x_{1i}}}{1 + \frac{x_{2f}}{x_{1f}}\frac{x_{2i}}{x_{1i}}} 
		= \frac{x_{2f}x_{1i} - x_{1f}x_{2i}}{x_{1f}x_{1i} + x_{2f}x_{2i}}.
	\end{split}
\end{equation}
Since the generating vector components are known , the final state of the generating vectors can be obtained from the transfer matrix, which will yield:
\begin{equation}
\tan(\Delta\mu_{1}) = \frac{M_{12}(1-u) - m_{11}\sqrt{\beta_{1x}\beta_{1y}}\sin\nu_{1} +m_{12}\sqrt{\frac{\beta_{1x}}{\beta_{1y}}}\left (u\cos\nu_{1} + \alpha_{1y}\sin\nu_{1} \right )}{M_{11}\beta_{1x}-M_{12}\alpha_{1x} + m_{11}\xi_{1xy} + m_{12}\xi_{1xy'}}.
\end{equation}
The same procedure can be carried out for other phase parameters. 

\section{Coupled Beam Matrix and Optics Functions}\label{appendix:B}
The beam matrix is parametrized using the Lebedev-Bogacz parametrization in~\cite{lebedev2010betatron}:
\begin{equation}
	\begin{split}
		\sigma_{xx} &= \epsilon_{1}\beta_{1x} + \epsilon_{2}\beta_{2x}, \\
		\sigma_{xx'} &= -\alpha_{1x}\epsilon_{1} - \alpha_{2x}\epsilon_{2},\\
		\sigma_{x'x'} &= \epsilon_{1}\frac{(1-u)^{2} + \alpha_{1x}^{2}}{\beta_{1x}} + \epsilon_{2}\frac{u^{2} + \alpha_{2x}^{2}}{\beta_{2x}}, \\
		\sigma_{yy}&= \epsilon_{1}\beta_{1y} + \epsilon_{2}\beta_{2y}, \\
		\sigma_{yy'} &= -\alpha_{1y}\epsilon_{1} - \alpha_{2y}\epsilon_{2}, \\
		\sigma_{y'y'} &= \epsilon_{1}\frac{u^{2}+\alpha_{1y}^{2}}{\beta_{1y}} + \epsilon_{2}\frac{(1-u)^{2} + \alpha_{2y}^{2}}{\beta_{2y}}, \\
		\sigma_{xy}&= \epsilon_{1}\sqrt{\beta_{1x}\beta_{1y}}\cos\nu_{1} + \epsilon_{2}\sqrt{\beta_{2x}\beta_{2y}}\cos\nu_{2}, \\
		\sigma_{xy'} &= \epsilon_{1}\sqrt{\frac{\beta_{1x}}{\beta_{1y}}}(u\sin\nu_{1} - \alpha_{1y}\cos\nu_{1}) - \epsilon_{2}\sqrt{\frac{\beta_{2x}}{\beta_{2y}}}((1-u)\sin\nu_{2}+\alpha_{2y}\cos\nu_{2}), \\
