		\sigma_{x'y'} &= \epsilon_{1}\frac{1}{\sqrt{\beta_{1x}\beta_{2x}}}((\alpha_{1y}(1-u)-\alpha_{1x}u)\sin\nu_{1} + (u(1-u) + \alpha_{1x}\alpha_{2y})\cos\nu_{1}) \\
		&+ \epsilon_{2}\frac{1}{\sqrt{\beta_{2x}\beta_{2y}}}\left( 
				(\alpha_{2x}(1-u) - \alpha_{2y}u)\sin\nu_{2} + (u(1-u) + \alpha_{2x}\alpha_{2y})\cos\nu_{2}
		\right).
	\end{split}
\end{equation}
The $(x,y)$ plane distribution for a general tilted ellipse is
\begin{equation}
\begin{split}
    &\frac{x^{2}}{\sigma_{x}^{2}} - \frac{2\tilde{\alpha}}{\sigma_{x}\sigma_{y}}xy + \frac{y^{2}}{\sigma_{y}^{2}} = 1-\tilde{\alpha}^{2}, \\
    & \tilde{\alpha} = \frac{\sigma_{xy}}{\sigma_{x}\sigma_{y}}.
\end{split}
\end{equation}
In order to have no tilt in $x-y$ plane, $\sigma_{xy}=0$. In coupled optics, no tilt suggests the phases of coupling are $\pi/2$.
\begin{equation}
    \frac{x^{2}}{\sigma_{x}^{2}} + \frac{y^{2}}{\sigma_{y}^{2}} = 1.
