\title[Double-Phase Poisson Equations with Variable Growth]{Existence and Uniqueness for Double-Phase Poisson Equations with Variable Growth}

\author[M. A. Khamsi \& O. M\'{e}ndez]{Mohamed  A. Khamsi, Osvaldo M\'{e}ndez}

\address{Mohamed A. Khamsi\\ Department of Applied Mathematics and Sciences, Khalifa University, Abu Dhabi, UAE}
