\section{Basics on causal spaces}\label{Subsec:BasicsLorentzianSpaces}

In this section, we briefly recall some basic notions and results from
the theory of causal spaces.
%
We give the definition of causal space,  following the convention of~\cite{KS}.


\begin{definition}[{Causal space  $(X,\ll,\leq)$~(\cite[Def.~2.11]{KS})}]
A \emph{causal space}  $(X,\ll,\leq)$ is a set $X$ endowed with a preorder $\leq$ and a transitive relation $\ll$ contained in $\leq$.
\end{definition}

Let us point out that this definition differs from the one present in
the paper by Kronheimer and Penrose~\cite{CausalSpace}, where the
notion of causal space was first introduced.
%
For the reader convenience, we compare in the table below the
two definitions. 

\begin{table}[ht]
  \newlength{\columnone}
  \setlength{\columnone}{1.65cm}
  \newlength{\columntwo}
  \setlength{\columntwo}{3.45cm}
  \newlength{\lastcolumn}
  \setlength{\lastcolumn}{\the\textwidth-7cm}
  \setlength{\lastcolumn}{\the\textwidth-\the\columnone-\the\columntwo-1.1cm}
  \centering
  \begin{tabular}{|p{\the\columnone}|p{\the\columntwo}|p{\the\lastcolumn}|}
    \hline
    &
      Causality\par\noindent (antisymmetry of $\leq$)
    &
      Push-up property (see~\Cref{def:push-up} for the push-up property)
    \\
    \hline
    K.--P.~\cite{CausalSpace}
    &
      Assumed
    &
      Assumed
    \\
    \hline
    K.--S.~\cite{KS}
    &
      Not assumed
    &
      Not assumed.
      %
      However, in the setting Lorentzian pre-length spaces (the
      topic of~\cite{KS}), the push-up
      property is always available.
    \\
    \hline
  \end{tabular}
\end{table}


\begin{remark}
 The framework of the present paper will be the one of causal spaces, recalled above. Another possible approach could have been to take as starting point the null-distance of Sormani--Vega \cite{Sormani-Vega}. It would be interesting to develop such a parallel theory, and investigate the relations with the present work. 
\end{remark}

We shall write $x<y$ when $x\leq y, x\neq y$. We say that $x$ and $y$ are \emph{timelike} (resp.\ \emph{causally}) related if $x\ll y$  (resp.\ $x\leq y$).  Let $A\subset X$ be an arbitrary subset of $X$. We define the \emph{chronological} (resp.\ \emph{causal}) future of $A$ the set
\begin{align*}
I^{+}(A)&:=\{y\in X\,:\, \exists x\in A,\, x\ll y\} \\
J^{+}(A)&:=\{y\in X\,:\, \exists x\in A,\, x\leq y\}
\end{align*}
respectively. Analogously, we define $I^{-}(A)$ (resp.\ $J^{-}(A)$) the   \emph{chronological} (resp.\ \emph{causal}) past of $A$. In case $A=\{x\}$ is a singleton, with a slight abuse of notation, we will write $I^{\pm}(x)$ (resp.\ $J^{\pm}(x)$) instead of  $I^{\pm}(\{x\})$ (resp.\ $J^{\pm}(\{x\})$).



\begin{definition}[Topological causal space]\label{def:topological-causal-space}
  We say that $(X,\ll,\leq,\mathfrak{T})$ is a \emph{topological causal space}, provided:
  \begin{itemize}
\item  $(X,\ll,\leq)$ is a causal space;
\item  $\mathfrak{T}$ is a Polish 
  and proper topology on $X$;
  \item In the product $X\times X$, the relation $\leq$ is closed and
    the relation $\ll$ is open.
    \end{itemize}
\end{definition}


Recall that a Polish topology is \emph{proper} if there exists a proper and separable metric 
inducing the topology; recall that a metric is proper if closed balls are compact.

%

%
Throughout the paper, $I\subset \R$ will denote an arbitrary interval. 

\begin{definition}\label{D:causalcurve}[Causal/timelike curves]
A non-constant curve $\gamma:I\to X$ is called (future-directed) \emph{causal}  (resp.\ \emph{timelike}) if $\gamma$ is continuous and if for all $t_{1}, t_{2}\in I$, with $t_{1}<t_{2}$, it holds $\gamma_{t_{1}}\leq \gamma_{t_{2}}$ (resp.\ $\gamma_{t_{1}}\ll \gamma_{t_{2}}$). We say that $\gamma$ is a \emph{null} curve if, in addition to being causal, no two points on $\gamma(I)$ are related with respect to $\ll$. 
\end{definition}

We recall the following  

\begin{definition}
    Let $(X,\ll,\leq,\mathfrak{T})$ be a topological causal space. 
    %
    We say that a set $A\subset X$ is weakly convex, if for all $x,y\in A$, such that $x\leq y$, there 
    exists a causal curve $\gamma$ contained in $A$ 
    connecting $x$ to $y$.
\end{definition}



\begin{remark}
  We point out that \Cref{D:causalcurve} is more general than the
  one given in the seminal paper~\cite{KS} by Kunziger and S\"amann,
  for we do not require that a causal curve is (locally) Lipschitz.
  %
  In that paper, the authors proved that if $(M,g)$ is a  strongly
  causal Lorentzian manifold (i.e., any point admits arbitrarily small neighborhoods which are weakly convex)  with  $g$ continuous, then a causal Lipschitz curve is casual in the classical
  sense (i.e., its tangent vector is causal almost everywhere).



  Next Lemma recovers Kunziger's and S\"amann's result, by proving, in
  the same setting, that any causal curve admits a Lipschitz
  reparametrization.
  %
  \end{remark}



\begin{lemma}\label{lem:lipschitz-reparametrization}
  Let $(M,g)$ be a strongly causal Lorentzian manifold with $g$ continuous.
  %
  Let $\gamma:I\to M$ be a causal curve.
  %
  Then there exists a reparametrization of $\gamma$ which is locally
  Lipschitz-continuous.
\end{lemma}
\begin{proof}
  We can assume without loss of generality that $\gamma$ is injective
  and that $0\in I$.
  %
  Since the statement is local, it suffices to show that $\gamma$
  admits a Lipschitz reparametrization in a neighborhood of $0$.
  %
  Let $U$ a neighborhood of $\gamma_0$.
  %
  We may assume that $U$ is coordinated, i.e., that $U\subset \R^n$.
  %
  Up to further restricting $U$, we can also assume that $g|_{U}$ is
  close to the standard Minkowski product, in the sense that, for all
  $x\in U$, the causal cone in $T_{x}U=\R^n$ of $g_x$ is contained in the
  causal cone of $-2\de x_n^2 +\frac{1}{2}\sum_{i=1}^{n-1} \de x_i^2$,
  i.e., if $X$ is a $g$-causal vector, then
  \begin{equation}
    \sum_{i=1}^{n-1} |X_i|^2
    \leq
    4|X_n|^2.
  \end{equation}
  %
  By strong causality, we can assume $U$ to be
  weakly convex.
  %
  Let $[a,b]$, such that $\gamma([a,b])\subset U$,
  and let $[\alpha,\beta]=\gamma_n([a,b])$.

  We claim that, for all $a\leq t_1\leq t_2\leq b$, it holds that
  \begin{equation}
    \label{E:causal-to-lipschitz}
    \sum_{i=1}^{n-1}
    |\gamma^{i}_{t_1}-\gamma^{i}_{t_2}|^2
    \leq
    4
    |\gamma^{n}_{t_2}-\gamma^{n}_{t_2}|^2
    .
  \end{equation}
  Indeed, fix $t_1\leq t_2$
  and let $\delta:[0,1]\to U$ be a causal (in the classical, i.e., differential sense) curve connecting
  $\gamma_{t_1}$ to $\gamma_{t_2}$.
  %
  A direct computation gives
  \begin{align*}
    \sqrt{
    \sum_{i=1}^{n-1}
    |\gamma^{i}_{t_1}-\gamma^{i}_{t_2}|^2
    }
    &
    %
      =
    \sqrt{
    \sum_{i=1}^{n-1}
    |\delta^{i}_0-\delta^{i}_1|^2
      }
      =
    \sqrt{
    \sum_{i=1}^{n-1}
    \left|\int_0^1 \dot\delta^i\right|^2
      }
      \leq
      \int_0^1
    \sqrt{
    \sum_{i=1}^{n-1}
      \left|
      \dot\delta^i
      \right|^2
      }
    \\
    %
    &
      \leq
      2
      \int_0^1
      |
      \dot\delta^n
      |
      =
      2(\delta^n_1
      -
      \delta^n_0)
      =
      2|\gamma^n_t-\gamma^n_r|
      .
  \end{align*}

  % 
  It follows that, for all $\tau\in[\alpha,\beta]$, there exists a
  unique $t\in[a,b]$, such that $\gamma_n(t)=\tau$ (if it were not
  unique, then~\eqref{E:causal-to-lipschitz} would contradict the injectivity of
  $\gamma$).
  %
  We can therefore define the reparametrization $\eta_\tau=\gamma_t$,
  so that $\tau=\gamma^n_t$.
  %
  This reparametrization is Lipschitz-continuous, because
  $|\eta^n_{\tau_1}-\eta^n_{\tau_2}|=|\tau_1-\tau_2|$, and
  \begin{equation}
    |\eta^i_{\tau_1}-\eta^i_{\tau_2}|
    =
    |\gamma^{i}_{t_1}-\gamma^{i}_{t_2}|
    \leq
    2|\gamma^{n}_{t_1}-\gamma^{n}_{t_2}|
    =
    2|\tau_1-\tau_2|
    .
    \qedhere
  \end{equation}
\end{proof}


