A Lorentzian pre-length space $(X,\sfd, \ll, \leq,\tau)$ is called
%
\begin{itemize}
\item \emph{non-totally imprisoning} if for every compact set $K\Subset X$ there is constant $C>0$ such that the $\sfd$-arc-length of all causal curves contained in $K$ is bounded by $C$;
\item  \emph{globally hyperbolic} if it is non-totally imprisoning and  for every $x,y\in X$ the set (called ``causal diamond'') $J^{+}(x)\cap J^{-}(y)$ is compact in $X$;
\item  \emph{geodesic} if for all $x,y\in X$ with $x \leq y$, $\Geo(x,y) \neq \emptyset $.
\end{itemize}
%
It was proved in~\cite[Theorem 3.28]{KS} that for a globally hyperbolic  Lorentzian geodesic (actually length would suffice) space $(X,\sfd, \ll, \leq,\tau)$, the time-separation function $\tau$ is finite and continuous.


The next useful result was proved by Minguzzi  (see~\cite[Corollary 3.8]{Minguzzi:23}).

\begin{proposition}\label{prop:GH-to-KGH}
Let $(X,\sfd, \ll, \leq,\tau)$ be a Lorentzian geodesic space. Then $X$ is globally hyperbolic if and only if
\begin{enumerate} 
\item[(i)]   for every $K_{1}, K_{2}\Subset X$ compact subsets,  the set (called ``causal emerald'')  $J^{+}(K_{1})\cap J^{-}(K_{2})$ is compact in $X$;
\item[(ii)]  the causal relation $\{x\leq y\}\subset X\times X$ is a closed subset (i.e.\;$X$ is causally closed).
\end{enumerate}
\end{proposition}
In the sequel we will use that global hyperbolicity implies (i) and (ii). Even if not used in the present work, the reverse implication is interesting at a conceptual level, as (i) and (ii) do not depend on $\sfd,\tau, \ll$, but only on the causal relation $\leq$ and on the topology induced by $\sfd$. \\


Using Proposition~\ref{prop:GH-to-KGH} (i),  it is readily seen that if $X$ is  globally hyperbolic and $K_{1}, K_{2}\Subset X$ are compact subsets  then 
\begin{equation}\label{I(K1K2)}
\fI(K_{1},K_{2},s)\Subset \bigcup_{t\in [0,1]}  \fI(K_{1},K_{2},t) \Subset X, \quad \forall s\in [0,1].
\end{equation}
%

We denote  with $\overline{C}$ the topological  closure (with respect to $\sfd$) of a subset $C\subset X$.




 In analogy to the metric setting, it is natural to introduce the next notion of timelike non-branching.

\begin{definition}[Timelike non-branching]\label{def:TNB}
A  Lorentzian pre-length space $(X,\sfd, \ll, \leq, \tau)$ is said to be \emph{forward timelike non-branching}  if and only if for any $\gamma^{1},\gamma^{2} \in \TGeo(X)$, it holds:
%
\begin{equation}\label{eq:defNonBranch}
\exists \;  \bar t\in (0,1) \text{ such that } \ \forall t \in [0, \bar t\,] \quad  \gamma_{ t}^{1} = \gamma_{t}^{2}   
\quad 
\Longrightarrow 
\quad 
\gamma^{1}_{s} = \gamma^{2}_{s}, \quad \forall s \in [0,1].
\end{equation}
It is said to be \emph{backward timelike non-branching} if the reversed causal structure is forward timelike non-branching. In case it is both forward and backward timelike non-branching it is said \emph{timelike non-branching}.
\end{definition}  

By Cauchy's Theorem, it is clear that if $(M,g)$ is a space-time whose Christoffel symbols are locally-Lipschitz (e.g.\ in case $g\in C^{1,1}$) then the associated synthetic structure is timelike non-branching. 



\begin{definition}[Measured Lorentzian pre-length space $(X,\sfd,  \mm, \ll, \leq, \tau)$]
A \emph{measured Lorentzian pre-length space} $(X,\sfd, \mm, \ll, \leq, \tau)$ is a Lorentzian pre-length space endowed with a Radon non-negative measure $\mm$ with full support, i.e.\ $\supp \, \mm=X$.
We say that $(X,\sfd, \mm, \ll, \leq, \tau)$ is globally hyperbolic (resp.\ geodesic) if $(X,\sfd, \ll, \leq, \tau)$ is so.
\end{definition}


Recall that a Radon measure $\mm$ on a  proper metric space $X$ is a Borel-regular measure which is finite on compact subsets. In this framework, it is well known  that Suslin sets  are $\mm$-measurable (see for instance~\cite[Section 1.6]{KrantzParks}). For the sake of this paper it will be enough to recall that   Suslin sets (also called analytic sets) are precisely images via continuous mappings of Borel subsets in complete and separable metric spaces (for more details see~\cite{KrantzParks, Srivastava}).

From now on, we make the standing assumptions that $(X,\sfd, \ll, \leq, \tau)$ is a globally hyperbolic Lorentzian geodesic  space
\fi

\section{Null synthetic setting}\label{Ss:mesures-on-H}


\subsection{Synthetic definitions}









In the general setting of topological causal spaces, the role of smooth 
null-hypersurfaces will be played by 
closed achronal sets where the causal relation does not trivialise in a sense that will be clarified later.

Among geometrically meaningful closed achronal sets, one can find, e.g.,
achronal boundaries and Cauchy horizons.
%
We recall below the definition of achronal boundary 
that is classical in the smooth literature, see for instance~\cite{Penrose-DiffTopGR, HawEll}.


\begin{definition}[Achronal boundary]
Let $(X,\ll,\leq,\mathfrak{T})$ be a topological causal space.
%
A set $H\subset X$ is an \emph{achronal boundary}  if 
there exists a set $S \subset X$ 
such that $H=\partial I^{+}(S)$.
\end{definition}



The next lemma shows that achronal boundaries are actually achronal, so the terminology is consistent.

\begin{lemma}\label{P:achronal-boundary}
  Let $(X,\ll,\leq,\mathfrak{T})$ be a topological causal space.
  %
  Then for any subset $S\subset X$, $\partial I^{+}(S)$ is achronal.
\end{lemma}
\begin{proof}
  Assume on the contrary that there exist $x,y\in \partial I^{+}(S)$,
  such that  $x\in I^-(y)$.
  %
  Since $I^-(y)$ is open, there exists an open neighborhood   $U\subset I^{-}(y)$ of $x$.
  %
  Since $x\in \partial I^{+}(S)$, then there exists
  $w\in U\cap I^{+}(S)$.
  %
  It follows that $w\ll y$ and thus, by transitivity of $\ll$, we get that  $y\in I^{+}(S)$, a contradiction.
\end{proof}

It is worth underlining that 
every maximal achronal set is an achronal boundary, see for instance~\cite[Theorem 2.97]{Minguzzi-Review2019}. Since 
achronal sets are subsets of their own achronal boundary, they 
provides the natural framework 
for a synthetic treatment of null geometry that  will take into account both the local and the global picture.


We  next define 
 the maximal and minimal elements of a closed achronal set $H$ with respect to
 the pre-order $\leq$, denoted below as $\finalWithH$ and $\initialWithH$ respectively. Such objects are well-known to be useful in the study of achronal boundaries  within  smooth space-times, see e.g.\;\cite[Section 6.3]{HawEll}, and in the analysis of the  $L^1$ optimal transport problem within metric spaces. 

%


%



\begin{definition}\label{D:maxmin}
Given a closed achronal set
$H$, the set of \emph{final} elements of $H$ is given by 
%
\[
  \finalWithH : =
  \{ m \in H \colon \ \nexists x \in H, \ m \leq x, \ x \neq m \}, 
\]
%
and the set of \emph{initial} elements of $H$ is given by 
%
\[
\initialWithH
: =
\{ m \in H \colon \ \nexists x \in H, \ x \leq m, \ x \neq m \}. 
\]
%
%
Then the achronal set without end-points is defined by 
\[
\noending{H} : = H \setminus  \left( \initialWithH \cup 
\finalWithH \right).
\]
Finally, the set of \emph{static} elements  of $H$ is given by
\[
\staticWithH : = \initialWithH \cap \finalWithH
.
\]
\end{definition}

In the sequel, whenever no confusion arises, we shall write
$\initial=\initialWithH$, and $\final$ and
$\static$ with the analogous meaning.

We briefly discuss 
the measurability of $\initial$ and $\final$. 


\begin{lemma}[]\label{L:measurable}
In a topological causal space $X$,
the sets $\initialWithH, \finalWithH, \staticWithH$,
and $H^\circ$ are Borel measurable.
\end{lemma}

\begin{proof}
Since the topology on $X$ 
is induced by a proper metric
and $J^{+}$ is closed, 
denoting by $\Delta = \{(x,x) \colon x \in X \}$, 
the set $J^{+} \setminus \Delta \cap H \times H$ is $\sigma$-compact, 
i.e., is countable union of compact sets.  
As projections of $\sigma$-compact set is $\sigma$-compact, 
writing
%
\[
\initial = H \setminus P_{2}\left( (J^{+} \setminus \Delta) \cap H \times H \right),
\]
%
we obtain  that $\initial$ is Borel measurable and the same conclusion is valid for $\final$ proving the  claims.
\end{proof}


\begin{remark}\label{R:intervalH}
If $\gamma : I \to H$ is any causal curve then 
$\gamma_I \cap 
\initial$ contains at most a single element:   
suppose by contradiction there are two of them, then one has to be in the causal future of the other giving a contradiction. The same is true for $\gamma_I \cap 
\final$. 


Hence $\gamma^{-1}(\initial)$ and 
$\gamma^{-1}(\final)$
are two closed intervals in $I$ 
on each of which $\gamma$ is constant. 
%
Therefore, without loss of generality we can assume that if $\gamma$ 
is a non-constant causal curve and if $I = [0,1]$, then $\gamma_{(0,1)} \subset \noending{H}$.
\end{remark}



We introduce the notion of gauge
function.
\begin{definition}\label{defn:gauge}
  Let $H$ be a closed  achronal set and let $G:\noending{H}\to\R$ be a Borel map. 
  %
  We say that $G$ is a \emph{gauge} function for $H$, if it satisfies the following properties:
  \begin{enumerate}
%  \item
%    $G=-\infty$ on $\initial$ and $G=+\infty$ on
%    $\final$;
  \item for any injective causal curve $\gamma$ in 
  $\noending{H}$,
    $G\circ \gamma$ is strictly increasing and continuous;
  \item for any causal curve $\gamma:[0,1]\to{H}$,
    such that $\gamma_{(0,1)}\subset \noending{H}$, then
    $\sup_{t\in (0,1)} G (\gamma_t)$ and 
    $\inf_{t\in (0,1)} G (\gamma_t)$ are both finite.
  \end{enumerate}
Finally a gauge function G is called \emph{proper}
if the pre-image of every compact set is precompact. 
\end{definition}


    Assumption (1) implies that 
    for any causal (possibly non injective) curve $\gamma$ in $\noending{H}$,
    $G\circ \gamma$ is non-decreasing
    and continuous.
    %
    This fact follows by reparametrizing $\gamma$. 
    %
    Assumption (2) above is needed in order to avoid possible
  blow-ups of the gauge, as the following example illustrates.
The concept of properness of a gauge will be used in \Cref{S:Penrose} to suitably reformulate the null completeness property. 


%\smallskip
In the smooth setting, a causal curve $\gamma:[0,1]\to H$  solves the geodesics equation if and only
if $G\circ\gamma$ is affine 
for a natural gauge $G$ (see \Cref{R:compatibility} below).
%
We take this last observation as the definition of a
causal null geodesic in the null synthetic setting.

\begin{definition}[$G$-Causal curves]\label{D:Gcausalcurve}
Let $H$ be a closed achronal set and let 
$G:\noending{H}\to \R$ be a gauge.
%
We say that a curve $\gamma:[0,1]\to H$ is \emph{$G$-causal}, if and only
if it is causal,  $\gamma_{(0,1)}\subset\noending{H}$,
and $G\circ \gamma|_{(0,1)}$ is an affine function.

The set of $G$-causal curves 
will be denoted by $\Caus_G\subset C([0,1]; H)$.  
\end{definition}

Sometimes, with a slight abuse of notation, we will consider
$G$-causal curves whose domain is not the interval $[0,1]$.


We are now in position to give the definition of synthetic null hypersurface.
%
We denote by $\M^{+}(H)$
the set of non-negative Radon measures on $H$.


\begin{definition}[Synthetic Null Hypersurface]\label{def:synthetic-null-hypersurface}
Let $(X,\ll,\leq,\mathfrak{T})$ be a topological causal space.
%
We say that the triple $(H,G, \mm)$ is a \emph{synthetic null hypersurface},
if
\begin{itemize}
    \item 
$H$ is
a closed achronal set, %such that $\overline{\noending{H}}=H,
\item 
$G:\noending{H}\to\R$ is a gauge for $H$,
\item $\mm\in\M^{+}(H)$ does not give postive mass to the static elements of $H$, i.e., $\mm(\static)=0$.
\end{itemize}
\end{definition}

\begin{remark}
The request of $\mm(\static)=0$ is necessary to avoid examples of closed achronal sets which do not have the geometry of a null hypersurface. For instance,  if $H$ is an acasual set (e.g., a spacelike hypersurface), then the set of static points will coincide with $H$ itself and therefore 
the only admissible measure 
to consider over $H$ in order to form a synthetic null hypersurface is $\mm\equiv 0$.
\end{remark}



\subsection{Compatibility with the smooth setting}\label{SS:CompatSyntNullHypers}


We next discuss the compatibility of the above synthetic constructions with the smooth
theory, by associating to a classical null hypersurface a synthetic
one.
%
This is the content of the following remarks.

\begin{remark}[Compatibility with the smooth setting: the global case]\label{R:compatibility}
We proceed by first discussing the global case, i.e., when a global smooth cross-section is available.
%
Let $H$ be a causal and achronal, smooth null hypersurface, admitting
 $S\subset H$ a global smooth cross-section for $H$.
 %
 Using the cross-section $S$, we can build a global null geodesic vector field
 $L$ over $H$ and the corresponding flow map
$\Psi_{L} : S \times \R \to H$.
%
A natural gauge function $G_{L,S}:H\to \R$
is then defined as the function such that $z=\gflow_L(p,G_{L,S}(z))$, for some
(unique) $p\in S$.  
%
To check that $G_{L,S}$ is indeed a gauge function, observe that
if $\gamma$ is a causal curve in $H$, then it lies in the generator of $H$ passing through $\gamma_0$ and, 
in particular, it must be of the form
$\gamma_t=\gflow(\gamma_0, s(t))$, 
for some non-decreasing function $s$.
%
Therefore $G_{L,S}(\gamma_t)=G_{L,S}(\gamma_0)+s(t)$, which is
non-decreasing.
%
If $\gamma$ is also injective, then $s$ must be strictly increasing.
%
Moreover, we point out that \emph{a causal curve is $G_{L,S}$-causal if and only 
if it is a null geodesic in $H$}.
%
Finally, as reference measure over $H$, we choose the rigged measure $\vol_L$ (see~\cite{CMM24a}).
%
A synthetic null hypersurface associated to $H$ is $(H, G_{L,S}, \vol_L)$.
%
\end{remark}

\begin{remark}[Compatibility with the smooth setting: the local case]\label{R:compatibility-local}
In several situations of interest (e.g., in the presence of recurring geodesics like the case of compact Cauchy horizons~\cite{MoncIsenCMP1983, BustReiGRG21, GuMinCMP2022})   a global cross-section for $H$ does not exist.
In these cases, it is possible to proceed via a local argument as follows. 

Let $(M,g)$ be a Lorentzian manifold and $U\subset M$ is any open set. For  $x,y\in U$, we set by definition $x \ll_U y$,  provided that there exists a $C^1$ curve 
$\gamma:[0,1]\to U$, connecting $x$ to $y$, such that $\dot \gamma$ 
is a future-directed timelike vector.
%
Notice that $\ll_U$ is (in general) strictly contained  in $\ll\cap\; (U\times U)$;
%
in a similar way we define $\leq_U$ and
%
denote by $\mathcal{T}_U$ the topology on $U$ induced by $\mathcal{T}$. 
%
We will write $X_U$ as a shorthand notation for the 
topological causal space $(U,\leq_U,\ll_U,\mathcal{T}_U)$; 
in particular $X_U$ is the topological causal space 
induced by the Lorentzian manifold $(U,g|_U)$.
%

Now if $H$ is a smooth null hypersurface, 
then for any $x\in H$, we can take a coordinated neighborhood $U$ for $x$.
%
Up to restricing $U$, we have that $H \cap U$ is causal, achronal and
closed and that
a cross-section $S$ is given by the intersection of $H$ and the
$0$-level set of the time coordinate.
%
We can thus apply the construction described in \Cref{R:compatibility}.
\end{remark}






