\subsection{Optimal transport and the synthetic \NEC\ \texorpdfstring{$\NC^{e}(N)$}{NCe(N)}}


A concept analogous to the one of optimal dynamical plan can be introduced in the
synthetic setting by means of the gauge function and the $G$-causal curves 
as follows. 
%
Firstly, given any two probability measures $\mu_0,\mu_1$, we introduce 
%
\[
\OptCaus^H(\mu_0,\mu_1) : = \{ \nu \in \mathcal{P}(C([0,1]; H)) \colon 
(e_0)_\sharp \nu = \mu_0, (e_1)_\sharp \nu = \mu_1, \ \nu(\Caus) = 1 \},
\]
%
where $\Caus \subset C([0,1]; H)$ is the closed subset of  causal curves and 
$e_{i} : C([0,1]; H) \to H$ are the evalutation map at $t = i$, with $i=0,1$.
We also recall the definition 
of the set of causal couplings
\[
\Pi_{\leq}(\mu_0,\mu_1)
= \{\pi \in \mathcal{P}(X\times X) \colon 
(e_{i})_\sharp \pi 
= \mu_{i}, 
\ 
i = 0,1
\}.
\]
In particular, 
$\OptCaus^H(\mu_0,\mu_1) \neq \emptyset$ only if $\Pi_\leq(\mu_0,\mu_1)\neq \emptyset$.
%
%
%
Notice that since $H$ is closed, as topological space $H$ is Polish and therefore $C([0,1]; H)$ is Polish with the topology of the uniform convergence.
In particular, every element of 
$\mathcal{P}(C([0,1]; H))$ is inner regular with respect to compact sets of 
$C([0,1]; H)$.

\begin{definition}
  Let $(H,G,\mm)$ be a synthetic null hypersurface and let $\mu_0,\mu_1\in \Prob(H)$ be
  two probability measures.
  Any $\nu\in\OptCaus^H(\mu_0,\mu_1)$ 
  is said to be \emph{$G$-causal} if
  and only if $\nu(\Caus_{G})=1$. The set of such $G$-causal plans $\nu$ is denoted by  $\OptGeo^G(\mu_0,\mu_1)$.
\end{definition}



%\smallskip
Given a synthetic null hypersurface $(H,G,\mm)$,
for $\mu \in \Prob({H})$, the Boltzmann--Shannon  
entropy $\Ent(\mu|\mm)$ of $\mu$ with respect to $\mm$ is defined by
\[
 \Ent(\mu|\mm) : = \int_{X} \rho \log(\rho) \, \mm
 \in [-\infty,+\infty),
\]
if $\mu = \rho \, \mm$ and $(\rho\log(\rho))_{+}$ is $\mm$-integrable;  
otherwise we set $\Ent(\mu|\mm) = +\infty$. 
We denote by
\[
\Dom(\Ent(\cdot|\mm)):=\{\mu\in \Prob(X): \Ent(\mu|\mm)\neq+\infty\}.
\]

Let us
consider the following dimensional variant of the Boltzmann--Shannon entropy: given $N>0$, 
for $\mu \in \Dom(\Ent(\cdot|\mm))$, define
%
\begin{equation}\label{eq:defSN}
\U_{N}(\mu|\mm) : = \exp\left(-\frac{\Ent(\mu|\mm)}{N} \right), 
\end{equation}
%
and set $\U_{N}(\mu|\mm) = 0$ otherwise. 
%
Such a functional $\U_{N}$ is well-known
in information theory as the Shannon entropy power (see, e.g.,~\cite{DCT-1991}; for instance, the entropy
power on $\R^N$ is the functional $\U_{N/2}$), 
and it was studied in connection to Ricci curvature bounds in~\cite{EKS}.


\begin{definition}[{$\NC^{e}(N)$ for synthetic null hypersurfaces}]\label{D:syntheticnull}
Let $N>0$. Let $(X,\ll, \leq, \mathfrak{T})$ be a topological causal
space.
%

The synthetic null hypersurface $(H,G,\mm)$ satisfies the \NEC\ $\NC^{e}(N)$ if and only if the following holds:
for all measures $\mu_0,\mu_1\in \Prob(H)$
such that 
$\Pi_{\leq}(\mu_0,\mu_1)\neq \emptyset$, 
there exists $\nu\in\OptGeo^G(\mu_0,\mu_1)$ 
%a $G$-causal monotone Wasserstein geodesic
%$(\mu_{t})_{t}$ connecting 
%$\mu_0$ to $\mu_1$
such that 
%
\begin{equation}\label{E:concavity}
  \U_{N-1}(\mu_{t}|\mm)
  \geq
  (1-t)
  \U_{N-1}(\mu_0|\mm)
  +
  t
  \U_{N-1}(\mu_1|\mm)
  , \quad \text{ for all }t\in [0,1],
\end{equation}
where $\mu_{t}:=(e_{t})_{\sharp}\nu$.
\end{definition}


We now collect two geometric consequences of \Cref{D:syntheticnull}. 
The first one is contained in the following

\begin{remark}[$\NC^e$ implies weak convexity]\label{R:absolutelycontinuous}
Note that if both 
$\mu_{0},\mu_{1}$ are not contained in $\Dom(\Ent(\cdot|\mm))$, then~\eqref{E:concavity} is trivially satisfied. 
On the other hand, if either $\mu_{0}$ or $\mu_{1}$ belongs to
$\Dom(\Ent(\cdot|\mm))$, then~\eqref{E:concavity} implies that,
for all $t \in (0,1)$,
$\mu_{t}$
is absolutely continuous with respect to $\mm$.

Notice also that if $x\leq y$ in $H$, then taking $\mu_0=\delta_{x}$, 
$\mu_1=\delta_{y}$, $\Pi_\leq(\mu_0,\mu_1)=\{\delta_{(x,y)}\}$.
%
\Cref{D:syntheticnull} implies that there exists $\nu\in\OptGeo^{G}(\mu_0,\mu_1)$, 
producing a $G$-causal curve from $x$ to $y$.
%
In other words, $H$ is weakly convex.
\end{remark}



We now prove that the sets of initial and 
final points can be neglected provided 
the set of $G$-causal curves satisfy the following compactness property: 
for $\mm$-a.e.\ $x\in H$ there exists a neighborhood $U$, such that $\mm(U)>0$ and 
the set 
\[
\{\gamma \in \Caus_{G} \colon \gamma_0 , \gamma_1 \in K \},
\]
%
is compact, where $K\subset U$ is any compact set. 
%
A synthetic null hypersurface $(H,G,\mm)$ satisfying such assumption 
will be said \emph{locally compact}.


This assumption is independent from the non-branching condition,
that is usually assumed in the literature  when that initial and final points have measure zero. 

\begin{proposition}\label{P:extrimal-negligible}
Let $(H,G,\mm)$ be a 
synthetic null hypersurface 
satisfying the \NEC\ 
$\NC^{e}(N)$, for some $N> 0$.
%
Assume $(H,G,\mm)$ to be locally compact.
%
Then 
%
\[
\mm(\initial)=\mm(\final)
  =
  0.
\]
%
\end{proposition}
\begin{proof}
It will suffice to prove that $\mm(\initial\setminus\final)
= 0$:
by assumption $\mm(\static)=0$ (see
%
  \Cref{def:synthetic-null-hypersurface})
  and therefore it will follow that
  $\mm(\initial)=0$.
  The remaining part is symmetric.

Suppose by contradiction
\begin{equation}
\mm(\initial\setminus\final) > 0.
\end{equation}
%
Define the function $A:\noending{H}\times \noending{H}\cap J\to \R$ as 
$A(x,y)=G(y)-G(x)\geq 0$.
%
Fix $\epsilon>0$ and consider the set 
\begin{equation}
    W_\epsilon
    :=
    \{
    (x,z,w)\in \initial\setminus\final
    \times \noending{H}
    \times \noending{H}
    \colon
    (x,z),(z,w)\in J,
    A(z,w)>\epsilon
    \}
    .
\end{equation}
%
The set $W_\epsilon$ is Borel.
%
It holds that 
\begin{equation}
    \initial\setminus\final
    =
    \bigcup_{\epsilon>0}
    P_1(W_\epsilon).
\end{equation}
The (contradiction) assumption gives  $\mm(P_1(W_\epsilon))>0$, for some $\epsilon>0$.
%
By inner regularity of $\mm$, there exists  a compact set  $K\subset P_1(W_\epsilon)$ with $\mm(K)>0$.
%
We define the following analytic set: 
%
\[
\Lambda: = P_{1,3}(W_\epsilon).
\]
%
By Von Neumann's selection Theorem (see for instance~\cite[Th.~5.5.2]{Srivastava}),
we  deduce that $\Lambda$ contains the graph of a measurable map $T$. 
%
Define the absolutely continuous measure 
$\mu_{0} : =  \mm\llcorner_{K}/ \mm(K)  \in \mathcal{P}(H)$ and 
$\mu_{1} : = T_{\sharp} \mu_{0}$ 
so that 
$({\rm Id},T)_\sharp \mu_0 \in \Pi_\leq(\mu_0,\mu_1)$.

Up to neglecting a set of small $\mu_0$-measure, we can also assume that 
$T$ is continuous and therefore  also $\mu_1$ 
can be assumed with compact support: 
hence we have deduced the existence of a compact set $K \subset H$ such that 
$\mu_0 (K) = \mu_1(K) = 1$.



\Cref{D:syntheticnull} gives then a measure
$\nu\in\OptGeo^G(\mu_0,\mu_1)$ such that
the function $t\mapsto \U_{N}((e_{t})_{\sharp}\nu)$ is concave.
By \Cref{R:absolutelycontinuous} $(e_{t})_{\sharp}\nu \ll \mm$. 

Fix any $x \in K$ and an open neighborhood $U$ of $x$ such that $\mu_0(U)>0$;
then we deduce the existence of $\bar t>0$ such that 
%
\[
\nu (\{\gamma \in \Caus_{G} \colon \gamma_0 \in U, \ \gamma_{t} \in U \} ) > 0.
\]
%
Indeed by continuity of causal curves, 
%
\[
\nu \otimes \mathcal{L}^1
\left(\left\{ (\gamma,t) \in \Caus_{G} \times (0,1) \colon \gamma_0 \in U, \gamma_{t} \in U \right\} \right) >0,
\]
%
then Fubini's Theorem implies the claim. 
Then, since $\nu$ is inner regular, 
there exists a compact set $\bar C$ such that
\[
\bar C \subset  \{ \gamma \in \Caus_{G} \colon
\gamma_0 \in U, \gamma_{\bar t} \in U\}, \quad
\text{with } \quad \nu(\bar C ) >0.
\]
Denote by $\bar \nu$ the renormalized restriction of $\nu$ to $\bar C$ and 
define the probability measures
\[
\bar \mu_0 : = (e_0)_\sharp \bar \nu,
\qquad \bar \mu_1 : = (e_{\bar t})_\sharp \bar \nu.
\]
By construction, they are causally related 
and both concentrated on a compact set inside $U$. 
Since $U$ was arbitrary, we can take as $U$ the one additional
verifying the local compactness hypothesis and deduce the existence of a measure
$\eta \in\OptGeo^G(\bar \mu_0,\bar \mu_1)$ such that
the function $t\mapsto \U_{N}((e_{t})_{\sharp}\bar \nu)$ is concave and   $\eta(C) = 1$, 
for some compact set $C$.

For each $t\in [0,1]$, denote now by $C_{t} : = e_{t}(C)$. Notice that each 
$C_{t}$ is a compact set, $C_{t}$ converges to $C_0$ in Hausdroff topology 
as $t \to 0$ and  
$C_0 \subset \initial\setminus\final$.
Finally, by the entropy inequality~\eqref{E:concavity} and a double Jensen's inequality we have
%
\[
\mm(C_{t})^\frac{1}{N-1} \geq \U_{N-1}(\mu_{t}|\mm)
  \geq
  (1-t)
  \U_{N-1}(\mu_0|\mm)
  =
  (1-t)\mm(C_0)^\frac{1}{N-1}.
\]
%
Then we reach a contradiction as follows. 
Since $C_0$ is a subset of initial points, necessarily $C_{t} \cap C_0 = \emptyset$; 
 by Hausdorff convergence for each $\ve >0$ 
 for $t$ sufficiently close to $0$ we have 
\[
\mm((C_0)^\ve)
\geq 
\mm(C_0 \cup C_{t})= 
\mm(C_0) +\mm( C_{t}) 
\geq (1+ (1-t)^N)\mm(C_0).
\]
Hence letting $t \to 0$ and then $\ve \to 0$ 
we reached a contradiction and proved the claim.
\end{proof}



Following the discussion on the compatibility of the notion of synthetic null hypersurfaces  with the smooth one
(see \Cref{R:compatibility}), we also report the
compatibility of the classical NEC with the synthetic $\NC^e(N)$ condition (see \Cref{D:syntheticnull}),
established in the authors' previous work~\cite{CMM24a}. 






\begin{theorem}[Compatibility of $\NC^e$ with the smooth NEC]\label{thm:compatibilityNEC-NCe}
  Let $(M,g)$ be a Lorentzian manifold of
  dimension $n$.
  %
  Let $H\subset M$ be a $C^2$ null hypersurface. 
  %
  Assume that the classical NEC is valid along $H$,
        i.e., $\Ric(w,w)\geq 0$, for any normal vector $w$ to $H$.
    Then the following two properties hold: 
     \begin{enumerate}
     \item\label{Item:NCGlob} 
  For any open set  $U\subset M$, if $H\cap U$ is closed in $U$
 and admits a global cross-section $S$ with respect to $\leq _{U}$, then
 the synthetic null hypersurface $(H\cap U,\vol_{L}, G_{L,S})$ 
 in $X_{U}$ defined in \Cref{R:compatibility} satisfies 
 $\NC^e(n)$.

% \smallskip 
 \item\label{Item:NCLoc} 
 For any $x\in H$, there exists a neighborhood $U$ 
 of $x$ in $M$, such that
 the synthetic null hypersurface $(H\cap U,\vol_{L}, G_{L,S})$ in $X_{U}$
 defined in \Cref{R:compatibility-local}
  satisfies 
 $\NC^e(n)$.
 \end{enumerate}

\end{theorem}
\begin{proof}
Part~\ref{Item:NCGlob} follows by~\cite[Theorem~1.6]{CMM24a}. The implication~\ref{Item:NCGlob} $\implies$~\ref{Item:NCLoc}:
is the content of \Cref{R:compatibility-local}.
\end{proof}



We now complement \Cref{thm:compatibilityNEC-NCe} by showing that the classical 
NEC is also compatible with the synthetic $\NC^e$ along achronal boundaries, 
without any further regularity assumption.  Recall that achronal 
boundaries  fall within the class of synthetic null hypersurfaces, see \Cref{R:compatibility-penrose}.


\begin{theorem}\label{T:compatibility-penrose}
  Let $(M,g)$ be a Lorentzian manifold of
  dimension $n$.
  %
  Assume $M$ to be causally closed and strongly causal.
  %
  Let $A\subset M$ be a $C^2$ achronal, space-like sub-manifold of
  codimension $k\geq 2$.
  %
  Let $H:=\partial I^{+}(A)$.
  %
    Assume that the classical NEC is valid on $H$, i.e.,
  $\Ric(w,w)\geq 0$, for any
  light-like vector $w\in TH$ at the differentiability points of $H$.


  Then the synthetic null hypersurface $(H,G,\mm)$, as defined in
  \Cref{R:compatibility-penrose}, satisfies $\NC^e(n)$.
\end{theorem}
\begin{proof}
The claim is a consequence of \Cref{T:localization} and the constructions performed in \Cref{R:compatibility-penrose}, to which we refer for the notation. For the sake of brevity, we outline the argument, omitting some straightforward technical details. 

Recall the definition~\eqref{eq:defhatH} of $\hat{H}$ as a $C^2$-submanifold of $TM$ endowed with the measure $\hat\mm$ locally given by~\eqref{eq:defhatmmloc}. By its very definition, $\hat{H}$ is a ruled submanifold, generated by the future pointing light-like vectors $v\in \normal\initial$. It is convenient to parametrize such generators on a suitable set $Q$ of indices, that can be identified with a suitable measurable subset of $\hat H$.
  %
  We disintegrate the measure $\hat\mm$ on $\hat{H}$ along such generators of $\hat H$, as
  follows
  \[
    \hat\mm
    =
    \int_{Q}
    \hat \mm_\alpha
    \,
    \qq(\de\alpha),
  \]
 where $\qq$ is a probability measure on $Q$, and each measure $\hat \mm_\alpha$ is concentrated on the future pointing half-line generated by $v_\alpha, \; \alpha \in Q$.
  %
  Since the exponential map does not mix such generators, we can also
  disintegrate the measure $\mm$, as
  follows
  \begin{equation}
    \mm
    =
    \int_{Q}
    \exp_{\sharp}
    (\hat\mm_\alpha\llcorner_{B})
    \,
    \qq(\de\alpha).
  \end{equation}
  %
  Fix a vector $v\in \hat H$. Consider the  $C^2$ null hypersurface $H_{v}$ defined in \eqref{eq:defHv}
  and its rigged measure $\vol_{L^v}$. Since $H_{v}$ is $C^2$, then 
  $\Ric(w,w)\geq 0$ for all light-like $w\in TH_{v}$ in the 
  differentiability points of $H$. Moreover $H$ is a locally-Lipschitz sub-manifold, then a.e.\;differentiable. It follows that 
  \[\Ric(w,w)\geq 0, \quad \text{for all } w\in TH_{v}|_{H}.\]
  %
  By disintegrating the rigged measure $\vol_{L^v}$ along the above family of generators, we get
  \[
    \vol_{L^v}
    =
    \int_{Q}
    \vol_{L^v,\alpha}
    \qq(\de\alpha)
    .
  \]
  %
  For $\qq$-a.e.\;$\alpha\in Q$, the conditional measure $\vol_{L^v,\alpha}$ is absolutely continuous w.r.t.\;the
  1-dimensional Lebesgue measure on the corresponding generator, with density $a_{L^v,\alpha}$. 
  %
  By~\cite[Theorem~5.11]{CMM24a}, such densities satisfy 
  \begin{equation}\label{eq:DiffIneqaLvalpha}
    (a_{L^v,\alpha})''(t)
    +
    \frac{((a_{L^v,\alpha})'(t))^2}{n-2}
    \leq
%    -\Ric_{x}(L^v,L^v)
    0
    ,
    \quad
    t=-g(W,(\exp|_{U_{v}})^{-1}(x))
    ,
    \quad
    \forall x\in H_{v}\cap H
    .
  \end{equation}
  %
  Since locally the measure $\mm$ coincides with $\vol_{L^v}$, the uniqueness of the disintegration implies that the conditional measure $\exp_{\sharp}
    (\hat\mm_\alpha\llcorner_{B})$ has density $a_{L^v,\alpha}$, for $\qq$-a.e.\,$\alpha\in Q$.
  %
  For $v_1,v_2\in \hat{H}$, one can check that 
  \[
  a_{L^{v_1},\alpha}(t)
  = 
  a_{L^{v_2},\alpha}(t)
  ,
  \qquad
  t=-g(W,u)
  ,
  \qquad
  u\in U_{v_1}\cap U_{v_2}
  .
  \]
  %
  Therefore, the disintegrated measures can be glued, finding that $\exp_{\sharp}(\hat\mm_\alpha\llcorner_{B})$ is absolutely continuous, w.r.t.\;the Lebesgue
  measure, with density $a_{\alpha}$ satisfying the differential inequality~\eqref{eq:DiffIneqaLvalpha}. The conclusion now follows from \Cref{T:localization}.
  %
%  On $B$, this density satisfies $a_\alpha''\geq(a_\alpha')^2/(n-2)$.
  %
  %
\end{proof}




