\section{Equivalence relations for measures and gauges}\label{Sec:CovarianceGaugeMeas}

In the smooth setting, the measure $\mm_{L}$ and
the gauge $G_{L,S}$ depend on the choice of the
vector field $L$.
Therefore,  a priori \Cref{D:syntheticnull} might
depend on these choices as well.  One of the goals of our previous work~\cite{CMM24a} was to show the independence of the $\NC^e$ condition from such a choice. 
%
The goal of this section is to show such independence  also in this 
more general setting.


%\smallskip
In this section, we consider a given topological causal space 
$(X,\ll, \leq, \mathfrak{T})$ and
all the synthetic null hypersurfaces will be subsets of $X$.
%




%\smallskip
Over $\noending{H}$ 
we can define two equivalence relations, one for measures
and one for gauges. 
%
Firstly we recall the concept of transverse function that in
the smooth setting can be given by asking $f$ to be constant along 
the generators of the null hypersurface.
%
Since this characterization can be stated without referring to 
the smooth structure, it is natural to consider it also in our framework. 

\begin{definition}[Transverse function]
Let $H$ be a closed achronal set. 
  %
A function $f:\noending{H}\to\R$ is transverse
if, for any causal curve $\gamma$ in $\noending{H}$, $f\circ \gamma$ is constant.
\end{definition}

%\smallskip

In the smooth setting, if $L_1,L_2\in\vfield(\normal H)$ are two null
geodesic vector fields, then $L_1=\phi L_2$ for some transverse
function $\phi$ and
%
the relation between the two rigged measures is $\vol_{L_1}=\frac{1}{\phi}
\vol_{L_2}$.
%
Accordingly, we identify measures which are equivalent up to multiplication by a transverse function.
%
\begin{definition}[Equivalence relation for measures]\label{D:equivm}
Let $H$ be a closed achronal set
and $\mm_1,\mm_2\in\M^{+}(H)$ be two measures.
% concentrated on $\noending{H}$. 
%
We set $\mm_1\sim\mm_2$ 
if and only if 
\[
%\iffalse
 %\mm_1\llcorner_{H\setminus\noending{H}}
%=\mm_2\llcorner_{H\setminus\noending{H}}
%\quad 
%\fi
\mm_1\llcorner_{H\setminus\noending{H}}
=
\mm_2\llcorner_{H\setminus\noending{H}} \quad \text{and}\quad 
\mm_1\llcorner_{\noending{H}}=f\mm_2\llcorner_{\noending{H}},
\]
for some
strictly positive transverse function $f$.
%
\end{definition}
%



Continuing the analogy with the smooth setting, 
the definition of
$G_{L,S}$ is  depending both on $L$ and $S$
but the only relevant aspect of the theory is the set $G$-causal curves.
%
We therefore introduce an equivalence relation also between gauges. 

\begin{definition}[Equivalence relation for gauges]\label{D:equivG}
  Let $H$ be a closed achronal set and 
  %
  let $G_1,G_2:\noending{H}\to\R$ be two gauges. 
  We set
  $G_1\sim G_2$ if and only if $\Caus_{G_1}=\Caus_{G_2}$ (see 
  \Cref{D:Gcausalcurve}).
\end{definition}


%
Next we prove that 
the $\NC^e(N)$ condition
is well defined for equivalence classes of gauges and reference measures, i.e.,\ the $\NC^e(N)$ condition
does not
depend on the choice of the measure and the gauge inside the respective
equivalence classes.
%


\begin{proposition}\label{lem:integral-transverse}
  Let $H$ be a closed achronal set, let $\nu\in\OptCaus^H(\mu_0,\mu_1)$ for a
  pair of  probability measures $\mu_0,\mu_1\in \Prob(H)$ which are 
  concentrated on $\noending{H}$. 

  Set $\mu_{t}:=(e_{t})_{\sharp}\nu$. Then, for every transverse function   $f:\noending{H}\to\R$, it holds that
  \begin{equation}
    \label{eq:integral-transverse}
    \int_{H}
    f
    \,\de\mu_{t}
    =
    \int_{H}
    f
    \,\de\mu_{s}
    ,
    \qquad
    \text{ for all }
    t,s\in[0,1]
    .
  \end{equation}

  If moreover $f$ is non-negative and the integrals
  above are equal to $1$,
  %
  defining $\tilde \mu_{t}:= f\mu_{t}$,
  %
  then 
  $\tilde\nu:=(f\circ e_0)\, \nu \in\OptCaus^H(\tilde\mu_0,\tilde\mu_1)$ 
  and $\tilde\mu_{t}=(e_{t})_{\sharp}\tilde\nu$.
\end{proposition}

\begin{proof}
  Since
  $f$ is transverse, then $f\circ\gamma$ is constant for all
  $\gamma\in \Caus_{H}$, such that $\gamma_{[0,1]}\subset\noending{H}$,
  therefore, since  $\nu(\Caus_{H})=1$,
   we can compute
  \begin{equation*}
    \int_{H}
    f
    \,\de\mu_{t}
    -
    \int_{H}
    f
    \,\de\mu_{s}
    =
    \int_{C([0,1];H)}
    (
    f\circ e_{t}-
    f\circ e_{s}
    )
    \,
    \de \nu
    =0
    .
  \end{equation*}
%
For the second part, a direct computation gives
\begin{equation*}
    \tilde\mu_{t}=f\mu_{t}
    =
    f(e_{t})_{\sharp}(\nu)
    =
    (e_{t})_{\sharp}(f\circ e_{t} \nu)
    =
    (e_{t})_{\sharp}(f\circ e_0 \nu)
    =
    (e_{t})_{\sharp}(\tilde\nu).
    \qedhere
  \end{equation*}
\end{proof}



\begin{proposition}\label{P:convexity-invariance}
Let $H$ be a closed achronal set, $\nu\in\OptCaus^H(\mu_0,\mu_1)$ for a pair of  probability measures $\mu_0,\mu_1\in \Prob(H)$ concentrated on $\noending{H}$ and  
let $\mm_1,\mm_2\in\M^{+}({H})$  such that $\mm_1\sim\mm_2$.


Then the function $t\mapsto \Ent(\mu_{t}|\mm_1)-\Ent(\mu_{t}|\mm_2)$ is constant.
\end{proposition}

\begin{proof}
  Let  $f$ be any transverse function such that 
  $\mm_1 = f \mm_2$ and
   $\rho_{k,t}$ be the density of $\mu_{t}$ w.r.t.\ 
   the measure
  $\mm_{k}$, $k=1,2$.
  %
  Since $\rho_{2,t}=\rho_{1,t}f$, a direct
  computation gives
  \begin{align*}
    \Ent(\mu_{t}|\mm_{2})
    &
    =
    \int_{H}
    \log(\rho_{2,t})
    \,
    \de\mu_{t}
    =
    \int_{H}
    \log(\rho_{1,t})
    \,
    \de\mu_{t}
    +
      \int_{H}
    \log f
    \,
      \de\mu_{t}
    \\
    %
    &
      =
      \Ent(\mu_{t}|\mm_{1})
    +
      \int_{H}
    \log f
    \,
    \de\mu_{t}
      \stackrel{\text{\eqref{eq:integral-transverse}}}{=}
      \Ent(\mu_{t}|\mm_{1})
    +
      \int_{H}
    \log f
    \,
    \de\mu_0
      .
      \qedhere
  \end{align*}
\end{proof}


The next result follows straightforwardly from the propositions above.

\begin{theorem}\label{T:invariance-NC-locally-compact}
Let $N>0$ and $(X,\ll, \leq, \mathfrak{T})$ be a topological causal space.
Consider a closed achronal set $H$,
two measures $\mm_1,\mm_2\in\M^+(H)$ and two gauges $G_1,G_2$ 
forming two locally compact synthetic null hypersurfaces $(H,G_1, \mm_1)$ and 
$(H,G_2, \mm_2)$. 
%

If $\mm_1\sim \mm_2$ and $G_1\sim G_2$, 
then $(H,G_1, \mm_1)$ satisfies the $\NC^e(N)$ condition
  if and only if $(H,G_2, \mm_2)$ does.
\end{theorem}

\begin{proof}
  Assume $(H,G_1,\mm_1)$ to be $\NC^e(N)$.
  %
  By~\Cref{P:extrimal-negligible},
  $\mm_1(H\setminus \noending{H})=0$, thus
  $\mm_2(H\setminus \noending{H})=0$.
  %
  This means that the only relevant probability measures for the
  $\NC^e(N)$ condition are the ones concentrated on $\noending{H}$.
  %
  Then \Cref{P:convexity-invariance} implies that also $(H,G_2,\mm_2)$
  satisfies $\NC^e(N)$.
\end{proof}







