\section{The geometry of synthetic null hypersurfaces}\label{S:decomposition-null-hypersurface}
%

This section investigates more in details the geometry of synthetic null hypersurfaces, starting with relations between gauges and causal curves. 

%
In this section we will often assume the closed achronal set to be weakly convex;  this assumption is justified by \Cref{R:absolutelycontinuous}.

\begin{proposition}\label{P:G-parametrization}
  Let $H$ be a closed achronal set, $G$ be a gauge and $\gamma : [0,1] \to H$ be a
  causal curve.
  %
  Then there exists a reparametrization of $\gamma$ which is
  $G$-causal.
\end{proposition}

\begin{proof}
By \Cref{R:intervalH} 
we can assume without loss of generality that 
$[0,1]\backslash\gamma^{-1}(\noending{H})\subset\{0,1\}$. 
Also assuming
$\gamma|_{(0,1)}$ injective is not restrictive.
%
Define $l(t):=G(\gamma_{t})$ and notice that by construction $l$ is strictly increasing.
  % 
%therefore $l|_{(0,1)}$ is uniformly continuous.
%
Let $(a,b):=l((0,1))$
and $m:(a,b)\to[0,1]$ be the inverse of $l|_{(0,1)}$.
  %
Define $\eta:=\gamma\circ m:(a,b)\to H$.
%
This function is continuous.
  %
  At this point extend $\eta$ by declaring that $\eta_{a}:=\gamma_0$ and
  $\eta_{b}=\gamma_1$.
  %
  To check that this function satisfies the desired properties is trivial.
\end{proof}

\begin{example}
  Consider the Minkowski space $\R^2$ ($t$ is the time variable, $x$
  is the space variable).
  %
  Let $H$ be the future light cone.
  %
  Let $G:H\to \R$ given by $G(x,t)=\log t$.
  %
  This function fails hypothesis (2) in the definition of gauge.

  Let $\gamma:[0,1]\to H$ be given by $\gamma_{r}=(r,r)$.
  %
  There is no reparametrization of $\gamma$ such that its
  post-composition with $G$ is affine.
\end{example}



It is then immediate to obtain the following

\begin{corollary}
Let $H$ be a weakly convex closed achronal set, $G$ be a gauge and
  $x,y\in {H}$.
  %
If $x\leq y$, $x\neq y$, then there exists a $G$-causal curve connecting $x$ to $y$.
\end{corollary}

\begin{proposition}\label{P:not-causally-related}
Let $H$ be a weakly convex closed achronal set and $G$ be a gauge for $H$.
%
Let $x,y\in \noending{H}$ be such that $G(x)=G(y)$.

Then either $x=y$ or $x$ and $y$ are not causally related. 
\end{proposition}

\begin{proof}
Assume that $x\neq y$
and, without loss of
generality, that $x\leq y$.
  %
Then by weakly convexity of $H$ there exists $\gamma$, a causal
curve connecting $x$ to $y$, that, up to reparametrization, we can assume to be injective.
%
Then $G\circ \gamma$ is strictly increasing
giving a contradiction.
\end{proof}


\begin{proposition}\label{P:Hcausal}
  Let $H$ be a weakly convex closed achronal set admitting a gauge $G$.
  %
  Then $H$ is causal, that is $\leq$ is a partial order relation over $H$ (or, equivalently, $H$ does not contain  causal loops).
\end{proposition}

\begin{proof}
  Assume by contradiction the existence of a non-constant causal curve 
  $\gamma : [0,1] \to H$ with $\gamma_0= \gamma_1$. 
  Without loss of generality $\gamma_0 \neq \gamma_{1/2}$ and $\gamma_{1/2} \neq \gamma_1$. 
  %
  By definition of end points, 
  $\gamma([0,1])\subset \noending{H}$
  and by \Cref{P:G-parametrization} $\gamma$ can be assumed to be $G$-causal.

  Since $\gamma_0=\gamma_1$ and $G\circ \gamma$ is monotone, then $G\circ\gamma$ is constant. Thus
  $\gamma$ itself is constant by \Cref{P:not-causally-related}, giving a
contradiction.
\end{proof}





\subsection{Null non-branching and first properties}

Assuming that branching phenomena do not occur within $H$ permits to deduce much more on the structure of the achronal set. 
We start giving the definition of null non-branching.

\begin{definition}
Let $H\subset X$ be a closed achronal set. We say that $H$  is \emph{forward null non-branching} if the following holds. 
For every pair of injective
causal curves $\gamma^{1},\gamma^{2} : [0,1] \to
H$, such that $\gamma^1_0=\gamma^2_0$ and $\gamma^1_{1/2}=\gamma^2_{1/2}$,
then 
either $\gamma^{1}_{[0,1]} \subset \gamma^{2}_{[0,1]}$ or
$\gamma^{2}_{[0,1]} \subset \gamma^{1}_{[0,1]}$.

We say that $H$ is \emph{backward null non-branching} if $H$ is
forward null non-branching in the causally reversed space.

We say that $H$ is \emph{null non-branching} if it is both forward
and backward null non-branching.
\end{definition}

The next two propositions guarantees that the null non-branching condition
is available for a broad class of Lorentzian manifolds.

