  %
  By taking the limit as $\epsilon\to 0$, we obtain that any
  restriction of
  $\gamma|_{(0,1)}$ to a closed interval is causal.
  %
  Since $\gamma$ is continuous at the endpoints, we conclude.
\end{proof}

We prove that the sets of initial and final points are
negligible without the local compactness assumption (see \Cref{P:extrimal-negligible}) but assuming instead the non-branching condition. 


\begin{theorem}\label{T:initialpoints}
Let $(H,G,\mm)$ be a null non-branching synthetic null hypersurface 
satisfying the \NEC\ 
$\NC^{e}(N)$, for some $N> 0$.
%
Then 
%
\[
\mm(\initial)=\mm(\final)
  =
  0
.
\]
%
\end{theorem}

\begin{proof}
The first part of the proof repeats verbatim the one of \Cref{P:extrimal-negligible}. Hence, 
we will argue by contradiction that $\mm(\initial\setminus\final)
> 0$ 
and deduce the existence 
of continuous map map $T : K \to H$, with $K\subset \initial\setminus\final$ of positive $\mm$-measure. 
%
Define the absolutely continuous measure 
$\mu_{0} : =  \mm\llcorner_{K}/ \mm(K)  \in \mathcal{P}(H)$ and 
$\mu_{1} : = T_{\sharp} \mu_{0}$ 
so that 
$({\rm Id},T)_\sharp \mu_0 \in \Pi_\leq(\mu_0,\mu_1)$.

\Cref{D:syntheticnull} gives then a measure
$\nu\in\OptGeo^G(\mu_0,\mu_1)$ such that
the function $t\mapsto \U_{N}((e_{t})_{\sharp}\nu)$ is concave.
By \Cref{R:absolutelycontinuous} $(e_{t})_{\sharp}\nu \ll \mm$. 
However, since $\mu_{0}$ is concentrated on the set of initial points $\initial$, necessarily $(e_{t})_{\sharp}\nu \perp (e_{s})_{\sharp}\nu$ for all $s \neq t$, 
giving a contradiction with the $\sigma$-finiteness of $\mm$:
indeed, suppose by contradiction that there exist two causal curves $\gamma^1, \gamma^2$,
such that $\gamma^1_{t}=\gamma^2_{s}$, with $1>t> s$ but $\gamma^1_0,\gamma^2_0\in K$.
%
Then by the null non-branching assumption 
($\gamma^1_{t}$ is not a final point),
necessarily $\gamma^2_{(0,1)}\subset \gamma^1_{(0,1)}$.
%
Hence, $\gamma^2_0$ cannot be an initial point, 
giving a contradiction.
\end{proof}

\begin{remark}\label{R:invariance-NC-non-branching}
As a consequence of \Cref{T:initialpoints}, we can prove 
that, under the null non-branching assumption, the $\NC^e(N)$ condition is independent of
the representative in the equivalence class of gauge and  measure.
%
That is, one can prove the same conclusion of \Cref{T:invariance-NC-locally-compact}, 
under the null non-branching assumption, in place of local compactness of the gauge.
\end{remark}




\subsection{Ray decomposition of achronal sets and disintegration}
We fix the following definition: the set $\mathcal{R} : = (J \cup
J^{-1})\cap (H\times H)$ will be called the \emph{transport relation}. 


\begin{proposition}\label{L:Requivalence}
  Let $H$ be a null non-branching, weakly convex closed achronal set.
  %
  Then $\relation$ is an equivalence relation on $\noending{H}$.
\end{proposition}

\begin{proof}
The symmetric and reflexive properties are trivially verified. We are therefore only left with checking the transitive property. 

Suppose then $(x,y), (y,z) \in \mathcal{R}$. 
Without any loss of generality we can assume that all these points are
different and that $x \leq y$ and $z \leq y$ (the other cases are either trivial or equivalent to this one). 
%
Assume on the contrary that neither $x\leq z$, nor $z\leq x$.
%
Let $p\in J^{+}(y)\cap H$, such that $p\neq y$.
%
Let $\gamma$ and $\delta$ be two curves connecting $x$ and $z$
(respectively) to $p$, passing through $y$.
%
Up to reparametrizing we can assume that $\gamma_{1/2}=\delta_{1/2}=y$, a
contradition with the backward non-branching-ness.
\end{proof}

If $\alpha\in \noending{H}$, we will denote by $\noending{H}_\alpha$
the equivalence class containing $\alpha$, also called ray:
\begin{equation}
  \noending{H}_\alpha
  :=
  \{
  x\in \noending{H}
  :
  (x,\alpha)\in\relation
  \}
  .
\end{equation}
%
We will denote by ${H}_\alpha$ the ray with
end-points:
\begin{equation}
  {H}_\alpha
  :=
  \{
  x\in H
  :
  (x,\alpha)\in\relation
  \}.
\end{equation}
%
The set $H_\alpha$ is closed, because $\relation$ is closed.
%
We will denote by $ \overline{\noending{H}_\alpha}$ the topological
closure of $ \noending{H}_\alpha$ in $H$.
%
By definition of closure $\overline{\noending{H}_\alpha}\subset
H_\alpha$.








\iffalse%
\begin{proposition}
  The set $H(S)$ is causal.
\end{proposition}
\begin{proof}
  Assume on the contrary that there exists a closed causal curve
  $\gamma$.
  %
  Let $x=\gamma_0=\gamma_1\in H(S)$ and $y=\gamma_{t}\neq x$, for some
  $t\in(0,1)$.
  %
  Since $\gamma_{[0,t]}$ connects $x$ to $y$, then $x\final$
\end{proof}
