\begin{remark}
As a consequence of non-branching, each of the sets $H_\alpha\cap\initial$
and $H_\alpha\cap\final$ contains at most one element.
%
Therefore, $\overline{\noending{H}_\alpha}=H_\alpha$.
%
Indeed, by contradiction assume
$\{x\}= H_\alpha\cap \initial\setminus \overline{\noending{H}_\alpha}$.
%
Since $x\leq \alpha$, by weakly convexity of $H$, there exists a $G$-causal curve $\gamma$ connecting $x$ to $\alpha$.
%
Since $\gamma_{t}\in \noending{H}_\alpha$, $t>0$, then $x=\gamma_0$ can be approximated by points in $\noending{H}_\alpha$.
\end{remark}




Since the causal relation $\mathcal{R}$ is  induced by $\leq$, we obtain the following consequence of 
\Cref{L:Requivalence}.


\begin{proposition}\label{C:parametrization}
Let $H$ be a null non-branching, weakly convex closed achronal set,
admitting a gauge $G$.
%
Then each equivalence class with end-points 
of $\mathcal{R}$ inside $H$ is contained in the image 
of a causal curve. 
\end{proposition}
\begin{proof}
Fix $\alpha\in\noending{H}$.
%
Consider the set
\begin{equation}
\zeta : = \{ (s, z )\in  \R \times \noending{H}_\alpha \colon  G(z) = s +G(\alpha)  \}
\end{equation}
%
Let $I:=P_1(\zeta)\subset \R$.
%
We want to see that the set $\zeta$ is the graph of a $G$-causal
curve covering all $\noending{H}_\alpha$.
%
By \Cref{P:not-causally-related}, for any $s$ there exists at most one $z\in\noending{H}_\alpha$, such that $G(z)=s$.
%
We need to see that $I$ is an interval, i.e., that $I$ is connected.
%
Given $s,t\in I$, there exist $x,y\in \noending{H}_\alpha$, such that $(s,x),(t,y)\in\zeta$.
%
Thus either $x\leq y$ or $y\leq x$.
%
Take $\gamma$ a causal curve connecting $x$ to $y$, contained in $\noending{H}_\alpha$.
%
By continuity of $G\circ \gamma$, $I$ contains all the elements between $s$ and $t$
, hence it is an interval. 
%
Therefore, $\zeta$ is the graph of a function $\eta:I\to \noending{H}_\alpha$ and $\eta$ satisfies $G(\eta_{t})=G(\alpha)+t$.

It holds that $\eta_{s}\leq \eta_{t}$, for all $t\leq s$, therefore we can apply 
\Cref{P:characterization-G-causal} and deduce that $\eta$ is $G$-causal.
%
Finally, for any point $w\in \noending{H}_\alpha$, $(G(w)-G(\alpha),w)\in \zeta$, 
therefore $\eta_{I}=\noending{H}_\alpha$. 


%

We now extend $\eta$ in order to cover the endpoints.
%
If $\initial\cap H_\alpha$ is empty there is nothing
to do, thus we consider $x\in\initial\cap H_\alpha$.
%
Let $\delta:[0,1]\to H$ be the $G$-causal
curve connecting $x$ to $\alpha$.
%
Let $r:=\inf_{t>0} G(\delta_{t})$.
%
We claim that $\inf I=r$.
%
If $\inf I<r$, then one can take the curve starting from
$\eta_{r-\epsilon}$, for $r-\epsilon\in I$, passing through $\delta_{1/2}$,
and reaching $\delta_1$, obtaining a contradiction; the other inequality
is trivial.
%
We can therefore define $\eta_{r}:= x$.
%
Both $G\circ \eta$ and $G\circ\delta$ are affine and increasing functions, thus 
$T:=(G\circ\delta)^{-1}\circ(G\circ\eta)$ 
is affine and increasing.
%
Since $G(\eta_{t})=G(\delta_{T(t)})$, for $\eta>r$, by defintion of $\zeta$ and $\eta$, we deduce $\eta_{t}=\delta_{T(t)}$, $t>r$.
%
As a consequence $\lim_{t\to r^+}\eta_{t}=\lim_{s\to 0^+} \delta_{s}=x$, proving 
that $\eta$ is continuous in $r$, and therefore causal.
%
\end{proof}





Notice that in~\Cref{C:parametrization} we have constructed a parametrization 
of each equivalence class with $G$-speed equal to one. 
%
We define the map $\gflow_{G}:\dom(\gflow_{G})\subset \noending{H}\times \R\to \noending{H}$, as the
map whose graph is given by
\begin{equation}
  \Graph(\gflow_{G})
  =
  \{
  (x,t,y):
  G(y)-G(x)=t
  \}
  .
\end{equation}
%
Following \Cref{C:parametrization}, we can extend $\gflow_{G}$ 
to cover also the possible end-points.


The next proposition characterizes the equivalence of gauges as an
affine transformation with transverse coefficients.

\begin{proposition}\label{P:characterization-equivalence}
Let $H$ be a null non-branching, weakly convex,
closed achronal set,
  admitting two gauges $G_1$ and $G_2$.
  %
  Then $G_1\sim G_2$, if and only if $G_1=f+h G_2$, for some
  transverse functions $f,h$, with $h>0$.
\end{proposition}
\begin{proof}
  The ``if'' part is trivial, so we consider the other implication.
  %
  Fix $G_1\sim G_2$ two equivalent gauges, and let
  \[
  h(z):=
  (G_1\circ \Psi_{G_2}(z,\,\cdot\,))'(0)
  .
  \]
  Since 
  $\gflow_{G_2}(z,\,\cdot\,)$ is $G_2$-causal, hence $G_1$-causal, 
  therefore $G_1\circ\gflow_{G_2}(z,\,\cdot\,)$ is affine;
  it follows that the derivative in the equation  above exists
  and $h$ is transverse.
  %
  Since
  \[
  G_2(\gflow_{G_1}(z,h(z)\, t))
  =G_2(z) +t
  ,
  \]
  then $\gflow_{G_1}(z,h(z)\, t)=\gflow_{G_2}(z, t)$.
  %
  We can thus compute
  \begin{align*}
    \big((G_1- h G_2)\circ \gflow_{G_1}(z,t)\big)'
    &
    =
    1-h(z) \big(G_2\circ \gflow_{G_1}(z,t)\big)'
    \\
    %
    &
    =
     1-h(z) \bigg(G_2\circ \gflow_{G_2}\bigg(z,\frac{t}{h(z)}\bigg)\bigg)'
    =
   0
    ,
  \end{align*}
  therefore $G_1-h G_2=:f$ is transverse.
\end{proof}









The next proposition guarantees the existence of a $\mathcal{A}$-measurable cross-section for the
equivalence relation $\relation$.
%
Here $\mathcal{A}$ is the $\sigma$-algebra generated 
by the set of analytic sets, i.e., projections of Borel sets inside a Polish space.

Recall also that we use the notation $x<y$ to denote  $x\leq y, \, x\neq y$.


\begin{proposition}[Measurable selection]\label{P:cross-section}
Let $H$ be a null non-branching, causal, weakly convex closed achronal set.
%
Then there exists a $\mathcal{A}$-measurable quotient map $\QQ :
\noending{H} \to \noending{H}$ for the equivalence relation
$\mathcal{R}$, i.e.,
for all $x \in H$, $(x,\QQ(x)) \in \relation$  and 
%
\[
\QQ(x) = \QQ(y) \iff (x,y) \in \relation(x).
\]
%
\end{proposition}

\begin{proof}
  We construct a cross-section $Q\subset\noending{H}$, as follows.
  %
  Let $(U_{n})_{n}$ be a countable base for the topology of $X$, such that $U_{n}$
  are precompact.
  %
  Consider the compact sets $C_{n}:=\overline{U_{n}\cap\noending{H}}\subset H$.
  %
  Define
  \begin{align}
    &
      \begin{aligned}
      A_{n}
      :=
        P_1((J^{-1}\setminus\Delta)\cap (C_{n}\times C_{n}))
        =
        \{x\in C_{n}\colon \exists y\in C_{n}, x<y\}
        ,
      \end{aligned}
      %
  \end{align}
  %
  The sets $A_{n}$ are $\sigma$-compact, as they are projections of
  intersections of $\sigma$-compact sets ($\Delta$ is the diagonal,
  whose complementary is open, thus $\sigma$-compact,
  by the properness of the topology).
  %
  Define
  \begin{align}
    \label{eq:maximal-elements}
    &
    L_{n}
    :=
    C_{n}\cap \noending{H}
      \setminus A_{n}
      =
      \{
      x\in
      C_{n}
      \cap \noending{H}
      \colon
      \nexists y\in C_{n}
      ,
      x<y
      \}
    ,
  \end{align}
  which is a Borel set.
  %
  Define
    \begin{align*}
    B_{n}
      :=
    P_1(\relation\cap(\noending{H}\times L_{n}))
        \cap 
        \noending{H}
      %
    =
    \{ x\in \noending{H}\colon
       \text{the set }
       \noending{H}_{x}\cap L_{n}
       \text{ is non-empty}
       \}
    ,
    \end{align*}
  which is an analytic set.
  %
  Finally, define
  \begin{equation}
    E_{n}:=
    B_{n}
    \setminus
    \bigg(
    \bigcup_{i=1}^{n-1}
    B_1
    \bigg)
    ,
    \qquad
    Q_{n}
    :=
    L_{n}
    \cap E_{n}
    ,
  \end{equation}
  which belong to the $\sigma$-algebra generated by analytic sets.
  %
  Define 
\begin{equation}\label{eq:def:Qpm}
Q:=\bigcup_{n=1}^{\infty} Q_{n}\subset V.
  \end{equation}
%
  Next, we show that  the set $Q$ is indeed a cross-sections.

{\bf Step 1.} For all $x\in\noending{H}$, $n\in\N$,  $L_{n}\cap
      \noending{H}_{x}$ contains at most one element.
      %
      Fix $x\in\noending{H}\cap\relation(U)$.
      %
  Assume on the contrary that there exists $v,w\in L_{n}\cap
  \noending{H}_{x}$, $w\neq v$.
  %
  Then either $v\leq w$ or $w\leq v$.
  %
  If $v\leq w$, then $v\notin L_{n}$, because~\eqref{eq:maximal-elements} would be contradicted by $y=w$.
  %
  Analogously, $w \leq v$ leads to a contradiction. 
  %


{\bf Step 2.} For all $x\in\noending{H}$, there exists $n\in\N$, such that
  $L_{n}\cap\noending{H}_{x}$
  contain one element.

      Fix $x\in\noending{H}$.
  %
  Then there exist two points $y,z\in \noending{H}_{x}$,
  such that $y< x< z$.
  %
  Since $H$ is causal, $x\notin J^{-}(y)\cup J^{+}(z)$, 
  therefore there exist $n$ and $W$, such that $U_{n}$
  is a neighborhood of $x$, and $W$ a neighborhood of
  $J^{-}(y)\cup J^{+}(z)$, such that $W\cap U_{n}=\emptyset$.
  %
  Thus, $C_{n}\cap W=\emptyset$.
  %
  Let $\gamma:[0,1]\to \noending{H}$ be a causal curve connecting $x$
  to $z$.
  %
  Let $\bar t:=\sup\{t:\gamma_{t}\in C_{n}\}<1$ and let $v=\gamma_{\bar{t}}\in C_{n}\cap \noending{H}_{x}$.
  %

  We claim that $v\in L_{n}$; if not, there exists $w\in C_{n}$, such
  that $v<w$, thus $w\in \noending{H}_\alpha$.
  %
  If $w\in J^{+}(z)\subset W$, then we obtain a contradiction with
  $C_{n}\cap W=\emptyset$, thus $w\leq z$; by forward
  non-branching, there exists $s\in (\bar t, 1)$, such that
  $w=\gamma_{s}$, a contradiction with the definition of $\bar t$.
  %

  We notice that $v\neq x$, otherwise $x\in \partial U_{n}$, a
  contradiction with the fact that $U_{n}$ is neighborhood of $x$.
  %
%  In particular $x<y$.



An immediate consequence of the last step is that for all $x\in
  \noending{H}$ there exists $n$, such that $x\in B_{n}$.
  %
  Therefore, it holds that
  $Q_{n}\cap \noending{H}_{x}= L_{n}\cap\noending{H}_{x}$, for the
  smallest $n$, such that $x\in B_{n}$.
  %
  As a consequence, for all $x$, $Q\cap \noending{H}_{x}$ is a
  singleton.


\textbf{Step 3.} Construction and measurability of the quotient map $\QQ$.
\\  Define the map $\QQ$ as $\QQ(x)=\alpha$, if
  $(x,\alpha)\in\relation$ and $\alpha\in Q$.
  %
  In other words, the graph of the map $\QQ$ is
  given by
  \begin{equation}
    \Graph \QQ
    =
    \relation
    \cap
    ( \noending{H}
    \times
    Q
    )
    .
\end{equation}
%
We next show that the map $\QQ$ is measurable.
We adopt the convention that $\times$ is computed before $\cap$.
  %
  Fix  an open set $W\subset X$ and compute
  \begin{align*}
    \QQ^{-1}(W)
    &
      =
      P_1(
    \relation
    \cap
     \noending{H}
      \times
      (
      Q
      \cap W)
      )
      \overset{\eqref{eq:def:Qpm}}{=}
      P_1
      \bigg(
    \relation
    \cap
    \noending{H}
      \times
      \bigcup_{n=1}^{\infty}
      \bigg(
    L_{n}
      \cap W
    \cap E_{n}
      \bigg)
      \bigg)
    \\
    %
    &
      =
      \bigcup_{n=1}^{\infty}
      P_1
      (
    \relation
    \cap
    \noending{H}
      \times
      (
    L_{n}
      \cap W
    \cap E_{n}
      )
      )
    \\
    %
    &
      \overset{\eqref{eq:stable-set}}{=}
      \bigcup_{n=1}^{\infty}
      P_1
      (
    \relation
    \cap
    \noending{H}
      \times
      (
      L_{n}
      \cap W
      )
      \cap
      E_{n}\times
      E_{n}
      )
    \\
    %
    &
      =
      \bigcup_{n=1}^{\infty}
      P_1
      (
    \relation
    \cap
    \noending{H}
      \times
      (
      L_{n}
      \cap W
      )
      )
      \cap
    E_{n}
      ,
  \end{align*}
  which belongs to the $\sigma$-algebra generated by analytic sets;
  we have used the fact
  \begin{equation}
    \label{eq:stable-set}
    \relation\cap
    \noending{H}
    \times
    (
    E_{n} \cap Y
    )
    =
    \relation\cap
    E_{n}
    \times
    E_{n}
    \cap
    \noending{H}\times Y
    ,
    \qquad
    \forall Y\subset X
    .
    \qedhere
  \end{equation}
\end{proof}











Once a measurable quotient map is available, one can invoke Disintegration theorem and obtain a strongly consistent 
disintegration formula for any element of the class $[\mm]$ with respect to $\mathcal{R}$. 
We refer to~\cite[Section 4.2]{CaMo:20} for this implication in the synthetic Lorentzian setting; for metric spaces we point to the references 
the cited in~\cite[Section 4.2]{CaMo:20} (see
in particular~\cite[Th.~3.4]{CaMoLap}). 
 We only recall that we will denote by $Q$ the quotient set associated to $\QQ$, i.e.\ $Q = \QQ(H)$.

\begin{theorem}\label{T:disintegration}
Let $(H,G,\mm)$ be a weakly convex, null non-branching synthetic null hypersurface.
Then the following disintegration formula holds:
%
\[
%\mm \llcorner_{H} =
\mm\llcorner_{\noending{H}} = \int_{Q} \mm_{\alpha} \, \qq(\de \alpha),
\]
%
where $\qq$ is a Borel probability measure over $Q \subset \noending{H}$ such that 
$\QQ_{\sharp} \mm\llcorner_{\noending{H}}  \ll \qq$ and the map 
$Q \ni \alpha \mapsto \mm_{\alpha} \in \mathcal{M}_{+}(\noending{H})$ satisfies the following properties:
\begin{enumerate}
%
\item for any $\mm$-measurable set $B$, the map $\alpha \mapsto \mm_{\alpha}(B)$ is $\qq$-measurable;% \smallskip
%
\item for $\qq$-a.e. $\alpha \in Q$, $\mm_{\alpha}$ is concentrated on $\QQ^{-1}(\alpha) = H_{\alpha}$ (strong consistency);% \smallskip
%
\item for any $\mm$-measurable set $B\subset\noending{H}$ and $\qq$-measurable set $C$, the following disintegration formula holds: 
%
\[
\mm(B \cap \QQ^{-1}(C)) = \int_{C} \mm_{\alpha}(B) \, \qq(\de \alpha);
\]
\item  For every compact subset $\mathcal K\subset X$ there exists a constant $C_{\mathcal K}\in (0,\infty)$ such that
\[
 \mm_{\alpha}(\mathcal K) \leq C_{\mathcal K}, \quad \text{for $\qq$-a.e. $\alpha\in Q$.}
\]
\end{enumerate}
%
Moreover, fixed any $\qq$ as above such that $\QQ_{\sharp} \mm \ll \qq$, the disintegration is $\qq$-essentially unique.
\end{theorem}



A few comments are in order.
%
If $\mm_1\sim \mm_2$ and $\qq\in\Prob(Q)$ is such that
$\q\ll\QQ_{\sharp}\mm_1\llcorner_{\noending{H}}$, then also $\qq\ll\QQ_{\sharp}\mm_2\llcorner_{\noending{H}}$.
%
Moreover, if $\mm_2\llcorner_{\noending{H}}=f\mm_1\llcorner_{\noending{H}}$ for some transverse function, then
$\mm_{2,\alpha}=f(\alpha)\mm_{2,\alpha}$, for $\q$-a.e.\ $\alpha\in Q$.







