\section{Light-like Optimal Transport  and localization}\label{Sec:OT-Loc}

In this section, we will establish existence and uniqueness results for the optimal transport problem along a synthetic null hypersurface $H$, and use these to localize the synthetic Ricci curvature lower bounds to the measures $\mm_\alpha$  concentrated on the null generators $H_\alpha$ of $H$, as in the disintegration  \Cref{T:disintegration}.


\subsection{Existence and uniqueness of a monotone light-like Optimal Transport}

\begin{definition}[Monotone set]\label{D:monotoneset}
Given $(Y,\leq)$ a partially ordered set, $A\subset Y \times Y$ is said to be \emph{monotone}
if 
\[
x_1 \leq x_2, \ x_1 \neq x_2
\Longrightarrow y_1\leq y_2, \quad \text{for all } (x_1,y_1), (x_2,y_2) \in A.
\]
\end{definition}


\begin{definition}[Monotone plans]\label{D:monotoneplan}
%
  Given a topological causal space $(X,\ll,\leq,\mathfrak{T})$ and two
  probability measures $\mu_0,\mu_1\in \Prob(X)$, a coupling
  $\pi \in \Pi_{\leq}(\mu_{0},\mu_{1})$ is called \emph{monotone} if
  it is concentrated on a Borel set $A \subset X\times X$ that is
  monotone in the sense of \Cref{D:monotoneset} in $(X,\leq)$.
  %
\end{definition}




\begin{lemma}\label{lem:monotone}
  Let $H$ be a null non-branching, weakly convex, 
  closed achronal set admitting 
  a gauge function $G$.
  %
  Let $A\subset J\cap (\noending{H}\times \noending{H})$.
  %
  The following are equivalent.
  \begin{enumerate}
  \item
    %
    The set $A$ is monotone in $(H,\leq)$.
  \item
    %
    for all $\alpha\in Q$, there exists a monotone set
    $B_\alpha\subset\R\times\R$, such that
    \begin{equation}
      A\cap (\noending{H}_\alpha\times \noending{H}_\alpha)
      \subset
      \gflow_{G}(\alpha,\,\cdot\,)
      \otimes
      \gflow_{G}(\alpha,\,\cdot\,)
      (B_\alpha)
    \end{equation}
  \end{enumerate}
\end{lemma}
\begin{proof}
  (1) $\implies$ (2).
  \quad
  %
  Take as
  $B_\alpha:=( \gflow_{G}(\alpha,\,\cdot\,) \otimes \gflow_{G}(\alpha,\,\cdot\,))^{-1}(A)$.
  %
  The fact that $B_\alpha$ is monotone is trivial.

  (2) $\implies$ (1).
  \quad
  %
  Fix $(x_1,y_1),(x_2,y_2)\in A$.
  %
  If $x_1< x_2$, then all these four points belong to the
  same class $H_\alpha$.
  %
  Then $x_{i}=\gflow_{G}(\alpha, t_{i})$ and $s_{i}=\gflow_{G}(\alpha, s_{i})$, for some
  $(t_{i},s_{i})\in B_\alpha$, $i=1,2$.
  %
  The assumption $x_1\leq x_2$ gives $t_1\leq t_2$ and the
  monotonicity of $B_\alpha$ gives $s_1\leq s_2$, concluding the
  proof.
\end{proof}



\begin{proposition}\label{P:monotone-transport-plan}
Let $H$ be a non-branching, weakly convex,
closed achronal set, admitting a gauge function $G$.
%
Let
$\mu_0,\mu_1\in \Prob(\noending{H})$ such that 
$\Pi_{\leq}(\mu_0,\mu_1)\neq \emptyset$.
%

Then there exists a unique monotone coupling
$\pi \in \Pi_{\leq}(\mu_0,\mu_1)$.
\end{proposition}

\begin{proof}
  Let $Q\subset\noending{H}$ be a measurable cross-section of $\relation$ and let
  $\QQ:\noending{H}\to Q$ be the quotient map.
  %
  \smallskip

{\bf Step 1.} Existence.
  %
 Let $\bar\pi\in\Pi_{\leq}(\mu_0,\mu_1)$.
  %
  Consider the
  map 
  \begin{equation}\label{eq:defQ1}
  \QQ^1:=\QQ\circ P_1: \noending{H}\times \noending{H}
  \to Q,
  \end{equation}
  where $P_1$ is the projection on
  the first variable.
  %
  By definition of coupling, we get
  \begin{equation}
    \qq:=
    \QQ_{\sharp}(\mu_1)
    =
    \QQ^1_{\sharp}(\bar\pi)
    .
  \end{equation}
  %
  We are therefore in position to apply the disintegration theorem,
  deducing that
  \begin{equation}
    \bar\pi
    =
    \int_{Q}
    \bar\pi_\alpha
    \,
    \qq(\de\alpha)
    ,
  \end{equation}
  where the probability measures $\bar\pi_\alpha$ are concentrated on
  the fibers of $\QQ^1$.
  %
  Since $\pi(J)=1$, then the measure $\bar\pi_\alpha$ are concentrated
  on
  \begin{equation}
    (\QQ^1)^{-1}(\alpha)
    \cap J
    =
    \{(x,y)\in \noending{H}: (x,\alpha)\in\relation\}
    \cap J
    \subset
    \noending{H}_\alpha
    \times
    \noending{H}_\alpha
    .
  \end{equation}
  %
  At this point we let
  \begin{equation*}
    \tilde{\bar{\pi}}_\alpha
    :=
    (
    \gflow(\alpha,\,\cdot\,)^{-1}
    \otimes
    \gflow(\alpha,\,\cdot\,)^{-1}
    )_{\sharp}
    \bar\pi_\alpha
    \in\Prob(\R^2)
    \quad
    \text{ and }
    \quad
    \tilde\mu_{i}
    :=
    (P_{i})_{\sharp}    \tilde{\bar{\pi}}_\alpha
    \in\Prob(\R)
    ,
    \quad
    i=0,1.
  \end{equation*}
  %
  Let $\tilde\pi_\alpha\in \Prob(\R^2)$ be the monotone rearrangement
  of $\tilde\mu_0$ into $\tilde\mu_1$, and let
  $B_\alpha:=\supp\tilde\pi_\alpha$.
  %
By~\cite[Lemma~6.4]{CMM24a},
    we have that 
    \[B_\alpha\subset\{(x,y) \in \R^2: x\leq y\}.\]
  %
  Define
  \begin{equation}
    \pi:=
    \int_{Q}
    (
    \gflow_{G}(\alpha,\,\cdot\,)
    \otimes
    \gflow_{G}(\alpha,\,\cdot\,)
    )_{\sharp}
    \tilde\pi_{\alpha}
    \,
    \de\alpha
    .
  \end{equation}
  %
  Since $\gflow_{G}(\alpha,\,\cdot\,)$ is order-preserving
  and $\tilde{\bar{\pi}}_\alpha$ is concentrated on 
  $B_\alpha\subset\{(x,y)\colon y\geq x\}$,  $\pi$ is concentrated on $J$.
%
Finally, it is a routine calculation to see that $\pi$ is coupling between $\mu_0$ and $\mu_1$.

\smallskip

{\bf Step 2.} Uniqueness.
  Let $\pi^1$ and $\pi^2$ be two monotone transport plans.
  %
  It holds that
  \begin{equation}
    \QQ^1_{\sharp}\pi^1
    =
    \QQ^1_{\sharp}\pi^2
    =:
    \q
    .
  \end{equation}
  We can therefore apply the disintegration theorem, finding that
  \begin{equation}
    \pi^{i}
    =
    \int_{Q}
    \pi^i_\alpha
    \,
    \q(\de\alpha).
  \end{equation}
  %
Let
\begin{equation*}
    \tilde\pi^k_\alpha
    :=
    ((\gflow_{G}(\alpha,\,\cdot\,))^{-1}\otimes
    (\gflow_{G}(\alpha,\,\cdot\,))^{-1})_{\sharp}\pi^k_\alpha
    \in\Prob(\R^2).
\end{equation*}
%
Since $\tilde\pi_\alpha^1$ and $\tilde\pi_\alpha^2$ have the same
marginals,
by the uniqueness of
the monotone rearrangement,
we deduce
$\tilde\pi_\alpha^1=\tilde\pi_\alpha^2$ giving $\pi^1 = \pi^2$.
\end{proof}


\begin{proposition}\label{P:G-causal-transport-plan}
  Let $H$ be a null non-branching, weakly convex, closed achronal set, admitting a gauge function $G$.
  %
  Let $\mu_0,\mu_1\in \Prob(\noending{H})$ be
  two probability measures, and assume there exists a causal coupling
  $\pi\in\Pi_{\leq}(\mu_0,\mu_1)$.
  %

  Then there exists a unique $G$-causal dynamical transport
  plan $\nu\in\OptGeo_{G}(\mu_0,\mu_1)$, such that $(e_0\otimes
  e_1)_{\sharp}\nu=\pi$.
\end{proposition}
\begin{proof}
  The plan $\pi$ gives full
  measure to $B:=J\cap (\noending{H}\times \noending{H})$.
  %
  Consider the map $\Gamma:B\to C_{G}$ given by 
  \Cref{R:measurablity-Gamma}, such that, for each 
  $(x_0,x_1)\in B$, $\Gamma\big((x_0,x_1)\big)_{i}=x_{i}$, $i=0,1$.
  %
  Then  $\nu:=\Gamma_{\sharp}\pi$, satisfies the claim.
\end{proof}





\begin{corollary}\label{C:monotone-G-causal}
  Let $H$ be a null non-branching, weakly convex, closed achronal set,
  admitting a gauge function $G$. 
  %
  Let $\mu_0,\mu_1\in \Prob(\noending{H})$ be
  two probability measures, such that $\Pi_{\leq}(\mu_0,\mu_1)\neq\emptyset$.
  %

  Then there exists $\nu\in\OptGeo_{G}(\mu_0,\mu_1)$, a unique $G$-causal, dynamical optimal
  transport plan, such that 
  $(e_0,e_1)_{\sharp}\nu$ is a  monotone coupling.
\end{corollary}
\begin{proof}
    Combine
  \Cref{P:monotone-transport-plan} with
  \Cref{P:G-causal-transport-plan}.
\end{proof}


As the following example shows, the requirement that the marginal
measures give no mass to the endpoints is necessary for the existence of a monotone coupling and 
it cannot be weakened by the requirement that only one
measure is concentrated on $\noending{H}$.

  \begin{example}
    Consider the $2$-dimensional Minkowski space $\R^2$ and let
    $H=\{(x,|x|)\}$.
    %
    Consider the measures
    \[\mu_0=\frac{1}{2}(\delta_{(0,0)}+\delta_{(1,1)}), \quad  \mu_1=\frac{1}{2}(\delta_{(-2,2)}+\delta_{(2,2)}).\]
    %
    The only transport plan $\pi\in\Pi_\leq(\mu_0,\mu_1)$ is
    induced by a map $T$ given by $T(0,0)=(-2,2)$ and
    $T(1,1)=(2,2)$.
    %
    Notice that
    \[
    \supp \pi=\{((0,0),(-2,2)),((1,1),(2,2))\}.
    \]
    %
    % $\pi=\frac{1}{2}(\delta_{((0,0),}+\delta_{1,1})$ and
    %
    For this set, it holds that $(1,1)\in J^{+}(0,0)$, but
    $(2,2)\notin J^+(-2,2)$, thus the plan is not monotone.
\end{example}





\subsection{Localization of the \NEC}




\begin{theorem}\label{T:localization}
  Let $(H,G,\mm)$ be a null-non-branching 
  synthetic null hypersurface.
  %
  Then the following are equivalent.
  \begin{itemize}
      \item 
  $(H,G,\mm)$ satisfies the \NEC\ $\NC^{e}(N)$.

\item
    Considering the disintegration given by \Cref{T:disintegration},
 for $\q$-a.e.\ $\alpha\in Q$, the metric measure space
  $(H_\alpha, |G(\,\cdot\,) - G(\,\cdot\,)|, \mm_\alpha)$ 
  satisfies the $\CD(0,N-1)$ condition.
  %
  That is, using the identification $\gflow_{G}(\alpha,\,\cdot\,)$ between $H_\alpha$ 
  and a real interval $I_\alpha\subset \R$,
  the measure $\mm_\alpha$ is absolutely continuous and, denoting
  by $h_\alpha:I_\alpha\to[0,\infty)$ its density, 
  $t\mapsto h_\alpha^{1/(N-2)}(t)$
 is concave.
 \end{itemize}
\end{theorem}

\begin{proof}
First notice that by \Cref{R:absolutelycontinuous}, 
the $\NC^{e}(N)$ condition implies that $H$ is weakly convex. Hence \Cref{T:disintegration} applies. 


  One can check that $(H_\alpha, |G(\,\cdot\,) - G(\,\cdot\,)|)$ is a metric space isometric to the metric 
  space  $(I_\alpha,|\cdot-\cdot|)$, via the map $\gflow_{G}(\alpha,\,\cdot\,)$.
  %
  Therefore, it is sufficient to check
  that $(I_\alpha,|\,\cdot\,|,\tilde\mm_\alpha)$ satisfies the $\CD(0,N-1)$
  condition, where
  $\tilde\mm_\alpha:=((\Psi_{G}(\alpha,\,\cdot\,))^{-1})_{\sharp}\mm_\alpha$.


