We are now in position to state and prove Hawking's area theorem.

\begin{theorem}\label{eq:HawSynt}
  Let  $(H,G,\mm)$ be a null non-branching, synthetic null hypersurface, satisfying the $\NC^e(N)$
  condition. Assume that $H$ is future complete for $G$ and that $\supp \mm=H$.  
  %
  Let $S_1, S_2\subset \noending{H}$ be two acausal sets with $S_1\subset J^{-}(S_2)$. Then
  \begin{equation}
    \mm^+_{G}(S_1)
    \leq
    \mm^+_{G}(S_2)
    ,
  \end{equation}
  where the value $+\infty$ is admitted.
\end{theorem}
\begin{proof}
  We use \Cref{T:disintegration} and we adopt its notation.
  %
Since $H=\supp \mm$ and $H$ is future 
complete for $G$, then the density $h_\alpha$ of $\mm_\alpha$ is positive on a unbounded interval.
%
Since by Theorem~\ref{T:localization}  $h_\alpha^{1/(N-2)}$ is concave, we infer that $h_\alpha$ is non-decreasing.
%
The assumption $S_1\subset J^{-}(S_2)$ implies that
$\QQ((S_1)^{+}_\epsilon)\subset \QQ((S_2)^{+}_\epsilon)$.
%
%
Using that  $(S_{i})_\epsilon^+ \subset \noending{H}$
\begin{align*}
\mm((S_2)_\epsilon^+)
&
= \int_{\QQ((S_2)_\epsilon^+)} \mm_\alpha((S_2)_\epsilon^{+})
\,
\q(\de\alpha)
\geq
\int_{\QQ((S_1)_\epsilon^+)} \mm_\alpha((S_2)_\epsilon^{+})
\,
\q(\de\alpha)
\\
%
&
\geq
\int_{\QQ((S_1)_\epsilon^+)} \mm_\alpha((S_1)_\epsilon^{+})
\,
\q(\de\alpha)
=
\mm((S_1)_\epsilon^{+})
,
\end{align*}
proving the theorem.
\end{proof}

\begin{remark}
Inspecting the proof of \Cref{eq:HawSynt}, one can check that the assumption~\eqref{eq:defHFCG} can be replaced by the following weaker (but slightly more tecnical) condition: for $\qq$-a.e. $\alpha$, the ray $H_\alpha$  (see \Cref{T:localization}) is isometric to a real interval  unbounded from above. 
\end{remark}



A priori,  the Minkowski content of $S$ could depend on the choice
of $\mm$ and $G$.
%
In the next proposition we show that, under suitable covariance
relations linking $G$ with $\mm$, the Minkowski content is independent from such choices.


\begin{proposition}\label{P:covariance-area}
  Let $(X,\ll,\leq,\mathfrak{T})$ be a topological causal space and let $H\subset X$ be
  a null non-branching closed achronal set.
  %
  Let $\mm_{i}\in\M^{+}(H)$ be a measure and $G_{i}$ be a gauge on $H$, $i=1,2$.
  %
  Let $S\subset H$ be an acausal set.
  %
  Assume that $G_1=f+hG_2$, for some transverse
  functions $h,f$ (cf.\ \Cref{P:characterization-equivalence})
 and that $\mm_1=\frac{1}{h}\mm_2$.
  %
  Assume that $(H,G_1,\mm_1)$ satisfies the $\NC^e(N)$
  condition (hence $(H,G_2,\mm_2)$ does, as well, see \Cref{R:invariance-NC-non-branching}).
  %
  Assume that $H$ is future complete for $G_1$ (hence for $G_2$).

  If
  \[
  (\mm_1)^{+}_{G_1}(S)<\infty
  \qquad
  \text{ and }
  \qquad
  (\mm_2)^{+}_{G_2}(S)<\infty
  ,
  \]
  then
  \begin{equation}
    (\mm_1)^+_{G_1}(S)
    =
    (\mm_2)^+_{G_2}(S).
  \end{equation}
\end{proposition}
\begin{proof}
  Let $\mm_{i,\alpha}$ be the conditional measures given by the
  disintegration of $\mm_{i}$ and let $h_{i,\alpha}$, be the density of
  $\mm_{i}$, $i=1,2$, see~\Cref{T:disintegration}.
  %
  Since by assumption $\mm_2=h\mm_1$, and $G_1=f + h G_2$,
  it is immediate to see that
  \begin{equation}
    \label{eq:transformation-h}
    h_{1,\alpha}(t)=h_{2,\alpha}(f(\alpha)+h(\alpha)\,t)
  \end{equation}
  %
  Denote by $S^{+}_{i,\epsilon}$ the $\epsilon$ enlargement w.r.t.\ the
  gauge $G_{i}$, $i=1,2$.
  %
  Let $A:=\QQ(S_{1,\epsilon}^{+})=\QQ(S_{2,\epsilon}^{+})$.
  %
  For every $\alpha\in A$, let $a_{i,\alpha}\in\R$ be such that
  $(a_{i,\alpha},a_{i,\alpha}+\epsilon)$ is the maximal interval
  satisfying
  $\gflow_{G_{i}}((a_{i,\alpha},a_{i,\alpha}+\epsilon))\in S^{+}_{i,\epsilon}$,
  $i=1,2$.
  %
  It holds that
  \begin{equation}
    \label{eq:a-affine}
    a_{1,\alpha}=f(\alpha)+h(\alpha) a_{2,\alpha}
    .
  \end{equation}
  %
  We compute
  \begin{align*}
    \mm^{+}_{G_{i}}(S)
    &
    =
      \limsup_{\epsilon\to 0^{+}}
      \frac{\mm(S_{i,\epsilon}^{+})}{\epsilon}
      =
      \limsup_{\epsilon\to 0^{+}}
      \int_{A} \frac{\mm_\alpha(S_{i,\epsilon}^{+})}{\epsilon}
\,
      \q(\de\alpha)
    \\
    %
    &
      =
            \limsup_{\epsilon\to 0^{+}}
\int_{A}
\int_{a_{i,\alpha}}^{a_{i,\alpha}+\epsilon}
\frac{h_{i,\alpha}(t)}{\epsilon}
\,
\de t
\,
      \q(\de\alpha)
      .
  \end{align*}
  %
  Denote by $v_{i,\alpha}$ the function
  \begin{equation}
    v_{i,\alpha}(t)
    :=
    \int_{a_{i,\alpha}}
    h_{i,\alpha}(s)
    \,\de s
    .
  \end{equation}
  %
  The $\NC^e(N)$ condition implies that $h_{i,\alpha}^{\frac{1}{N-2}}$
  is concave, thus the future completeness w.r.t.\ $G_{i}$ guarantees
  that $h_{i,\alpha}$ is non-decreasing, therefore $v_{i,\alpha}$ is
  convex.
  %
  It follows that the limit $\lim_{\epsilon\to
    0^{+}}\frac{v_{i,\alpha}(\epsilon)}{\epsilon}$ exists and it is
  monotone decreasing.
  %
  The hypothesis $\mm^{+}_{G_{i}}(S)<\infty$, guarantees that for
  $\epsilon>0$ small enough,
  $\frac{v_{i,\alpha}(\epsilon)}{\epsilon}\in L^1(\q)$.
  %
  We are in position to apply the dominated convergence theorem,
  deducing
  %
  \begin{equation}
    \mm^{+}_{G_{i}}(S)
    =
    \int_{A}
    h_{i,\alpha}(a_{i,\alpha})
    \,
    \q(\de\alpha)
    .
  \end{equation}
  %
  We conclude by combining~\eqref{eq:transformation-h} and~\eqref{eq:a-affine}.
\end{proof}





\section{Penrose's singularity theorem for synthetic and continuous spacetimes}\label{S:Penrose}

In this section, we propose a way to extend Penrose's singularity
theorem to the setting of a continuous spacetime (i.e., when the
Lorentzian metric is continuous).
Recall that Penrose's singularity theorem~\cite{Penrose65} states that if a spacetime satisfyng the \NEC\ admits a non-compact Cauchy hypersurface and it contains a trapped surface, then it is null geodesic incomplete; i.e., there exists a null geodesic $\gamma$ (in the sense that it solves the geodesics-ODE: $\nabla_{\dot{\gamma}}\dot{\gamma}$) whose maximal domain of definition is strictly contained in $\R$.
Besides the proof, a first challenge in generalizing such a result for a continuous spacetime is to make sense of the very statement. We first start with the concept of null completeness. 
%



\subsection{Weak null completeness}\label{SS:WNC}

In the smooth setting, it is known to experts that  the incomplete geodesic yielded by Penrose’s singularity theorem is achronal (see \cite{Penrose65, Penrose-DiffTopGR},~\cite[Sec.~12.4]{BEE-Book}, \cite[Th.~2.67]{Min}).
%
Negating the existence of such a geodesic therefore amounts to requiring that every maximally extended geodesic is either complete or fails to remain achronal (or, equivalently, fails to be maximizing).
%
We adopt this condition as the definition of \emph{weak null completeness}, as it admits an equivalent synthetic characterization, which we establish below.


\begin{definition}[Weak null completeness]\label{defn:wgnc}
  Let $(M,g)$ be a strongly causal Lorentzian manifold.
We say that $(M,g)$ is \emph{weakly future  null complete} if for any
  maximally-defined (on the right) null geodesic (in the differential
  sense) $\gamma:[0,b)\to M$, either $b=\infty$, or
  $\gamma_0\ll\gamma_{t}$, for some $t\in[0,b)$. The notion of \emph{weakly past null  complete} is analogous, by considering maximally defined (on the left) null geodesics. We say that $(M,g)$ is \emph{weakly  null complete} if it is both weakly future and past  null complete.
\end{definition}

It is clear that  a null complete manifold is weakly null complete as the case of $b<\infty$ never occur (and therefore being weakly null incomplete will be a stronger property of being null incomplete). 
On the other hand, we now exhibit an example of a weakly null complete Lorentzian manifold that is not null complete justifying the terminology. 

In particular, we now provide a sufficient condition for a
warped product to be weakly null complete but not
null complete.  This amounts to show that all the incomplete inextendible null geodesics are not globally maximizing. The geometric idea is, roughly, of an upside down cone-like shape where all the causal geodesic end in the tip and all the null geodesics move in spiral, more and more densely as they approach the tip.

  \begin{proposition}\label{Prop:ExNotComplete}
    Let $(F,g_F)$ be a compact Riemaniann manifold and consider the
    warped product $M:=(-\infty,0)\times_f F$, endowed with the metric
    \begin{equation}
      g= \de t^2 - f^2(t)\, g_{F}.
    \end{equation}
  %
    Assume that $f(t)\leq O(\sqrt{-t})$ as $t\to 0^-$.

    Then $M$ is a weakly null complete, but 
    both null and time-like incomplete. More precisely, every future directed geodesic (either timelike or null) is future incomplete, and every future directed null geodesic is not globally maximizing. 
  \end{proposition}
  %

  \begin{proof}
    In this proof, we denote by $\gamma:[0,b)\to M$ an arbitrary maximally-defined
    future-directed geodesic in $M$, with $\gamma_{s}=(t_{s},x_{s})$.
  %
  We will write $(\dot{t}, \dot{x})= \dot\gamma := \frac{\de}{\de s}\gamma$ and $\nabla_{\dot x_{s}} \dot{x}_{s}$ for the covariant derivative in $(F,g_{F})$ of $\dot{x}$ with respect to itself, i.e., the acceleration of the curve $s\mapsto x_{s}\in F$. Also, we  denote the derivative of the warping function $f:(-\infty, 0)\to \R$ by  $f':= \frac{\de}{\de t} f$.
    The equations governing the evolution of $\gamma$
    are~\cite[Prop.~7.38,~p.~208]{O'Neill}
    \begin{align}
      &
        \label{eq:acceleration-base}
        \ddot t_{s}
        =
        -
        g_{F}(\dot x_{s},\dot x_{s})
        \,f(t_{s})
        \,
        f'(t_{s})
        ,
      \\
    %
      &
        \label{eq:acceleration-fiber}
        \nabla_{\dot x_{s}} \dot{x}_{s}
        =
        -2
        \,
        \frac{f'(t_{s})}{f(t_{s})}
        \,
        \dot t_{s}
        % \frac{\de \log(f\circ t)}{\de s}
        \,\dot x_{s}
        =
        -2
        \,
        \frac{\de \log (f \circ t_{s})}{\de s}
        % \frac{\de \log(f\circ t)}{\de s}
        \,\dot x_{s}
        .
    \end{align}

    Notice that $|\dot\gamma|^2=
    |\dot{t}_{s}|^2-f^2(t_{s})g_{F}(\dot x_{s},\dot x_{s})$ is constant in $s$, since $\gamma$ is a geodesic.   We can rewrite~\eqref{eq:acceleration-base} as
    \begin{equation}
              \ddot t_{s}
              =
              -
        (|\dot t_{s}|^2-|\dot{\gamma}|^2)
        \,
        \frac{f'(t_{s})
        }{
          f(t_{s})
        }
        .
      \end{equation}
      %
      If $\dot x_{s}\equiv 0$ then, from~\eqref{eq:acceleration-base}, we get that  $t$ is affine and thus $b$ must be
      finite.
      %
      \\ If instead $\dot x_{s}\not \equiv 0$, then
      \begin{equation*}
        \frac{
          \dot t_{s}
          \,
          \ddot t_{s}
        }{
          |\dot t_{s}|^2-|\dot{\gamma}|^2
        }
        =
        \frac{1}{2}\,
        \frac{
          \de \log(|\dot t_{s}|^2-|\dot{\gamma}|^2)
        }{
          \de s
        }
        =
        -
        \frac{
          f'(t_{s})
          \,
          \dot t_{s}
        }{
          f(t_{s})
        }
        =
        -
        \frac{
          \de \log(f( t_{s}))
        }{
          \de s
        }
        .
        \end{equation*}
    %
    By integrating, we deduce that
    \begin{equation*}
      \frac{|\dot t_{s_2}|^2-|\dot{\gamma}|^2}{|\dot t_{s_1}|^2-|\dot{\gamma}|^2}
      =
      \frac{f^2(t_{s_1})}{f^2(t_{s_2})}
      ,
      \qquad
      \forall s_1, s_2\in [0,b), s_1\leq s_2
      ,
    \end{equation*}
    therefore
    \begin{equation}
      \dot t_{s_2}
      =
      \sqrt{
        |\dot{\gamma}|^2
        +
        (|\dot t_{s_1}|^2 - |\dot{\gamma}|^2)
      \frac{f^2(t_{s_1})}{f^2(t_{s_2})}
    }
    .
  \end{equation}
  %
  We can now take the limit on the r.h.s.\ as $s_2\to b^{-}$, deducing
  that $\lim_{s\to b^{-}} \dot t_{s}=\infty$, therefore $b$ must be
  finite.
  %
  This proves future incompleteness.

  A consequence of the limits $\lim_{s\to b^{-}} t_{s}=0$
  and
  $\lim_{s\to b^{-}} \dot t_{s}=\infty$
  is that
  \begin{align*}
    t_{s}
    =
    \int_{b}^s\dot t_{w} \,\de w
    \geq
    s-b
    ,
    \qquad
    \text{ for $s$ large enough,}
  \end{align*}
  therefore
    \begin{equation}
      \label{eq:expansion-f}
      f(t_{s})
      \leq
      O(\sqrt{b-s})
      .
    \end{equation}

    We now show that any null geodesic starting at a given
    point $p=(t_0,x_0)$ will definitely enter in $I^+(p)$.
  %
    We claim that for any $z\in M$,
    \begin{equation}
      \label{eq:warped-future}
      J^{+}(p)\cup (-\infty,0) \times \{z\}
      \neq
      \emptyset
      .
    \end{equation}
  %
    Suppose on the contrary that there exists $z$ contradicting~\eqref{eq:warped-future}.
    Let $L:=(\exp^{g_{F}}_{x_0})^{-1}(z)$ and
    $\dot t_0:=f(t)\sqrt{g_{F}(L,L)}$, and consider the null geodesic
    $\gamma$ starting from $p$, with initial velocity
    $\dot\gamma_0=(\dot t_0,L)$.
  %
    We will obtain a contradiction by showing that the projection of $\gamma$ on $F$ passes through $z$.
  %
    Equation~\eqref{eq:acceleration-fiber} states that the geodesic
    acceleration of $x$ is parallel to its velocity, thus $x$ is a
    reparametrization of a geodesic $y$ in $F$, i.e., $x_{s}=y_{r(s)}$.
  %
    Since $F$ is compact, then Hopf--Rinow theorem guarantees it is complete. Then $y_{r}$ is defined for all positive $r$
    and $y$ accumulates at some point in $F$.
  %
    A simple computation gives
    \begin{align*}
       \nabla_{\dot{x}_{s}} \dot{x}_{s}
      =
      \nabla_{\dot r(s)\dot y_{r(s)}}
      (\dot r(s)\dot y_{r(s)})
      =
      \ddot r(s) \dot y_{r(s)}
      =
      \frac{\ddot r(s)}{\dot r(s)} \dot x_{s}
      ,
    \end{align*}
   which, combined with~\eqref{eq:acceleration-fiber}, yields
    \begin{equation*}
      \frac{\de \log \dot r}{\de s}
      =
      \frac{\ddot r}{
        \dot r}
      =
      -2
      \frac{\de \log (f \circ t)}{\de s},
    \end{equation*}
    or, equivalently:
    \begin{equation*}
      \dot r(s)=\frac{C}{f^2(t_{s})},
    \end{equation*}
    for some constant $C$. Integrating, we get  that
    \begin{equation*}
      r(s)=\int_0^s\frac{C}{f^2(t_{w})}
      \,\de w
      .
    \end{equation*}
  %
    Plugging the expansion~\eqref{eq:expansion-f} in the equation
    above, we deduce that $r(s)\to+\infty$, as $s\to b^-$.
  %
    This means that $x$ runs on the whole trajectory of $y$ and therefore the curve
    $x$ passes through the point $z$.
  %

    Having proved~\eqref{eq:warped-future}, we deduce that
    $\partial I^{+}(p)$ intersect each line $(-\infty, 0)\times \{z\}$ in
    only one point,  for each fixed $z\in F$.
  %
    Moreover, it is well-known
    (see~\cite[Cor.~14.27,~p.~415]{O'Neill}) that $\partial I^{+}(p)$
    is a $C^{0}$ manifold, thus $\partial I^{+}(p)$ can be seen as a
    graph hypersurface over $F$ (in particular, it is a Cauchy hypersurface).
  %
    Since  $F$ is compact and $\partial I^{+}(p)$ is a graph
    surface, then there exists $t_1\in (t_0, 0)$ such that
    \[
      \partial I^{+}(p) \subset (t_0,t_1) \times F.  
    \]
  %
    It follows that any maximal null geodesic
    starting from $p$ will definitely enter $I^{+}(p)$, thus failing to be maximizing.
  \end{proof}



The weak null completeness condition can be rephrased using gauges. 
We recall that if $M$ is a smooth Lorentzian manifold
and $H=\partial I^{+}(A)$, with $A$ a compact acausal submanifold, 
a \emph{natural} gauge function on $H$ is 
 given by pushing via the exponential a fiber-wise affine function
  in the normal bundle $\normal\initial$
  (see~\Cref{R:compatibility-penrose}).
  %
  In particular $G$ can be extended to $0$ along
$\initial$, continuously on each generator.
 Recall also that  $G$ is called \emph{proper}
if the pre-image of every compact set is precompact. 

We will now show that if $M$ is a strongly causal Lorentzian manifold,
the weak null completeness of $M$ is equivalent to the existence of natural proper gauges, with the latter having the great advantage of being formulated without any need of an underlying manifold structure. 

Thus, \emph{the properness of the gauge shall be seen as a synthetic
    counterpart of the weak null completeness}.
  %
The statement of the next proposition is given for weak future null completeness; 
one can state a similar theorem for past completeness.

\begin{proposition}\label{prop:wgnc}
    Let $(M,g)$ be a strongly causal, causally closed
    Lorentzian manifold.
    %
%    Let $S$ be a compact achronal space-like $(n-2)$-submanifold and
%    let $H=\partial I^{+}(S)$.
    Let $H=\partial I^{+}(A)$, 
    for some $C^2$ compact space-like achronal submanifold $A$.
    %
    %Assume $H$ to be smooth.
    \begin{enumerate}
    \item\label{WGNC-to-GProper}
      Let $G$ be any natural gauge for $H$ which is continuously extendible to $0$ at $A$
      (see \Cref{R:compatibility-penrose}).
      %
       If $(M,g)$ is weakly future  null complete, then $G$ is proper.

    \item\label{GProper-to-WGNCH}
      Conversely, if $H$ admits a proper natural gauge $G$,
      then for every
      maximally (on the right) defined null geodesic
      $\gamma:[0,b)\to M$,
      the following dichotomy holds:
      either $b=\infty$ or $\gamma$ will leave $H$ definitely.
      %
    \item\label{GProperCones-to-WGNCH}   Finally, if every future light-cone of $M$ admits a  proper natural gauge,
    then $(M,g)$ is weakly future null future complete.
    \end{enumerate}
\end{proposition}
  \begin{proof}
    \textbf{Proof of~\ref{WGNC-to-GProper}}.
    We recall from \Cref{R:compatibility-penrose} that 
    \begin{equation}
%      \hat H
%      :=
      \noending{H}
      \subset
      \exp(
      \{
      v\in\normal A
      \colon
      g(v,v)=0
      \text{ and }
      g(v,W)<0
      \}
      )
      ,
    \end{equation}
    where $W$ is a time-like vector field given by the
    time-orientation of $M$ (notice that here, differently form
    \Cref{R:compatibility-penrose}, we are considering the larger set
    $A\supset\initial$).
    %
    %
    If we define
    \begin{equation*}
      C:=
      \{v\in \normal A
      \cap \dom(\exp)
      \colon
      g(v,v)=0
      ,
      \;
      g(v,W)\leq
      0
      ,
      \text{ and }
      \exp(v)\not\in I^{+}(A)
      \}
      ,
    \end{equation*}
    it is then clear that $H=\exp(C)$.
    %
    By definition of natural gauge, it holds that
    \begin{equation*}
        G^{-1}([a,b]) 
      \subset
      \exp(
      D)
      ,
      \qquad
      \text{ where }
      \qquad
      D:=
      \{
      v\in C
      \colon
      -g(v,W)\in [a,b]
      \}
      \subset \normal A
      .
    \end{equation*}
    %
    We check that $D$ is compact; by continuity of the exponential the
    thesis will follow.
    %
    Boundedness of $D$ is immediate.
    %
    %
    Regarding closedness% (in $\normal A$)
, let $v_{n}$ be a sequence in
    $D$, converging to $v_\infty\in\normal A$.
  %
    Assume by contradiction that $v_\infty\not\in D$.
  %
    Then $v_\infty\not\in \dom(\exp)$, since the other conditions
    defining $D$ are closed.
  %
    It follows that the curve $\gamma_{t}:=\exp(tv_\infty)$ is defined
    on $[0,b)$ with $b \leq 1$.
  %
    We exploit the weak null completeness to infer that,
    for some $t<b$,
    $\gamma_0\ll\gamma_{t}\in I^{+}(\gamma_0)\subset I^{+}(A)$.
  %
    Since $\exp(tv_{n}) \overset{n\to \infty}\longrightarrow \gamma_{t}$,
    then, for $n$ large enough,
    $\exp(tv_{n})\in I^{+}(A)$.
    %
    Therefore, $\exp(v_{n})\in I^{+}(A)$, yielding a
    contradiction with the definition of $D$.

  %
\smallskip

 \textbf{Proof of~\ref{GProper-to-WGNCH}}.
 % Let    $\gamma_{t}=\exp_{\gamma_0}(tL)=\gflow_{L}(\gamma_0,t)$.
 Fix $\gamma:[0,b)\to M$ an inextendible geodesic.
 %
 Up to a reparametrization, we can assume $G(\gamma_{t})=t+G(\gamma_0)$.
  %
    Suppose by contradiction that $b<\infty$ and that $\gamma$ is
    contained in $H$.
  %
    Let $F:=\overline{G^{-1}([0,b+G(\gamma_0)])}\subset H$.
    By the properness assumption on $G$, we have that $F$
    is compact.
  %
    Let $t_{n}\uparrow b$.
  %
    Up to a subsequence, $\gamma_{t_{n}}\in F$ is
    converging in $F$.
    %
    By standard properties of the geodesic flow,
    it follows that  $\exp_{\gamma_0}(bL)$ is well-defined,
    a contradiction with
    the inextendability  of $\gamma$.
\smallskip

\textbf{Proof of~\ref{GProperCones-to-WGNCH}}.     Fix $\gamma:[0,b)\to M$ a future inextendable null
    geodesic.
    %
    Consider $H=\partial I^{+}(\gamma_0)$ the future light-cone emanating from
    $\gamma_0$.
    %
    Applying part~\ref{GProper-to-WGNCH}, yields  that either $b=\infty$ or
    $\gamma$ leaves $H$.
    %
    In the latter case,  there exists $t\in (0,b)$ such that
    $\gamma_0\ll\gamma_{t}$.
\end{proof}











%







\subsection{Penrose's singularity theorem}\label{Ss:penrose}
Having thoroughly discussed the completeness issue, a possible way to state 
the desired result on the existence of trapped sets is the following: 
if $S$ is a compact
achronal surface, such that $(\partial I^+(S),G,\mm)$ satisfies the
$\NC^e(N)$ with a proper gauge
and $S$ is $(G,\mm)$-future converging, then $\partial I^{+}(H)$ is compact.


The $\NC^e(N)$ has already been defined.  It remains to discuss the
``$(G,\mm)$-future converging'' condition.
%
This is a delicate point, firstly because of the non-smooth synthetic setting, secondly because 
of the presence  of initial points of $H$ inside $S$, where the parametrization given by the
gauge is not available.
\\
We next define the ``$(G,\mm)$-future converging'' condition, followed by a discussion of its compatibility with the smooth notions. 


\begin{definition}\label{def:future-converging}
Let $(H,G,\mm)$ be a synthetic null
hypersurface satisfying the $\NC^e(N)$ condition,
with $H=\partial I^+(S)$, for some achronal set $S$.
  %

We say that $S$ is \emph{$(G,\mm)$-future converging},
if there exists $\theta<0$, such that
\begin{equation}\label{eq:mean-curvature}
   \limsup_{\epsilon \to 0^{+}}
\frac{\mm(S_\epsilon^{+}\cap \relation(A))-\epsilon\, \mm^{+}_{G}(S;A)
    }{
      \epsilon^2/2}
    \leq\theta
    \,
    \mm^{+}_{G}(S;A)
    ,
  \end{equation}  
for all $A\subset \noending{H}$.
\end{definition}  
%
 Recall that the classical future convergence requires the mean curvature of
  $S$ on both (incoming and outgoing) sides of $\partial I^{+}(S)$ to be strictly negative.
  %
  If $S$ is smooth and compact, this is equivalent to assume that its mean
  curvature (in both the incoming and outgoing directions) is bounded above by some $\theta<0$.
  %
  Equation~\eqref{eq:mean-curvature} is then an integral
  characterization of this curvature bound. The basic idea is that the mean curvature is given by first variation of area, and area is in turn given as first variation of volume. Notice indeed that~\eqref{eq:mean-curvature} corresponds to a second order Taylor expansion of the volume (cf.~\cite[Remark 5.4]{CaMo:20}, for a similar construction in the timelike framework). 
  %

  A careful reader may wonder about the necessity of the set  $A\subset \noending{H}$ in Definition~\ref{def:future-converging} and whether one can simplify the definition by stating 
  everything just in terms of $S$. The reason for including $A\subset \noending{H}$ in Definition~\ref{def:future-converging} is that, in general, there is more than one generator for $H$ leaving at
  each point of $S$ (in the classical setting, exactly two generators) and it is desirable to have a criterion to select exaclty one.
  %
  Restricting the analysis to $\relation(A)$, for any $A\subset \noending{H}$, allows to overcome this issue.
  % 
\smallskip

In the statement of the synthetic Penrose's theorem,
we will assume the gauge to satisfy the additional condition
  \begin{equation}
    \label{eq:infimum-of-gauge}
    \inf_{x\in H_\alpha}
    G(x)
    =
    0  
    ,
    \qquad
    \text{ for $\q$-a.e.\ } \alpha\in Q
    ,
  \end{equation}
%
where $Q$ is the quotient set of \Cref{T:disintegration}. In the smooth
setting, one can always find a gauge satisfying~\eqref{eq:infimum-of-gauge}, as discussed in \Cref{R:compatibility-penrose}.
%












Moreover we recall the classical terminology that a compact achronal set $S$ is \emph{future trapped} if $\partial I^+(S)$ is compact. 



\begin{theorem}[Penrose's theorem in a synthetic setting]\label{T:penrose}
Let $(H,G,\mm)$ be a null non-branching, synthetic null 
hypersurface satisfying the $\NC^e(N)$ condition for some $N> 2$,
where $H=\partial I^+(S)$ for some compact achronal set $S$, and  $\supp\mm=H$.
Assume moreover~\eqref{eq:infimum-of-gauge}.


  %
  If $S$ is $(G,\mm)$-future converging,
  then $\norm{G}_{L^\infty(\mm)}<\infty$.
  %
  In particular, if the gauge $G$ is proper, then   $H$ is compact; i.e., $S$ is future trapped.
\end{theorem}



\begin{proof}
We divide the proof in two parts. 


{\bf Step 1.}
By the Localization \Cref{T:localization}, there exists a disintegration of $\mm$, 
given by the measures $\mm_\alpha$ satisfying the $\CD(0,N-1)$ condition.
%
Let $h_\alpha:[0,b_\alpha)\to[0,\infty)$ be the density of $\mm_\alpha$.
%
%
For the class of synthetic null hypersurfaces 
fulfilling~\eqref{eq:infimum-of-gauge}
the relative Minkowski content can be more easily described.
%
In particular, it will be convenient to look for a class of sets $A \subset \noending{H}$ for which the following identity is valid: 
\begin{equation}\label{E:meancurvature}
   \int_{B} h_\alpha(0)\,\qq(d\alpha) 
   =
   \mm^{+}_{G}(S;A),  
\end{equation}
where $B = \relation(A) \cap Q$. 
To establish~\eqref{E:meancurvature}, notice that 
%
\[
    \limsup_{\epsilon\to 0^{+}}
    \frac{
      \mm(S^+_{\epsilon}\cap \relation (A))
    }{\epsilon}
= 
  \limsup_{\epsilon\to 0^{+}}
\frac{1}{\epsilon} 
\int_{B}\int_0^\epsilon h_\alpha(t)\, \de t.
\]
%
Since $t\mapsto h_\alpha(t)$ is continuous, we can consider the 
real-valued measurable map 
$Q \ni \alpha \mapsto \| h_\alpha(\cdot)\|_{L^\infty(0,1)}$. 
For each $\delta >0$ there exists a compact set $K\subset Q$
such that $\qq(K)> 1- \delta$ and, for all $\alpha \in K$, 
it holds that
$\| h_\alpha(\cdot)\|_{L^\infty(0,1)} \leq C$, 
for some positive constant. 
 A direct application of dominated convergence theorem implies that for all $A\subset \relation(K)\cap \noending{H}$,
the identity in \Cref{E:meancurvature} is valid. 

In the next step, we will use \Cref{E:meancurvature} in order to obtain an upper bound on $b_\alpha$ independent on $\delta>0$; this will imply  that $\|G\|_{L^\infty}<\infty$.  




{\bf Step 2.}
The concavity of the function $t\mapsto h_\alpha(t)^{\frac{1}{N-2}}$ implies that
\begin{equation}\label{eq:mcp-penrose}
    h_\alpha(t)
    \geq
h_\alpha(0)
    \bigg(
    \frac{b_\alpha-t}
    {b_\alpha }
    \bigg)^{N-2}
    ,
    \qquad
    \forall t\in[0,b_\alpha]
    .
\end{equation}
%
If  $N\geq 3$, Bernoulli's inequality
(i.e., $x^{N-2} \geq 1 + (N-2)(x-1)$,  for all $x\geq 0$) yields
\begin{equation}\label{eq:expansion-convexity}
  \begin{aligned}
  \int_{0}^{\epsilon}
\bigg(
      \bigg(
    \frac{b_\alpha-t}
    {b_\alpha }
    \bigg)^{N-2}
-
1
\bigg)
  \,\de t
  %
    \geq
    \frac{2-N}{b_\alpha}
\int_{0}^
{\varepsilon}
    t
      \,\de t
    =
    \epsilon^2
    \frac{2-N}{2b_\alpha}
    ,
    \qquad
    \forall
    \epsilon >0
    .
  \end{aligned}
\end{equation}
If $2<N< 3$, the trivial inequality $x^{N-2} \geq  x$, holding for all $x\in [0,1]$, implies that
\begin{equation}\label{eq:expansion-convexityN-less-3}
  \begin{aligned}
  \int_{0}^{\epsilon}
\bigg(
      \bigg(
    \frac{b_\alpha-t}
    {b_\alpha }
    \bigg)^{N-2}
-
1
\bigg)
  \,\de t
  %
    \geq
    {b_\alpha}
\int_{0}^
{\varepsilon}
    t
      \,\de t
    =
    \frac{\epsilon^2}
    {2b_\alpha}
    ,
    \qquad
    \forall
    \epsilon >0
    .
  \end{aligned}
\end{equation}
In the rest of the proof, we will assume that $N\geq 3$ and we will use~\eqref{eq:expansion-convexity}; in case $2<N<3$, the argument is completely analogous, using~\eqref{eq:expansion-convexityN-less-3}.


Let $\theta<0$ be given by \Cref{def:future-converging}.
%
Consider any $\delta>0$
and the let $K\subset Q$ be 
given by the step 1 of the proof.
Let
$A\subset \relation(K)\cap \noending{H}$ be any measurable set where~\eqref{E:meancurvature} holds, with  $B=\relation(A)\cap Q$.
% 
Then~\eqref{eq:mean-curvature} can written as
\begin{align*}
   \theta
  \int_{B}
  h_\alpha(0)
  \,
  \q(\de\alpha)
  & 
\overset{\eqref{eq:mean-curvature}}{\geq}
     \limsup_{\epsilon \to 0^{+}}
  \frac{2}{\epsilon^2}
  \int_{B}
  \int_{0}^{\epsilon}
  (h_\alpha(t)-h_\alpha(0))\,\de t
  \,
    \q(\de\alpha)
  \\
  %
  &
  \overset{\eqref{eq:mcp-penrose}}{\geq}
       \limsup_{\epsilon \to 0^{+}}
  \frac{2}{\epsilon^2}
  \int_{B}
  h_\alpha(0)
  \int_{0}^{\epsilon}
      \bigg(
      \bigg(
    \frac{b_\alpha-t}{b_\alpha}
    \bigg)^{N-2}
-
1
\bigg)
  \,\de t
  \,
  \q(\de\alpha) 
    \\
  %
  &
  \overset{\eqref{eq:expansion-convexity}}{\geq}
  \int_{B}
  \,
  h_\alpha(0)\frac{2-N}{b_\alpha}
  \,
  \q(\de\alpha)
  .
\end{align*}
%
The arbitrariness of $A\subset \relation(K) \cap \noending{H}$ implies the 
arbitrariness of $B\subset K$, and thus 
\begin{equation}\label{eq:balphaleqN-2Theta}
b_\alpha \leq -\frac{N-2}{\theta}
,
\qquad
\text{ for $\q$-a.e.\ }\alpha\in K
.
\end{equation}
Since the estimate is independent of $\delta >0$, taking the limit as $\delta \to 0$ yields that the inequality in~\eqref{eq:balphaleqN-2Theta} is valid for $\qq$-a.e.\;$\alpha \in Q$.
Combining this with~\eqref{eq:infimum-of-gauge}, we deduce 
that
\[
G(x)\in\left[0,\frac{2-N}{\theta}  \right]
, \quad
\text{for $\mm$-a.e.\ $x\in \noending{H}$}.
\]
  %
The properness of $G$ implies that $G^{-1}([0,\frac{2-N}{\theta} ])$ is precompact. 
 Therefore $\mm$ is concentrated on a precompact set, yielding that
  $H=\supp\mm$ is compact.
\end{proof}


% \begin{remark}[Properness of the gauge as a ``synthetic null-geodesic completeness"]
%   Let us discuss the properness condition of gauge functions.
%   %
%   In the smooth setting, consider a compact $(n-2)$-space-like
%   manifold $S$ and its closed achronal set $H$.
%   %
%   Provided that the space is future light-like complete, then it is possible to
%   endow $H$ by a natural gauge function which is proper (we will use the notation of~\Cref{R:compatibility}).
%   Indeed, in this case, $\gflow_{L}$ coincides with the exponential map of the null
%   vector field $L$.
%   %
%   The properness of the gauge follows by the compactness of $S$, coupled with the fact
%   that the exponential map is everywhere defined on future light-like
%   vectors, thanks to the future light-like completeness 
%   (cf.~\cite[Prop.~60]{O'Neill}).

%   Thus, \emph{the properness of the gauge shall be seen as a synthetic counterpart of the null geodesic completeness}. Indeed the latter is formulated in terms of solutions of the geodesic equation, which is not available in the synthetic setting (or for continuous spacetimes).
% \end{remark}

\begin{remark}\label{R:non-constant-infimum}
Inspecting the proof of \Cref{T:penrose}, one can check that the assumption~\eqref{eq:infimum-of-gauge} can be replaced by the following weaker (but slightly more technical) condition: 
%
the function 
    $
    \alpha\mapsto \mathcal{G}(\alpha):=  \inf_{x\in H_\alpha} G(x)
    $ belongs to $L^\infty(\qq)$.
    In this case, the proof gives that 
    $G\leq \frac{2-N}{\theta}+\|\mathcal{G}\|_{L^\infty(\qq)}$, $\mm$-a.e.. The same argument as above yields that, if $G$ is proper, then $H$ is compact.
\end{remark}

  \begin{remark}
    In the spirit of \Cref{P:covariance-area}, we discuss how
    \Cref{T:penrose} behaves under a different choice of  gauge and
     reference measure.
    %
    Namely, let $H=\partial I^{+}(S)$ and let $G_{i}$ be a gauge for $H$
    and $\mm_{i}$ be a measure, $i=1,2$.
    %
    Assume that $G_1$ and $G_2$ (resp.\ $\mm_1$ and $\mm_2$) are related by the covariance relation   (cf.\ \Cref{P:characterization-equivalence})
    \[
      G_1=f+hG_2, \quad \mm_1=\frac{1}{h}\mm_2,
    \]
    for some  transverse functions $h$ and $f$, 
    \begin{equation}\label{eq:boundfhC}
    -C\leq f \leq C, \quad 1/C \leq h\leq C,
    \end{equation}
    for some constant $C\geq 1$.
 Let us discuss the invariance of the assumptions of \Cref{T:penrose}, under such transformations.
    \begin{itemize}
    \item The assumption that the reference measure has full support is trivially preserved (i.e.,
      $\supp \mm_1=H\iff\supp \mm_2=H$).
    \item Eq.~\eqref{eq:infimum-of-gauge} is not  preserved exactly; however,
      one can apply \Cref{R:non-constant-infimum}, noting that
        the condition $\norm{\mathcal{G}}_{L^{\infty}(\q)}<\infty$ is preserved.
    \item Regarding the  future converging assumption, following the argument of
      \Cref{P:covariance-area} one can prove that $S$ is
      $(G_1,\mm_1)$-future converging if and only if it is
      $(G_2,\mm_2)$-future converging.
      %
      In this case, the constant $\theta$ is replaced by
      $\theta/C$.
    \end{itemize}
    %
    Notice that also the thesis of \Cref{P:covariance-area} is covariant, i.e., properness of the
    gauge does not depend on the choice of the gauge but only
    on its equivalence class; indeed,
    $G_2^{-1}([-a,a])\subset G_1^{-1}([-C(a+1),C(a+1)])$.

    Finally, let us point out that the bound~\eqref{eq:boundfhC} is necessary, otherwise both the hypothesis and
    the thesis of \Cref{P:covariance-area}  would cease to be invariant.

  \end{remark}
  % 












      The following corollary follows by combining \Cref{T:penrose}
and the $C^0$-extension
of the classical result by Penrose, stating that there are no future
trapped sets in a spacetime admitting a non-compact Cauchy surface,
as specified in Th.~4.9 of~\cite{Ling}, after~\cite[Th.~2.67]{Min}.
%
We refer
to~\cite{Chr-Grant, SaC0, Ling, Minguzzi-Review2019} for the basics of causality theory and useful notions for continuous spacetimes.




\begin{corollary}[Penrose's singularity theorem in $C^0$-spacetimes]\label{Cor:PenroseC0}
Let $(M,g)$ be a spacetime endowed with a continuous Lorentzian metric.
%
Let $S\subset M$ be a compact achronal set. Let $H=\partial I^+(S)$ and endow $H$ with a gauge function $G$ satisfying~\eqref{eq:infimum-of-gauge} and a positive Radon measure $\mm\in \M^+(H)$ with $\supp \mm=H$.
%
Assume that $H$ is null non-branching
%
\footnote{%
The assumption that $H$ is null non-branching is always satisfied
if 
\begin{itemize}
\item $\noending{H}$ is $C^{1,1}$ and $g$ is locally Lipschitz 
(see  \Cref{prop:Lipschitz-nonBranch}), 
\item  $g$ is $C^2$, 
without any further regularity assumption on $H$ (see \Cref{C:null-non-branching-c2}).
\end{itemize}
}
and that:
\begin{enumerate}
\item The synthetic null hypersurface $(H,G,\mm)$ satisfies the
$\NC^e(N)$ condition, for some $N>2$.
\item $(M,g)$ admits a non-compact Cauchy surface.
\item $S$ is $(G,\mm)$-future converging.
\end{enumerate}
 Then the gauge $G$ cannot be proper.
\end{corollary}

\begin{proof}
Assume by contradiction that $(M,g)$  contains a compact achronal set $S\subset M$ such that $H=\partial I^+(S)$ satisfies the conditions (1), (2), (3) and moreover the gauge $G$ is proper. Then, Theorem~\ref{T:penrose} implies that $S$ is future trapped.
Since by assumption $(M,g)$ admits a non-compact Cauchy surface, we obtain a contradiction with~\cite[Thm.\,4.9]{Ling}.
\end{proof}

\begin{remark}
The corollary above is valid also for the more general setting of closed cone structures.
%
In this case, one needs to assume the existence of a stable Cauchy hypersurface and apply~\cite[Th.~2.67]{Min}, in place of~\cite[Th.~4.9]{Ling}. 
\end{remark}

Finally, we state and prove a version of Penrose's singularity theorem where the incomplete geodesic is \emph{maximizing}. The maximizing property was implicit in Penrose's arguments \cite{Penrose65,Penrose-DiffTopGR} and is known to experts (see for instance \cite[Sec.\,12.4]{BEE-Book} and \cite[Th.\,2.67]{Min}). Nevertheless, we include it with a proof for the reader's convenience. 


\begin{corollary}[Penrose's  maximizing incompleteness Theorem]\label{cor:SharpenedPenrose}
Let $(M,g)$ be a spacetime endowed with a  $C^2$ Lorentzian metric.
Assume that:
\begin{enumerate}
    \item 
    The \NEC\ holds.
    \item 
    $M$ admits a non-compact Cauchy hypersurface.
    \item 
    There exists a future-converging compact $(n-2)$-dimensional achronal 
    space-like  $C^2$ submanifold $S$.
    %(i.e., the mean curvature vector of $S$ is timelike and past-pointing).
\end{enumerate}


Then there exists an inextendible (on the right),  null geodesic $\gamma:[0,b)\to \R$, $b<\infty$. 

Moreover, $\gamma$ is maximizing, i.e., $\tau_{g}(\gamma_{s}, \gamma_{t})=0$ for all $s\leq t\in [0,b)$.
\end{corollary}

\begin{proof}  
The existence of a Cauchy hypersurface implies that $(M,g)$ is strongly causal.
We can therefore apply \Cref{R:compatibility-penrose} and endow 
$H:=\partial I^{+}(S)$ with a natural gauge $G$ and the associated rigged measure $\mm$, 
making $(H,G,\mm)$ a synhtetic null hypersurface, which, by 
\Cref{thm:compatibilityNEC-NCe}, satisfies $\NC^e(n)$.
As observed after~\eqref{eq:defGhatH},
  $G$ can be continuously extended to $0$ on the set
  $\initial$ of initial points of the null generators of $H$, thus it satisfies \eqref{eq:infimum-of-gauge}.  We next claim that
%
$S$ is 
$(G,\mm)$-future-converging.
%
Indeed, one can check~\eqref{eq:mean-curvature} by 
performing a second-order Taylor expansion in $\epsilon$ of $\mm(A^+_\epsilon)$ and then apply the future-converging hypothesis (cf.~\cite[Remark~5.4]{CaMo:20}).
%
Applying \Cref{Cor:PenroseC0}, yields that $G$ is not proper.
%
By the first point of \Cref{prop:wgnc}, it follows that $(M,g)$  is not weakly 
future null complete; i.e, there exists an inextendible null geodesic like in the claim which is a global maximizer.
\end{proof}



\section{Stability of the \texorpdfstring{$\NC^e(N)$}{NCe(N)} condition}\label{Sec:StabNCe}

In this section we state and prove two stability theorems for the
\NEC. The first one is a null counterpart of Sturm's  stability of the $\CD$ condition \cite{sturm:I, sturm:II}.

We recall that, in a metric space $(X,\sfd)$ given a sequence of
closed sets $B_{n}$, $n\in\N$ the   Kuratowski-lim-sup
 of $B_{n}$ is
\begin{equation}\label{eq:kuratowski-definition}
    \text{K-}\limsup_{n\to\infty}
    B_{n}
    =
    \{
    x\in X
    \colon 
    \exists
    \text{ a subsequence }
    x_{n_{k}}\in B_{n_{k}}
    \text{ such that }
    x_{n_{k}}\to x
    \}
    .
\end{equation}




We recall the definition of push-up property.
%

\begin{definition}\label{def:push-up}
  Let $(X,\leq,\ll)$ be a causal space.
  %
  We say that it has the \emph{push-up property}, if $\forall x,y,z\in X$
  \begin{equation}
    x\leq y\ll z
    \text{ or }
    x\ll y\leq z
    \qquad
    \implies
    \qquad
    x\ll z
    .
  \end{equation}
\end{definition}

The push-up property is satisfied in 
locally-Lipschitz Lorentzian manifolds~\cite{Chr-Grant}
and, more generally, in Lorentzian pre-length spaces~\cite{KS} (see also~\cite{Ling} for the case of $C^0$-Lorentzian metrics). 



\begin{theorem}\label{thm:StabNCProb}
  Let $(X,\ll,\leq, \mathfrak{T})$ be a topological causal space 
  satisfying the push-up property and let $N>1$.
  %
  Let $(H_{n},G_{n},\mm_{n})$, $n\in\N\cup\{\infty\}$, be a sequence of 
  synthetic null hypersurfaces, with $\mm_{n}\in\Prob(H_{n})$.
  %
  Assume the following.
  \begin{enumerate}
  \item
    There exist  monotone
   (recall \Cref{D:monotoneplan})
    transport plans $\Lambda_{n}\in
    \Pi(\mm_\infty,\mm_{n})$,
    such that
    \begin{equation}
      \label{eq:convergence-lambda}
       \Lambda_{n}
      \weak
      (\id,\id)_{\sharp}
      \mm_\infty
      ,
      \qquad
      \text{ in duality with continuous and bounded functions}
      .
    \end{equation}
    \item
    For every compact set $K\subset X$, the set of curves
    \begin{equation}
    \label{eq:compactness-gauges}
        \{\gamma\in C([0,1];X)\colon
        \gamma \in C_{G_{n}}\text{ for some 
        $n\in\N$ and }
        \gamma_{i}\in K,\, i=0,1
        \}
        \text{ is precompact.}
    \end{equation}
  \item 
  Denoted by $C_{G_{n}}$  the set of $G_{n}$-causal curves, it 
  holds that
  \begin{equation}\label{eq:kuratowski-gauges}
      \text{\rm K-}\limsup_{n\to\infty}
      C_{G_{n}}
      \subset C_{G_\infty}
      .
  \end{equation}
    \end{enumerate}

    If the synthetic null hypersurfaces $(H_{n},G_{n},\mm_{n})$ satisfy the $\NC^e(N)$
    condition, for all $n\in \N$, then also
    $(H_\infty,G_\infty,\mm_\infty)$ satisfies the $\NC^{e}(N)$
    condition, as well.
\end{theorem}

\begin{proof}
  Let $\mu_{i}^\infty\in\Prob(H_\infty)$, $i=0,1$, be two probability
  measures, transported one in the other by a plan
  $\hat\pi_\infty\in \Pi_{\leq}(\mu_0^\infty,\mu_1^\infty)$.
  %
  Notice that, if $\mu_{i}^\infty$ is not absolutely continuous
  w.r.t.\ $\mm_\infty$, then the concavity inequality of $\NC^e(N)$ 
  trivializes; therefore we can assume that $\mu_{i}^\infty\ll\mm_\infty$.
\smallskip

\textbf{Step 1}. Definition of the approximations $\mu_{i}^n\in \Prob(H_{n})$, $i=1,2$.  
\\  We disintegrate $\Lambda_{n}$, in the following way
  \begin{equation}
    \Lambda_{n}
    =
    \int_{H_\infty}
    \Lambda_{n,x}
    \,
    \mm_\infty(\de x)
    ,
  \end{equation}
  where $\Lambda_{n,x}$ is a probability measure concentrated on
  $\{x\}\times H_{n}$.
  %
  Notice that, by monotonicity of $\Lambda_{n}$, if $x\leq y$,
  then 
  \begin{equation}\label{eq:monotonicity-Lambda}
       (P_2)_{\sharp}\Lambda_{n,x}
     \otimes
      (P_2)_{\sharp}\Lambda_{n,y}
      (J)
      =1
      .
  \end{equation}
  %
  We  push the measures
  $\mu_{i}^\infty$ and $\hat\pi_\infty$, as follows
  \begin{equation}
    \label{eq:defn-mu-n-pi-n}
    \mu_{i}^n
    :=
    \int_{H_\infty}
    (P_2)_{\sharp}\Lambda_{n,x}
    \,
    \mu_{i}^\infty(\de x)
    ,
    \qquad
    \hat\pi_{n}
    :=
    \int_{H_\infty\times H_\infty}
    ((P_2)_{\sharp}\Lambda_{n,x})
    \otimes
    ((P_2)_{\sharp}\Lambda_{n,y})
    \,
    \hat\pi_\infty(\de x\,\de y)
    ,
  \end{equation}
  where $P_2$ is the projection on the second variable.
  %
  We now check that $\hat\pi_{n}$ is a transport plan between $\mu_0^n$ and
  $\mu_1^n$:
  \begin{align*}
    (P_1)_{\sharp}
    \hat\pi_{n}
    &
      =
    (P_1)_{\sharp}
    \int_{H_\infty\times H_\infty}
    ((P_2)_{\sharp}\Lambda_{n,x})
    \otimes
    ((P_2)_{\sharp}\Lambda_{n,y})
    \,
      \hat\pi_\infty(\de x\,\de y)
    \\
    %
    &
      =
    \int_{H_\infty\times H_\infty}
    (P_1)_{\sharp}
      (
      ((P_2)_{\sharp}\Lambda_{n,x})
    \otimes
      ((P_2)_{\sharp}\Lambda_{n,y})
      )
    \,
    \hat\pi_\infty(\de x\,\de y)
    \\
    %
    &
      =
    \int_{H_\infty\times H_\infty}
      (P_2)_{\sharp}\Lambda_{n,x}
    \,
    \hat\pi_\infty(\de x\,\de y)
      =
    \int_{H_\infty\times H_\infty}
      (P_2)_{\sharp}\Lambda_{n,x}
    \,
      \mu_0^\infty(\de x)
      =
      \mu_0^n
      ,
  \end{align*}
  and analogously one can prove the same for the other projection.
  %
  The next step is to prove that $\hat\pi_{n}(J)=1$:
  \begin{align*}
    \hat\pi_{n}(J)
    &
    =
    \int_{H_\infty\times H_\infty}
    ((P_2)_{\sharp}\Lambda_{n,x})
    \otimes
    ((P_2)_{\sharp}\Lambda_{n,y})
    (J)
    \,
    \hat\pi_\infty(\de x\,\de y)
    \\
    %
    &
    =
    \int_{H_\infty\times H_\infty
    \cap J}
    ((P_2)_{\sharp}\Lambda_{n,x})
    \otimes
    ((P_2)_{\sharp}\Lambda_{n,y})
    (J)
    \,
    \hat\pi_\infty(\de x\,\de y)
    \overset{\text{\eqref{eq:monotonicity-Lambda}}}{=}1
    .
  \end{align*}
\smallskip

\textbf{Step 2}. Proof that $\mu_{i}^n\weak\mu_{i}^\infty$, $i=0,1$.





  %
  We first claim that, up to a subsequence,
%
\begin{equation}\label{eq:P2LambdatoDelta}
  (P_2)_{\sharp}(\Lambda_{n,x})\weak\delta_{x}, \quad \text{for $\mm_\infty$-a.e.\ $x$.}
  \end{equation}
%
 Indeed, using assumption~\eqref{eq:convergence-lambda},
  we compute
  \begin{align*}
    0&=
       \int_{X\times X} \sfd\wedge 1
       \;
       \de((\id,\id)_{\sharp}\mm_\infty)
       =
       \lim_{n\to\infty}
       \int_{X\times X} \sfd\wedge 1
       \,
       \de\Lambda_{n}
    \\
    %
    &
       =
       \lim_{n\to\infty}
       \int_{\noending{H}}
       \int_{X\times X} \sfd\wedge 1
       \,
       \de\Lambda_{n,x}
       \,
      \mm_\infty(\de x).
  \end{align*}
  Therefore, the function
  \begin{equation}
    \label{eq:convergence-disintegration}
    x\mapsto
       \int_{X\times X} \sfd\wedge 1
       \,
       \de\Lambda_{n,x}
       =
       \int_{X}
       \sfd(x,y)
       \wedge 1
       \,
       ((P_2)_{\sharp}\Lambda_{n,x})(\de y)
  \end{equation}
  converges in $L^1(\mm_\infty)$ to $0$ (in the last equality we used
  the fact that $\Lambda_{n,x}$ is concentrated on $\{x\}\times H_{n}$).
  %
  Up to a subsequence, it also converges $\mm_\infty$-a.e.\;to $0$,  proving the claim~\eqref{eq:P2LambdatoDelta}.

  Using the claim~\eqref{eq:P2LambdatoDelta}, we next show that $\mu_{i}^n\weak\mu_{i}^\infty$, $i=0,1$. Since the  weak convergence is  metrizable, it is enough to show that any subsequence of $\mu_{i}^n$ converges to $\mu_{i}^\infty$.
  %
  To this aim,  fix $\phi\in C_{b}(X)$ and compute, using~\eqref{eq:P2LambdatoDelta} and
  dominated convergence theorem:
  \begin{align*}
    \lim_{n\to\infty}
    \int_{X}
    \phi
    \,
    \de\mu_{i}^n
    &
      %
    =
    \lim_{n\to\infty}
    \int_{\noending{H}}
    \int_{X}
    \phi(y)
    \,
    (P_2)_{\sharp}(\Lambda_{n,x})(\de y)
    \mu_{i}^\infty(\de x)
    \\
    %
    &
    =
    \int_{\noending{H}} \left(
    \lim_{n\to\infty}
    \int_{X}
    \phi(y)
    \,
    (P_2)_{\sharp}(\Lambda_{n,x})(\de y) \right)
    \mu_{i}^\infty(\de x)
    \overset{\eqref{eq:P2LambdatoDelta}}{=}x
    \int_{\noending{H}}
    \phi(x)
    \mu_{i}^\infty(\de x)
    ,
  \end{align*}
  yielding that $\mu_{i}^n\weak\mu_{i}^\infty$, $i=0,1$.
  %



  Arguing as in  of~\cite[Lemma~4.19]{sturm:I}, since 
  $\mu_{i}^n=(\Lambda_{n})_{\sharp}\mu_{i}^\infty$
  and 
  $\mm_{n}=(\Lambda_{n})_{\sharp}\mm_\infty$, we deduce that
  \begin{equation}
    \label{eq:entropy-decreases-push-forward}
    \Ent(\mu_{i}^n|\mm_{n})
    \leq
    \Ent(\mu_{i}^\infty|\mm_\infty)
    .
  \end{equation}
  %

\textbf{Step 3}. Weak  convergence of the  $G_{n}$-causal
dynamical optimal transport plans.
\\  Let now $\nu_{n}\in\OptGeo^{G_{n}}(\mu_0^n,\mu_1^n)$ be the $G_{n}$-causal
dynamical optimal transport plan given by the definition of
$\NC^e(N)$,
 i.e., (recall~\eqref{eq:defSN}, for the definition of $\U_{N}$)
  \begin{equation}
    \label{eq:concavity-entropy-in-stability-proof}
    \U_{N-1}((e_{t})_{\sharp}\nu_{n}|\mm_{n})
    \geq
    (1-t)
    \U_{N-1}((e_0)_{\sharp}\nu_{n}|\mm_{n})
    +
    t
    \U_{N-1}((e_1)_{\sharp}\nu_{n}|\mm_{n})
    .
  \end{equation}
  %
  %
  We show that the sequence $\nu_{n}$ is tight.
  %
  Fix $\epsilon>0$.
  %
  By tightness of $(\mu_{i}^n)_{n}$, there exists a compact set
  $K\subset X$ such that $\mu_{i}^\infty(K)\geq 1-\epsilon$,
  $i=0,1$, for all $n\in \N\cap\{\infty\}$.
  %
  We deduce that
  $\nu_{n}(C_{K})\geq 1-2\epsilon$, where
  $C_{K}\subset C([0,1]; X)$ is the family set
  of $G_{n}$-causal curves with endpoints in $K$.
  %
  By~\eqref{eq:compactness-gauges}, we have that $C_{K}$ is 
    compact, therefore the family $(\nu_{n})_{n}$ is tight.
%
    By Prokhorov's Theorem, up to taking
    a subsequence, it holds 
    that $\nu_{n}\weak\nu_\infty$, for some probability
    measure $\nu_\infty$.

    We claim that $\nu_\infty$ is
  concentrated on $G_\infty$-causal curves in $H_\infty$.
  %
  Since $(e_0,e_1)_{\sharp}\nu_\infty\in\Pi_\leq(\mu_0^\infty,\mu_1^\infty)$, then $\nu_\infty$ is concentrated on causal curves whose end-points belong to $H_\infty$.
  %
  Since $H_\infty$ is  a closed achronal set, 
  by the push-up property, any causal curve with endpoints in $H_\infty$ 
  lays in $H_\infty$, therefore $\nu_\infty$ is concentrated 
  on causal curves in $H_\infty$.
  %
  Making use of Lemma~\ref{lem:kuratowski-weak} below, we can thus compute
\begin{align*}
    1=
    \limsup_{n\to\infty}
  \nu_{n}(C_{G_{n}})
  \overset{\eqref{eq:kuratowski-weak}}{\leq}
    \nu_\infty\Big(  \text{\rm K-}\limsup_{n\to\infty}
C_{G_{n}}\Big)
    \overset{\eqref{eq:kuratowski-gauges}}{\leq}
    \nu_\infty(C_{G_\infty})
    \leq
    1
    .
\end{align*}


  Using the joint lower semicontinuity of the entropy under weak convergence of probability measures~\cite[Theorem 29.20]{villani:oldandnew}, we deduce that
  \begin{align}
    \label{eq:convergence-sturm-middle-points}
    \liminf_{n\to\infty}
    \Ent((e_{t})_{\#}(\nu_{n})|\mm_{n})
    \geq
    \Ent((e_{t})_{\#}(\nu_\infty)|\mm_\infty).
  \end{align}
  %
    We can thus compute
    \begin{equation*}
      \begin{aligned}
        \U_{N-1}((e_{t})_{\sharp}\nu_\infty|\mm_\infty)
        &\overset{\eqref{eq:convergence-sturm-middle-points}}{\geq}
        \limsup_{n\to\infty}
        \U_{N-1}((e_{t})_{\sharp}\nu_{n}|\mm_\infty)
        \\
        %
        &
          \overset{\eqref{eq:concavity-entropy-in-stability-proof}}{\geq}
          \limsup_{n\to\infty}
          \big(
          (1-t)
          \U_{N-1}((e_0)_{\sharp}\nu_{n}|\mm_{n})
          +
          t
          \U_{N-1}((e_1)_{\sharp}\nu_{n}|\mm_{n})
          \big)
        \\
        %
        &
          \overset{\eqref{eq:entropy-decreases-push-forward}}{\geq}
          (1-t)
          \U_{N-1}((e_0)_{\sharp}\nu_\infty|\mm_\infty)
          +
          t
          \U_{N-1}((e_1)_{\sharp}\nu_\infty|\mm_\infty)
          .
      \end{aligned}
    \end{equation*}
    deducing that $\nu_\infty$ enjoys concavity for the entropy, thus
    $(H_{\infty},G_\infty,\mm_\infty)$ is $\NC^e(N)$.  
\end{proof}


The next two technical lemmas (included for the
reader's convenience) recall two elementary facts linking the
Kuratowski convergence of sets and the weak convergence of probability
measures.


\begin{lemma}\label{lem:kuratovski-characterization}
  Let $(X,\sfd)$ be a metric space.
  %
  Let $(C_{n})_{n}$ be a sequence of subsets of $X$.
  %
  Assume that $\text{\rm K-}\limsup_{n\to\infty} C_{n}\subset C$, for
  some subset $C\subset X$.

  Then, for any compact subset $K\subset X$, the following holds: for every 
  $\epsilon>0$ there exists $k\in\N$  such that
    \begin{equation}
      C_{n}\cap K
      \subset C^{\epsilon}, \quad \text{for all } n>k.
    \end{equation}
\end{lemma}
\begin{proof}
  Assume on the contrary that there exists $\epsilon_0>0$ such that, up
  to passing to a unrelabeled subsequence, there exists a sequence
  $x_{n}\in C_{n}\cap K$, such that $\dist(x_{n},C)>\epsilon_0$.
  %
  Up to a further  subsequence, using the compactness of
  $K$, we have that $x_{n}\to x$, for some $x\in K$.
  %
  Therefore, by definition of Kuratowski
  convergence~\eqref{eq:kuratowski-definition}, we infer that
  $x\in\text{\rm K-}\limsup_{n\to\infty} C_{n}\subset  C$. This contradicts that
   $\dist(x, C)\geq\epsilon_0$.
\end{proof}


\begin{lemma}\label{lem:kuratowski-weak}
  Let $(X,\sfd)$ be a Polish space.
  %
  Let $(\mu_{n})_{n}$ be a sequence of probability
  measures, weakly converging to $\mu$.
  %
  Let $(C_{n})_{n}$ be a sequence of subsets of $X$.
  %
  Then
  \begin{equation}
    \label{eq:kuratowski-weak}
    \limsup_{n\to\infty}
    \mu_{n}(C_{n})
    \leq
    \mu\Big(
    \text{\rm K-}\limsup_{n\to\infty} C_{n}
    \Big)
    .
  \end{equation}
\end{lemma}
\begin{proof}
  Define $C:=\text{\rm K-}\limsup_{n\to\infty} C_{n}$.
  %
  Fix $\epsilon>0$.
  %
  By tightness, there exists a compact set $K\subset X$, such that
  $\mu_{n}(K)\geq 1-\epsilon$, for all $n$.
  %
  From \Cref{lem:kuratovski-characterization}, we deduce that $C_{n}\cap K\subset C^\epsilon$, for all
  $n$ large enough.
  %
  It follows that
  \begin{align*}
    \limsup_{n\to\infty}
    \mu_{n}(C_{n})
    &
    \leq
    \limsup_{n\to\infty}
    \mu_{n}(C_{n}\cap K)
    +\epsilon
    \leq
    \limsup_{n\to\infty}
    \mu_{n}(C^{\epsilon})
    +\epsilon
    \\
    %
    &
    \leq
    \mu(\overline{C^{\epsilon}})
    +\epsilon
    \leq
    \mu(C^{2\epsilon})
    +\epsilon
    ,
  \end{align*}
  having used the upper semicontinuity of measures of a closed set
  under weak convergence.
  %
  By arbitrariness of $\epsilon>0$, since $C$ is closed, we conclude.
\end{proof}


%
On a closed achronal set $H$ endowed with a gauge $G$, we define the set 
of $(G,\epsilon)$-causal curves as
\begin{align*}
  C_{G,\epsilon}:=\bigg\{
  &
    \gamma:[0,1]\to H
    \text{ causal: }
  \gamma_{r}\in \noending{H},
  \forall r\in(0,1)
    \text{ and }
  \\
  %
  &
    \qquad 
    \bigg|
    \frac{G(\gamma_{t})
    -G(\gamma_{s})}{t-s}
    -
%    \frac{
    \lim_{u\to 0^{+}}(G(\gamma_{1-u})-G(\gamma_{u}))
%    }{
%   1-2\epsilon}
    \bigg|
    \leq \epsilon
    \lim_{u\to 0^{+}}(G(\gamma_{1-u})-G(\gamma_{u}))
    ,
    \\
    %
    &
   \;\ \qquad
        \forall t,s\in(0,1)
    \colon t<s
    \bigg\}
    .
\end{align*}
%
%Such set will be denoted by $C_{G,\epsilon}$.

We stress out that the limit in the definition above 
exists by monotonicity.
%
Moreover, the definition is invariant by an affine transformation 
of $G$ (cf.\ \Cref{P:characterization-equivalence}).  

\smallskip



The next result shall be seen as a  null counterpart
   of Lott and
 Villani's~\cite{lottvillani, villani:oldandnew} stability of the $\CD(K,N)$ condition under pointed measured Gromov--Hausdorff convergence of pointed metric measure spaces. More precisely, the next theorem establishes a stability result for the $\NC^e(N)$ condition under a suitable pointed measured convergence of (possibly) non-compact synthetic null hypersurfaces endowed with a $\sigma$-finite measure (note that, in the previous stability result, Theorem~\ref{thm:StabNCProb}, the reference measures $\mm_{n}$ were probabilities).  
In order to handle convergence in such a higher generality, it is convenient to consider \emph{pointed}  synthetic null hypersurfaces  $(H,G,\mm, \star)$, where $\star\in H$ is a marked point.


\begin{theorem}\label{thm:StabNCePointed}
Let $N>1$.
%
  Let $(X_{n},\leq_{n},\ll_{n}, \mathfrak{T}_{n})$, $n\in\N\cup\{\infty\}$
  be a sequence of topological causal spaces.
  %
  Let $(H_{n},G_{n},\mm_{n}, \star_{n})$, $n\in\N\cup\{\infty\}$ be a pointed
  synthetic null hypersurface in $(X_{n},\leq_{n},\ll_{n},\mathfrak{T}_{n})$,
  $n\in\N\cup\{\infty\}$.
  %
  Assume the following.
  \begin{enumerate}
  \item
    There exist Borel and monotone maps $h_{n}: H_{n}\to H_\infty$
    and $g_{n}:H_\infty\to H_{n}$ and an infinitesimal
    sequence $\epsilon_{n}\downarrow 0$, 
    such that $h_{n}(\star_{n})=\star_\infty$
    and $g_{n}(\star_\infty)=\star_{n}$,
    \begin{align}
  %
      \label{eq:weak-hn}
  &
    (h_{n})_{\sharp}\mm_{n}\weak \mm_\infty,
      \\
      %
      \label{eq:assumption-sigma}
  &
    (g_{n})_{\sharp}(\mm_\infty)=\sigma_{n}\mm_{n},
    \qquad
    \text{
    %for some
    %density functions satisfying
    with \qquad 
    }
    \sigma_{n}\leq 1+ \epsilon_{n},
  \\
  %
  &
    \label{eq:compatibility-g-h}
    h_{n}\circ g_{n}(x)
    \to x
    ,
    \qquad
    \text{ for $\mm_\infty$-a.e.\ }
    x\in H_\infty
    .
\end{align}
%
Moreover $h_{n}$ transforms, by post-composition, $G_{n}$-causal
      curves into $(G_\infty,\epsilon_{n})$-causal
      curves; i.e., 
      \[
      h_{n}\circ\gamma\in C_{G_\infty,
      \epsilon_{n}},\quad  \text{for all }\gamma\in C_{G_{n}}.
      \]
\item For every precompact set $K\subset \noending{H}_\infty$ 
and for every $\epsilon>0$,
it holds that the set
\begin{equation}
  \begin{aligned}
    \label{eq:uniform-compactness}
    &\{
    \gamma\in C_{G_\infty,\epsilon}
    \colon
    \gamma_{i}\in K, i=0,1
    \}
    \text{ is precompact}
    .
    \end{aligned}
\end{equation}
\item It holds that\footnote{Since
    $C_{G_\infty,\epsilon}$ is a decreasing sequence of sets, the
    assumption~\eqref{eq:kuratowski-G-epsilon} is equivalent to
    require that
    $C_{G_\infty}= \bigcap_{\epsilon>0}C_{G_\infty,\epsilon}
    =\text{K-}\lim_{\epsilon\to 0} C_{G_\infty,\epsilon}$.  }
\begin{equation}\label{eq:kuratowski-G-epsilon}
    \text{\rm K-}\limsup_{\epsilon\to 0}
    C_{G_\infty,\epsilon}
    \subset
    C_{G_\infty}
    .
\end{equation}
  \end{enumerate}

    If the synthetic null hypersurfaces $(H_{n},G_{n},\mm_{n})$ satisfy the $\NC^e(N)$
    condition, for all $n\in \N$, then also
    $(H_\infty,G_\infty,\mm_\infty)$ satisfies the $\NC^{e}(N)$
    condition, as well.
\end{theorem}



\begin{remark} Recently, inspired by the measured Gromov--Hausdorff convergence in positive signature,  several notions of convergence for smooth and non-smooth space-times appeared in the literature, see e.g.,~\cite{CaMo:20, MiSu:2024, Muller, ByMiSu:2025, SaSo:2025, MoSae:2025}. 
It is an interesting problem, that we do not address here due to length constraint, to compare these with the convergence used in the stability results.
\end{remark}


\begin{proof}

  Let $\mu^\infty_{i}\in \Prob(H_\infty)$, $i=0,1$, be such that $\Pi_\leq(\mu_0^\infty,\mu_1^\infty)\neq\emptyset$. Notice that, if $\mu_{i}^\infty$ is not absolutely continuous
  w.r.t.\ $\mm_\infty$, then the concavity inequality of $\NC^e(N)$ 
  trivializes; therefore we can assume that
  \begin{equation}
    \label{eq:density-mu-infty}
    \mu_{i}^\infty=\rho_{i,\infty}\mm_\infty\ll\mm_\infty
    .
  \end{equation}
  % 
  Let
  \begin{equation}
    \label{eq:density-mu}
    \mu^n_{i}:=
    (g_{n})_{\sharp}\mu^\infty_{i}
    =
    \rho_{i,n}
    (g_{n})_{\sharp}
    \mm_\infty
    =
    \rho_{i,n}
    \sigma_{n}
    \mm_{n}
    ,
%    =
%    \rho_{i}\circ g_{n}^{-1}
%    \sigma_{n}
%    \mm_{n}
  \end{equation}
  for some function $\rho_{i,n}$, $n\in \N$.
