  \begin{align*}
    \Ent(\mu_{i}^\infty|\mm_\infty)
    &
    \geq
    \Ent(\mu_{i}^n|(g_{n})_{\sharp}\mm_\infty)
    =
    \int_{H_{n}}
    \log(\rho_{i,n})
    \,
    \de \mu_{i}^n
    \\
    %
    &
    =
    \int_{H_{n}}
    \log(\rho_{i,n}\sigma_{n})
    \,
    \de \mu_{i}^n
    -
    \int_{H_{n}}
