  \end{equation}

    We next prove that $(h_{n})_{\sharp}\mu_{i}^n\weak \mu_{i}^\infty$.
    %
    Fix $\phi\in C_{b}(H_\infty)$ and compute, using dominated
    convergence theorem
    %
    \begin{align*}
        \int_{H_{n}}
        \phi
        \,
        \de((h_{n})_{\sharp}\mu_{i}^n)
        &
        =
         \int_{H_{n}}
        \phi
        \,
        \de((h_{n}\circ g_{n})_{\sharp}\mu_{i}^\infty)
        =
        \int_{H_{n}}
        \phi(h_{n}\circ g_{n}(x))
