    \end{align*}
    %
    Using the joint lower-semicontinuity of the entropy under weak
    convergence and assumption~\eqref{eq:weak-hn}, we deduce that
    \begin{equation}\label{eq:liminfEntnueta}
      \liminf_{n\to\infty}
      \Ent((e_{t})_{\sharp}\nu_{n}|\mm_{n})
      \geq
      \liminf_{n\to\infty}
      \Ent(
      (e_{t})_{\sharp}
      \eta_{n}|
      (h_{n})_{\sharp}\mm_{n})
      \geq
      \Ent(
      (e_{t})_{\sharp}
      \eta_\infty
      |
      \mm_\infty
      )
      .
    \end{equation}
    %
    Combining,~\eqref{eq:limsupEntnueta} and~\eqref{eq:liminfEntnueta},
    we  can pass to the
  limit~\eqref{eq:concavity-entropy-in-stability-novel-proof},
  concluding the proof (see the last steps of the proof of
  \Cref{thm:StabNCProb} for the details).
  \end{proof}












