\end{table}

The Yukawa Lagrangian has the form
%
\begin{equation}
{\cal L}_Y = - \sum_{i=1}^3 \frac{m_f}{v} \bar{\psi}_f \left[ c^e_{H_i
  ff} + i c^o_{H_i ff} \gamma_5 \right] \psi_f H_i \;, \label{eq:yuklag}
\end{equation}
%
where $\psi_f$ denotes the fermion fields with mass $m_f$. The
coefficients of the CP-even and of the CP-odd part of the Yukawa
