The pseudocode of the BISC routine is listed in Algorithm \ref{alg:BISC}. The BISC routine is flexible and can be executed after a system reset, following a classification task, or periodically at predefined intervals, depending on application needs. This demonstrates the seamless integration of BISC with the RISC-V core, ensuring efficient real-time calibration if needed.

\begin{algorithm}[htbp]
\caption{BISC Calibration Routine}
\label{alg:BISC}
\textbf{Initialization:} \\
\textbf{Set} \texttt{RISC-V controls}. \\
\textbf{Initialize Calibration Variables:} \\
\Indp
- $V_{CAL} \gets \frac{V_L + V_H}{2}$, \& $R_{SA} \gets \frac{R_U}{N}$. \\
- $V_{ADC}^{L} \gets 0.95\,V_{ADC}^{L,\text{default}}$. \\
- $V_{ADC}^{H} \gets 1.05\,V_{ADC}^{H,\text{default}}$. \\
\Indm
\textbf{Store ADC Parameters:} $(\alpha_D,\,\beta_D,\,C_{ADC})$. \\
\textbf{Define Test Vectors:} $\{V_{t}[Z],W_t[Z]\}$ and $Q_{exp}$. \\


\BlankLine
\textbf{Characterization Phase:} \\
\ForEach{column $c$ in CIM array}{
    - Write $W_t \gets W_{\max}.\ \ V_{t} \gets$ stepped input.\\
    - $\{V_{t}[Z],W_t[Z]\} \to  \{I_{MAC}[Z]\}$.\\
    - Measure $\hat{Q}_{act}$ per column. \\
    - Compute: $\hat{g}_{tot} \gets$ per Eq.\eqref{eq:LS_g}, $\hat{\epsilon}_{tot} \gets$ per Eq.\eqref{eq:LS_eps}.
}
%\BlankLine
\textbf{Correction Phase:} \\
\ForEach{column $c$ in CIM array}{
    \textbf{Gain Correction:} 
    $R_{SA}' \gets \dfrac{\alpha_D\,R_{SA}}{\hat{g}_{tot}}$.\\
    %\BlankLine
    \textbf{Offset Correction:} 
    $V_{CAL}' \gets V_{CAL} - \dfrac{\hat{\epsilon}_{tot}-\beta_D}{\alpha_D\,C_{ADC}}$.\\
    %\BlankLine
}
Update BISC circuits with $R_{SA}' \& V_{CAL}'$.
\end{algorithm}



