\section{Details of the sampling scheme}

Algorithm \ref{alg:SparseSample} provides a schematic overview of the sampling scheme used to sample a sparse symmetric precision matrix as defined in Equation (8).

\begin{algorithm}[H]
\small
	\KwIn{$p$, $\calG$, $L$, $g_o(\cdot)$, $g_d(\cdot)$. Obtain $\bZ$ from $\calG$.}
	\For{$\ell=1,\dots,L$}{
        \For{$j=1,\dots,p$}{
            Sample $q_{jj}\sim g_d(\cdot)$\\
            \If{$j>1$}{ 
            \uIf{$z_{j1}=1$}{
                sample $q_{j1}\sim g_o(\cdot)$}
            \Else{set $q_{j1}=0$}
    }}
    \For{$k=2,\dots,p$}{
        \For{$j=2,\dots, k-1$}{
            \uIf{$z_{jk}=1$}{
                sample $q_{jk}\sim g_o(\cdot)$}
            \Else{set $q_{jk}=-\frac{\sum_{t = 1}^{k-1} q_{jt}\cdot q_{kt}}{q_{kk}}$}
    }}}
    Obtain $\bLambda^{(\ell)}=\bQ\bQ^{\top}$\\
	\KwOut{sample of symmetric positive definite matrices $\bLambda^{(\ell)}, \ell=1,\dots,L$}
	\caption{Sampling algorithm for sparse symmetric precision matrices}
\label{alg:SparseSample}
\end{algorithm}
