\section{Approximation properties and Schauder frames}
%\section{Approximation properties, bases and frames}

%The approximation properties, which already appeared in Banach's book in 1932, plays a fundamental role in the structure theory of Banach spaces.

Firstly, we introduce some basic definitions and results concerning the approximation property \cite{C2001} as follows.

\begin{de}
A Banach space $X$ is said to have the approximation property if for every compact set $K$ in $X$ and every $\varepsilon>0$, there is a finite rank operator $S$ such that $\|Sx-x\|\leq\varepsilon$ for every $x\in K$.
\end{de}

\begin{de}
Let $X$ be a Banach space and $1\leq\lambda<\infty$. We say that $X$ has the $\lambda$-bounded approximation property ($\lambda$-BAP for short) if for every $\varepsilon >0$ and every compact set $K$ in $X$, there is a finite rank operator $S$ such that $\|S\|\leq \lambda$ and $\|Sx-x\|\leq\varepsilon$ for every $x\in K$. We say that $X$ has the bounded approximation property (BAP for short) if $X$ has the $\lambda$-BAP for some $\lambda$. Moreover, a Banach space is said to have the metric approximation property (MAP for short) if it has the $1$-BAP.
\end{de}

%\begin{de}
%Let $X$ and $Y$ be Banach spaces. Let $\lambda> 0$ and $T\in B(X,Y)$. Then $T$ is said to have the $\lambda$-bounded approximation property ($\lambda$-BAP) if there exists a net $\{S_{\alpha}\}_{\alpha\in\Gamma}\subseteq B(X,Y)$ with $\dim(S_{\alpha}X)<\infty$ for all $\alpha\in\Gamma$ such that $$\sup_{\alpha\in\Gamma}\|S_{\alpha}\|\leqslant\lambda \quad \text{and} \quad \lim_{\alpha}\|S_{\alpha}x-Tx\|=0$$ for all $x\in X$. We say $T$ has the bounded approximation property (BAP) if there exists a $\lambda>0$ such that $T$ has the $\lambda$-bounded approximation property.
%\end{de}
