%\end{re}

The following lemma provides an alternative formulation of the BAP, and we omit its proof (c.f. \cite{C2001}).

\begin{lem}\label{lem1}
Let $X$ be a separable Banach space. Then $X$ has the $\lambda$-BAP if and only if there is a sequence of finite rank operators $\{S_n\}_{n=1}^\infty$ on $X$ converging strongly to the identity operator such that $S_m S_n=S_n$ for all $n<m$, and $\lim\sup_n\left\|S_n\right\| \leq \lambda$.
\end{lem}

We call such a sequence $\{S_n\}_{n=1}^\infty$ in Lemma \ref{lem1} an approximating sequence. Moreover, if $\{S_n\}_{n=1}^\infty$ is a commuting approximation sequence, that is, $S_n S_m=S_m S_n$ for all $n, m \in \N_+$, then $X$ is said to have the $\lambda$-commuting bounded approximation property ($\lambda$-CBAP for short).


\begin{de}\label{UMAP}
  Let $X$ be a separable Banach space, then $X$ has the $\lambda$-unconditional BAP ($\lambda$-UBAP for short) if for every $\varepsilon>0$ there is an approximating sequence $\{S_n\}_{n=1}^\infty$ such that if $A_n=S_n-S_{n-1}$ (and $S_0=0)$ for $n\in\mathbb{N}_+$ then for every $N\in\mathbb{N}_+$, we have
  $$\sup_{N \in \N_+, \theta_i= \pm 1}\left\|\sum_{i=1}^N \theta_i A_i\right\| \leq \lambda+\varepsilon.$$
  A Banach space is said to have the unconditional MAP (UMAP for short) if it has the $1$-UBAP.
\end{de}


\begin{lem}\label{lem3.4}
  Let $\{A_n\}_{n=1}^\infty$ be an operator sequence in Definition \ref{UMAP} of a separable Banach space $X$, then for all $\{a_n\}_{n=1}^\infty \in \ell^\infty$, the following inequality holds
  \[ \norm{\sum_{n=1}^\infty a_n A_n} \leq \|\{a_n\}\|_\infty (\lambda+\varepsilon).\]
  Moreover, if $X$ has the $\lambda$-UBAP, then there is an approximating sequence $\{S_n\}_{n=1}^\infty$ such that \[\limsup_{n}\|id_X -2 S_n\| \leq \lambda+\varepsilon.\]
\end{lem}
\begin{proof}
   For all $N \in \N_+$, $x \in X$ and $f \in X^*$, we have
   \begin{align*}
       &\left| f \left(\sum_{n=1}^{N}a_n  A_n x\right)\right|  \leq \sum_{n=1}^{N}|a_n| \left| f(A_n x) \right|\\
       \leq &\sup_{n\leq N}|a_n|\sum_{n=1}^{N} |f(A_n x)| \leq (\lambda+\varepsilon)\|\{a_n\}\|_\infty \|f\|\|x\|.
   \end{align*}
  Taking the supremum over all $N \in \N_+$, $x \in B_X$ and $f \in B_{X^*}$, then we have $$\norm{\sum_{n=1}^\infty a_n A_n} \leq \|\{a_n\}\|_\infty (\lambda+\varepsilon).$$
  Note that for all $\varepsilon>0$, by the uniform boundedness principle, we have \[\|id_X -2 S_n\| \leq \liminf_m \norm{-\sum_{1\leq j \leq n}A_j+\sum_{n<j\leq m}A_j} \leq \lambda+\varepsilon.\]
  Thus there is an approximating sequence $\{S_n\}_{n=1}^\infty$ such that $\limsup_{n}\|id_X -2 S_n\| \leq \lambda+\varepsilon$.
\end{proof}

An unconditional approximating sequence is actually an approximating sequence and it is worthwhile to know the relationship between the BAP constant and the UBAP constant.

