The existence of an approximating sequence $\{S_n\}_{n=1}^\infty$ with $\lim_{n}\|id_X -2 S_n\| = \lambda$ is not enough to determine whether $X$ has the $\lambda$-UBAP or even the UBAP since $L^1[0,1]$ has the MAP but fails the UBAP. However, when $\lambda=1$, Casazza and Kalton \cite{C1991} proved that $X$ has the UMAP.


\begin{thm}
Let $X$ be a separable Banach space. Then $X$ has the UMAP if and only if there is an approximating sequence $\left\{S_n\right\}_{n=1}^\infty$ such that $$\lim_{n \rightarrow \infty}\left\|id_X-2 S_n\right\|=1.$$
\end{thm}


It is known that Banach space frames have close relationship with various forms of the approximation properties. Casazza, Han and Larson \cite{CHL} introduced the concept of Schauder frames for Banach spaces, which is a natural generalization of frames for Hilbert spaces and Schauder bases for Banach spaces. The techniques inspired by Schauder frames \cite{ST2008,L2010} might play a critical role in the study of Banach space geometry and operator algebras \cite{LR2016}.

 \begin{de}
  Let $X$ be a separable Banach space and $\left\{(x_{n},f_{n})\right\}_{n=1}^\infty \subseteq X \times X ^{\ast}$. Then $\left\{(x_{n},f_{n})\right\}_{n=1}^\infty$ is a Schauder frame of $X$ if for all $ x \in X$, we have \[x=\sum_{n=1}^{\infty} f_{n}(x) x_{n}.\]
  \end{de}

  \begin{de}
 Let $X$ be a separable Banach space and $\left\{(x_{n},f_{n})\right\}_{n=1}^\infty\subseteq X \times X ^{\ast}$ be a Schauder frame. Then $\left\{(x_{n},f_{n})\right\}_{n=1}^\infty$ is said to be block unconditional if there exists a subsequence $\{N_k\}_{k=1}^\infty$ of $\mathbb{N}_+$ such that
  \begin{equation}\label{bufb}
  \sup_{N\in\mathbb{N_+},\theta_k=\pm1}\left\|\sum_{k=1}^{N}\theta_k \sum_{n=N_k+1}^{N_{k+1}}f_n\otimes x_n\right\| < \infty.
  \end{equation}
 We call $\sup_{N\in\mathbb{N_+},\theta_k=\pm1}\left\|\sum_{k=1}^{N}\theta_k \sum_{n=N_k+1}^{N_{k+1}}f_n\otimes x_n\right\|$ satisfying (\ref{bufb}) the block unconditional frame bound of $\left\{(x_{n},f_{n})\right\}_{n=1}^\infty$.
\end{de}

\begin{lem}\label{decomposable}
  Let $X$ be a separable Banach space with the $\lambda$-UBAP and $\varepsilon > 0$. Then there exists a (block unconditional) Schauder frame $\{(x_n,f_n)\}_{n\in\mathbb{N}+} \subseteq X\times X^\ast$ such that for all $x\in X$ we have
  $$x=\sum_{n=1}^{\infty}f_n(x) x_n.$$  And there exists a subsequence
  $\{N_k\}_{k=1}^{\infty}$ of $\N_+$ such that
  $$\sup_{N\in\mathbb{N}_+,\theta_k=\pm1}\left\|\sum_{k=1}^{N}\theta_k \sum_{n=N_k+1}^{N_{k+1}}f_n \otimes x_n\right\|\leq \lambda+\varepsilon  \text{ and } \sup_{N\in\mathbb{N}_+}\left\|\sum_{n=1}^{N}f_n \otimes x_n\right\|\leq \lambda+\varepsilon.$$
  In addition, we can assume $\|x_n\| = 1$ and $\|f_n\| \leq 1$  for all $n \in \N_+$.
\end{lem}
\begin{proof}
  Since $X$ has the $\lambda$-UBAP, by Definition \ref{UMAP} and Remark \ref{rem3.5}, we can take an unconditional approximating sequence $\left\{S_n\right\}_{n=1}^\infty$ on $X$ converging strongly to the identity operator such that $S_m S_n=S_n$ for all $n<m$. By passing to a subsequence, we can assume $\sup_n \left\|T_n\right\| \leq \lambda+2^{-1}\varepsilon$.

  Let $A_n=S_n-S_{n-1}$ (with $S_0=0$), $E_n=A_n X$ and $d_n=\dim(E_n)$ for every $n\in\mathbb{N}_+$, then $d_n<\infty$ and for all $x \in X$, $x=\sum_{n=1}^{\infty} A_n(x)$. By Definition \ref{UMAP}, for every $\varepsilon>0$, we have
  $$\sup_{N \in \N_+, \theta_i= \pm 1}\left\|\sum_{i=1}^N \theta_i A_i\right\| \leq \lambda+ 2^{-1}\varepsilon.$$

  For every finite-dimensional space $E_{n}$, let  $\left\{z_1^n,z_2^n,\dots,z_{d_{n}}^n\right\}$ be a Schauder basis of $E_{n}$ and its normalized bi-orthogonal basis be $$\left\{(z_1^n,z_1^{n*}),(z_2^n,z_2^{n*}),\dots,(z_{d_{n}}^n,z_{d_{n}}^{n*})\right\}.$$
  Then for all $x \in X$, we have
  $$x=\sum_{n=1}^{\infty}A_{n}(x)=
  \sum_{n=1}^{\infty}\sum_{j=1}^{d_{n}}z_j^{n*}(A_{n}(x))z_j^{n}.$$

  Let $C_n$ be the basis constant for $\left\{(z_1^n,z_1^{n*}),(z_2^n,z_2^{n*}),\dots,(z_{d_{n}}^n,z_{d_{n}}^{n*})\right\}$, then $C_n<\infty$.
  Choose $M_n \in \N_+$  such that \[M_n \geq  2\lambda+\varepsilon \quad\text{ and }\quad \frac{C_{n}}{M_{n}}\leq\frac{\varepsilon}{4\lambda+2\varepsilon}.\]
  Let $$x_{i}=z_{j}^{n} \quad \text{ and } \quad f_{i}=\frac{z_{j}^{n *}\circ A_n}{M_{n}} \quad \text{if} \quad i=\sum_{k=1}^{n-1} M_{k} d_{k} + rd_{n}+j,$$ where $r=0,\dots, M_{n}-1$ and $j=1,\dots, d_{n}$. It is obvious that $\|x_k\|= 1$ and $\|f_k\|\leq 1$ for every $k\in \N_+$. Thus for all $x \in X$, we have
  \begin{align*}
    x & =\sum_{n=1}^{\infty}\sum_{j=1}^{d_{n}}z_j^{n*}(A_{n}(x))z_j^{n} \\
      & =\sum_{n=1}^{\infty}M_{n}\sum_{j=1}^{d_{n}}\frac{z_j^{n*}(A_{n}(x))z_j^{n}}{M_{n}} \\
      & =\sum_{n=1}^{\infty} f_{n}(x)x_{n}\\
      & =\sum_{n=1}^{\infty} (f_{n}\otimes x_{n})(x).
  \end{align*}
  Therefore $\sum_{n=1}^{\infty} f_{n}\otimes x_{n}$ converges strongly to $id_X$.

  Next we estimate the frame bound and block unconditional frame bound of
  $\{(x_n,f_n)\}_{n\in\mathbb{N}+}$. For every well-defined $s=\sum_{k=1}^{n-1} M_{k} d_{k} + rd_{n}+j$ and every $x \in X$, we have

  \begin{align*}
    \left\|\sum\limits_{k=1}^{s} f_{k}(x) x_{k}\right\| &=\left\|\sum\limits_{k=1}^{n-1}A_k(x)+\frac{r}{M_{n}}A_n(x)+
    \sum\limits_{k=1}^{j}\frac{z_k^{n*}(A_{n}(x)) z_k^{n}}{M_{n}}\right\|\\
    &=\left\|\sum\limits_{k=1}^{n-1}A_k(x)+\frac{r}{M_{n}}\left(\sum\limits_{k=1}^n A_k(x)-\sum\limits_{k=1}^{n-1} A_k(x)\right)+
    \sum\limits_{k=1}^{j}\frac{z_k^{n*}(A_{n}(x)) z_k^{n}}{M_{n}}\right\|\\
    &=\left\|\frac{r}{M_{n}}\sum\limits_{k=1}^{n}A_k(x)+\left(1-\frac{r}{M_{n}}\right)
    \sum\limits_{k=1}^{n-1} A_k(x)+
    \sum\limits_{k=1}^{j}\frac{z_k^{n*}(A_{n}(x)) z_k^{n}}{M_{n}}\right\|\\
    &=\left\|\frac{r}{M_{n}}S_n(x)+\left(1-\frac{r}{M_{n}}\right)S_{n-1}(x)+
    \sum\limits_{k=1}^{j}\frac{z_k^{n*}(A_{n}(x)) z_k^{n}}{M_{n}}\right\|\\
    & \leq\frac{r}{M_{n}}\|S_n(x)\|+\left(1-\frac{r}{M_{n}}\right)\|S_{n-1}(x)\|
    +\frac{\left\|\sum\limits_{k=1}^{j} z_k^{n*}(A_{n}(x)) z_k^{n}\right\|}{M_{n}}\\
    & \leq\frac{r}{M_{n}}\left(\lambda+\frac{1}{2}\varepsilon\right)\|x\|+
    \left(1-\frac{r}{M_{n}}\right)\left(\lambda+\frac{1}{2}\varepsilon\right)\|x\|\\
    &\quad+\frac{\left\|\sum\limits_{k=1}^{j} z_k^{n*}(A_{n}(x)) z_k^{n}\right\|}{M_{n}}\\
    & \leq \left(\lambda+\frac{1}{2}\varepsilon\right)\|x\|+\frac{C_{n}}{M_{n}}\|A_{n}(x)\|\\
    & \leq \left(\lambda+\frac{1}{2}\varepsilon\right)\|x\|+\frac{\varepsilon}{4\lambda+2\varepsilon}\|A_{n}(x)\|\\
    & \leq \left(\lambda+\frac{1}{2}\varepsilon\right)\|x\|+\frac{\varepsilon}{4\lambda+2\varepsilon}\left(\|S_n x\|+\|S_{n-1}x\|\right)\\
    & \leq  \left(\lambda+\frac{1}{2}\varepsilon\right)\|x\|+\frac{\varepsilon}{4\lambda+2\varepsilon}
    \left(2\lambda+\varepsilon\right)\|x\|\\
    &= \left(\lambda+\varepsilon\right)\|x\|.
    \end{align*}
    Therefore $$\sup_{N\in\mathbb{N}_+}\left\|\sum_{n=1}^{N}f_n \otimes x_n\right\|\leq
    \lambda+\varepsilon.$$

    Let $N_1=0$ and for all $k \in \N_+$ with $k \geq 2$, let \[N_k=\sum_{i=1}^{k-1} d_{i}M_{i}, \]
    then $A_n=\sum_{n=N_k+1}^{N_{k+1}} f_{n}\otimes x_{n}$.
    Therefore, we have
    $$\sup_{N\in\mathbb{N}_+,\theta_k=\pm1}\left\|\sum_{k=1}^{N}\theta_k \sum_{n=N_k+1}^{N_{k+1}}f_n \otimes x_n\right\|=\sup_{N\in\mathbb{N}_+,\theta_k=\pm1}\left\|\sum_{k=1}^{N}\theta_k A_k\right\|\leq \lambda+\varepsilon. $$
  \end{proof}

\begin{de}(\cite{LSZ2023})
Let $X$ be a separable Banach space and $\left\{(x_{n},f_{n})\right\}_{n\in\N_+} \subseteq X\times X^*$ be a Schauder frame of $X$. Then $\left\{(x_{n},f_{n})\right\}_{n\in\N_+}$ is an unconditional Schauder frame if \[x=\sum_{n=1}^{\infty} f_{n}(x)x_n\] converges unconditionally for all $x \in X$.
\end{de}

If $X$ has an (unconditional) Schauder frame, then it is straightforward to construct
a separable Banach space $Z$ with an (unconditional) basis such that $X$ is complemented in $Z$. But if $X$ only has a block unconditional Schauder frame, that is, $X$ has the UBAP, then $X$ is complemented in a separable Banach space with an unconditional finite-dimensional decomposition.

\begin{de}
  A sequence $\{E_n\}_{n=1}^\infty$ of finite-dimensional subspaces of a Banach space $X$ is called an unconditional finite-dimensional decomposition for $X$ (UFDD for short) if for every $x\in X$ there is a unique sequence $x_n\in E_n$ such that $x=\sum_{n}x_n$ and this series converges unconditionally. In this case, we will write $X=\sum_{n}\oplus E_n$ and say $X$ has an unconditional finite-dimensional decomposition. We say $X$ has the $\lambda$-UFDD, if for all $\varepsilon>0$, there is a sequence $\{E_n\}_{n=1}^\infty$ such that
  \[\sup_{\varepsilon_n=\pm1}\norm{\sum_{n}\varepsilon_n x_n} \leq (\lambda+\varepsilon) \norm {\sum_{n} x_n}.\]
\end{de}

%The following theorem is due to \cite{GK1997} and we give an extended version and a new proof by using dilation techniques.
In general, it is very difficult to discover whether a concrete Banach space such as the Orlicz space or the Lorentz space which is complemented in a Banach space with an unconditional basis has an UFDD \cite{C2001}.

The following theorem is due to Godefroy and Kalton's approximation theorem \cite{GK1997}. Here we give an extended version and a new proof by using dilation techniques on Schauder frames.

\begin{thm}
Let $X$ be a separable Banach space. Then $X$ has the $\lambda$-UBAP if and only if for any $\varepsilon>0$, $X$ embeds as a $(\lambda+\varepsilon)$-complemented subspace of a Banach space $Y_{\varepsilon}$ with an $1$-UFDD.
\end{thm}
\begin{proof}
The ``if" part is trivial, we only need to prove the ``only if" part.

Since $X$ has the $\lambda$-UBAP, by Lemma \ref{decomposable}, for every $\varepsilon > 0$, there exists a block unconditional Schauder frame $\{(x_n,f_n)\}_{n\in\mathbb{N}_+} \subseteq X\times X^\ast$ such that
$x=\sum_{n=1}^{\infty}f_n(x) x_n$ for all $x\in X$ and there exists a subsequence
 $\{N_k\}_{k=1}^{\infty}$ of $\N_+$ such that $$\sup_{N\in \N_+,\theta_k=\pm1}\left\|\sum_{k=1}^{N}\theta_k \sum_{n=N_k+1}^{N_{k+1}}f_n\otimes x_n\right\|\leq \lambda+\varepsilon \text{ and } \sup_{N\in\mathbb{N}_+}\left\|\sum_{n=1}^{N}f_n \otimes x_n\right\|\leq \lambda+\varepsilon.$$
Let $\{I_k:=\{i\}_{i=N_k+1}^{N_{k+1}}\}_{k\in\mathbb{N}_+}$ and it is a partition of $\mathbb{N}_+$. Let $\{z_k\}_{k\in\mathbb{N}_+}$ be a copy of $\{x_k\}_{k\in\mathbb{N}_+}$ and $Y_k=\overline{\mathrm{span}}\{z_n: n\in I_k\}$, then $Y_k$ is a finite-dimensional subspace since every $I_k$ is finite. Let $c_{00}$ be the collection of all sequences of real numbers with all but finite nonzero elements. For every $k=1,2,\cdots$, let $\{a_{k}\}_{k\in \N_+}\in c_{00}$, we define the space $Y_\varepsilon$ as the completion of $(\sum_{k}\oplus Y_k)$ under the norm
$$\left\|\sum_{k=1}^{\infty}a_{k}z_k\right\|_{Y_{\varepsilon}}=\max\left\{\sup_{N \in \N_+, \theta_n=\pm1}\left\|\sum_{n=1}^{N}\theta_n\sum_{k\in I_n}a_{k}x_k\right\|,\sup_{N\in \N_+}\norm{\sum_{k=1}^N a_k x_k}\right\}.$$
It is easily seen that $\textbf{bc}(Y_k)=1$ for all $k$ and follows immediately that $Y_\varepsilon$ is a Banach space and $\{Y_k\}_{k=1}^{\infty}$ is an $1$-UFDD of $Y_{\varepsilon}$.
%For every $N\in\mathbb{N}_+$ and $\varepsilon_n=\pm1$, we have
%\begin{align*}
% \left\|\sum_{n=1}^{N}\varepsilon_n\sum_{k\in I_n}a_{k}z_k\right\| & =\sup_{K\in\mathbb{N}_+, \theta_n=\pm1}\left\|\sum_{n=1}^{\min\{K,N\}}\varepsilon_n\theta_n\sum_{k\in I_n}a_{k}x_k\right\| \\
%& \leq  \sup_{N\in\mathbb{N}_+, \varepsilon_n=\pm1}\left\|\sum_{n=1}^{N}\varepsilon_n\sum_{k\in I_n}a_{k}x_k\right\|\\
%& \leq \left\|\sum_{n=1}^{\infty}\sum_{k\in I_n}a_{k}z_k\right\|.
%\end{align*}
%Thus $$\sup_{N\in\mathbb{N}_+, \theta_n=\pm1}\left\|\sum_{n=1}^{N}\varepsilon_n\sum_{k\in I_n}a_{k}z_k\right\|\leq \left\|\sum_{n=1}^{\infty}\sum_{k\in I_n}a_{k}z_k\right\|,$$ this implies that $\{Y_k\}_{k=1}^{\infty}$ is an $1$-UFDD of $Y_{\varepsilon}$.

Define the map $S:Y_{\varepsilon}\rightarrow X$ by $$S(z)=\sum_{k=1}^{\infty}a_{k}x_k$$ for all $z=\sum_{k=1}^{\infty}a_{k}z_k\in Y_{\varepsilon}$, then \[\|Sz\|=\norm{\sum_{k=1}^{\infty}a_{k}x_k}\leq \sup_{N\in \N_+}\norm{\sum_{k=1}^N a_k x_k}\leq \|z\|.\]
Thus $\|S\| \leq 1$ and $S$ is a bounded linear operator.

Define the map $T:X\rightarrow Y_{\varepsilon}$ by $$T(x)=\sum_{k=1}^{\infty}\sum_{n\in I_k}f_n(x)z_n$$ for all $x=\sum_{n=1}^{\infty}f_n(x)x_n\in X$, then
\[\begin{aligned}
  \|Tx\|&=\norm{\sum_{k=1}^{\infty}\sum_{n\in I_k}f_n(x)z_n}\\
  &=\max\left\{\sup_{N \in \N_+, \varepsilon_n=\pm1}\left\|\sum_{n=1}^{N}\varepsilon_n\sum_{k\in I_n}f_k(x)x_k\right\|,\sup_{N\in \N_+}\norm{\sum_{k=1}^N f_k(x) x_k}\right\}\\
  &\leq (\lambda+\varepsilon)\|x\|.
\end{aligned}\]
Thus $\|T\| \leq \lambda+\varepsilon$ and $T$ is a bounded linear operator.

For every $x\in X$, we have
\begin{align*}
  & S\circ T(x)=S \circ T\left(\sum_{n=1}^\infty f_n(x)x_n\right)\\
= & S\left(\sum_{k=1}^{\infty}\sum_{n\in I_k}f_n(x)z_n\right)=\sum_{k=1}^{\infty}\sum_{n\in I_k}f_n(x)x_n=x.
\end{align*}
Thus $S\circ T=id_X$.

It is clear that $T$ is injective and $S$ is surjective. So $T(X)$ is a closed subspace of $Y_\varepsilon$. Let $P=T \circ S$, then
$$P^2= (T \circ S) \circ(T \circ S)=T \circ S=P.$$ Since $S$ is surjective,  we obtain $P: Y_{\varepsilon} \rightarrow T(X)$ is a projection with $\|P\|\leq \|S\|\|T\| \leq \lambda+\varepsilon$.
Therefore $T(X)$ is a complemented subspace of $Y_{\varepsilon}$. Then $X$ is isomorphic to a $(\lambda+\varepsilon)$-complemented subspace $T(X)$ of $Y_{\varepsilon}$ with an 1-UFDD.
\end{proof}


\section{The UBCP of operator spaces}

Let $X$ and $Y$ be Banach spaces, and let $K(X,Y)$ be the ideal of compact operators in $B(X,Y)$. We fix a real number $\alpha\in [0,1]$, and define a new norm by  \begin{align}\|\cdot\|_{\alpha}=\alpha\|\cdot\|_{B(X,Y)}+(1-\alpha)\|\cdot\|_{B(X,Y)/ K(X,Y)}. \label{renorm}\end{align}
Denote $B(X,Y)/ K(X,Y)$ by $Q(X,Y)$. Then we consider the ball-covering property of the renormed space $Z_\alpha=(B(X,Y),\|\cdot\|_{\alpha})$.

\begin{thm}\label{thm3.12}
Let $X$ be a Banach space with $X^\ast$ separable and $Y$ be a separable Banach space with the $(2-\varepsilon)$-UBAP for any $\varepsilon>0$. Then $B(X,Y)$ has the $(2,\varepsilon-\sigma)$-UBCP for all $0<\sigma<\varepsilon$.
\end{thm}
\begin{proof}
By Lemma \ref{decomposable}, for all $0<\varepsilon_1<\sigma/2$, there exists a block unconditional Schauder frame $\{(y_n,f_n)\}_{n\in\mathbb{N}} \subseteq Y\times Y^\ast$ such that
$$y=\sum_{n=1}^{\infty}f_n(y) y_n=\sum_{n=1}^{\infty}(f_n\otimes y_n)(y)$$ for all $y\in Y$ and there exists a subsequence $\{N_k\}_{k=1}^{\infty}$ of $\N_+$ such that $$\sup_{N\in\N_+,\theta_k=\pm1}\left\|\sum_{k=1}^{N}\theta_k \sum_{n=N_k+1}^{N_{k+1}}f_n\otimes y_n\right\|\leq 2-\varepsilon+\varepsilon_1  \text{ and } \sup_{N\in\mathbb{N}_+}\left\|\sum_{n=1}^{N}f_n \otimes y_n\right\|\leq
2-\varepsilon+\varepsilon_1.$$

For all $T \in B(X,Y)$ with $\|T\|=1$ and for all $x \in X$, we have
  \[Tx=\sum_{n=1}^{\infty}\left(f_n T\otimes y_n\right) (x).\]
Now we show that for all $0<\varepsilon_2< \sigma/2$, there exists $k_0$ such that
 \[\max\left\{1-\frac{\varepsilon_2}{16},\frac{3}{4}\right\}< \norm{\sum_{n=1}^{N_{k_0}}f_nT\otimes y_n} \leq (2-\varepsilon+\varepsilon_1)\|T\|=2-\varepsilon+\varepsilon_1.\] We only need to show that there exists $k_0$ such that $$\max\left\{1-\frac{\varepsilon_2}{16},\frac{3}{4}\right\}< \norm{\sum_{n=1}^{N_{k_0}}f_nT\otimes y_n}.$$ Suppose on the contrary, for all $k$, we have
 $$\norm{\sum_{n=1}^{N_k}f_nT\otimes y_n}\leq \max\left\{1-\frac{\varepsilon_2}{16},\frac{3}{4}\right\}.$$
 Let $T_{k}=\sum_{n=1}^{N_k}f_nT\otimes y_n$, then $T$ is the limit of $T_{k}$ in the strong operator topology, that is, $\lim_{k\rightarrow\infty}\|T_kx-Tx\|=0$ for all $x\in X$. We claim that $\|T\|\leq\liminf_{k\rightarrow \infty}\|T_{k}\|$. Since $$\|Tx\|\leq \|Tx-T_kx\|+\|T_kx\|,$$ we have $\|Tx\|\leq \liminf_{k\rightarrow\infty}\|T_kx\|$.
 Thus $\|T\|\leq \liminf_{k\rightarrow\infty}\|T_k\|$. Since $\|T_{k}\|\leq \max\left\{1-\varepsilon_2 /16,3/4\right\}<1$ for all $k$, we have $\|T\|<1$, and it is a contradiction.

 Since $X^*$ and $Y$ are separable, there exists a countable dense subset $\mathcal{A}=\{x_n^*\}_{n=1}^\infty$ in $B_{X^\ast}$ and a countable dense subset $\mathcal{B}=\{u_n\}_{n=1}^\infty$ in $B_Y$.  For all  $n=1,2,\cdots$, there exists $x^{*}_{m_n} \in \mathcal{A}$, $m_{n}\in\N_+$ and $u_{l_n}\in \mathcal{B}$, $l_{n}\in\N_+$  such that
  $$\norm{x^{*}_{m_n}-f_{n} T} <\min\left\{\frac{1}{8N_{k_0}},\frac{\varepsilon_2}{64N_{k_0}}\right\} \text{ and } \norm{u_{l_n}-y_n} <\min\left\{\frac{1}{8N_{k_0}},\frac{\varepsilon_2}{64N_{k_0}}\right\}.$$
  Thus \[\norm{\sum_{n=1}^{N_{k_0}}f_{n}T\otimes y_{n} -\sum_{n=1}^{N_{k_0}}x^{*}_{m_n}\otimes u_{l_n}}< \min\left\{\frac{1}{4},\frac{\varepsilon_2}{32}\right\}.\]
  Let $\xi_{k_0}=\norm{\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}$, then we have
  \[\max\left\{1-\frac{3\varepsilon_2}{32},\frac{1}{2}\right\}<\xi_{k_0}< \min\left\{\frac{9}{4},2+\frac{\varepsilon_2}{16}\right\}.\]
 We will show that the countable set
  \[\left\{\frac{2\sum_{i=1}^{m} g_{i}^{\ast}\otimes s_{i}}{\norm{\sum_{i=1}^{m} g_{i}^{\ast}\otimes s_{i}}}: m\in \mathbb{N}_+, g_{i}^{\ast}\in\mathcal{A}\ (1\leq i\leq m), s_{i}\in\mathcal{B}\ (1\leq i\leq m)\right\}\] is a set of BCP points for $B(X,Y)$.

By triangular inequality and a regular computation, we have
\begin{align}
    &\quad\norm{T - \frac{2\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}{\norm{\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}}}\notag\\
    &=\norm{\sum_{n=1}^{N_{k_0}} f_{n} T \otimes y_{n} -\sum_{n=1}^{N_{k_0}} \frac{2 }{\xi_{k_0}} x^{*}_{m_n}\otimes u_{l_n}+\sum_{n=N_{k_0}+1}^{\infty} f_{n} T\otimes y_{n}}\notag\\
    &\leq \norm{\frac{2}{\xi_{k_0}}\left(\sum_{n=1}^{N_{k_0}} f_{n} T\otimes y_{n} -\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n} \right) }\notag\\
    &\quad+\norm{\left(1-\frac{2}{\xi_{k_0}} \right)\sum_{n=1}^{N_{k_0}} f_{n} T\otimes y_{n}+\sum_{n=N_{k_0}+1}^{\infty} f_{n} T\otimes y_{n} } \notag\\
    &\leq \norm{\frac{2}{\xi_{k_0}}\left(\sum_{n=1}^{N_{k_0}} f_{n} T\otimes y_{n} -\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n} \right)}\notag\\
    &\quad+\left(2-\varepsilon+\varepsilon_1\right)\max\left\{\left|1-\frac{2}{\xi_{k_0}}\right|,1\right\} \label{ieq1}\\
    &<\frac{\varepsilon_2}{8\xi_{k_0}}+\left(2-\varepsilon+\varepsilon_1\right)
    \left(\frac{2}{\xi_{k_0}}-1\right)\label{ieq3}\\
    &=2-\varepsilon+\varepsilon_1+(2-\varepsilon+\varepsilon_1)
    \left(\frac{2}{\xi_{k_0}}-2\right)+\frac{\varepsilon_2}{8\xi_{k_0}}\notag\\
    &< 2-\varepsilon+\varepsilon_1+(8-8\xi_{k_0})+\frac{1}{4} \varepsilon_2\notag\\
    &< 2-\varepsilon+\varepsilon_1+\frac{3}{4}\varepsilon_2+\frac{1}{4} \varepsilon_2\notag\\
    &<2-\varepsilon+\sigma \label{ieq2}\\
    %&=2-(\varepsilon-\sigma)\notag\\
    &< 2\notag,
\end{align}
where inequality (\ref{ieq1}) is obtained by Lemma \ref{lem3.4}. In (\ref{ieq3}), without loss of generality, we can always assume $\xi_{k_0}\leq1$. And inequality (\ref{ieq2}) shows that $B(X,Y)$ has the $(2,\varepsilon-\sigma)$-UBCP.
\end{proof}

\begin{thm}\label{thm3.13}
  Let $X$ be a Banach space with $X^\ast$ separable and $Y$ be a separable Banach space with the $(2-\varepsilon)$-UBAP for any $\varepsilon>0$. Then for all $1-\varepsilon/2 < \alpha \leq 1$, the renormed space $Z_\alpha=\left(B(X,Y), \|\cdot\|_\alpha \right)$ defined in (\ref{renorm}) has the $(2\alpha,2\alpha+\varepsilon-2-\sigma)$-UBCP for all $0<\sigma<2\alpha+\varepsilon-2$.
  \end{thm}
  \begin{proof}
  We only need to prove the case when $1-\varepsilon/2 < \alpha < 1$ as the case $\alpha=1$ has been proved in Theorem \ref{thm3.12}. By Lemma \ref{decomposable}, for all $0<\varepsilon_1<\sigma/2$, there exists a block unconditional Schauder frame $\{(y_n,f_n)\}_{n\in\mathbb{N}} \subseteq Y\times Y^\ast$ such that $$y=\sum_{n=1}^{\infty}f_n(y) y_n=\sum_{n=1}^{\infty}(f_n\otimes y_n)(y)$$ for all $y\in Y$ and there exists a subsequence $\{N_k\}_{k=1}^{\infty}$ of $\N_+$ such that $$\sup_{N\in\N,\theta_k=\pm1}\left\|\sum_{k=1}^{N}\theta_k \sum_{n=N_k+1}^{N_{k+1}}f_n\otimes y_n\right\|\leq 2-\varepsilon+\varepsilon_1 \text{ and } \sup_{N\in\mathbb{N}_+}\left\|\sum_{n=1}^{N}f_n \otimes y_n\right\|\leq
  2-\varepsilon+\varepsilon_1.$$

  For all $T \in B(X,Y)$ with $\|T\|_\alpha=1$, we have $\|T\| \geq 1$ and $\|T\|_{Q(X,Y)} \leq 1$. Since for all $x \in X$, we have
    \[Tx=\sum_{n=1}^{\infty}\left(f_n T\otimes y_n\right) (x).\]
  The following existence of $k_0$ can be proved by the same way as in Theorem \ref{thm3.12}. For all $0<\varepsilon_2< \sigma/4$, there exists $k_0$ such that
   \[\max\left\{\|T\|-\frac{\varepsilon_2}{16},\frac{3}{4}\right\}< \norm{\sum_{n=1}^{N_{k_0}}f_nT\otimes y_n} \leq (2-\varepsilon+\varepsilon_1)\|T\|.\]

   Since $X^*$ and $Y$ are separable, there exists a countable dense subset $\mathcal{A}=\{x_n^*\}_{n=1}^\infty$ in $B_{X^\ast}$ and a countable dense subset $\mathcal{B}=\{u_n\}_{n=1}^\infty$ in $B_Y$.  For all $n=1,2,\cdots$, there exists $x^{*}_{m_n} \in \mathcal{A}$, $m_{n}\in\N_+$ and $u_{l_n}\in \mathcal{B}$, $l_{n}\in\N_+$  such that
   $$\norm{x^{*}_{m_n}-f_{n} T} <\min\left\{\frac{1}{8N_{k_0}},\frac{\varepsilon_2}{64N_{k_0}}\right\} \text{ and } \norm{u_{l_n}-y_n} <\min\left\{\frac{1}{8N_{k_0}},\frac{\varepsilon_2}{64N_{k_0}}\right\}.$$
   Thus \[\norm{\sum_{n=1}^{N_{k_0}}f_{n}T\otimes y_{n} -\sum_{n=1}^{N_{k_0}}x^{*}_{m_n}\otimes u_{l_n}}< \min\left\{\frac{1}{4},\frac{\varepsilon_2}{32}\right\}.\]
   Let $\xi_{k_0}=\norm{\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}$, then we have
   \[1-\frac{3\varepsilon_2}{32}\leq\max\left\{\|T\|-\frac{3\varepsilon_2}{32},\frac{1}{2}\right\}<\xi_{k_0}< \min\left\{\frac{17}{4},2\|T\|+\frac{\varepsilon_2}{16}\right\}.\]
  We will show that the countable set
   \[\left\{\frac{2\sum_{i=1}^{m} g_{i}^{\ast}\otimes s_{i}}{\norm{\sum_{i=1}^{m} g_{i}^{\ast}\otimes s_{i}}}: m\in \mathbb{N}_+, g_{i}^{\ast}\in\mathcal{A}\ (1\leq i\leq m), s_{i}\in\mathcal{B}\ (1\leq i\leq m)\right\}\] is a set of BCP points for $Z_\alpha$ ($1-\varepsilon/2 < \alpha \leq 1$).

 By triangular inequality and a regular computation, we have
 \begin{align}
     &\quad\norm{T - \frac{2\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}{\norm{\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}}}_\alpha\notag\\
     &=\alpha\norm{T - \frac{2\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}{\norm{\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}}}+(1-\alpha)\norm{T - \frac{2\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}{\norm{\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}}}_{Q(X,Y)}\notag\\
     &=\alpha\norm{\sum_{n=1}^{N_{k_0}} f_{n} T \otimes y_{n} -\sum_{n=1}^{N_{k_0}} \frac{2}{\xi_{k_0}} x^{*}_{m_n}\otimes u_{l_n}+\sum_{n=N_{k_0}+1}^{\infty} f_{n} T\otimes y_{n}}\notag\\
     &\quad+(1-\alpha)\norm{T - \frac{2\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}{\xi_{k_0}}}_{Q(X,Y)}\notag\\
     &\leq\alpha\norm{\frac{2}{\xi_{k_0}}\left(\sum_{n=1}^{N_{k_0}} f_{n} T\otimes y_{n} -\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n} \right)}\notag\\
     &\quad+\alpha\norm{\left(1-\frac{2}{\xi_{k_0}}\right)\sum_{n=1}^{N_{k_0}} f_{n} T \otimes y_{n}+\sum_{n=N_{k_0}+1}^{\infty} f_{n} T\otimes y_{n}}\notag\\
     &\quad+(1-\alpha)\norm{T - \frac{2\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}{\xi_{k_0}}}_{Q(X,Y)}\notag\\
     %&=\norm{\sum_{n=1}^{N_{k_0}} f_{n} T \otimes y_{n} -\sum_{n=1}^{N_{k_0}} \frac{2 }{\xi} x^{*}_{m_n}\otimes u_{l_n}+\sum_{n=N_{k_0}+1}^{\infty} f_{n} T\otimes y_{n}}_\alpha\notag\\
     %&\leq \norm{\frac{2}{\xi}\left(\sum_{n=1}^{N_{k_0}} f_{n} T\otimes y_{n} -\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n} \right) }_\alpha+\norm{\left(1-\frac{2}{\xi} \right)\sum_{n=1}^{N_{k_0}} f_{n} T\otimes y_{n}+\sum_{n=N_{k_0}+1}^{\infty} f_{n} T\otimes y_{n} }_\alpha \notag\\
     &\leq \alpha\norm{\frac{2}{\xi_{k_0}}\left(\sum_{n=1}^{N_{k_0}} f_{n} T\otimes y_{n} -\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n} \right)}\notag\\
     &\quad+\alpha\left(2-\varepsilon+\varepsilon_1\right)\max\left
     \{\left|1-\frac{2}{\xi_{k_0}}\right|,1\right\}\|T\|+(1-\alpha)\|T\|_{Q(X,Y)} \label{ieq4}\\
     &< \frac{\varepsilon_2}{8\xi_{k_0}}+\left(2-\varepsilon+\varepsilon_1\right)
     \left(\frac{2}{\xi_{k_0}}-1\right)\alpha\|T\|+(1-\alpha)\|T\|_{Q(X,Y)}\label{ieq5}\\
     &\leq \frac{\varepsilon_2}{8\xi_{k_0}}+\left(2-\varepsilon+\varepsilon_1\right)\left(\frac{2}{\xi_{k_0}}-1\right)\notag\\
     &=2-\varepsilon+\varepsilon_1+\frac{\varepsilon_2}{8\xi_{k_0}}+(2-\varepsilon+\varepsilon_1)
     \left(\frac{2}{\xi_{k_0}}-2\right)\notag\\
     &< 2-\varepsilon+\frac{\sigma}{2}+\frac{\sigma}{8}+\frac{3\varepsilon_2}{4}\notag\\
     &< 2-\varepsilon+\sigma \label{ieq6}\\
     &= 2\alpha-\left(2\alpha+\varepsilon-2-\sigma\right)\notag\\
     &< 2\alpha \notag\\
     &=\norm{\frac{2\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}{\norm{\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}}}_\alpha, \notag
   \end{align}
where inequality (\ref{ieq4}) is obtained by Lemma \ref{lem3.4}. In inequality (\ref{ieq5}), without loss of generality, we can always assume $\xi_{k_0}\leq1$. And inequality (\ref{ieq6}) shows that $Z_\alpha$ ($1-\varepsilon/2 < \alpha \leq 1$) has the $(2\alpha,2\alpha+\varepsilon-2-\sigma)$-UBCP.
\end{proof}

%In particular, the basis property is a kind of approximation property. We know that every Banach space with a basis has the bounded approximation property, and it is immediate that every Banach space with an $\lambda$-unconditional basis has the $\lambda$-UBAP.
Thus we have the following result.

\begin{cor}\label{main1}
Let $X$ be a Banach space with $X^\ast$ separable and $Y$ be a Banach space with an $(2-\varepsilon)$-unconditional basis for any $\varepsilon>0$. Then for all $1-\varepsilon/2<\alpha\leq1$, the renormed space $Z_\alpha=(B(X,Y),\|\cdot\|_\alpha)$ has the $(2\alpha, 2\alpha+\varepsilon-2-\sigma)$-UBCP for all $0<\sigma<2\alpha+\varepsilon-2$.
\end{cor}

\begin{re}\label{rem3.14}
In the proof of Theorem \ref{thm3.12} and Theorem \ref{thm3.13}, we need to control \[\norm{\left(1-\frac{2}{\xi} \right)\sum_{n=1}^{N_{k_0}} f_{n} T\otimes y_{n}+\sum_{n=N_{k_0}+1}^{\infty} f_{n} T\otimes y_{n} }=\norm{\left(id_Y-\frac{2}{\xi}\sum_{n=1}^{N_{k_0}}f_n \otimes y_n\right) \circ T }.\]
%Thus we further consider the Banach spaces with other approximation properties and present more sufficient conditions for $B(X,Y)$ to have the UBCP.Essentially
%Then if $\textbf{BAP}(Y)=1$ and $\lim_{n}\|id_Y-2T_n\| \leq 2-\varepsilon$, a slight modification in the proof of Theorem \ref{thm3.12} actually shows that $B(X,Y)$ has the UBCP. Also, when $\textbf{BAP}(Y)>1$ and $\lim_{n}\|id_Y-2\textbf{BAP}(Y)^{-1}T_n\| =1 $, then it follows that $B(X,Y)$ has the UBCP.
\end{re}

In \cite{J1972}, Johnson showed that every separable Banach space with the CBAP can be renormed to have the commuting MAP. In \cite{C1991}, Casazza and Kalton showed that a separable Banach space with the MAP has the commuting MAP. These two results show that the CBAP is an isomorphic equivalent form of the MAP. Recall that \cite{C1991} a separable Banach space has the MAP if and only if there exists $\rho>0$ and an approximating sequence $\{S_n\}_{n=1}^\infty$ with $\lim_n\|id_X+\rho S_n\|=1+\rho$. There is also a reverse metric approximation property which implies the CBAP and defined as follows \cite{C2001,C1991}.
\begin{de}\label{RMAP}
  Let $X$ be a separable Banach space with an approximating sequence
  $\{S_n\}_{n=1}^\infty$, then $X$ has the reverse metric approximation property (RMAP for short) if $\lim_n\|id_X-S_n\|=1$. Let $\rho>0$, we say $X$ has the $\rho$-RMAP if $\lim_n\|id_X-\rho S_n\|=1$.
\end{de}

Clearly, the $2$-RMAP is equivalent to the UMAP. It was shown in \cite{C1991} that if $X$ has the $\rho$-RMAP for some $\rho>0$ then $X$ has the RMAP. We call the approximating sequence $\{S_n\}_{n=1}^\infty$ in Definition \ref{RMAP} a reverse metric approximating sequence. By Remark \ref{rem3.14}, we get the following corollary.
\begin{cor}\label{cor 3.6}
  Let $X$ be a Banach space with $X^\ast$ separable, $Y$ be a separable Banach space with the $\lambda$-RMAP and $\{S_n\}_{n=1}^\infty$ be the $\lambda$-reverse metric approximating sequence. If $1< \lambda\leq 2$, then $B(X,Y)$ has the $(2,\sigma)$-UBCP for all $0<\sigma<\lambda-1$.
\end{cor}
\begin{proof}
  Since $\{S_n\}_{n=1}^\infty$ is a $\lambda$-reverse metric approximating sequence, then \[\limsup_{n}\|S_n\|\leq \frac{2}{\lambda}<\infty.\] Thus we have $\lambda\leq 2/\limsup_{n}\|S_n\| \leq 2$ and $Y$ has the BAP. By Lemma \ref{decomposable}, for all $\varepsilon_1>0$, there exists a Schauder frame $\{(y_n,f_n)\}_{n\in\mathbb{N}} \subseteq Y\times Y^\ast$ such that $$y=\sum_{n=1}^{\infty}f_n(y) y_n=\sum_{n=1}^{\infty}(f_n\otimes y_n)(y)$$ for all $y\in Y$ and$$\sup_{N\in\mathbb{N}_+}\left\|\sum_{n=1}^{N}f_n \otimes y_n\right\|\leq
  \limsup_{n}\|S_n\|+\varepsilon_1.$$
  For all $T \in B(X,Y)$ with $\|T\|=1$, let $T_{k}=\sum_{n=1}^{N_k}f_nT\otimes y_n$, then
  $$1=\|T\| \leq  \liminf_{k}\|T_k\| \leq \limsup_{k}\|T_k\| \leq \limsup_{k}\|S_k\|\|T\|=\limsup_{k}\|S_k\|.$$
 Let $\xi_{k}=\norm{\sum_{n=1}^{N_{k}} x^{*}_{m_n}\otimes u_{l_n}}$. Let $k_0$ be large enough and $\xi_{k_0}=\norm{\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}$ be chosen the same as that in Theorem \ref{thm3.12}.
 Thus for any $\varepsilon_2>0$, we have
   \[\max\left\{\|T\|-\frac{3\varepsilon_2}{32},\frac{1}{2}\right\}< \xi_{k_0}<\min\left\{\frac{17}{4},\limsup_{k}\|S_k\|\|T\|+\frac{\varepsilon_2}{16}\right\}.\]
  By passing to a subsequence, we can assume $\lim_k \xi_k=\beta$, then
  \[\max\left\{\|T\|-\frac{3\varepsilon_2}{32},\frac{1}{2}\right\}\leq \beta\leq\min\left\{\frac{17}{4},\limsup_{k}\|S_k\|\|T\|+\frac{\varepsilon_2}{16}\right\}.\]
  Since $Y$ has the $\lambda$-RMAP, we have $\lambda\|S_k\|\leq2$ which implies $\lambda\|S_kT\|\leq2$. Thus $\lambda\beta\leq2$.

  By Remark \ref{rem3.14}, it is sufficient to show that for some $\sigma>0$ the following inequality holds \[\norm{\left(id_Y-\frac{2}{\xi_{k_0}}\sum_{n=1}^{N_{k_0}}f_n \otimes y_n\right) \circ T } < 2-\sigma.\]
  Actually we have
  \[
  \begin{aligned}
    &\quad\norm{\left(id_Y-\frac{2}{\xi_{k_0}}\sum_{n=1}^{N_{k_0}}f_n \otimes y_n\right) \circ T }\\
    &\leq\norm{\left(id_Y-\lambda\sum_{n=1}^{N_{k_0}}f_n \otimes y_n\right) \circ T }+\left|\lambda-\frac{2}{\xi_{k_0}}\right|\norm{\sum_{n=1}^{N_{k_0}}f_n T \otimes y_n}\\
    &\leq 1+\left|\lambda-\frac{2}{\lim_{k}\xi_k}\right|\norm{\sum_{n=1}^{N_{k_0}}f_n T \otimes y_n}+\left|\frac{2}{\lim_{k}\xi_k}-\frac{2}{\xi_{k_0}}\right|\norm{\sum_{n=1}^{N_{k_0}}f_n T \otimes y_n}\\
    &\leq 1+\left|\lambda-\frac{2}{\beta}\right|\|T_{k_0}\|+o(1)\\
    &\leq 1+\left|\lambda-\frac{2}{\beta}\right|\xi_{k_0}+o(1)\\
    &\leq 1+\left|\lambda-\frac{2}{\beta}\right|\beta+o(1)\\
    &=1+\left|\lambda\beta-2\right|+o(1)\\
   % &\leq 2-(\varepsilon-1)\\
    &<2,
  \end{aligned}
  \]
  where $o(1)$ can be arbitrarily small when $\varepsilon_1,\varepsilon_2$ small enough. Then the proof presented in Theorem \ref{thm3.12} can be applied with minor modifications.
  %We need to ensure that $\left|\varepsilon\beta-2\right|<1$, this implies $1<\varepsilon\beta<3$. Since $X$ has $\varepsilon$-RMAP, we have $\varepsilon\beta\leq 2$. Thus $1<\varepsilon\leq\varepsilon\beta\leq 2$ which implies $1<\varepsilon\leq 2$.
\end{proof}

By Corollary \ref{cor 3.6}, we obtain the following corollary.

\begin{cor}
  Let $X$ and $Y$ be Banach spaces with $X^\ast$ and $Y$ separable. If $Y$ has the $\lambda$-RMAP for some $\lambda>1$, then $B(X,Y)$ has the UBCP.
\end{cor}

Also, it is true for the renormed spaces.

\begin{cor}\label{cor 3.8}
   Let $X$ be a Banach space with $X^\ast$ separable, $Y$ be a separable Banach space with the $\lambda$-RMAP and $\{S_n\}_{n=1}^\infty$ be the $\lambda$-reverse metric approximating sequence. If $\lambda$ and $(1+\sqrt{17})/8 <\alpha \leq 1$ satisfy
   \[ \frac{1}{\alpha} <\lambda<\frac{4\alpha-1}{\limsup_n\|S_n\|},\] then the renormed space $Z_\alpha=(B(X,Y),\|\cdot\|_\alpha)$ has the $(2\alpha,\sigma)$-UBCP for all \[0<\sigma<\min\{\alpha\lambda-1, 4\alpha-1-\lambda\limsup_n\|S_n\|\}.\]
\end{cor}
\begin{proof}
  If $T \in Z_\alpha$ with $\|T\|_\alpha=1$, then $1 \leq \|T\| \leq \alpha^{-1}$.
  By Remark \ref{rem3.14} and Corollary \ref{cor 3.6}, it is sufficient to show that for some $\sigma>0$ the following inequality holds \[\norm{\left(id_Y-\frac{2}{\xi}\sum_{n=1}^{N_{k_0}}f_n \otimes y_n\right) \circ T }_\alpha < 2\alpha-\sigma.\]
  Actually we have
  \[
  \begin{aligned}
    &\quad\norm{\left(id_Y-\frac{2}{\xi}\sum_{n=1}^{N_{k_0}}f_n \otimes y_n\right) \circ T }_\alpha\\
    &= \alpha\norm{\left(id_Y-\frac{2}{\xi}\sum_{n=1}^{N_{k_0}}f_n \otimes y_n\right) \circ T }+(1-\alpha)\norm{\left(id_Y-\frac{2}{\xi}\sum_{n=1}^{N_{k_0}}f_n \otimes y_n\right) \circ T }_{Q(X,Y)}\\
    &=\alpha\norm{\left(id_Y-\frac{2}{\xi}\sum_{n=1}^{N_{k_0}}f_n \otimes y_n\right) \circ T }+(1-\alpha)\|T \|_{Q(X,Y)}\\
    &\leq \alpha\|T\|+\alpha\left|\lambda-\frac{2}{\beta}\right|\beta+(1-\alpha)\|T \|_{Q(X,Y)}+o(1)\\
    &=1+\alpha\left|\lambda-\frac{2}{\beta}\right|\beta+o(1)\\
    &=1+\left|\alpha\lambda\beta-2\alpha\right|+o(1)\\
    &<2\alpha,
  \end{aligned}
  \]
where $o(1)$ can be arbitrarily small. Then the proof presented in Theorem \ref{thm3.13} can be applied with minor modifications.
%Since \[ \frac{1}{\alpha\|T\|} \leq \frac{1}{\alpha} <\varepsilon<\frac{4\alpha-1}{\limsup_n\|S_n\|} \leq \frac{4\alpha-1}{\alpha\|T\|\limsup_n\|S_n\|},\]
%we have \[\alpha\left|\varepsilon\limsup_n\|S_n\|\|T\|-2\right| \leq 2\alpha-1 -\min\{\alpha\varepsilon\limsup_n\|S_n\|-1, 4\alpha-1-\varepsilon\limsup_n\|S_n\|\}.\]

\end{proof}

Note that the inequality (\ref{ieq1}) and inequality (\ref{ieq3}) hold if the upper bound of the reflection of approximating operator $id_Y-2S_n$ can be controlled.

\begin{cor}\label{cor 3.9}
  Let $X$ and $Y$ be Banach spaces with $X^\ast$ and $Y$ separable. If $Y$ has an approximating sequence $\{S_n\}_{n=1}^\infty$ such that $\lim_n\|id_Y-2S_n\|=\lambda$ for some $\lambda>0$, then for all \[\frac{\lambda}{4}+\frac{\limsup_n\|S_n\|}{2} < \alpha \leq 1,\] the renormed space $Z_\alpha=\left(B(X,Y), \|\cdot\|_\alpha \right)$ has the $(2\alpha,\sigma)$-UBCP for all \[0<\sigma<4\alpha-2\limsup_{n}\|S_n\|-\lambda.\]
\end{cor}
\begin{proof}
    By Remark \ref{rem3.14} and Corollary \ref{cor 3.8}, we have \begin{align*}
    &\quad\norm{\left(id_Y-\frac{2}{\xi_{k_0}}\sum_{n=1}^{N_{k_0}}f_n \otimes y_n\right) \circ T }_\alpha\\
    &\leq \alpha\norm{\left(id_Y-2\sum_{n=1}^{N_{k_0}}f_n \otimes y_n\right) \circ T }+\alpha\left|2-\frac{2}{\xi_{k_0}}\right|\norm{\sum_{n=1}^{N_{k_0}}f_n T \otimes y_n}+(1-\alpha)\|T\|_{Q(X,Y)}\\
    &\leq \alpha\norm{\left(id_Y-2\sum_{n=1}^{N_{k_0}}f_n \otimes y_n\right) \circ T }+\alpha\left|2-\frac{2}{\lim_{k}\xi_k}\right|\norm{\sum_{n=1}^{N_{k_0}}f_n T \otimes y_n}\\
    & \quad +\alpha\left|\frac{2}{\lim_{k}\xi_k}-\frac{2}{\xi_{k_0}}\right|\norm{\sum_{n=1}^{N_{k_0}}f_n T \otimes y_n}+(1-\alpha)\|T\|_{Q(X,Y)}\\
    &\leq\alpha\lambda\|T\|+(1-\alpha)\|T\|_{Q(X,Y)}+\alpha\left|2-\frac{2}{\beta}\right|\|T_{k_0}\|+o(1)\\
    &= 1+\alpha(\lambda-1)\|T\|+\alpha\left|2-\frac{2}{\beta}\right|\|T_{k_0}\|+o(1)\\
    &\leq 1+\alpha(\lambda-1)\|T\|+\alpha\left|2-\frac{2}{\beta}\right|\xi_{k_0}+o(1)\\
    &\leq \lambda+\alpha\left|2-\frac{2}{\beta}\right|\beta+o(1)\\
    &=\lambda+\left|2\alpha\beta-2\alpha\right|+o(1)\\
    &<2\alpha,
    \end{align*}
where $o(1)$ can be arbitrarily small. Then the proof presented in Theorem \ref{thm3.13} can be applied with minor modifications.
%So $Z_\alpha$ has the $(2\alpha,\sigma)$-UBCP for all $0<\sigma<4\alpha-2\limsup_{n}\|S_n\|-\varepsilon$.
\end{proof}


\begin{cor}
     Let $X$ and $Y$ be Banach spaces with $X^\ast$ and $Y$ separable. If $Y$ has an approximating sequence $\{S_n\}_{n=1}^\infty$ such that $\lim_n\|id_Y-2S_n\| < 3/2$, then  $B(X,Y)$ has the UBCP.
\end{cor}
\begin{proof}
    Since $\lim_n\|id_Y-2 S_n\|<3/2$, we have $\limsup_n\|S_n\| \leq 5/4$. Thus $4-2\limsup_n\|S_n\|-\lim_n\|id_Y-2 S_n\| > 4-5/2-3/2=0$ and  $B(X,Y)$ has the UBCP by Corollary \ref{cor 3.9}.
\end{proof}


Let $X$ be a separable Banach space with the BAP, then $X$ has a Schauder frame $\{(x_n,f_n)\}_{n=1}^\infty \subseteq X\times X^*$. Thus for all $x\in X$ we have $x=\sum_{n=1}^{\infty} f_n(x) x_n$.
Then for all $x \in X$ and $T \in B(X,Y)$, we have
\[Tx=T\left(\sum_{n=1}^{\infty}f_n(x)x_n\right)=\sum_{n=1}^{\infty}\left(f_n\otimes T x_n\right)(x).\] Therefore, we obtain the symmetric version of Theorem \ref{thm3.13} and its following corollaries.

\begin{thm}\label{thm3.19}
  Let $X$ and $Y$ be Banach spaces with $X^\ast$ and $Y$ separable. If $X$ or $Y$ has the $(2-\varepsilon)$-UBAP for any $\varepsilon>0$, then for all $1-\varepsilon/2 < \alpha \leq 1$, the renormed space $Z_\alpha=\left(B(X,Y), \|\cdot\|_\alpha \right)$ has the $(2\alpha,2\alpha+\varepsilon-2-\sigma)$-UBCP for all $0<\sigma<2\alpha+\varepsilon-2$.
\end{thm}
\begin{proof}
The case $Y$ with the $(2-\varepsilon)$-UBAP for any $\varepsilon>0$ has been proved in Theorem \ref{thm3.13}.
If $X$ has the $(2-\varepsilon)$-UBAP for any $\varepsilon>0$, then by Lemma \ref{decomposable}, for all $0<\varepsilon_1<\sigma/2$, there exists a block unconditional Schauder frame $\{(x_n,f_n)\}_{n\in\mathbb{N}} \subseteq X\times X^\ast$ such that $$x=\sum_{n=1}^{\infty}f_n(x) x_n=\sum_{n=1}^{\infty}(f_n\otimes x_n)(x)$$ for all $x\in X$ and there exists a subsequence $\{N_k\}_{k=1}^{\infty}$ of $\N_+$ such that $$\sup_{N\in\N,\theta_k=\pm1}\left\|\sum_{k=1}^{N}\theta_k \sum_{n=N_k+1}^{N_{k+1}}f_n\otimes x_n\right\|\leq 2-\varepsilon+\varepsilon_1 \text{ and } \sup_{N\in\mathbb{N}_+}\left\|\sum_{n=1}^{N}f_n \otimes x_n\right\|\leq
2-\varepsilon+\varepsilon_1.$$

For all $T \in B(X,Y)$ with $\|T\|_\alpha=1$ and for all $x \in X$, we have
\[Tx=T\left(\sum_{n=1}^{\infty}f_n(x)x_n\right)=\sum_{n=1}^{\infty}\left(f_n\otimes T x_n\right)(x).\]
By similar proof with Theorem \ref{thm3.13}, we can show that the countable set
   \[\left\{\frac{2\sum_{i=1}^{m} g_{i}^{\ast}\otimes s_{i}}{\norm{\sum_{i=1}^{m} g_{i}^{\ast}\otimes s_{i}}}: m\in \mathbb{N}_+, g_{i}^{\ast}\in\mathcal{A}\ (1\leq i\leq m), s_{i}\in\mathcal{B}\ (1\leq i\leq m)\right\}\] is a set of BCP points for $Z_\alpha$ ($1-\varepsilon/2 < \alpha \leq 1$).

 Actually we have
 \begin{align}
     &\quad\norm{T - \frac{2\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}{\norm{\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}}}_\alpha\notag\\
     %&=\alpha\norm{T - \frac{2\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}{\norm{\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}}}+(1-\alpha)\norm{T - \frac{2\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}{\norm{\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}}}_{Q(X,Y)}\notag\\
     &=\alpha\norm{\sum_{n=1}^{N_{k_0}} f_{n} \otimes T x_{n} -\sum_{n=1}^{N_{k_0}} \frac{2}{\xi_{k_0}} x^{*}_{m_n}\otimes u_{l_n}+\sum_{n=N_{k_0}+1}^{\infty} f_{n} \otimes T x_{n}}\notag\\
     &\quad+(1-\alpha)\norm{T - \frac{2\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}{\xi_{k_0}}}_{Q(X,Y)}\notag\\
     &\leq\alpha\norm{\frac{2}{\xi_{k_0}}\left(\sum_{n=1}^{N_{k_0}} f_{n} \otimes T x_{n} -\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n} \right)}\notag\\
     &\quad+\alpha\norm{\left(1-\frac{2}{\xi_{k_0}}\right)\sum_{n=1}^{N_{k_0}} f_{n} \otimes T x_{n}+\sum_{n=N_{k_0}+1}^{\infty} f_{n} \otimes T x_{n}}\notag\\
     &\quad+(1-\alpha)\norm{T - \frac{2\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}{\xi_{k_0}}}_{Q(X,Y)}\notag\\
     %&=\norm{\sum_{n=1}^{N_{k_0}} f_{n} T \otimes y_{n} -\sum_{n=1}^{N_{k_0}} \frac{2 }{\xi} x^{*}_{m_n}\otimes u_{l_n}+\sum_{n=N_{k_0}+1}^{\infty} f_{n} T\otimes y_{n}}_\alpha\notag\\
     %&\leq \norm{\frac{2}{\xi}\left(\sum_{n=1}^{N_{k_0}} f_{n} T\otimes y_{n} -\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n} \right) }_\alpha+\norm{\left(1-\frac{2}{\xi} \right)\sum_{n=1}^{N_{k_0}} f_{n} T\otimes y_{n}+\sum_{n=N_{k_0}+1}^{\infty} f_{n} T\otimes y_{n} }_\alpha \notag\\
     &\leq \alpha\norm{\frac{2}{\xi_{k_0}}\left(\sum_{n=1}^{N_{k_0}} f_{n} \otimes T x_{n} -\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n} \right)}\notag\\
     &\quad+\alpha\left(2-\varepsilon+\varepsilon_1\right)\max\left
     \{\left|1-\frac{2}{\xi_{k_0}}\right|,1\right\}\|T\|+(1-\alpha)\|T\|_{Q(X,Y)}\notag\\
     &< \frac{\varepsilon_2}{8\xi_{k_0}}+\left(2-\varepsilon+\varepsilon_1\right)
     \left(\frac{2}{\xi_{k_0}}-1\right)\alpha\|T\|+(1-\alpha)\|T\|_{Q(X,Y)}\notag\\
     &\leq \frac{\varepsilon_2}{8\xi_{k_0}}+\left(2-\varepsilon+\varepsilon_1\right)\left(\frac{2}{\xi_{k_0}}-1\right)\notag\\
     %&=2-\varepsilon+\varepsilon_1+\frac{\varepsilon_2}{8\xi}+(2-\varepsilon+\varepsilon_1)
     %\left(\frac{2}{\xi}-2\right)\notag\\
     &< 2-\varepsilon+\frac{\sigma}{2}+\frac{\sigma}{8}+\frac{3\varepsilon_2}{4}\notag\\
     &< 2-\varepsilon+\sigma \notag\\
     &= 2\alpha-\left(2\alpha+\varepsilon-2-\sigma\right)\notag\\
     &< 2\alpha.\notag
     %&=\norm{\frac{2\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}{\norm{\sum_{n=1}^{N_{k_0}} x^{*}_{m_n}\otimes u_{l_n}}}}_\alpha.\notag
   \end{align}
Thus the renormed space $Z_\alpha$ ($1-\varepsilon/2 < \alpha \leq 1$) has the $(2\alpha,2\alpha+\varepsilon-2-\sigma)$-UBCP.
\end{proof}
\begin{cor}
   Let $X$ and $Y$ be Banach spaces with $X^\ast$ and $Y$ separable, and one of them has the $\lambda$-RMAP. Let $\{S_n\}_{n=1}^\infty$ be the $\lambda$-reverse metric approximating sequence. If $\lambda$ and $(1+\sqrt{17})/8 <\alpha \leq 1$ satisfy
   \[ \frac{1}{\alpha} <\lambda<\frac{4\alpha-1}{\limsup_n\|S_n\|},\] then the renormed space $Z_\alpha=(B(X,Y),\|\cdot\|_\alpha)$ has the $(2\alpha,\sigma)$-UBCP for all \[0<\sigma<\min\{\alpha\lambda-1, 4\alpha-1-\lambda\limsup_n\|S_n\|\}.\]
\end{cor}
\begin{cor}
  Let $X$ and $Y$ be Banach spaces with $X^\ast$ and $Y$ separable. If $X$ or $Y$ has the $\varepsilon$-RMAP for some $\varepsilon>1$, then $B(X,Y)$ has the UBCP.
\end{cor}

\begin{cor}
  Let $X$ and $Y$ be Banach spaces with $X^\ast$ and $Y$ separable. If $X$ or $Y$ has an approximating sequence $\{S_n\}_{n=1}^\infty$ such that $\lim_n\|id-2S_n\|=\lambda$ for some $\lambda>0$, then for all \[\frac{\lambda}{4}+\frac{\limsup_n\|S_n\|}{2} < \alpha \leq 1,\]the renormed space $Z_\alpha=\left(B(X,Y), \|\cdot\|_\alpha \right)$ has the $(2\alpha,\sigma)$-UBCP for all \[0<\sigma<4\alpha-2\limsup_{n}\|S_n\|-\lambda.\]
\end{cor}
\begin{cor}
     Let $X$ and $Y$ be Banach spaces with $X^\ast$ and $Y$ separable.  If $X$ or $Y$ has an approximating sequence $\{S_n\}_{n=1}^\infty$ such that $\lim_n\|id-2S_n\| < 3/2$, then  $B(X,Y)$ has the UBCP.
\end{cor}

The mutual symmetry between the two theorems suggests that we need to minimize the influence of the domain and range and instead shift our focus to operators. Here we introduce the notion of (unconditional) bounded approximation property of operators.
\begin{de}\label{defn3.22}(\cite{LSZ2023})
  Let $X$ and $Y$ be separable Banach spaces. Let $\lambda >0$ and $S \in B(X,Y)$. Then $S$ is said to have the $\lambda$-bounded approximation property ($\lambda$-BAP) if there exists  $\left\{S_{n}\right\}_{n \in \N_+}\subseteq B(X,Y)$ with
\[\sup_{n \in \N_+}\|S_{n}\| \leq \lambda\] such that both $\dim(S_{n}X)<\infty$ for all $n \in \N_+$ and $\lim_{n}\|S_{n}x-S x\|=0$ for all $x \in X$. We say $S$ has the bounded approximation property (BAP) if there exists a $\lambda>0$ such that $S$ has the $\lambda$-bounded approximation property.
\end{de}

\begin{de}\label{defn3.23}
  Let $X$ and $Y$ be separable Banach spaces. Let $\lambda >0$ and $S \in B(X,Y)$. Then $S$ is said to have the $\lambda$-unconditional bounded approximation property ($\lambda$-UBAP) if for all $\varepsilon>0$ there exists  $\left\{R_{n}=S_n-S_{n-1}\right\}_{n \in \N_+}\subseteq B(X,Y)$ and $S_0=0$ with
\[\sup_{N \in \N_+, \varepsilon_n=\pm1}\left\|\sum_{n=1}^{N}\varepsilon_n R_{n}\right\| \leq \lambda+\varepsilon\] such that both $\dim(S_{n}X)<\infty$ for all $n \in \N_+$ and $\lim_{n}\|S_{n}x-S x\|=0$ for all $x \in X$.
\end{de}

\begin{de}
  Let $X$ be a separable Banach space, $Y$ be a Banach space and $T \in B(X,Y)$. Then $T$ is said to be linear decomposable if there exists $\left\{(y_{n},f_{n})\right\}_{n\in\N}\subseteq Y \times X^* $ such that $T x=\sum_{n=1}^{\infty} f_{n}(x) y_{n}$ for all $x \in X$.  And $T$ is said to be block unconditional decomposable if there exists a subsequence
  $\{N_k\}_{k=1}^\infty$ of $\N_+$ such that $$\sup_{N\in\mathbb{N_+},\theta_k=\pm1}\left\|\sum_{k=1}^{N}\theta_k \sum_{n=N_k+1}^{N_{k+1}}f_n\otimes y_n\right\| < \infty.$$
\end{de}

It was proved in \cite{LSZ2023} that $T$ has the BAP if and only if $T$ is linear decomposable for all $T \in B(X,Y)$.

The method of proof in Lemma \ref{decomposable} carries over to the relationship between the $\lambda$-UBAP and block unconditional decomposition for all $T \in B(X,Y)$.
\begin{lem}
  Let $T\in B(X,Y)$ with the $\lambda$-UBAP and $\varepsilon > 0$. Then there exists a (block unconditional) decomposition  $\{(y_n,f_n)\}_{n\in\mathbb{N}+} \subseteq Y\times X^\ast$ such that for all $x\in X$ we have
  $$Tx=\sum_{n=1}^{\infty}f_n(x) y_n.$$  And there exists a subsequence
  $\{N_k\}_{k=1}^{\infty}$ of $\N_+$ such that
  $$\sup_{N\in\mathbb{N}_+,\theta_k=\pm1}\left\|\sum_{k=1}^{N}\theta_k \sum_{n=N_k+1}^{N_{k+1}}f_n \otimes y_n\right\|\leq \lambda+\varepsilon  \text{ and } \sup_{N\in\mathbb{N}_+}\left\|\sum_{n=1}^{N}f_n \otimes y_n\right\|\leq \lambda+\varepsilon.$$
  In addition, we can assume $\|y_n\| = 1$ and $\|f_n\| \leq 1$  for all $n \in \N_+$.
\end{lem}

Let $T \in B(X,Y)$ with the UBAP, then define
$$\textbf{UBAP}(T)=\inf\{\lambda: T \text{ has the } \lambda\text{-UBAP}\}.$$ Thus if $X$ has the UBAP then
\[\textbf{UBAP}(id_X)=\textbf{UBAP}(X).\]
And if either $\textbf{UBAP}(X)=\lambda$ or $\textbf{UBAP}(Y)=\lambda$, then for all $T \in B(X,Y)$, we have $\textbf{UBAP}\left(T/\|T\|\right) \leq \lambda$. Therefore we have the following result.
\begin{thm}\label{thm3.26}
  Let $X$ and $Y$ be Banach spaces with $X^\ast$ and $Y$ separable. For any $\varepsilon>0$, define \[\mathcal{Z}_\varepsilon=\left\{T \in B(X,Y): \textbf{UBAP}\left(\frac{T}{\|T\|}\right) \leq 2-\varepsilon \right\}.\]
  Then for all $1-\varepsilon/2 < \alpha \leq 1$, $\left(\mathcal{Z}_\varepsilon, \|\cdot\|_\alpha \right)$ has the $(2\alpha,2\alpha+\varepsilon-2-\sigma)$-UBCP for all $0<\sigma<2\alpha+\varepsilon-2$.
\end{thm}

Next we consider the case when either $X$ or $Y$ has the UMAP. The UMAP is associated with the lattice structure of compact operator space $K(X)$ and $B(X)$. Casazza and Kalton \cite{C1991} introduced the notion of u-ideal which is a generalization of M-ideal \cite{AE1972,HW1993} and it is well known that if $X$ is an M-ideal in $Y$ then $X$ is a u-ideal.

\begin{de}[\cite{C1991}]
  Let $X$ be a subspace of a Banach space $Y$. Then $X$ is a u-ideal in $Y$ if there is a projection $P$ from $Y^*$ onto $X^{\bot}$ (the kernel of $P$) such that $\|id-2P\|=1$.
\end{de}

The following theorem demonstrates the important relationship between the UMAP and u-ideals.

\begin{thm}[\cite{C1991}]
Let $X$ be a separable reflexive Banach space with the approximation property. Then $X$ has the UMAP if and only if $K(X)$ is a u-ideal in $B(X)$.
\end{thm}

Also, u-ideals can be characterized by the ball intersection property.

\begin{thm}[\cite{LA2007}]\label{BIP}
Let $X$ be a closed subspace of a Banach space $Y$ and let $y \in Y \backslash X$ and $Z=\operatorname{span}(X,\{y\})$. The following statements are equivalent.
\begin{enumerate}
\item[(1)] $X$ is a u-ideal in $Z$.
\item[(2)] $X^{\perp \perp} \bigcap_{x \in X} B_{Z^{* *}}(y+x,\|y-x\|) \neq \emptyset$.
\item[(3)] $X \cap \bigcap_{i=1}^n B_Z\left(y+x_i,\left\|y-x_i\right\|+\varepsilon\right) \neq \emptyset$ for every finite collection $\left(x_i\right)_{i=1}^n \subseteq X$ and $\varepsilon>0$.
\item[(4)] $X \cap \bigcap_{i=1}^3 B_Z\left(y+x_i,\left\|y-x_i\right\|+\varepsilon\right) \neq \emptyset$ for every collection of three points $\left(x_i\right)_{i=1}^3 \subseteq X$ and $\varepsilon>0$.
\end{enumerate}
\end{thm}

