Thus we get the following corollary.
\begin{cor}\label{u-ideal and BIP}
  Let $X$ and $Y$ be separable reflexive Banach spaces with the approximation property.
  \begin{enumerate}
    \item[(1)]   If either $K(X)$ is a u-ideal in $B(X)$ or $K(Y)$ is a u-ideal in $B(Y)$,  then for all $1/2 < \alpha \leq 1$, the renormed space $Z_\alpha=\left(B(X,Y), \|\cdot\|_\alpha \right)$ has the $(2\alpha,2\alpha-1-\sigma)$-UBCP for all $0<\sigma<2\alpha-1$.
    \item[(2)] If either $K(X)$ or $K(Y)$ has the ball intersection property defined in Theorem \ref{BIP}, then for all $1/2 < \alpha \leq 1$, the renormed space $Z_\alpha=\left(B(X,Y), \|\cdot\|_\alpha \right)$ has the $(2\alpha,2\alpha-1-\sigma)$-UBCP for all $0<\sigma<2\alpha-1$.
  \end{enumerate}
\end{cor}
For classsical sequence space, by Corollary \ref{u-ideal and BIP}, we have the following results.
\begin{cor}\label{cor3.31}
  $B(\ell_p(F_n),\ell_q(H_n))$ has the UBCP for all finite-dimensional Banach space sequences $\{F_n\}_{n=1}^\infty$ and $\{H_n\}_{n=1}^\infty$ where $1< p,q <\infty$.
\end{cor}

\begin{cor}
  Let $C_p$ denote the space $\ell_p(F_n)$ where $F_n$ is a sequence of finite-dimensional Banach spaces dense in the Banach-Mazur sense in the collection of all finite-dimensional Banach spaces. Then $B(C_p,C_q)$ has the UBCP for $1< p,q <\infty$.
\end{cor}

%\begin{cor}
%$B((\oplus_{n=1}^\infty F_n )_{\ell_{p_n}},(\oplus_{n=1}^\infty H_n)_{\ell_{q_n}})$ has the UBCP for all finite-dimensional Banach space sequences $\{F_n\}_{n=1}^\infty$ and $\{H_n\}_{n=1}^\infty$ where $\{p_k,q_k\}_{k=1}^\infty \subseteq (1,\infty)$.
%\end{cor}

\begin{exa}
  In \cite{S1987}, Szarek constructed a Banach space $\ell_2(W_n)$ which has the $1$-UFDD thus has the $1$-UBAP but fails to have a basis, where $W_n$ is a sequence of normed spaces. By Corollary \ref{cor3.31}, if $W_n$ is a sequence of finite-dimensional Banach spaces, then $B(\ell_2(W_n))$ has the UBCP.
\end{exa}

In \cite{LGK1996}, Godefroy, Kalton and Li gave a description of the subspace with the UMAP of $L^1[0,1]$.

\begin{thm}[\cite{LGK1996}]
  Let $X$ be a closed subspace of $L^1[0,1]$ with the approximation property. The following assertions are equivalent.
  \begin{enumerate}
    \item[(1)] The unit ball of $X$ is compact locally convex in the topology of convergence in measure.
    \item[(2)] $X$ has the UMAP and the $1$-strong Schur property.
    \item[(3)] For any $\varepsilon>0$, there is a quotient $Y_\varepsilon$ of $c_0$ such that
    $d(X, Y_{\varepsilon}^\ast) < 1 + \varepsilon$.
  \end{enumerate}
\end{thm}

Therefore, we get the following sufficient condition for $B(X,Y)$ to have the UBCP.
\begin{cor}
  Let $X$ be a Banach space with $X^\ast$ separable and $Y$ be a closed subspace of $L^1[0,1]$ with the approximation property. If the unit ball of $Y$ is compact locally convex in the topology of convergence in measure, then $B(X,Y)$ has the UBCP.
\end{cor}
Following Proposition 4.5 in \cite{LGK1996} which qualifies the UMAP, we obtain two spaces of bounded linear operators whose range spaces are concrete natural spaces have the UBCP.
\begin{exa}
 Let $Y$ be a separable predual of a von Neumann algebra. Then $Y$ has the UMAP if and only if $Y$ is isometric to $\ell_1(N(H_n))$, where $N(H_n)$ is a space of nuclear operators on the finite-dimensional Hilbert space $H_n$ for every $n$. Thus if $X$ is a Banach space with $X^*$ separable and $Y$ is isometric to $\ell_1(N(H_n))$, then $B(X,Y)$ has the UBCP.
\end{exa}

\begin{exa}
  There exist infinite subsets $\Lambda$ of $\Z$ such that $L_{\Lambda}^1(\mathbb{T})$ has the UMAP. Thus if $X$ is a Banach space with $X^\ast$ separable, then $B(X, L_{\Lambda}^1(\mathbb{T}))$ has the UBCP.
\end{exa}

