% A function $u(t,x)$ solving Eq.~(\ref{Kolmogorov2})  is often called a {\em mild solution} of KE.

%Next let us define  ``sufficiently regular" functions. To this end we need Gauss-Sobolev spaces~\cite{chow2007stochastic}. 

In this section, following~\cite[p.284]{chow2007stochastic} we introduce Gauss Sobolev spaces: namely, the spaces of functions which are integrable together with their derivatives w.r.t. Gaussian measure -- a generalization of classical Sobolev spaces, commonly used in theory of PDEs. As we shall see below elements of these spaces are the natural choice for the solution of KE, and more importantly these functions admit Hermite polynomial expansion which we use in turn to simulate KE on a quantum computer.
\begin{dfn}[\bf Gauss-Sobolev space]
Let $k\ge 0$ be an integer. The $k$-th order Gauss-Sobolev space  $\calG\calS_k$ is a Hilbert space
of functions 
% \begin{align*}
% \frac{dX_i}{dt} &= c_i(X(t))\\
% \frac{dX_i}{dt} &= c_i(X(t))\hspace{12pt}\color{blue}{- \lambda_i X_i(t)}\\
% dX_i &= c_i(X(t))dt\hspace{3pt}\color{blue}{- \lambda_i X_i(t)dt}  \hspace{6pt} \color{orange}{+ \sqrt{q}\,dW_i}
% \end{align*}
\be\label{eq:HermitExpansion}
g(x)=\sum_{k=1}^\infty\sum_{|\mm|=k,\mm \in \calJ} \psi_\mm \HH_\mm(x)
\ee
where $\psi_\mm$ are real coefficients that obey 
\be
\label{GSk}
\sum_{\mm \in \calJ} \lambda_\mm^p \psi_\mm^2 <\infty \qquad \mbox{for all $p=0,1,\ldots,k$}.
\ee
Here $\lambda_\mm= \sum_{i=1}^N m_i \lambda_i$.
The inner product between a function $g(x)$ as above and $h(x)=\sum_{\mm \in \calJ} \phi_\mm \HH_\mm(x)$ is defined as
\be
\label{GSinner_product}
(g,h)_{\mu,k} = \sum_{\mm \in \calJ} \lambda_\mm^k  \psi_\mm \phi_\mm =  \int_{\RR^N} dx\, \mu(x) g(x) \calA^k h(x)
\ee
and the corresponding norm is $\| g\|_{\mu,k} = \sqrt{(g,g)_{\mu,k}}$.
We shall write
\be
(g,h)_\mu \equiv (g,h)_{\mu,0} \quad \mbox{and} \quad \|g\|_\mu \equiv \|g\|_{\mu,0}.
\ee
\end{dfn}
Let us stress that the equality in~\eqref{eq:HermitExpansion} is understood as follows: \[
\lim_{M\to\infty }\|g-\sum_{k=1}^M\sum_{|\mm|=k,\mm \in \calJ} \psi_\mm \HH_\mm\|_{\mu,k} = 0
\]
and thus one should not expect\footnote{It does converge pointwise for locally Lipschitz and bounded functions.} that the Hermite series in the r.h.s. of~\eqref{eq:HermitExpansion} converges pointwise for any $g$. Moreover, the coefficients $\psi_{\mm}$ are given by $\psi_\mm=(g,\HH_\mm)_\mu$ hence if we change the function $g$ on a set $x\in A$ of measure zero w.r.t. $\mu$, i.e. $\int_A dx \mu(x) =0$, the coefficents $\psi_\mm$ will not change suggesting that there is a class of functions $g$, elements of which are the same up to sets of $\mu$-measure zero, for which~\eqref{eq:HermitExpansion} holds.

Recall that the set of multi-indices $\calJ$ does not include the all-zero string $\mm=(0,0,\ldots,0)$.
Thus the space $\calG\calS_k$ does not include the constant Hermite polynomial. 
This is justified since we shall only work with functions which have zero mean with respect to the measure $\mu$.

Note that for any constant $k\ge 0$ one has $\lambda_\mm^k \le |\mm| \lambda_\mm^k \le \lambda_1^{-1} \lambda_\mm^{k+1}$.
Thus $\|g\|_{\mu,k}<\infty$ implies $\|g\|_{\mu,p}<\infty$ for all $0\le p\le k$ and Gauss-Sobolev spaces form a nested sequence, that is, 
\be
\calG\calS_{k+1} \subseteq \calG\calS_k
\ee
for all $k\ge 0$ (here we ignore the Hilbert space structure and consider $\calG\calS_k$ as linear spaces).

We shall primarily work with the spaces $\calG\calS_k$ for $k=0,1,2$.
The space $\calG\calS_0$ coincides with the space of functions square integrable with respect to the measure $\mu$
that have zero mean with respect to $\mu$.  
We shall always consider test functions $u_0\in \calG\calS_0$. Clearly, a linear function such that $u_0(x)=x_i$ 
and any finite degree polynomial which has zero mean with respect to $\mu$ belong to  $\calG\calS_0$. 

$\calG\calS_1$  admits a very intuitive interpretation: Using the identity $\frac{\partial}{\partial x_i} \HH_{\mm}(x) =(2m_i \lambda_i/q)^{1/2}\, \HH_{\mm-e^i}(x)$
and the orthogonality relations for Hermite polynomials one gets
\be
\label{1norm_eq1}
\| g\|_{\mu,1}^2 =  \sum_{\mm\in \calJ} \lambda_\mm \psi_\mm^2 = (q/2)\sum_{i=1}^N  \int_{\RR^N} dx \, \mu(x) (\partial g(x)/\partial x_i)^2.
\ee
Thus $g\in \calG\calS_1$ iff  $g$ and  all first derivatives of $g$ are square integrable with respect to the measure $\mu$
and $g$ has zero mean with respect to $\mu$. This also implies that any function $g\in \calG\calS_1$ has first derivatives with respect to any
variable almost everywhere with respect to the measure $\mu$. Indeed, one can 
define the derivative $\partial g(x)/\partial x_i$ 
using the expansion of $g(x)$ in Hermite polynomials by applying the derivative term-wise.

The space $\calG\calS_2$ serves as domain of the operators $\calA$ and $\calB$ describing noise/dissipation and linear part of the drift. 
Indeed, for any function $g\in \calG\calS_2$ one has $\| \calA g\|_\mu^2 = (g, \calA^2 g)_\mu = \|g\|_{\mu,2}^2<\infty$, that is,
$\calA$ maps $\calG\calS_2$ to $\calG\calS_0$. 
Recall that $\calB$ is a linear combination of operators $x_j \partial/\partial x_i$. 
It is well known that multiplication by a single variable $x_j$ and differentiation $\partial/\partial x_i$ 
are linear operators mapping $\calG\calS_{k+1}$ to $\calG\calS_k$ for any order $k$~\cite[p.197]{da_prato_second_2002}.
Hence we can choose domain and range of $\calB$ as $\calG\calS_2$ and $\calG\calS_0$ respectively (this can also be seen directly from Eq.~(\ref{KolmogorovL2explicit})). 

Prior to giving the definition of the mild solution of KE we restrict the coefficients of the differential operator $\calC=\sum_{i=1}^N c_i(x) \partial/\partial x_i$ mimicking the notion of hypo-ellipticity~\cite{delgado2016spectral} well known in the theory of PDEs: 
\begin{dfn}[\bf Relatively bounded systems]
The system Eq.~(\ref{SDE}) is called relatively bounded if there exists a real number $\gamma \in [0,\infty)$ such that 
\be
\label{gamma_definition}
(h,\calC g)_\mu \le \gamma \|h\|_\mu \cdot \|g\|_{\mu,1} \equiv
\gamma \sqrt{(h,h)_\mu (g,\calA  g)_\mu }
\ee
for any functions $h\in \calG\calS_0$ and $g\in \calG\calS_1$.
\end{dfn}
%The space $\calG\calS_0$ contains solutions of KE, see Definition~\ref{dfn:solution}.
A few important properties of the operator $\calC$ are collected in the following
\begin{lemma}
\label{lemma:Cprops}
Suppose the system of Eq.~(\ref{SDE}) is relatively bounded. Then $\calC$ is a bounded linear operator from $\calG\calS_1$ to $\calG\calS_0$, and it is unbounded if considered as a linear operator in $\calG\calS_0$ with domain $\calG\calS_1$. If $\sum_{i=1}^N c_i^2(x)\le J^2$ for some $J\in [0,\infty)$ and all $x\in \RR^N$ then the system is relatively bounded
and one can choose
\be
\label{gamma_from_J}
\gamma =J \sqrt{2/q}.
\ee
Suppose the system of Eq.~(\ref{SDE}) is divergence-free.
Then the  operator $\calC$ is skew-hermitian, $\calC^\dag = -\calC$. 
\end{lemma}
The proof is provided in Appendix~\ref{sec:appC}. Now we are ready to make the notion of KE' mild solution given in~\eqref{Kolmogorov2} more precise: 
\begin{dfn}
\label{dfn:solution}
A continuous function $u\, : \, \RR_{\ge 0} \to \calG\calS_0$ is called a solution of the Kolmogorov equation Eq.~(\ref{Kolmogorov0}) with the initial condition~\footnote{In fact we will see in Lemma~\ref{lemma:exp} that the operator $e^{-t\calL} \calC $ is bounded in $\calG\calS_0$ for any $t>0$ making $\int_0^t ds e^{-(t-s)\calL} \calC u(s)$ well defined for any $u\in C(0,T,\calG\calS_0)$.}
$u_0\in \calG\calS_0$ if $u(0)=u_0$,
\be
\sup_{t\ge 0 } \| u(t)\|_\mu <\infty
\ee
and
\be\label{eq:KEmild}
u(t) = e^{- t \calL} u_0 + \int_0^t ds \, e^{-(t-s)\calL} \calC u(s), \quad \forall t\ge 0
%(g,u(t))_\mu  =  (g,e^{-t\calL} u_0)_\mu + \int_0^t ds\, (g,e^{-(t-s) \calL} \calC u(s))_\mu
\ee
%for all $t>0$ and any function $g\in \calG\calS_0$. 
\end{dfn}
