\subsection{\acf{nse}} 
\label{sec:NSE}

The notation and discretization of \ac{nse} of this example closely follows~\cite{zhuk2023detectability,flandoli1998kolmogorov}. Here we omit all the formal definition of spaces required for applying Galerkin projection~\cite[p.55]{Foias_Manley_Rosa_Temam_2001}, which effectively approximates the solution of the continuous \ac{nse}, $\vec v$, by a linear combination of finitely many eigen-functions of the Stokes operator with time-dependent coefficients, then projects \ac{nse} onto a subspace generated by this eigen-functions to get a non-linear divergence-free ODE describing dynamics of the time-dependent coefficients. This ODE is then stochastically forced and we apply our algorithm to estimate expectations of certain functions $u_0$ of the solution.  

The classical \ac{nse} in 2D is a system of two PDEs defining dynamics of the scalar pressure field $p(x,y)$ and the viscous fluid velocity vector-field $\vec v(t,x,y)=[v_1(t,x,y),v_2(t,x,y)]$ which depends on the initial condition $\vec v(0)=\vec v_0$, forcing $\vec f$, and Boundary Conditions (BC), e.g. periodic BC $v_{1,2}(t,x+\ell_1,y) = v_{1,2}(t,x,y)$, $v_{1,2}(t,x,y+\ell_2) = v_{1,2}(t,x,y)$. In the vector form it reads as follows:
\begin{equation}
  \label{eq:NSE-vector}
  \begin{split}
    \dfrac{d\vec{v}}{dt} &+ (\vec{v} \cdot \nabla) \vec{v} - \nu\Delta\vec{v}+\nabla p = \vec f,\quad \nabla\cdot\vec{v} = 0
  \end{split}
\end{equation}
To eliminate pressure $p$ and obtain an evolution equation just for $\vec{v}$ it is common to use Leray projection~\cite[p.38]{Foias_Manley_Rosa_Temam_2001}: every vector-field $\vec{v}$ in $\RR^2$ admits Helmholtz-Leray decomposition, $\vec{v} = \nabla p + \vec q$ with $\nabla\cdot\vec q = 0$ which in turn defines Leray projector, $P_l(\vec{v})=\vec q$ (e.g.~\cite[p.36]{Foias_Manley_Rosa_Temam_2001}). %Applying $P_l$ to both sides of~\eqref{eq:NSE-vector} one can project~\eqref{eq:NSE-vector} onto the subspace of div-free vector-fields with zero mean, $\vsVza$ and thus eliminate $p$. In fact,
Multiplying~\eqref{eq:NSE-vector} by a smooth divergence-free test function $\vec\phi$, and integrating by parts in $\Omega$ allows one to obtain Leray's weak formulation of NSE in 2D:
\begin{equation}
\label{eq:NSE-var}
    \dfrac{d}{dt}(\vec{v},\vec \phi) + b(\vec{v},\vec{v},\vec\phi) + \nu(A \vec v,\vec \phi) = (\vec f,\vec \phi), 
\end{equation}
with initial condition $(\vec{v}(0),\vec\phi)=(\vec{v}_0,\vec\phi)$. Here the Stokes operator~\cite[p.52]{Foias_Manley_Rosa_Temam_2001} $A$ and trilinear form $b$ are defined as follows: 
\[
    A\vec v = -\Delta \vec v = 
    \left[\begin{smallmatrix}-\Delta v_1\\ -\Delta v_2, 
    \end{smallmatrix}\right], 
    %\quad {D}(A) =  W^{2,2}(\Omega)\cap \mathcal{V}
    \quad
    b(\vec v,\vec y,\vec \phi) = %\int_\Omega [(\vec u\cdot \nabla_\xi)\vec{y}]\cdot\vec zd\xi = \int_\Omega \vec x\cdot [ \nabla_\xi\vec{y}\,]\vec z d\xi=  
    \int_\Omega (\vec v\cdot \nabla y_1) \phi_1 d\vec\xi + \int_\Omega (\vec v\cdot \nabla y_2) \phi_2 d\vec\xi
\]
The orthonormal set of eigenfunctions of $A$ is given by (see~\cite{flandoli1998kolmogorov})
\begin{align*}
    A\vec{e}_{\vec k} &= \lambda_{\vec k} \vec{e}_{\vec k}, & \lambda_{\vec k} &= 4\pi^2|\vec k|^2_2,&\vec k &= (k_1,k_2)^\top, k_{1}\in\mathbb{N}, k_{2}\in\mathbb{Z}\\
    \vec{e}_{\vec k}&= \frac{\vec{k}^\perp}{|\vec k|_2}\sqrt{2}\sin(2\pi\vec{k}\cdot\vec{\xi}),
    & \vec{k}^\perp&=(k_2,-k_1)^\top,&\vec{k}\cdot\vec{\xi}&=k_1\xi_1+k_2\xi_2, |\vec k|_2^2=\vec k\cdot\vec k
\end{align*}
Additionally, we enumerate 2-dimensional vectors (multi-indices) $\vec k$ with a scalar index $k\in\mathbb{N}$ permitting us to define $\lambda_{k}=\lambda_{\vec k}$ and $\vec{e}_{k}=\vec{e}_{\vec k}$. Furthermore, in what follows we will abuse the notation and write $\xi$ for $\vec \xi$ and $e_k$ for $\vec{e}_{k}$ for simplicity. We note that (see~\cite[p.99,p.101]{Foias_Manley_Rosa_Temam_2001} \[
b(\vec u ,\vec y,\vec \phi)=-b(\vec u,\vec \phi,\vec y), \quad b(\vec u,\vec u,A\vec u)=0. 
\]
Now we approximate $\vec v$ by $\vec v_N=\sum_{k=1}^N x_{k}(t) e_{k}(\xi)$, substitute $\vec v_N$ into~\eqref{eq:NSE-var} instead of $\vec v$, set $\vec\phi=e_{k}$ and obtain a system of finitely many ODEs: 
\begin{align}\label{eq:NSEODE}
    \dot x_k &= -\nu\lambda_k x_k - b(\vec u_N,\vec u_N,e_k) + (\vec f,e_k)\\
    &=-\nu\lambda_k x_k - \sum_{i,j=1}^N b(e_i,e_j,e_k)x_ix_j + (\vec f,e_k)\\
    &=-\nu\lambda_k x_k + b_k(x) +(\vec f,e_k)
\end{align}
with initial conditions $x_k^0=(\vec{v}_0,e_k)$. Since $b(e_k,e_k,\vec u)\equiv 0$ and $b(e_i,e_k,e_k)=0$ we get that $b_k(x)$ is independent of $x_k$ hence $\sum_k \partial_{x_k} b_k(x)=0$. Also $\sum \lambda_k x_k b_k(x) = b(\vec u_N,\vec u_N, A \vec u_N)=0$. Hence, the disretized NSE given by~\eqref{eq:NSEODE} satisfies divergence-free conditions~\eqref{NDE1}-\eqref{NDE2}.  

Now, set $\vec f=0$ and consider the stochastic discretized \ac{nse} in which $w_k$ is a standard scalar Wiener process:
\begin{equation} \label{eq:stochastic_disc_nse}
    d X_k = -\nu\lambda_k X_k dt + b_k(X)dt + \sqrt{q} d W_k
\end{equation}
We are interested in computing the following expectation value: $u(t,x)=\EE_W\left(u_0(X(t)|X(0)=x)\right)$, for a given function $u_0:\RR^N\to\RR$. As suggested above this task can be performed by rewriting $u$ by means of Hermite polynomials $u(t,x) = \sum_{\mm\in \calJ} u_\mm(t) \HH_\mm(x)$ and introducing the KE in coordinate Gauss-Sobolev space (recall~\eqref{regul_eq2}) describing dynamics of coefficients $\psi(t) (t)=\{\psi_\mm(t)\}_{\mm\in \calJ}$: 
\be
\label{eq:ke_assoc_nse}
\frac{d}{dt} |\psi(t)\ra = (-\nu\Lambda + C)|\psi(t)\ra
\ee
%in correspondence to~\eqref{eq:stochastic_disc_nse}:
% \begin{equation} \label{eq:ke_assoc_nse}
%     \frac{\partial}{\partial t} u_{\calJ}(t) = \left(-\nu\Lambda + C\right) u_{\calJ}(t)
% \end{equation}
where $\Lambda=\text{diag}(\{\lambda_{\mm}\}_{\mm\in\calJ})$ with elements $\lambda_\mm=\sum_{i=1}^N \mm_i 4\pi^2|\vec i|^2_2$, and $C=\{C_{\mm,\nn}\}_{\mm,\nn\in\calJ}$ is a skew-symmetric matrix with elements $C_{\mm,\nn} = \sum_{k=1}^N \int_{\RR^N}  (b_k(x) \partial_{x_k}\HH_\nn)\HH_\mm \mu(dx)$.
% \begin{equation} \label{eq:ke_assoc_nse}
%     \frac{\partial}{\partial t} u(t,x) = \sum_{i=1}^N (-\nu\lambda_i x_i + b_i(x)) \frac{\partial}{\partial x_i} u(t,x)
%     +\frac{q}2 \sum_{i=1}^N  \frac{\partial^2}{\partial x_i^2} u(t,x).
% \end{equation}

We omit the demonstration of the existence of the solution of KE~\eqref{eq:ke_assoc_nse} (which can be done e.g. by employing~\cite[Lemma 4.1]{flandoli1998kolmogorov}). We stress that even though KE has the unique solution, operator $C$ corresponding to the nonlinearity $b_k$ does not verify the relative boundedness condition~\ref{gamma_definition}.   

Let us compute $C_{\mm,\nn}$. To this end we note that 
\begin{align}
    b(e_i,e_j,e_k) &= 2(2\lambda_s)^{\frac12}B_{i,j}^k \\
    B_{i,s}^k &= \int_\Omega \sin(2\pi\vec k\cdot \xi) \sin(2\pi\vec i\cdot \xi) \cos(2\pi\vec j\cdot \xi)
    \frac{(\vec{i}^\perp\cdot\vec j)(\vec j^\perp\cdot\vec k^\perp)}{|\vec i|_2||\vec k|_2|\vec j|^2_2}d\xi \\
    &= \frac{(\vec{i}^\perp\cdot\vec j)(\vec j^\perp\cdot\vec k^\perp)}{|\vec i|_2||\vec k|_2|\vec j|^2_2}
    \int_\Omega \sin(2\pi\vec k\cdot \xi) \sin(2\pi\vec i\cdot \xi) \cos(2\pi\vec j\cdot \xi) d\xi \\
    &= \frac14 \frac{(\vec{i}^\perp\cdot\vec j)(\vec j^\perp\cdot\vec k^\perp)}{|\vec i|_2||\vec k|_2|\vec j|^2_2}
    \left( \delta_{\vec k-\vec i+\vec j,0} + \delta_{\vec k-\vec i- \vec j,0} - \delta_{\vec k+\vec i+\vec j,0} - \delta_{\vec k+ \vec i- \vec j,0} \right) \\
    &= \frac14 \frac{(\vec{i}^\perp\cdot\vec s)(\vec s^\perp\cdot\vec k^\perp)}{|\vec i|_2||\vec k|_2|\vec s|^2_2}
    \left( \delta_{\vec k,\vec i+\vec s} + \delta_{\vec k,\vec i- \vec s} - \delta_{\vec k, \vec s- \vec i} \right) 
    %\frac{(\vec{i}^\perp\cdot\vec s)(\vec s^\perp\cdot\vec k^\perp)}{|\vec i|_2||\vec k|_2|\vec s|^2_2}     I_{i,s}^k    
    %\frac{(\vec{i}^\perp\cdot\vec s)(\vec s^\perp\cdot\vec k^\perp)}{|\vec i|_2||\vec k|_2|\vec s|^2_2}     I_{i,s}^k \\    
\end{align} where the last expression is obtained since multi-indices $\vec k,\vec i,\vec j$ are taken such that either $\vec k_1+\vec i_1+\vec j_1 > 0$ or $\vec k_1=0, \vec k_2>0, \vec i_1=0, \vec i_2>0, \vec j_1 =0, \vec j_2 > 0$  resulting in $\delta_{\vec k+\vec i+\vec j,0}\equiv0$ and so 
% \begin{align}
%     C_{\mm,\nn} &= \sum_{k=1}^N \int_{\RR^N}  (b_k(x) \partial_{x_k}\HH_\nn)\HH_\mm \mu(dx) \\
%     &= \sum_{k,i,j=1}^N b(e_i,e_k,e_j) \int_{\RR^N} x_ix_j \partial_{x_k}\HH_\nn \HH_\mm \mu(dx)\\
%     &=\sum_{k,i,j=1}^N 2(2\lambda_k)^{\frac12} 
%     \int_{\RR^N} \sqrt{n_k 2\lambda_k/q}\sqrt{q/(2\lambda_i)}\sqrt{q/(2\lambda_j)}\HH_{1_i} \HH_{1_j} \HH_\nn \HH_\mm \mu(dx)
% \end{align}
\begin{align}
    C_{\mm,\nn} &= \sum_{k=1}^N \int_{\RR^N}  (b_k(x) \partial_{x_k}\HH_\nn)\HH_\mm \mu(dx) \\
    &= -\sum_{\substack{k,i,j\ge 1\\i\ne k,j\notin\{k,i\}}}^N b(e_i,e_j,e_k) \int_{\RR^N} x_ix_j \partial_{x_k}\HH_\nn \HH_\mm \mu(dx)\\
    &= -\sum_{\substack{k,i,j\ge 1\\i\ne k,j\notin\{k,i\}}}^N 2(2\lambda_j)^{\frac12} B_{i,j}^k
    \int_{\RR^N} \sqrt{\nn_k 2\lambda_k/q}\sqrt{q/(2\lambda_i)}\sqrt{q/(2\lambda_j)}\HH_{1_i} \HH_{1_j} \HH_{\nn-1_k} \HH_\mm \mu(dx) \\
    &= -\sum_{\substack{k,i,j\ge 1\\i\ne k,j\notin\{k,i\}}}^N 2B_{i,j}^k (\nn_k \lambda_k/\lambda_i q)^\frac{1}{2}
    \int_{\RR^N} \HH_{1_i} \HH_{1_j} \HH_{\nn-1_k} \HH_\mm \mu(dx)
\end{align}

% {$C_{mn}$ for Navier--Stokes equations}
% We will adhere to the following notations: indeces $k$, $i$ and $s$ are scalar integers, $\Phi$ is a set of 2D multi-indeces corresponding to each eigen-function such that $\vec k:=\Phi_k$, $\vec i:=\Phi_i$, $\vec s:=\Phi_s$ and consequently $\gamma_i=\gamma_{\vec i}$, $\lambda_i=\lambda_{\vec i}$, $\rho_i=\rho_{\vec i}$. We stress however that generally $\Phi_{i+s} \neq \Phi_i + \Phi_s$ or in other words if $\vec k = \vec i + \vec s$ it does not imply $k=i+s$.

Notice that for $i\neq j$, $k \notin {i,j}$:
\begin{align}
    (\HH_{1_i} \HH_{1_j}, \HH_{\nn-1_k} \HH_\mm )_\mu 
    &= ((1+\nn_i)^{\frac12}\HH_{1_j}\HH_{\nn-1_k+1_i}+\nn_i^{\frac12}\HH_{1_j}\HH_{\nn-1_k-1_i}, \HH_\mm)_\mu\\
    &=(1+\nn_i)^{\frac12}(1+\nn_j)^{\frac12} (\HH_{\nn-1_k+1_i+1_j}, \HH_\mm)_\mu \\
    &+(1+\nn_i)^{\frac12}\nn_j^{\frac12} (\HH_{\nn-1_k+1_i-1_j}, \HH_\mm)_\mu\\
    &+\nn_i^{\frac12}(1+\nn_j)^{\frac12} (\HH_{\gamma-1_k-1_i+1_j}, \HH_\mm)_\mu \\
    &+\nn_i^{\frac12} \nn_j^{\frac12} (\HH_{\nn-1_k-1_i-1_j}, \HH_\mm)_\mu\\
    &=(1+\nn_i)^{\frac12}(1+\nn_j)^{\frac12}\delta_{\nn-1_k+1_i+1_j,\mm}
    +(1+\nn_i)^{\frac12}\nn_j^{\frac12}\delta_{\nn-1_k+1_i-1_j,\mm}\\
    &+\nn_i^{\frac12}(1+\nn_j)^{\frac12} \delta_{\nn-1_k-1_i+1_j,\mm}
    +\nn_i^{\frac12}\nn_j^{\frac12} \delta_{\nn-1_k-1_i-1_j,\mm}
\end{align}

Then

\begin{align}
    C_{\mm,\nn} = -\frac 12 \sum_{\substack{k,i,j\ge 1\\i\ne k,j\notin\{k,i\}}}^N
    \left(\nn_k q \frac{\lambda_k}{\lambda_i} \right)^\frac{1}{2}
    \frac{(\vec{i}^\perp\cdot\vec j)(\vec j\cdot \vec k)}{|\vec i|_2||\vec k|_2|\vec j|^2_2} 
    \bigl( &\delta_{\vec k,\vec i+\vec j} + \delta_{\vec k,\vec i-\vec j} -\delta_{\vec k,\vec j-\vec i} \bigr) \\
    \biggl(
    (1+\nn_i)^{\frac12}(1+\nn_j)^{\frac12}&\delta_{\nn-1_k+1_i+1_j,\mm}\\
    +(1+\nn_i)^{\frac12}\nn_j^{\frac12} &\delta_{\nn-1_k+1_i-1_j,\mm}\\
    +\nn_i^{\frac12}(1+\nn_j)^{\frac12} &\delta_{\nn-1_k-1_i+1_j,\mm}\\
    +\nn_i^{\frac12}\nn_j^{\frac12} &\delta_{\nn-1_k-1_i-1_j,\mm}
    \biggr)
\end{align}

Finally we notice that the sum of coefficient in front of $\delta_{\nn-1_k-1_i-1_j,\mm}$ should equals to zero since the matrix $C_{\mm,\nn}$ is skew-symmetric. Accounting for that we obtain the final representation:
\begin{align} \label{eq:c_mn_final}
    C_{\mm,\nn} = -\frac 12 \sum_{\substack{k,i,j\ge 1\\i\ne k,j\notin\{k,i\}}}^N
    \left(\nn_k q \frac{\lambda_k}{\lambda_i} \right)^\frac{1}{2}
    \frac{(\vec{i}^\perp\cdot\vec j)(\vec j\cdot \vec k)}{|\vec i|_2||\vec k|_2|\vec j|^2_2} 
    \bigl( &\delta_{\vec k,\vec i+\vec j} + \delta_{\vec k,\vec i-\vec j} - \delta_{\vec k,\vec j-\vec i} \bigr)\\
    \biggl(
    (1+\nn_i)^{\frac12}(1+\nn_j)^{\frac12}&\delta_{\nn-1_k+1_i+1_j,\mm}\\
    +(1+\nn_i)^{\frac12}\nn_j^{\frac12} &\delta_{\nn-1_k+1_i-1_j,\mm}\\
    +\nn_i^{\frac12}(1+\nn_j)^{\frac12} &\delta_{\nn-1_k-1_i+1_j,\mm}
    \biggr)
\end{align}

