\section{Unbounded norm of Dirac Delta}\label{sec:dirac}
We believe that adding noise to the initial state $x$ is essential for the readout state to be well defined. 
Indeed, suppose the  initial state $x$ is noiseless. As noted above Dirac delta concentrated at $x$ is formally associated with the readout state $|\psi_{out}(x)\ra = \sum_{\mm \in \calJ} \HH_\mm(x)|\mm\ra$.
 We claim that this state has an infinite norm. For example, suppose $x$ is the all-zero vector, $x=0^N$.
By definition, $\HH_\mm(0^N)=\prod_{i=1}^N (1/\sqrt{m_i!}) \herm_{m_i}(0)$. 
Using the identity $\herm_n(0)=(-1)^{n/2} (n-1)!!$ for even $n$ and $\herm_n(0)=0$ for odd $n$ one gets
\be
\frac1{n!} \herm_n(0)^2  = \frac{(n-1)!!}{n!!}  \sim 1/\sqrt{n}.
\ee
Thus the sum  $\sum_{\mm\in \calJ} \HH_\mm(0^N)^2\sim\left( \sum_{n=0}^\infty 1/\sqrt{n}\right)^N$ diverges and the state $|\psi_{out}(x)\ra = \sum_{\mm \in \calJ} \HH_\mm(x)|\mm\ra$
has an infinite norm. 
Using  Mehler's formula one can check that the sum $\sum_{\mm\in \calJ} \HH_\mm(x)^2$ diverges for any $x\in \RR^N$.



\section{Hermite polynomial identities and proof of Lemma~\ref{l:AB-HermiteBasis}}
\label{sec:appB}

Let us first collect several identities that will be used in the proofs and establish some properties of the operators $\calA$ and $\calB$ from the Kolmogorov equation. We have
\[
\frac{d}{dx} \herm_n(x) = n \herm_{n-1}(x)
\quad \mbox{and} \quad
x \herm_n(x) =  \herm_{n+1}(x) + n  \herm_{n-1}(x).
\]
As a consequence,
\be
\label{rec1}
\frac{\partial}{\partial x_i} \HH_{\mm}(x) =(2m_i \lambda_i/q)^{1/2}\, \HH_{\mm-e^i}(x).
\ee
and
\be
\label{rec2}
x_i \HH_{\mm}(x)  = (m_i+1)^{1/2} (2\lambda_i/q)^{-1/2} \, \HH_{\mm+e^i}(x)  + m_i^{1/2}(2\lambda_i/q)^{-1/2} \,  \HH_{\mm-e^i}(x).
\ee
Here $e^i=(0,\ldots,0,1,0,\ldots,0)$ is a multi-index with a single '1'  at the position $i$.
The  umbral identity for  single-variate Hermite polynomials reads as 
\be
\label{umbral_eq1}
\herm_n(x+y) = \sum_{k=0}^n {n \choose k} x^{n-k} \herm_k(y)
\ee
for any $x,y\in \RR$.
This identity will be crucial in analyzing the readout step of our quantum algorithm.
We are now ready to prove 
Lemma~\ref{l:AB-HermiteBasis} restated below.
\begin{lemma*}
   $\calA$ is a diagonal operator in the basis of Hermite polynomials: 
   \be
\label{eigenvectors_of_L}
\calA\,  \mathbb{H}_{\multi{m}}(x) = \lambda_{\multi{m}}  \mathbb{H}_{\multi{m}}(x) 
\ee
for any multi-index $\mm\in\calJ$, 
where
\be
\label{lambda_m}
\lambda_{\multi{m}}  = \sum_{i=1}^N m_i \lambda_i.
\ee
Operator $\calB$
preserves the order of Hermite polynomials: 
\be
\label{KolmogorovL2explicit}
\calB\, \HH_\mm(x) =\sum_{i,j=1}^N \beta_{i,j} (m_i (m_j+1))^{1/2} \, \HH_{\mm - e^i + e^j}(x).
\ee 
where $\beta_{i,j} = b_{i,j}\lambda_j^{-1/2} \lambda_i^{1/2}$
and $e^i\in \calJ$ is a multi-index with $e^i_i=1$ and $e^i_j=0$ for all $j\ne i$. 
\end{lemma*}
\begin{proof}
    From Eq.~(\ref{Hermite_equation}) one gets
\be
\label{Hermite_equation_multivariate}
\left[ \frac{q}2  \frac{\partial^2}{\partial x_i^2} -\lambda_i x_i \frac{\partial}{\partial x_i} 
 \right] \HH_\mm(x) = -\lambda_i m_i \HH_\mm(x) 
\ee
for all $i$. 
The identity Eq.~(\ref{Hermite_equation_multivariate}) implies~Eq.~(\ref{eigenvectors_of_L})
hence $\calA$ is indeed diagonal in the basis of Hermite polynomials.

Next consider the operator $\calB$.
Using the identities Eq.~(\ref{rec1},\ref{rec2}) one gets
\be
\calB\, \HH_\mm(x) = \sum_{i,j=1}^N \beta_{i,j} \left[ (m_i (m_j+1))^{1/2} \, \HH_{\mm - e^i + e^j}(x) + (m_i m_j)^{1/2}  \, \HH_{\mm - e^i - e^j}(x)\right].
\ee
The last term drops out  since the divergence-free condition $\lambda_i b_{i,j} = -\lambda_j b_{j,i}$ implies
that the matrix 
$\beta$
 is skew-symmetric. Thus we get Eq.~(\ref{KolmogorovL2explicit})   
which implies that $\calB$
preserves the order of Hermite polynomials, that is, $\calB\, \HH_\mm(x)$ is a linear combination of Hermite polynomials of the order $|\mm|$. 
\end{proof}

\section{Proof of Lemma~\ref{lemma:Cprops}}
\label{sec:appC}

\begin{lemma*}
Suppose the system of Eq.~(\ref{SDE}) is relatively bounded. Then $\calC$ is a bounded linear operator from $\calG\calS_1$ to $\calG\calS_0$, and it is unbounded if considered as a linear operator in $\calG\calS_0$ with domain $\calG\calS_1$. If $\sum_{i=1}^N c_i^2(x)\le J^2$ for some $J\in [0,\infty)$ and all $x\in \RR^N$ then the system is relatively bounded
and one can choose
\be
\label{gamma_from_J}
\gamma =J \sqrt{2/q}.
\ee
Suppose the system of Eq.~(\ref{SDE}) is divergence-free.
Then the  operator $\calC$ is skew-hermitian, $\calC^\dag = -\calC$. 
\end{lemma*}

% \begin{lemma}
% Suppose 
% $\sum_{i=1}^N c_i^2(x)\le J^2$ for  some $J\in [0,\infty)$ and all $x\in \RR^N$. Then the system is relatively bounded
% and one can choose
% \be
% \gamma =J \sqrt{2/q}.
% \ee
% \end{lemma}
\begin{proof}
Let us prove the 1st statement. Suppose $g\in \calG\calS_1$. By definition, this means $(g,\calA g)_\mu<\infty$.
Combining this and Eq.~(\ref{gamma_definition}) one gets $|(h,\calC g)_\mu|<\infty$ for all $h\in \calG\calS_0$.
This is equivalent to $\calC g\in \calG\calS_0$.

Let us prove the 2nd statement (it is analogous to Proposition 5.4 of~\cite{delgado2016spectral}): By Cauchy-Schwartz inequality,
\begin{align}
(h,\calC g)_\mu^2  & = \left( \sum_{i=1}^N \int_{\RR^N} dx\, \mu(x) h(x) c_i(x) \partial g(x)/\partial x_i\right)^2 \nonumber \\
& \le \left(\sum_{i=1}^N \int_{\RR^N} dx\, \mu(x) h^2(x) c_i^2(x) \right) \left( \sum_{i=1}^N \int_{\RR^N} dx\, \mu(x) (\partial g(x)/\partial x_i)^2\right)
\end{align}
The first factor is upper bounded by $J^2 (h,h)_\mu$.
From Eq.~(\ref{1norm_eq1}) one infers that the second factor equals $2q^{-1} (g,\calA  g)_\mu$.

To prove the last statement, let $f(x)\equiv \HH_{\multi{n}}(x)$ and $g(x)\equiv \HH_{\multi{m}}(x)$.
It suffices  to check that 
\be
\label{skew_symmetric_eq1}
\int_{\RR^N} dx \, \mu(x) f(x) \calC g(x) = - \int_{\RR^N} dx \, \mu(x) g(x)  \calC f(x).
\ee
Substituting $\calC=\sum_{i=1}^N c_i(x) \partial/\partial x_i$ and 
integrating by parts gives
\be
\label{skew_symmetric_eq2}
\int_{\RR^N} dx \, \mu(x) f(x) \calC g(x) =-\int_{\RR^N} dx\, g(x)\sum_{i=1}^N   \frac{\partial}{\partial x_i}\left( c_i(x) \mu(x) f(x)\right).
\ee
Here we noted  that $g(x)  c_i(x)\mu(x) f(x)$ vanishes in the limit $x_i\to \pm \infty$ for any index $i$
due to the exponential  factor $e^{- \lambda_i x_i^2/q}$ in $\mu(x)$.
We have
\[
 \frac{\partial}{\partial x_i}\left( c_i(x) \mu(x) f(x)\right) = 
 \mu(x)f(x) \frac{\partial}{\partial x_i}c_i(x)
 - 2q^{-1} \lambda_i x_i c_i(x) \mu(x) f(x) + c_i(x) \mu(x) \frac{\partial}{\partial x_i} f(x).
\]
Taking the sum  over $i$ and using divergence-free conditions Eqs.~(\ref{NDE1},\ref{NDE2})
gives
\[
\sum_{i=1}^N 
 \frac{\partial}{\partial x_i}\left( c_i(x) \mu(x) f(x)\right) =  \sum_{i=1}^N c_i(x) \mu(x) \frac{\partial}{\partial x_i} f(x).
\]
Substituting this into Eq.~(\ref{skew_symmetric_eq2}) proves Eq.~(\ref{skew_symmetric_eq1}). Thus $\calC$ is a skew-hermitian operator, as promised.
\end{proof}

\section{Proof of Theorems~\ref{thm:regul} and \ref{t:existence}}
\label{sec:appD}

We begin with Theorem~\ref{thm:regul} restated below.
\begin{theorem*}
Let $\phi(\cdot)$ denote the unique solution of~\eqref{regul_eq1} and assume that $\psi(\cdot)$ is the unique differentiable solution of Eq.~(\ref{Kolmogorov5}). Then Eq.~(\ref{Kolmogorov5}) is equivalent to 
\be
\label{regul_eq2}
\frac{d}{dt} |\psi(t)\ra = (-\Lambda + C)|\psi(t)\ra
\ee
and for all $t\ge 0$ one has
\be
\label{regul_error}
\| \psi(t) - \phi(t) \|^2 \le \frac{3\gamma^2}{2r} \|\psi(0)\|^2.
\ee
\end{theorem*}
\begin{proof}
 Define the error state
\be
|e(t)\ra = |\psi(t)\ra - |\phi(t)\ra.
\ee
Let
\be
|\psi_i(t)\ra = \Pi_i |\psi(t)\ra \quad \quad \mbox{and} \quad
|e_i(t)\ra = \Pi_i |e(t)\ra.
\ee
Here $i=1,2$.
From Eqs.~(\ref{regul_eq1},\ref{regul_eq2}) one gets
\begin{align}
\frac{d}{dt}|e_1(t)\ra &= -\Lambda |e_1(t)\ra + C_{11} |e_1(t)\ra  + C_{12} |\psi_2(t)\ra, \label{regul_eq3} \\
\frac{d}{dt}|e_2(t)\ra &= -\Lambda |e_2(t)\ra + C_{22} |\psi_2(t)\ra  + C_{21} |\psi_1(t)\ra.\label{regul_eq4}
\end{align}
Here we noted that $\Pi_1 \Lambda\Pi_2=0$ and $\Pi_2 \Lambda\Pi_1=0$ 
since $\Lambda=A-B$, where $A$ is diagonal and $B$ is block-diagonal 
due to condition (4).

Let us first upper bound the norm of $e_1(t)$.
Multiplying Eq.~(\ref{regul_eq3}) one the left by $\la e_1(t)|$ one gets
\be
\frac12 \frac{d}{dt} \la e_1(t)|e_1(t)\ra = - \la e_1(t)|\Lambda|e_1(t)\ra + \la e_1(t) |C|e_1(t)\ra +  \la e_1(t) |C  |\psi_2(t)\ra.
\ee
We have $\la e_1(t)|\Lambda|e_1(t)\ra=\la e_1(t)|A|e_1(t)\ra$ since $B$ is skew-hermitian.
We have $ \la e_1(t) |C|e_1(t)\ra=0$ and $\la e_1(t) |C  |\psi_2(t)\ra = - \la \psi_2(t) |C |e_1(t)\ra$ since $C$ is skew-hermitian.
Thus
\be
\label{regul_eq10}
\frac12 \frac{d}{dt} \la e_1(t)|e_1(t)\ra  =- \la e_1(t)|A|e_1(t)\ra -  \la \psi_2(t) |C |e_1(t)\ra.
\ee
Applying the relative boundness property Eq.~(\ref{gamma_eq1}) gives
\be
\label{regul_eq11}
 | \la \psi_2(t) |C |e_1(t)\ra|
\le   \gamma \sqrt{ \la \psi_2(t)|\psi_2(t)\ra \cdot \la e_1(t)|A|e_1(t)\ra}.
\ee
AM–GM inequality gives $\sqrt{ab}\le (\gamma a+\gamma^{-1} b)/2$ for any $a,b\ge 0$. Thus
\be
\label{regul_eq12}
\sqrt{ \la \psi_2(t)|\psi_2(t)\ra \cdot \la e_1(t)|A|e_1(t)\ra}
 \le \frac{\gamma}{2}  \la \psi_2(t)|\psi_2(t)\ra +  \frac{1}{2\gamma }  \la e_1(t)|A|e_1(t)\ra
\ee
Combining Eqs.~(\ref{regul_eq10},\ref{regul_eq11},\ref{regul_eq12}) gives
\be
 \frac{d}{dt} \la e_1(t)|e_1(t)\ra \le -  \la e_1(t)|A|e_1(t)\ra +  \gamma^2 \la \psi_2(t)|\psi_2(t)\ra.
\ee
Recall that all eigenvalues of $A$ are at least $\lambda_1$.  Thus $\la e_1(t)|A|e_1(t)\ra\ge \lambda_1 \la e_1(t)|e_1(t)\ra$
and
\be
 \frac{d}{dt} \la e_1(t)|e_1(t)\ra \le -\lambda_1  \la e_1(t)|e_1(t)\ra + \gamma^2  \la \psi_2(t)|\psi_2(t)\ra.
\ee
By Gronwall lemma,
\be
\label{regul_eq18}
 \la e_1(t)|e_1(t)\ra \le e^{-\lambda_1t} \la e_1(0)|e_1(0)\ra  +  \gamma^2 
 \int_0^t ds\, e^{-\lambda_1(t-s) } \la \psi_2(s)|\psi_2(s)\ra.
\ee
By definition, the regularized KE has the same initial condition as the bare KE.
Hence $e_1(t)=0$ and we arrive at
\be
\label{regul_eq19}
 \la e_1(t)|e_1(t)\ra \le \gamma^2
 \int_0^t ds\, \la \psi_2(s)|\psi_2(s)\ra.
\ee
Here we noted that $e^{-\lambda_1 (t-s) } \le 1$.

Recall that $A=\sum_{\mm\in \calJ} \lambda_\mm |\mm\ra\la \mm|$.
Since $\lambda_\mm \ge r$ for all $\mm\in \calJ_2$ and $\Pi_2=\sum_{\mm\in \calJ_2} |\mm\ra\la \mm|$,
the operator $A-r\Pi_2$ is positive semidefinite and we have
$\la \psi(s) |r\Pi_2|\psi(s)\ra \le \la \psi(s)|A|\psi(s)\ra$ for all $s$. As a consequence,
\be
\label{regul_eq20}
\la \psi_2(s) |\psi_2(s)\ra = \la \psi(s) |\Pi_2 |\psi(s)\ra = \frac1r \la \psi(s) |r \Pi_2 |\psi(s)\ra\le \frac1r \la \psi(s)|A|\psi(s)\ra.
\ee
The identity Eq.~(\ref{norm_derivative}) gives
\be
2\int_0^t ds\,  \la \psi(s)|A|\psi(s)\ra = \la \psi(0)|\psi(0)\ra - \la \psi(t)|\psi(t)\ra \le \la \psi(0)|\psi(0)\ra.
\ee
Combining  this and Eq.~(\ref{regul_eq20}) gives
\be
\int_0^t ds\,  \la \psi_2(s)|\psi_2(s)\ra \le \frac1{2r} \la \psi(0)|\psi(0)\ra.
\ee
Substituting this into Eq.~(\ref{regul_eq19})  one gets
\be
\label{regul_eq21}
 \la e_1(t)|e_1(t)\ra \le  \frac{\gamma^2}{2r } \la \psi(0)|\psi(0)\ra.
\ee
We can apply the same arguments to upper bound the norm of $e_2(t)$. 
Multiplying Eq.~(\ref{regul_eq4}) on the left by $\la e_2(t)|$ gives
\be
\label{regul_eq21+}
\frac12 
\frac{d}{dt} \la e_2(t)|e_2(t)\ra = -\la e_2(t)|\Lambda |e_2(t)\ra + \la e_2(t)| C |\psi(t)\ra
=-\la e_2(t)|A |e_2(t)\ra - \la\psi(t)|C|e_2(t)\ra.
\ee
Applying the relative boundness condition Eq.~(\ref{gamma_eq1}) and AM-GM inequality one gets
\be
\label{regul_eq21++}
| \la\psi(t)|C|e_2(t)\ra|  \le \gamma \sqrt{\la \psi(t)|\psi(t) \ra \cdot \la e_2(t)|A|e_2(t)\ra} 
\le \frac{\gamma^2}{2} \la \psi(t)|\psi(t)\ra + \frac{1}{2}  \la e_2(t)|A|e_2(t)\ra.
\ee
This gives
\be
\frac{d}{dt} \la e_2(t)|e_2(t)\ra  \le - \la e_2(t) | A  |e_2(t)\ra + \gamma^2 \la \psi(t)|\psi(t)\ra.
\ee
We can replace $A$ here by $\Pi_2 A\Pi_2$ since $\Pi_2 |e_2(t)\ra = |e_2(t)\ra$.
Recall that $\lambda_\mm \ge r$ for all $\mm \in \calJ_2$.
Thus all eigenvalues of $\Pi_2 A\Pi_2$ are at least $r$. Hence
$ \la e_2(t) | A  |e_2(t)\ra \ge r\la e_2(t)|e_2(t)\ra$ and we get
\be
\frac{d}{dt} \la e_2(t)|e_2(t)\ra  \le -r \la e_2(t) | e_2(t)\ra + \gamma^2 \la \psi(t)|\psi(t)\ra.
\ee
Recalling that $e_2(0)=0$ and using  Gronwall lemma gives
\be
\la e_2(t)|e_2(t)\ra \le \gamma^2  \int_0^t ds \, e^{-r(t-s)} \la \psi(s)|\psi(s)\ra.
\ee
We have already established that $\la \psi(s)|\psi(s)\ra\le \la \psi(0)|\psi(0)\ra$. Thus
\be
\la e_2(t)|e_2(t)\ra \le \gamma^2  \la \psi(0)|\psi(0)\ra \int_0^\infty ds \, e^{-rs}
=  \frac{\gamma^2}{r} \la \psi(0)|\psi(0)\ra.
\ee
Combining this and Eq.~(\ref{regul_eq21}) completes the proof of the theorem.
\end{proof}

To prove Theorem~\ref{t:existence} we shall use a certain property of the semigroup generated by $-\Lambda$ stated in the following lemma.
\begin{lemma}
\label{lemma:exp}
Let $\kappa=\lambda_N/\lambda_1$. For any state $|\eta\ra \in \mathsf{GS}_0$  and for any $t>0$ one has
\be
\label{exp_norm2}
\| A^{1/2}  e^{-t \Lambda}|\eta\ra \| \le  \frac12 (\kappa/t)^{1/2}  \| \eta\|,
\ee
\be
\label{exp_norm3}
\| C e^{-t \Lambda}|\eta\ra \| \le
\frac12 \gamma  (\kappa/t)^{1/2}
\| \eta\|,
\ee
\be
\label{exp_norm4}
\| e^{-t\Lambda}C|\eta\ra \| \le \frac12 \gamma  (\kappa/t)^{1/2}
\| \eta\|.
\ee
The same bounds hold if $\Lambda$ is replaced with $\Lambda^\dag$.
The following linear operator 
\begin{equation}
\label{eq:VltrOp}
    \psi(t)\mapsto \int_0^t e^{-\Lambda (t-s)} C \psi(s) ds,\quad \psi\in  C(0,T,\mathsf{GS}_0)
\end{equation} is bounded in $C(0,T,\mathsf{GS}_0)$.
\end{lemma}
\begin{proof}
Recall that  the operators $A$ and $\Lambda=A-B$ preserve the particle number. 
Let $A_K$ and $B_K$ be the projections of $A$ and $B$ onto the $K$-particle subspace
(i.e. the subspace spanned by basis states $|\mm\ra$ with $|\mm|=K$).
Then it suffices to prove that 
\be
\| A_K^{1/2}  e^{-t (A_K-B_K)}  \| \le \frac12  (\kappa/t)^{1/2}
\ee
for all $K\ge 1$.
Note that $A_K$ is hermitian, its largest eigenvalue is at most $\lambda_N K$
and its smallest eigenvalue is at least $\lambda_1 K$.
Hence  $\| A_K^{1/2} \| \le (\lambda_N K)^{1/2}$
and $\| e^{-\tau A_K}\|\le e^{-\tau K \lambda_1}$ for any $\tau\ge 0$.
Recall that $B_K^\dag = -B_K$. Thus $e^{\tau B_K}$ is unitary for any $\tau \in\RR$
and $\|e^{\tau B_K}\|=1$.
Using the Trotter formula and the sub-multiplicativity of the norm gives
\be
\|  e^{-t (A_K-B_K)} \| = \left\| \lim_{m\to \infty} \left( e^{-t A_K/m} e^{t B_K/m}\right)^m \right\|
\le \lim_{m\to \infty} \| e^{-t A_K/m}\|^m 
\le e^{-t K \lambda_1}.
\ee
We arrive at
\be
\| A_K^{1/2}  e^{-t (A_K-B_K)}  \| \le
\|  A_K^{1/2} \| \cdot \| e^{-t (A_K-B_K)}  \| 
\le
 (\lambda_N K)^{1/2}  e^{-tK \lambda_1}
= (\lambda_N/ t \lambda_1)^{1/2} x^{1/2} e^{-x}
\ee
with $x= tK \lambda_1$. However, $x^{1/2} e^{-x}\le 1/2$ for all $x\ge 0$, proving Eq.~(\ref{exp_norm2}).
Exactly the same proof applies if $\Lambda$ is replaced by $\Lambda^\dag$.

To prove Eq.~(\ref{exp_norm3}) use the relative boundness condition Eq.~(\ref{gamma_eq1}).
It is equivalent to $\| C \phi\| \le \gamma \| A^{1/2} \phi\|$ for any $\phi \in \mathsf{GS}_1$.
Choosing $|\phi\ra =  e^{-t \Lambda}|\eta\ra$ and using Eq.~(\ref{exp_norm2}) proves
 Eq.~(\ref{exp_norm3}).  

Let us prove Eq.~(\ref{exp_norm4}). First assume that $\eta\in\calG\calS_1$. We have
\be
\label{expCeq1}
\| e^{-t\Lambda}C|\eta\ra \|  = \sup_{\psi\in \mathsf{GS}_0} \frac1{\|\psi\|} \la \psi | e^{-t\Lambda} C |\eta\ra,
\ee
where the supremum is over nonzero states.  For any fixed $\psi$ one has
\be
 \la \psi | e^{-t\Lambda} C |\eta\ra = -\la \eta| C e^{-t\Lambda^\dag} |\psi\ra
\ee
since $C$ is skew-hermitian. Cauchy-Schwartz inequality and the relative boundness condition give
\be
|\la \eta| C e^{-t\Lambda^\dag} |\psi\ra| \le \| \eta \| \cdot \| C  e^{-t\Lambda^\dag} \psi\| \le \gamma \| \eta\| \cdot \| A^{1/2} e^{-t\Lambda^\dag} \psi\|.
\ee
Applying Eq.~(\ref{exp_norm2}) with $\Lambda$ replaced by $\Lambda^\dag$ to bound  $ \| A^{1/2} e^{-t\Lambda^\dag} \psi\|$ gives
\be
 \la \psi | e^{-t\Lambda} C |\eta\ra\le 
|\la \eta| C e^{-t\Lambda^\dag} |\psi\ra|  \le  \frac12 \gamma (\kappa/t)^{1/2} \|\psi\|\cdot \|\eta\|.
\ee
Substituting this into Eq.~(\ref{expCeq1}) proves Eq.~(\ref{exp_norm4}). The latter implies that operator $e^{-t \Lambda} C$ is a bounded linear operator in $\mathsf{GS}_0$ defined on $\mathsf{GS}_1\subset\mathsf{GS}_0$ with norm upper-bounded by $\frac12 \gamma  (\kappa/t)^{1/2}$ which diverges as $t$ approaches $0$: intuitively this means that operator $e^{-t \Lambda} C$ "approaches" an unbounded operator $C$. Now fix $t>0$ and let us extend $e^{-t \Lambda} C$ to the whole of $\mathsf{GS}_0$ without changing its norm. Since $\mathsf{GS}_1$ is everywhere dense in $\mathsf{GS}_0$ for any $|\eta\ra\in\mathsf{GS}_0$ there is a sequence of elements $|\eta_k\ra\in\mathsf{GS}_1$ such that $|\eta\ra=\lim_k|\eta_k\ra$. We have that
\[
\|e^{-t \Lambda} C |\eta_k\ra - e^{-t \Lambda} C |\eta_s\ra\|\le \frac12 \gamma  (\kappa/t)^{1/2} \||\eta_k\ra-|\eta_s\ra\|\to 0
\]
hence $\{e^{-t \Lambda} C |\eta_k\ra\}$ is a Cauchy sequence in $\mathsf{GS}_0$ and we can define:
\[
e^{-t \Lambda} C|\eta\ra \coloneqq \lim_k e^{-t \Lambda} C|\eta_k\ra
\]


Let us prove the last statement of the lemma. Recall from~\eqref{exp_norm4} that for any state $|\eta\ra \in \mathsf{GS}_0$ and for any $t>0$ one has $\| e^{-t \Lambda} C|\eta\ra \| \le
\frac12 \gamma  (\kappa/t)^{1/2}
\| \eta\|$. This implies that operator $e^{-t \Lambda} C$ is a bounded linear operator in $\mathsf{GS}_0$ with norm upperbounded by $\frac12 \gamma  (\kappa/t)^{1/2}$ which diverges as $t$ approaches $0$: intuitively this means that operator $e^{-t \Lambda} C$ "approaches" an unbounded operator $C$. We will show that this problem goes away for the operator defined by~\eqref{eq:VltrOp}. 

% Let fix $t>0$ and extend $e^{-t \Lambda} C$ to the whole of $\mathsf{GS}_0$ without changing its norm. Since $\mathsf{GS}_1$ is everywhere dense in $\mathsf{GS}_0$ for any $|\eta\ra\in\mathsf{GS}_0$ there is a sequence of elements $|\eta_k\ra\in\mathsf{GS}_1$ such that $|\eta\ra=\lim_k|\eta_k\ra$. We have that 
% \[
% \|e^{-t \Lambda} C |\eta_k\ra - e^{-t \Lambda} C |\eta_s\ra\|\le \frac12 \gamma  (\kappa/t)^{1/2} \||\eta_k\ra-|\eta_s\ra\|\to 0
% \]
% hence $\{e^{-t \Lambda} C |\eta_k\ra\}$ is a Cauchy sequence in $\mathsf{GS}_0$ and we can define: 
% \[
% e^{-t \Lambda} C|\eta\ra \coloneqq \lim_k e^{-t \Lambda} C|\eta_k\ra
% \]    
Now if $\psi(\cdot)=\lim_k \psi_k(\cdot)$ then \[
e^{-(t-s) \Lambda} C|\psi(s)\ra \coloneqq \lim_k e^{-(t-s) \Lambda} C|\psi_k(s)\ra,\quad \forall~ 0\le s< t
\] and \[
\|e^{-(t-s) \Lambda} C|\psi(s)\ra\|\le \frac12 \gamma  (\kappa/(t-s))^{1/2}\| \psi(s)\|
\]
so that for any $\varepsilon>0$ 
\begin{align}
    \|\int_0^{t-\varepsilon} &e^{-(t-s) \Lambda} C|\psi(s)\ra ds\|
\le \frac12 \gamma 
\int_0^{t-\varepsilon} (\kappa/(t-s))^{1/2}\| \psi(s)\| ds\\
&\le \frac12 \gamma \kappa \max_{s}\| \psi(s)\| \int_0^{t-\varepsilon} (1/(t-s))^{1/2} ds =  \gamma \kappa \max_{s}\| \psi(s)\| (t-\varepsilon)^{\frac12}
\end{align}
% \[
% \|\int_0^{t-\varepsilon} e^{-(t-s) \Lambda} C|\psi(s)\ra ds\|
% \le \frac12 \gamma 
% \int_0^{t-\varepsilon} (\kappa/(t-s))^{1/2}\| \psi(s)\| ds \le \frac12 \gamma \kappa \max_{s}\| \psi(s)\| \int_0^{t-\varepsilon} (1/(t-s))^{1/2} ds =  \gamma \kappa \max_{s}\| \psi(s)\| (t-\varepsilon)^{\frac12}
% \]
Hence we see that in fact 
\begin{equation}\label{eq:intC-up-bnd}
\|\int_0^{t} e^{-(t-s) \Lambda} C|\psi(s)\ra ds\| \le \gamma \kappa t^{\frac12}\, \max_{s}\| \psi(s)\| 
\end{equation} which demonstrates the very last claim. 
\end{proof}

Now we are ready to prove Theorem~\ref{t:existence}. 
\begin{proof}
    Consider any pair $k<\ell$. We can apply the proof of Theorem~\ref{thm:regul} where $|\psi(t)\ra$ and  $|\phi(t)\ra$ are replaced with $|\phi_\ell(t)\ra$ and $|\phi_k(t)\ra$ respectively, $C_{11}$ is replaced with $\Pi_k C \Pi_k$,
and $C$ is replaced with $\Pi_\ell C \Pi_\ell$. Thus
\be
\label{regul_eq30}
\forall t\ge0: \| \phi_k(t) - \phi_\ell(t) \|^2 \le \frac{3\gamma^2}{2r_k} \|\psi(0)\|^2
\ee
\eqref{regul_eq30} implies that the sequence of continuous functions $\{\phi_k(\cdot)\}_k$ is a Cauchy sequence in the space of continuous functions with values in $\mathsf{GS}_0$, $C(0,T,\mathsf{GS}_0)$,  and hence this sequence converges (in the norm of $C(0,T,\mathsf{GS}_0)$) to a function $|\psi(\cdot)\ra$: 
\be
\label{regul_eq31}
\lim_{k\to \infty} \max_{t\in[0,T]}\|\psi(t)\ra -|\phi_k(t)\ra\| = 0 
\ee
and more specifically \[
\max_{t\in[0,T]}
\| \psi(t) - \phi_k(t) \|^2 \le \frac{3\gamma^2}{2r_k} \|\psi(0)\|^2
\]
which demonstrates~\eqref{regul_eq32}.  
%Furthermore, it is clear that $\phi_k(t)$ is a continuous function of time for any finite $k$.
Since $C(0,T,\mathsf{GS}_0)$ is a complete metric space, $|\psi(\cdot)\ra$ -- the limit of Cauchy sequence of continuous functions $\{\phi_k(\cdot)\}_k$, belongs to $C(0,T,\mathsf{GS}_0)$. 

Let us prove that $\psi$ solves KE. Recall from~\eqref{eq:KEreg} that
\begin{equation}\label{regul_eq33}
\begin{split}
    |\phi_k(t)\ra &= e^{-t \Lambda } |\psi(0)\ra + \int_0^t ds \, e^{-(t-s)\Lambda} \Pi_1^k C \Pi_1^k  |\phi_k(s)\ra\\
    &=e^{-t \Lambda } |\psi(0)\ra + \int_0^t ds \,e^{-(t-s)\Lambda} C \Pi_1^k|\phi_k\ra \\
    &- \int_0^t ds \, e^{-(t-s)\Lambda}(I-\Pi_1^k)C\Pi_1^k|\phi_k\ra
    \end{split}
\end{equation}
Clearly for any $\phi\in\mathsf{GS}_0$ we have:
\[
  \|\Pi_1^k |\phi\ra\|^2=\sum_{|\mm|\le k} \la\mm|\phi\ra^2\le \| \phi\|^2,\quad
  \|(I-\Pi_1^k)|\phi\ra \|^2=\sum_{|\mm|> k} \la\mm|\phi\ra^2\to 0, k\to\infty
  \]
  hence $\||\psi(s)\ra-\Pi_1^k  |\phi_k(s)\ra\|\le \|\psi(s)-\Pi_1^k |\psi(s)\ra\|+\|\Pi_1^k\|  \||\psi(s)\ra - |\phi_k(s)\ra\|\to 0$ as $k\to\infty$. This and the fact that operator
  \begin{equation}
    \psi(t)\mapsto \int_0^t e^{-\Lambda (t-s)} C \psi(s) ds,\quad \psi\in  C(0,T,\mathsf{GS}_0)
\end{equation} is bounded (see Lemma~\ref{lemma:exp}) allow us to write: \[
\lim_k \int_0^t ds \, e^{-(t-s)\Lambda}  C \Pi_1^k|\phi_k\ra  =  \int_0^t ds \, e^{-(t-s)\Lambda}  C |\phi(s)\ra 
\]
Hence 
\begin{equation}
\begin{split}
    |\psi(t)\ra &= \lim_k|\phi_k(t)\ra = e^{-t \Lambda } |\psi(0)\ra + \int_0^t ds \, e^{-(t-s)\Lambda}  C |\psi(s)\ra\\ 
   &- \lim_k \int_0^t ds \, e^{-(t-s)\Lambda}(I-\Pi_1^k)C\Pi_1^k|\phi_k\ra
    \end{split}
\end{equation}
Hence to demonstrate the last claim we just need to prove that: \[
\lim_k \int_0^t ds \, e^{-(t-s)\Lambda}(I-\Pi_1^k)C\Pi_1^k|\phi_k\ra ds=0
\]
The latter can be demonstrated by noting that $e^{-(t-s)\Lambda}$ commutes with $\Pi_1^k$ so that $e^{-(t-s)\Lambda}(I-\Pi_1^k)C\Pi_1^k|\phi_k = (I-\Pi_1^k)\psi_k$ where $|\psi_k(s)\ra\coloneqq e^{-(t-s)\Lambda} C\Pi_1^k|\phi_k\ra\in\mathsf{GS}_0$ and hence 
%\[
% e^{-(t-s)\Lambda}(I-\Pi_1^k)C\Pi_1^k|\phi_k\ra = e^{-(t-s)\Lambda}(I-\Pi_1^k) e^{(t-s)\Lambda} |\psi_k(s)\ra =  (I-\Pi_1^k)|\psi_k(s)\ra
% \]
%since $e^{-(t-s)\Lambda}$ commutes with $\Pi_1^k$. 
\begin{align*}
    \|\int_0^t ds \, (I-\Pi_1^k)\psi_k(s)  \| &\le \|I-\Pi_1^k\| \|\int_0^t ds e^{-(t-s)\Lambda} C(\Pi_1^k\phi_k(s)-\psi(s))\|+ \|(I-\Pi_1^k)\int_0^t ds e^{-(t-s)\Lambda} C\psi(s)\|\\
&\overset{\text{by~\eqref{eq:intC-up-bnd}}}{\le}\gamma\kappa t^\frac12 \max_s \|\Pi_1^k\phi_k(s)-\psi(s)\|+\left(\sum_{|\mm|>k}\la\mm|\tilde \psi(t)\ra^2\right)^\frac{1}{2}\rightarrow 0, k\to\infty
\end{align*}
provided $\tilde \psi(t)=\int_0^t ds e^{-(t-s)\Lambda} C\psi(s)\in C(0,T,\mathsf{GS}_0)$.

Let us prove that $\|\psi(t)\|$ is bounded for any $t\ge0$ as required by Definition~\ref{dfn:solution}. Indeed, since $\psi_k$ is differentiable it also solves $\dfrac{d\psi_k}{dt}=(-\Lambda+\Pi_1^k C \Pi_1^k)  \phi_k$ and $\Pi_1^k C \Pi_1^k$ is skew-symmetric implying that $\dfrac{d}{dt}\la\psi_k|\psi_k\ra = -2\la\psi_k|\Lambda|\psi_k\ra$ so that \begin{equation}
    \label{eq:norm-bound}
    \la\psi_k(t)|\psi_k(t)\ra =\la\psi_k(0)|\psi_k(0)\ra - 2\int_0^t \la\psi_k|\Lambda|\psi_k\ra ds \le \la\psi_k(0)|\psi_k(0)\ra
\end{equation} 
Taking limits we get: $\la\psi(t)|\psi(t)\ra\le \la\psi(0)|\psi(0)\ra$. Note that the latter  implies that \[
\|e^{-t \Lambda } |\psi(0)\ra + \int_0^t ds \, e^{-(t-s)\Lambda}  C |\psi(s)\ra\|^2\le \|\psi(0)\|^2  
\] implying in turn that \[
\|\int_0^{+\infty} ds \, e^{-(t-s)\Lambda}  C |\psi(s)\ra\|^2\le \|\psi(0)\|^2 
\] hence \[
|\psi(t)\ra = e^{-t \Lambda } |\psi(0)\ra + \int_0^t ds \, e^{-(t-s)\Lambda}  C |\psi(s)\ra
\]
holds for any $t\ge0$. This completes the proof.  
\end{proof}

