	\begin{align}
		0 =&\, - \tfrac{\tau_1 \frac{G}{r} (\lambda_2+\lambda_3)}{V} (\tfrac{V_B(\alpha)}{V})^{\lambda_2+\lambda_3-1} V_B'(\alpha) - \rho (\lambda_2+\lambda_3+1) (\tfrac{V_B(\alpha)}{V})^{\lambda_2+\lambda_3} V_B'(\alpha) \notag \\
		&+ \tau_2 \int_0^\infty c_{do} (V,k,V_B(\alpha),t) \diff t + \alpha \tau_2 \int_0^\infty \tfrac{\partial c_{do} (V,k,V_B(\alpha),T)}{\partial \alpha} \diff t, \label{eq: solution alpha*}
	\end{align}
	where $\tfrac{\partial c_{do} (V,k,V_B(\alpha),T)}{\partial \alpha}$ is given in \eqref{eq: dalpha cdo<} resp. \eqref{eq: dalpha cdo>}. For an explicit formula of $V_B'(\alpha)$ see \eqref{eq: formula dvb dalpha}.
