\begin{lemma} \label{lemma: phi bounded}
	Let $a,y,x>0$, and $b \in \Real$. Then, the function $h(x):=\Phi(-a \ln(x)+b)x^{y}$ is continuous on $(0,\infty)$ and there exists a constant $C>0$ such that $|h(x)| \leq C$ for all $x \in (0,\infty)$. Furthermore, we have the following properties: $\lim_{x \to 0} |h(x)| = 0$ and $\limsup_{x \to \infty} |h(x)| \leq C$. Additionally, we consider the functions $\tilde{h}(x):=\frac{\Phi(-a \ln(x)+b)}{x^{y}}$ and $\hat{h}(x):=\frac{\Phi(a \ln(x)+b)}{x^{y}}$. For these functions, it holds that $\lim_{x \to \infty} |\tilde{h}(x)| = 0$ and $\lim_{x \to 0} |\hat{h}(x)| = 0$.
\end{lemma}

\begin{myproof}%[Proof of Lemma \ref{lemma: phi bounded}]
	First, note that $h$ is obviously continuous in $(0,\infty)$, and therefore bounded (by a possibly larger $C>0$) if there exists a $C>0$ such that $\lim_{x \to 0} |h(x)| \leq C$ and $\lim_{x \to \infty} |h(x)| \leq C$. Moreover, we observe that $h(\cdot)>0$, $\tilde{h}(\cdot)>0$, and $\hat{h}(\cdot)>0$ on $(0,\infty)$. Now, we obtain for a suitable $C>0$:
	\begin{align*}
		\lim_{x \to 0} |h(x)| &= \lim_{x \to 0} \Phi(-a \ln(x)+b) x^y = 0, \\
		\limsup_{x \to \infty} |h(x)| &= \limsup_{x \to \infty} \frac{\Phi(-a \ln(x)+b)}{x^{-y}} \\
		&\leq \limsup_{x \to \infty} \frac{\varphi(-a \ln(x)+b) \frac{-a}{x}}{-yx^{-y-1}} = \tfrac{a}{y} \limsup\limits_{x \to \infty} \dfrac{\varphi(-a \ln(x)+b)}{x^{-y}} \leq C,
	\end{align*}
	since $a,y>0$ and $\lim_{z \to -\infty} \Phi(z)=0$. Note that we used the generalized rule of de l'H{\^o}pital (see, e.g., Picone \cite{picone1929sul}) in the second step of the second limit and Lemma \ref{lemma: varphi bounded} in the last step. Thus, the first claim follows. For the second claim, we have:
	\begin{align*}
		\lim_{x \to \infty} |\tilde{h}(x)| &= \lim_{x \to \infty} \frac{\Phi(-a \ln(x)+b)}{x^{y}} = 0, \\
		\lim_{x \to 0} |\hat{h}(x)| &= \lim_{x \to 0} \frac{\Phi(a \ln(x)+b)}{x^{y}} = \lim_{x \to 0} \frac{\varphi(a \ln(x)+b) \tfrac{a}{x}}{yx^{y-1}} = \tfrac{a}{y} \displaystyle \lim_{x \to 0} \frac{\varphi(a \ln(x)+b)}{x^{y}} = 0,
	\end{align*}
	since $a,y>0$ and $|\Phi(\cdot)| \leq1$. Note that we used again the rule of de l'H{\^o}pital in the second step of the second limit, and Lemma \ref{lemma: varphi bounded} in the last step. Thus, the second claim follows.
\end{myproof}

\begin{lemma} \label{lemma: cdo bounded L1}
	For all $k \geq 0$, $V_B \geq 0$, and $T>0$, there exists a constant $C>0$ such that $|\frac{\partial}{\partial V} c_{do} (V,k,V_B,T)| \leq C (e^{-\nu T} + e^{-rT})$ for all $V \geq V_B$.
\end{lemma}

\begin{myproof}%[Proof of Lemma \ref{lemma: cdo bounded L1}]
	For this proof, we need to consider two cases: when $V_B=0$ and when $V_B>0$. Let us start with $V_B=0$. Then, the Down-and-Out Call option becomes a classical Call option as $V_t>0$ for all $t \geq 0$ by the non-negativity of Geometric Brownian Motions, i.e., $c_{do}^{V_B \leq k} (V,k,V_B,T) = c(V,k,T)$. Then, the result follows analogously to the proof of Lemma \ref{lemma: cdo c1}:
	\begin{align*}
		\tfrac{\partial}{\partial V} c(V,k,T) =&\, e^{-\nu T} \Phi(d_1(\tfrac{V}{k},T))+ \frac{e^{-\nu T} \varphi(d_1(\frac{V}{k},T))}{\sigma \sqrt{T}} - \frac{ke^{-rT} \varphi(d_2(\frac{V}{k},T))}{\sigma \sqrt{T} V}.
	\end{align*} 
	Thus, Lemma \ref{lemma: varphi bounded} and $|\Phi(\cdot)| \leq 1$ immediately provide the desired result.

	Now, consider the case when $V_B>0$. From equations \eqref{eq: derivative cdo vb<k} and \eqref{eq: derivative cdo vb>k}, we can conclude that the claim will hold if we show that each individual term in equations \eqref{eq: derivative cdo vb<k} and \eqref{eq: derivative cdo vb>k} is bounded by $C(e^{-\nu T} + e^{-rT})$ for some constant $C>0$, both as $V \to V_B$ and as $V \to +\infty$. Once we establish this, it follows that $|\frac{\partial}{\partial V} c_{do} (V,k,V_B,T)| \leq C (e^{-\nu T} + e^{-rT})$, where $C>0$ may be larger, but still finite. For the case $V \to V_B >0$, the result holds immediately. For $V \to + \infty$, each individual term is bounded by $C(e^{-\nu T} + e^{-rT})$, with $C>0$, due to the fact that $|\Phi(\cdot)|\leq 1$, Lemma \ref{lemma: varphi bounded}, or Lemma \ref{lemma: phi bounded} since $\ln(\tfrac{V_B^2}{Vk}) = 2\ln(V_B)-\ln(V)-\ln(k)$ (resp. $\ln(\tfrac{V_B}{V}) = \ln(V_B)-\ln(V)$). 
	%The argumentation for the limit of $V \to 0$ is similar if $\lambda_1\leq0$ (resp. $2\lambda_1-1\leq0$). If $\lambda_1>0$ (resp. $2\lambda_1-1>0$), we need another argumentation for the boundedness of the fourth (resp. sixth) term of \eqref{eq: derivative cdo vb<k} and \eqref{eq: derivative cdo vb>k}. In this case, we get for the fourth term that $|\tfrac{V_B}{V}|^{2\lambda_1} \leq 1$ due to $V \geq V_B$ since otherwise the Down-and-Out Call option has a price and payoff of $0$ (which also transfers to the derivative). Thus, we get the boundedness of this term due to $|\Phi(\cdot)|\leq 1$. For the sixth term in this case, we need a case distinction if $k=0$ or $k>0$. If $k=0$ the term is already $0$ and there is nothing to prove, thus we can assume that $k>0$. Now, using again that $V \geq V_B$, it remains to check the formula for \eqref{eq: derivative cdo vb<k}, i.e., $V_B\leq k$, for $V_B \leq V \to 0$. Again, we then use that $|\tfrac{V_B}{V}|^{2\lambda_1} \leq 1$ and use the last statement of Lemma \ref{lemma: phi bounded} to get the boundedness. We are allowed to use the last statement of Lemma \ref{lemma: phi bounded} since $V_B \leq V$, $\Phi(\cdot)$ and $d_2(\cdot)$ are non-decreasing and thus $\Phi(d_2(\tfrac{V_B^2}{Vk},T)) \leq \Phi(d_2(\tfrac{V}{k},T))$ with $\ln(\tfrac{V}{k})=\ln(V)-\ln(k)$. Hence, the claim follows in all cases.
\end{myproof}

\begin{lemma} \label{lemma: cdo limit of derivative to 0 and infty}
	For all $V_B \geq 0$, and $T>0$, it holds:
	\begin{enumerate}[(a)]
		\item $\lim_{V_B \to \infty} (\frac{\partial}{\partial V} c_{do} (V,k,V_B,T) \big|_{V=V_B}) = e^{-\nu T}(2\lambda_1 \Phi(d_1(1,T))+ \frac{2}{\sigma \sqrt{T}} \varphi(d_1(1,T)))$ for all $k \geq 0$,
		\item $\lim_{V_B \to 0} (\frac{\partial}{\partial V} c_{do} (V,k,V_B,T) \big|_{V=V_B}) = 0$ for all $k>0$,
		\item\label{lemma, item: k=0 limit} $\frac{\partial}{\partial V} c_{do} (V,0,V_B,T) \big|_{V=V_B} = e^{-\nu T}(2\lambda_1 \Phi(d_1(1,T))+ \frac{2}{\sigma \sqrt{T}} \varphi(d_1(1,T)))$.
	\end{enumerate}
\end{lemma}

\begin{myproof}%[Proof of Lemma \ref{lemma: cdo limit of derivative to 0 and infty}]
	First, we obtain from \eqref{eq: derivative cdo vb<k} and \eqref{eq: derivative cdo vb>k}:
	\begin{align}
		\tfrac{\partial}{\partial V} c_{do}^{V_B \leq k} (V,k,V_B,T) \big|_{V=V_B} =&\, e^{-\nu T} \Phi(d_1(\tfrac{V_B}{k},T))+ \frac{e^{-\nu T} \varphi(d_1(\frac{V_B}{k},T))}{\sigma \sqrt{T}} - \frac{ke^{-rT} \varphi(d_2(\frac{V_B}{k},T))}{\sigma \sqrt{T} V_B} \notag \\
		&- (1-2\lambda_1)e^{-\nu T} \Phi(d_1(\tfrac{V_B}{k},T)) + \frac{e^{-\nu T} \varphi(d_1(\frac{V_B}{k},T))}{\sigma \sqrt{T}} \notag \\
		&+ (2-2\lambda_1) \tfrac{ke^{-rT}}{V_B} \Phi(d_2(\tfrac{V_B}{k},T)) - \frac{ke^{-rT} \varphi(d_2(\frac{V_B}{k},T))}{\sigma \sqrt{T} V_B}, \notag \\
		=&\, 2 \lambda_1 e^{-\nu T} \Phi(d_1(\tfrac{V_B}{k},T))+ \frac{2 e^{-\nu T} \varphi(d_1(\frac{V_B}{k},T))}{\sigma \sqrt{T}} - \frac{2ke^{-rT} \varphi(d_2(\frac{V_B}{k},T))}{\sigma \sqrt{T} V_B} \notag \\
		&+ (2-2\lambda_1) \tfrac{ke^{-rT}}{V_B} \Phi(d_2(\tfrac{V_B}{k},T)), \label{eq: dv cdo< v=vb} \\
		\tfrac{\partial}{\partial V} c_{do}^{V_B \geq k} (V,k,V_B,T) \big|_{V=V_B} =&\, e^{-\nu T} \Phi(d_1(1,T))+ \tfrac{e^{-\nu T} \varphi(d_1(1,T))}{\sigma \sqrt{T}} - \frac{ke^{-rT} \varphi(d_2(1,T))}{\sigma \sqrt{T} V_B} \notag\\
		&- (1-2\lambda_1)e^{-\nu T} \Phi(d_1(1,T)) + \tfrac{e^{-\nu T} \varphi(d_1(1,T))}{\sigma \sqrt{T}} \notag\\
		&+ (2-2\lambda_1) \tfrac{ke^{-rT}}{V_B} \Phi(d_2(1,T)) - \frac{ke^{-rT} \varphi(d_2(1,T))}{\sigma \sqrt{T} V_B} \notag \\
		=&\, 2\lambda_1 e^{-\nu T} \Phi(d_1(1,T))+ \tfrac{2e^{-\nu T} \varphi(d_1(1,T))}{\sigma \sqrt{T}} - \frac{2ke^{-rT} \varphi(d_2(1,T))}{\sigma \sqrt{T} V_B} \notag\\
		&+ (2-2\lambda_1) \tfrac{ke^{-rT}}{V_B} \Phi(d_2(1,T)). \label{eq: dv cdo> v=vb}
	\end{align}
	Now, we conclude for the proof of parts (a) and (b):
	\begin{align*}
		\lim_{V_B \to \infty} \tfrac{\partial}{\partial V} c_{do} (V,k,V_B,T) \big|_{V=V_B} =&\, \lim_{V_B \to \infty} \tfrac{\partial}{\partial V} c_{do}^{V_B \geq k} (V,k,V_B,T) \big|_{V=V_B} \\
		=&\, 2 \lambda_1 e^{-\nu T} \Phi(d_1(1,T))+ \tfrac{2e^{-\nu T} \varphi(d_1(1,T))}{\sigma \sqrt{T}} - 0 + 0,\\
		=&\, e^{-\nu T} \left( 2 \lambda_1 \Phi(d_1(1,T)) + \tfrac{2}{\sigma \sqrt{T}} \varphi(d_1(1,T)) \right), \\
		\lim_{V_B \to 0} \tfrac{\partial}{\partial V} c_{do} (V,k,V_B,T) \big|_{V=V_B} =&\, \lim_{V_B \to 0} \tfrac{\partial}{\partial V} c_{do}^{V_B \leq k} (V,k,V_B,T) \big|_{V=V_B} \\
		=&\, 2 \lambda_1 e^{-\nu T} \Phi(d_1(0,T))+ \tfrac{2e^{-\nu T} \varphi(d_1(0,T))}{\sigma \sqrt{T}} - \tfrac{2ke^{-rT}}{\sigma \sqrt{T}} \cdot \lim\limits_{V_B \to 0} \tfrac{\varphi(d_2(\frac{V_B}{k},T))}{V_B} \\
		&+ (2-2\lambda_1) ke^{-rT} \cdot \lim\limits_{V_B \to 0} \tfrac{\Phi(d_2(\frac{V_B}{k},T))}{V_B} \\
		=&\, 0,
	\end{align*}
	due to $d_1(0,T)=-\infty$, $\lim_{z \to -\infty} \varphi(z)=0$, $\lim_{z \to -\infty} \Phi(z)=0$, Lemma \ref{lemma: varphi bounded}, and Lemma \ref{lemma: phi bounded}. Note that the first step (i.e., using the formula of the Down-and-Out Call option for $V_B \geq k$ (resp. $V_B \leq k$) when taking the limit $V_B \to \infty$ (resp. $V_B \to 0$)) is valid because $k>0$. 

	For part (c), when $k = 0$, it holds since $V_B \geq 0$: 
	\begin{align*}
		\tfrac{\partial}{\partial V} c_{do} (V,0,V_B,T) \big|_{V=V_B} =&\, \tfrac{\partial}{\partial V} c_{do}^{V_B \geq k} (V,0,V_B,T) \big|_{V=V_B} \\
		=&\, e^{-\nu T} \Phi(d_1(1,T))+ \tfrac{e^{-\nu T} \varphi(d_1(1,T))}{\sigma \sqrt{T}} - 0 \\
		&- (1-2\lambda_1)e^{-\nu T} \Phi(d_1(1,T)) + \tfrac{e^{-\nu T} \varphi(d_1(1,T))}{\sigma \sqrt{T}} + 0 - 0 \\
		=&\, e^{-\nu T}(2\lambda_1 \Phi(d_1(1,T))+ \tfrac{2}{\sigma \sqrt{T}} \varphi(d_1(1,T))). \qedhere
	\end{align*} 
\end{myproof}

\begin{lemma} \label{lemma: cdo unif bounded L1}
	For all $k \geq 0$, and $T>0$, there exists a constant $C>0$ such that \linebreak $|\frac{\partial}{\partial V} c_{do} (V,k,V_B,T)| \big|_{V=V_B} \leq C (e^{-\nu T} + e^{-rT})$ for all $V=V_B \in (0,\infty)$.
\end{lemma}

\begin{myproof}%[Proof of Lemma \ref{lemma: cdo unif bounded L1}]
	By equations \eqref{eq: dv cdo< v=vb} and \eqref{eq: dv cdo> v=vb}, the claim holds if we can show that each individual term is bounded by $C(e^{-\nu T} + e^{-rT})$ for some constant $C>0$ in the limits $V_B \to 0$ and $V_B \to +\infty$. Then, in total, we have $|\frac{\partial}{\partial V} c_{do} (V,k,V_B,T)| \big|_{V=V_B} \leq C (e^{-\nu T} + e^{-rT})$ with a possibly larger constant $C>0$. We now distinguish the cases $k=0$ and $k>0$. If $k=0$, we find that $|\frac{\partial}{\partial V} c_{do} (V,k,V_B,T)| \big|_{V=V_B}$ is constant, and hence bounded. Now, let $k>0$. For the limit as $V_B \to \infty$, the claim follows directly from equation \eqref{eq: dv cdo> v=vb} (since $V_B \geq k$ for $V_B$ sufficiently large). For the limit as $V_B \to 0$, we can assume that $|\frac{\partial}{\partial V} c_{do} (V,k,V_B,T)| \big|_{V=V_B} = |\frac{\partial}{\partial V} c_{do}^{V_B \leq k} (V,k,V_B,T)| \big|_{V=V_B}$, since $k>0$ and $V_B<k$ for $V_B$ sufficiently small. In this case, the claim follows from equation \eqref{eq: dv cdo< v=vb} using that $|\Phi(\cdot)| \leq 1$, $|\varphi(\cdot)| \leq 1$, and Lemmas \ref{lemma: varphi bounded} and \ref{lemma: phi bounded}.
\end{myproof}

\begin{lemma} \label{lemma: i1 i2 derivative}
	It holds:
	\begin{align*}
		\tfrac{\partial I_1^V(T)}{\partial V} \big|_{V=V_B} =&\, -\tfrac{2}{rTV_B} \Big( \tfrac{\lambda_2-\lambda_3}{2} + \lambda_3 \Phi (\lambda_3 \sigma \sqrt{T}) - \lambda_2 e^{-rT} \Phi(\lambda_2 \sigma \sqrt{T})\Big),\\
		\tfrac{\partial I_2^V(T)}{\partial V} \big|_{V=V_B} =&\, - \tfrac{2}{V_B} \Big( \tfrac{\lambda_2-\lambda_3}{2} - \tfrac{1}{2 \lambda_3 \sigma^2 T} + (\lambda_3+\tfrac{1}{\lambda_3 \sigma^2 T} ) \Phi (\lambda_3 \sigma \sqrt{T}) + \tfrac{\varphi (\lambda_3\sigma\sqrt{T})}{\sigma \sqrt{T}} \Big). 
	\end{align*}
\end{lemma}

\begin{myproof}%[Proof of Lemma \ref{lemma: i1 i2 derivative}]
	By the definition of $I_1$ (see \eqref{eq: def of i1}), we begin by differentiating $F$ and $G$ (which are defined in equations \eqref{eq: def of F} and \eqref{eq: def of G}, respectively):
	\begin{align*}
		\tfrac{\partial F^V(T)}{\partial V} =&\, \varphi(-d_3(\tfrac{V}{V_B},T))\tfrac{-1}{\sigma \sqrt{T} V} -2\lambda_2  V_B^{2\lambda_2} V^{-2\lambda_2-1} \Phi(-d_4(\tfrac{V}{V_B},T)) + (\tfrac{V_B}{V})^{2\lambda_2} \varphi(-d_4(\tfrac{V}{V_B},T))\tfrac{-1}{\sigma \sqrt{T} V} \\
		=&\, -\tfrac{1}{V} \Big( \tfrac{\varphi(-d_3(\frac{V}{V_B},T))}{\sigma \sqrt{T}} + 2 \lambda_2 (\tfrac{V_B}{V})^{2\lambda_2} \Phi(-d_4(\tfrac{V}{V_B},T)) + (\tfrac{V_B}{V})^{2\lambda_2} \tfrac{\varphi(-d_4(\frac{V}{V_B},T))}{\sigma \sqrt{T}}  \Big), \\
		\tfrac{\partial G^V(T)}{\partial V} =&\, (-\lambda_2+\lambda_3) V_B^{\lambda_2-\lambda_3} V^{-\lambda_2+\lambda_3-1} \Phi (-d_5(\tfrac{V}{V_B},T)) + (\tfrac{V_B}{V})^{\lambda_2-\lambda_3} \varphi (-d_5(\tfrac{V}{V_B},T)) \tfrac{-1}{\sigma \sqrt{T} V} \\
		&+ (-\lambda_2-\lambda_3) V_B^{\lambda_2+\lambda_3} V^{-\lambda_2-\lambda_3-1} \Phi (-d_6(\tfrac{V}{V_B},T)) + (\tfrac{V_B}{V})^{\lambda_2+\lambda_3} \varphi (-d_6(\tfrac{V}{V_B},T)) \tfrac{-1}{\sigma \sqrt{T} V} \\
		=&\, -\tfrac{1}{V} \Big( (\lambda_2-\lambda_3) (\tfrac{V_B}{V})^{\lambda_2-\lambda_3} \Phi (-d_5(\tfrac{V}{V_B},T)) + (\tfrac{V_B}{V})^{\lambda_2-\lambda_3} \tfrac{\varphi (-d_5(\frac{V}{V_B},T))}{\sigma \sqrt{T}} \\
		&\hspace{30pt}+ (\lambda_2+\lambda_3) (\tfrac{V_B}{V})^{\lambda_2+\lambda_3} \Phi (-d_6(\tfrac{V}{V_B},T)) + (\tfrac{V_B}{V})^{\lambda_2+\lambda_3} \tfrac{\varphi (-d_6(\frac{V}{V_B},T))}{\sigma \sqrt{T}} \Big).
	\end{align*}
	Hence, using equation \eqref{eq: def of i1} and the relationships $\varphi(-d_3(1,T)) = \varphi(-d_4(1,T)) = \varphi(\lambda_2 \sigma \sqrt{T})$, $\Phi(-d_4(1,T)) = \Phi(\lambda_2 \sigma \sqrt{T})$, $\varphi (-d_5(1,T))=\varphi (-d_6(1,T))=\varphi (\lambda_3\sigma\sqrt{T})$, and $1-\Phi (-d_5(1,T))=\Phi (-d_6(1,T))=\Phi (\lambda_3 \sigma \sqrt{T})$, we obtain:
	\begin{align*}
		\tfrac{\partial I_1^V(T)}{\partial V} \big|_{V=V_B} =&\, \tfrac{1}{rT} (\tfrac{\partial G^V(T)}{\partial V} \big|_{V=V_B}-e^{-rT}\tfrac{\partial F^V(T)}{\partial V} \big|_{V=V_B}) \\
		=&\, -\tfrac{1}{rTV_B} \Big( (\lambda_2-\lambda_3)(1-\Phi (\lambda_3 \sigma \sqrt{T})) + \tfrac{\varphi (\lambda_3\sigma\sqrt{T})}{\sigma \sqrt{T}} + (\lambda_2+\lambda_3) \Phi (\lambda_3 \sigma \sqrt{T}) + \tfrac{\varphi (\lambda_3\sigma\sqrt{T})}{\sigma \sqrt{T}} \\
		&\hspace{40pt}- \tfrac{e^{-rT}\varphi (\lambda_2\sigma\sqrt{T})}{\sigma \sqrt{T}} - 2 \lambda_2 e^{-rT} \Phi(\lambda_2 \sigma \sqrt{T}) - \tfrac{e^{-rT}\varphi (\lambda_2\sigma\sqrt{T})}{\sigma \sqrt{T}} \Big) \\
		=&\, -\tfrac{2}{rTV_B} \Big( \tfrac{\lambda_2-\lambda_3}{2} + \tfrac{\varphi (\lambda_3\sigma\sqrt{T})}{\sigma \sqrt{T}} + \lambda_3 \Phi (\lambda_3 \sigma \sqrt{T}) - \tfrac{e^{-rT}\varphi (\lambda_2\sigma\sqrt{T})}{\sigma \sqrt{T}} - \lambda_2 e^{-rT} \Phi(\lambda_2 \sigma \sqrt{T})\Big),
	\end{align*}
	which is the first claim since $\tfrac{\varphi (\lambda_3\sigma\sqrt{T})}{\sigma \sqrt{T}}= \tfrac{e^{-rT}\varphi (\lambda_2\sigma\sqrt{T})}{\sigma \sqrt{T}}$. Indeed, we have $\varphi (\lambda_3\sigma\sqrt{T}) = \tfrac{1}{\sqrt{2 \pi}} e^{-\frac{1}{2}\lambda_3^2 \sigma^2 T}$ and $e^{-rT}\varphi (\lambda_2\sigma\sqrt{T}) = \tfrac{1}{\sqrt{2 \pi}} e^{-\frac{1}{2}\lambda_2^2 \sigma^2 T - rT}$. Furthermore, by the definition of $\lambda_3$, we find that $\tfrac{1}{2}\lambda_3^2 \sigma^2 T = \tfrac{1}{2} \tfrac{\lambda_2^2 \sigma^4 +2r\sigma^2}{\sigma^4} \sigma^2 T = \tfrac{1}{2} \lambda_2^2 \sigma^2 T + rT$, which completes the proof of this claim.

	For $I_2$ (as defined in \eqref{eq: def of i2}), we get:
	\begin{align*}
		\lambda_3 \sigma \sqrt{T} \tfrac{\partial I_2^V(T)}{\partial V} =&\, (-\lambda_2+\lambda_3)V_B^{\lambda_2-\lambda_3} V^{-\lambda_2+\lambda_3-1} \Phi(-d_5(\tfrac{V}{V_B},T))d_5(\tfrac{V}{V_B},T) \\
		&+ (\tfrac{V_B}{V})^{\lambda_2-\lambda_3} \varphi(-d_5(\tfrac{V}{V_B},T))\tfrac{-d_5(\frac{V}{V_B},T)}{\sigma \sqrt{T} V} +(\tfrac{V_B}{V})^{\lambda_2-\lambda_3} \Phi(-d_5(\tfrac{V}{V_B},T))\tfrac{1}{\sigma\sqrt{T}V} \\
		&- (-\lambda_2-\lambda_3) V_B^{\lambda_2+\lambda_3} V^{-\lambda_2-\lambda_3-1} \Phi (-d_6(\tfrac{V}{V_B},T)) d_6(\tfrac{V}{V_B},T) \\
		&- (\tfrac{V_B}{V})^{\lambda_2+\lambda_3} \varphi (-d_6(\tfrac{V}{V_B},T)) \tfrac{-d_6(\frac{V}{V_B},T)}{\sigma \sqrt{T} V} - (\tfrac{V_B}{V})^{\lambda_2+\lambda_3} \Phi (-d_6(\tfrac{V}{V_B},T)) \tfrac{1}{\sigma \sqrt{T} V}.
	\end{align*}
	Thus, using the identities for $\varphi$ and $\Phi$ from above, along with $d_{5/6}(1,T) = \pm \lambda_3 \sigma \sqrt{T}$, we obtain:
	\begin{align*}
		\tfrac{\partial I_2^V(T)}{\partial V} \big|_{V=V_B} =&\, \tfrac{1}{\lambda_3 \sigma \sqrt{T} V_B} \Big( (-\lambda_2+\lambda_3) (1-\Phi (\lambda_3 \sigma \sqrt{T}))\lambda_3 \sigma \sqrt{T} -\varphi (\lambda_3\sigma\sqrt{T})\tfrac{\lambda_3 \sigma \sqrt{T}}{\sigma \sqrt{T}} + \tfrac{1-\Phi (\lambda_3 \sigma \sqrt{T})}{\sigma\sqrt{T}}\\
		&\hspace{44pt} - (\lambda_2+\lambda_3) \Phi (\lambda_3 \sigma \sqrt{T}) \lambda_3 \sigma \sqrt{T}- \varphi (\lambda_3\sigma\sqrt{T}) \tfrac{\lambda_3 \sigma \sqrt{T}}{\sigma \sqrt{T}} - \tfrac{\Phi (\lambda_3 \sigma \sqrt{T})}{\sigma \sqrt{T}} \Big) \\
		=&\, \tfrac{1}{V_B} \Big( -\lambda_2+\lambda_3 - 2 \lambda_3 \Phi (\lambda_3 \sigma \sqrt{T}) + \tfrac{1}{\lambda_3 \sigma^2 T} - \tfrac{2\Phi (\lambda_3 \sigma \sqrt{T})}{\lambda_3 \sigma^2 T} - \tfrac{2\varphi (\lambda_3\sigma\sqrt{T})}{\sigma \sqrt{T}} \Big) \\
		=&\, - \tfrac{2}{V_B} \Big( \tfrac{\lambda_2-\lambda_3}{2} - \tfrac{1}{2 \lambda_3 \sigma^2 T} + (\lambda_3+\tfrac{1}{\lambda_3 \sigma^2 T} ) \Phi (\lambda_3 \sigma \sqrt{T}) + \tfrac{\varphi (\lambda_3\sigma\sqrt{T})}{\sigma \sqrt{T}} \Big),
	\end{align*}
	which is the second claim.
\end{myproof}

\begin{lemma} \label{lemma: explicit calculation integral}
	It holds:
	\begin{enumerate}[(a)]
		\item $\int_0^T \tfrac{e^{-\nu t}}{\sqrt{t}} \varphi(\lambda_1\sigma\sqrt{t}) \diff t = \sqrt{\tfrac{1}{\lambda_1^2\sigma^2+2\nu}}(2 \Phi(\sqrt{\lambda_1^2\sigma^2+2\nu}\sqrt{T})-1)$,
		\item $\int_0^\infty \tfrac{e^{-\nu t}}{\sqrt{t}} \varphi(\lambda_1\sigma\sqrt{t}) \diff t = \sqrt{\tfrac{1}{\lambda_1^2\sigma^2+2\nu}}$,
		\item $\int_0^T e^{-\nu t} \Phi(\lambda_1\sigma\sqrt{t}) \diff t = \tfrac{1}{2\nu} - \tfrac{e^{-\nu T} \Phi(\lambda_1\sigma\sqrt{T})}{\nu} + \tfrac{\lambda_1 \sigma}{2 \nu} \sqrt{\tfrac{1}{\lambda_1^2\sigma^2+2\nu}}(2 \Phi(\sqrt{\lambda_1^2\sigma^2+2\nu}\sqrt{T})-1)$,
		\item $\int_0^\infty e^{-\nu t} \Phi(\lambda_1\sigma\sqrt{t}) \diff t = \tfrac{1}{2\nu} + \tfrac{\lambda_1 \sigma}{2 \nu} \sqrt{\tfrac{1}{\lambda_1^2\sigma^2+2\nu}}$.
	\end{enumerate}
\end{lemma}

\begin{myproof}%[Proof of Lemma \ref{lemma: explicit calculation integral}]
	We begin by proving property (a). To do so, we define the function $\text{erf}$ as $\text{erf}(x):=\tfrac{2}{\sqrt{\pi}} \int_0^x e^{-u^2} \diff u$, which is also known as the Gaussian error function. This function has the identity $\text{erf}(x)=2\Phi(\sqrt{2}x)-1$. Now, considering $\lambda_1\geq 0$, we proceed with:
	\begin{align*}
		\int_0^T \tfrac{e^{-\nu t}}{\sqrt{t}} \varphi(\lambda_1\sigma\sqrt{t}) \diff t &= \tfrac{2}{\lambda_1\sigma} \int_0^{\lambda_1\sigma\sqrt{T}} \exp\{-\tfrac{\nu}{\lambda_1^2\sigma^2} s^2\} \varphi(s) \diff s \\
		&= \tfrac{2}{\lambda_1\sigma} \cdot \tfrac{1}{\sqrt{2\pi}} \int_0^{\lambda_1\sigma\sqrt{T}} \exp\{-s^2 (\tfrac{1}{2}+\tfrac{\nu}{\lambda_1^2\sigma^2}) \} \diff s \\
		&= \tfrac{2}{\lambda_1\sigma} \cdot \sqrt{\tfrac{2\lambda_1^2\sigma^2}{\lambda_1^2\sigma^2+2\nu}} \cdot \tfrac{1}{\sqrt{2\pi}} \int_0^{\sqrt{\frac{\lambda_1^2\sigma^2+2\nu}{2\lambda_1^2\sigma^2}}\lambda_1\sigma\sqrt{T}} \exp\{-u^2 \} \diff u \\
		&= \sqrt{\tfrac{1}{\lambda_1^2\sigma^2+2\nu}} \cdot \text{erf}(\sqrt{\tfrac{\lambda_1^2\sigma^2+2\nu}{2}}\sqrt{T}),
	\end{align*}
	where we made the substitutions $s=\lambda_1\sigma\sqrt{t}$ and $u=\sqrt{\tfrac{\lambda_1^2\sigma^2+2\nu}{2\lambda_1^2\sigma^2}} \cdot s$ in the first, resp. third step. In particular, this establishes claim (a). If $\lambda_1<0$, the proof follows similarly, as the two arising negative signs cancel out (from $\text{erf}(-x)=-\text{erf}(x)$ and the calculation of $\tfrac{\sqrt{\lambda_1^2}}{\lambda_1}$). Property (b) follows by taking the limit $T \to \infty$.

	Next, we proceed with the proof of property (c). Using (a), %and the fact that $\Phi(0)=\tfrac{1}{2}$, 
	we obtain:
	\begin{align*}
		\int_0^T e^{-\nu t} \Phi(\lambda_1\sigma\sqrt{t}) \diff t &= \big[ \tfrac{-1}{\nu} e^{-\nu t} \Phi(\lambda_1 \sigma \sqrt{t}) \big]_0^T + \int_0^T \tfrac{1}{\nu} e^{-\nu t} \varphi(\lambda_1 \sigma \sqrt{t}) \tfrac{\lambda_1 \sigma}{2 \sqrt{t}} \diff t \\
		&= \tfrac{1}{2\nu} - \tfrac{e^{-\nu T} \Phi(\lambda_1\sigma\sqrt{T})}{\nu} + \tfrac{\lambda_1 \sigma}{2 \nu} \cdot \sqrt{\tfrac{1}{\lambda_1^2\sigma^2+2\nu}}(2 \Phi(\sqrt{\lambda_1^2\sigma^2+2\nu}\sqrt{T})-1)
	\end{align*}
	where we derived the first equation by integration by parts. Property (d) follows directly by taking the limit as $T \to \infty$.
\end{myproof}

\begin{lemma} \label{lemma: ass reformulation derivative}
	It holds that $\tfrac{-2\frac{G}{r}A_1}{rT} + 2 \tfrac{G}{r} A_2 \geq \tau_1 \frac{G}{r}(\lambda_2+\lambda_3)$ and $\int_0^T \frac{\partial c_{do} (V,k,V_B,t)}{\partial V} \big|_{V=V_B} \diff t \geq \tau_2 \int_0^\infty \frac{\partial  c_{do} (V,k,V_B,t) }{\partial V} \big|_{V=V_B} \diff t$.
\end{lemma}

\begin{proof}
	First, we observe that, by definition, the liability value of the guaranteed payment and of the surplus participation (see term $1$ and $4$ in \eqref{eq: def liability for small t}), and the associated tax benefits (see \eqref{eq: def TB1} and \eqref{eq: def TB2}) are $0$ when $V=V_B$. Therefore, the inequalities in equations \eqref{eq: ass guarantee excess} and \eqref{eq: ass surplus excess} hold even when we differentiate with respect to $V$ and evaluate at $V=V_B$ obtaining:
	\begin{align}
		\tfrac{\partial}{\partial V}\displaystyle\int_0^T \EX^\QQ \left[\int_0^t e^{-rs} g \1_{\{\min_{r \in [0,s]} V_r \geq V_B\}} \diff s \right] \diff t \,\Big|_{V=V_B}&\geq \tfrac{\partial}{\partial V}TB_1 \,\Big|_{V=V_B}, \label{eq: ass guarantee excess derivative} \\
		\tfrac{\partial}{\partial V}\displaystyle\int_0^T c_{do} (V,k,V_B,t) \diff t \,\Big|_{V=V_B} &\geq \tau_2 \tfrac{\partial}{\partial V}\displaystyle\int_0^\infty c_{do} (V,k,V_B,t) \diff t \,\Big|_{V=V_B}. \label{eq: ass surplus excess derivative}
	\end{align}

	From \eqref{eq: liability value L} (with $\alpha=p=0$ and $\rho=1$), we have:
	\begin{align*}
		\int_0^T \EX^\QQ \left[\int_0^t e^{-rs} g \1_{\{\min_{r \in [0,s]} V_r \geq V_B\}} \diff s \right] \diff t = \tfrac{G}{r} - \tfrac{G}{r} ( \tfrac{1-e^{-rT}}{rT} - I_1^V(T) )  - \frac{G}{r} I_2^V(T).
	\end{align*}
	Next, using the definitions of $A_1$ and $A_2$ in \eqref{eq: a1} and \eqref{eq: a2}, along with Lemma \ref{lemma: i1 i2 derivative}, we find that $\tfrac{\partial I_1^V(T)}{\partial V} \big|_{V=V_B} = - \tfrac{2A_1}{rTV_B}$ and $\tfrac{\partial I_2^V(T)}{\partial V} \big|_{V=V_B} = - \tfrac{2A_2}{V_B}$. Additionally, note that $\tfrac{\partial (\frac{V_B}{V})^{\lambda_2+\lambda_3}}{\partial V} \big|_{V=V_B} = (-\lambda_2-\lambda_3)V_B^{\lambda_2+\lambda_3} V^{-\lambda_2-\lambda_3-1} \big|_{V=V_B} = -\tfrac{(\lambda_2+\lambda_3)}{V_B}$. Using the definition of $TB_1$ from equation \eqref{eq: firm value v}, we obtain the first result after canceling the factor of $\tfrac{1}{V_B} > 0$ from both sides in \eqref{eq: ass guarantee excess derivative}.

	For the second claim, we are permitted in \eqref{eq: ass surplus excess derivative} to interchange the derivative and the integral sign by the Dominated Convergence Theorem, as established by Lemma \ref{lemma: cdo unif bounded L1}. This directly leads to the conclusion.
\end{proof}

\begin{lemma} \label{lemma: term bigger 0 for vb}
	It holds:
	\begin{align*}
		1 + \rho(\lambda_2+\lambda_3)+2(1-\rho)[\tfrac{\lambda_2-\lambda_3}{2} - \tfrac{1}{2 \lambda_3 \sigma^2 T} + (\lambda_3+\tfrac{1}{\lambda_3 \sigma^2 T} ) \Phi (\lambda_3 \sigma \sqrt{T}) + \tfrac{\varphi (\lambda_3\sigma\sqrt{T})}{\sigma \sqrt{T}}] > 0.
	\end{align*}
\end{lemma}

\begin{myproof}%[Proof of Lemma \ref{lemma: term bigger 0 for vb}]
	It holds:
	\begin{align*}
		B:=&\,2[\tfrac{\lambda_2-\lambda_3}{2} - \tfrac{1}{2 \lambda_3 \sigma^2 T} + (\lambda_3+\tfrac{1}{\lambda_3 \sigma^2 T} ) \Phi (\lambda_3 \sigma \sqrt{T}) + \tfrac{\varphi (\lambda_3\sigma\sqrt{T})}{\sigma \sqrt{T}}] \\
		=&\, \lambda_2+\lambda_3 - 2\lambda_3 + 2\lambda_3 \Phi (\lambda_3 \sigma \sqrt{T}) - \tfrac{1}{\lambda_3 \sigma^2 T} + \tfrac{2}{\lambda_3 \sigma^2 T} \Phi (\lambda_3 \sigma \sqrt{T}) + 2 \lambda_3 \tfrac{\varphi (\lambda_3\sigma\sqrt{T})}{\lambda_3 \sigma \sqrt{T}} \\
		=&\, (\lambda_2+\lambda_3) + 2\lambda_3 (\Phi (\lambda_3 \sigma \sqrt{T})+\tfrac{\varphi (\lambda_3\sigma\sqrt{T})}{\lambda_3 \sigma \sqrt{T}}-1) + \tfrac{1}{\lambda_3 \sigma^2 T} (2\Phi (\lambda_3 \sigma \sqrt{T})-1).
	\end{align*}
	By definition, $\lambda_3 \geq 0$. Moreover, since $\lambda_3 = \tfrac{\sqrt{(\lambda_2 \sigma^2)^2+2r\sigma^2}}{\sigma^2} = \sqrt{\lambda_2^2+\tfrac{2r}{\sigma^2}}$, we see that $\lambda_3 > |\lambda_2|$ given that $r>0$ and $\sigma>0$. In particular, this implies that $\lambda_2+\lambda_3>0$. Therefore, since $\lambda_3 \sigma \sqrt{T}>0$, we have $2\Phi (\lambda_3 \sigma \sqrt{T})-1>0$. For the middle term, the situation is more intricate. Let $x > 0$ and define $h(x):=\Phi(x)+\tfrac{\varphi(x)}{x}-1$. Now, $h'(x) = \varphi(x) + \tfrac{-\varphi(x)x^2-\varphi(x)}{x^2} = - \tfrac{\varphi(x)}{x^2} <0$, meaning that $h$ is decreasing in $x$. Since $\lim_{x \to \infty} h(x) = 0$, we conclude that $h(x)>0$ for all $x \in \Real$. Therefore, we obtain the expression that $2\lambda_3 (\Phi (\lambda_3 \sigma \sqrt{T})+\tfrac{\varphi (\lambda_3\sigma\sqrt{T})}{\lambda_3 \sigma \sqrt{T}}-1)>0$, since $\lambda_3 \sigma \sqrt{T}>0$. Thus, $B>0$. 

	Hence, it follows:
	\begin{align*}
		&\, 1 + \rho(\lambda_2+\lambda_3)+2(1-\rho)[\tfrac{\lambda_2-\lambda_3}{2} - \tfrac{1}{2 \lambda_3 \sigma^2 T} + (\lambda_3+\tfrac{1}{\lambda_3 \sigma^2 T} ) \Phi (\lambda_3 \sigma \sqrt{T}) + \tfrac{\varphi (\lambda_3\sigma\sqrt{T})}{\sigma \sqrt{T}}] \\
		=&\, 1 + \rho(\lambda_2+\lambda_3)+ (1-\rho) B >0,
	\end{align*}
	since $\lambda_2+\lambda_3>0$, $B>0$ as discussed above, and $\rho \in [0,1]$.
\end{myproof}

\begin{lemma} \label{lemma: a1,a2,a3,a4>0}
	It holds that $A_1, A_2 >0$ and $A_3 > A_4 > 0$ with $A_1$, $A_2$, $A_3$, and $A_4$ defined as in equations \eqref{eq: a1}, \eqref{eq: a2}, \eqref{eq: a3} and \eqref{eq: a4}.
\end{lemma}

\begin{myproof}%[Proof of Lemma \ref{lemma: a1,a2,a3,a4>0}]
	We begin by proving that $A_1>0$: First, we rewrite $A_1$ as $A_1 = \lambda_3 (\Phi(\lambda_3\sigma\sqrt{T})-\tfrac{1}{2}) - \lambda_2 (e^{-rT}\Phi(\lambda_2\sigma\sqrt{T})-\tfrac{1}{2})$. Now, if $\lambda_2 \geq 0$, we obtain the inequality $A_1 \geq \lambda_3 (\Phi(\lambda_3\sigma\sqrt{T})-\tfrac{1}{2}) - \lambda_2 (\Phi(\lambda_2\sigma\sqrt{T})-\tfrac{1}{2})$, since $e^{-rT}<1$. Since $r,\sigma>0$, it follows from the definition that $\lambda_3>\lambda_2$. This implies that $\Phi(\lambda_3\sigma\sqrt{T})-\tfrac{1}{2}>\Phi(\lambda_2\sigma\sqrt{T})-\tfrac{1}{2}$, because $\Phi(\cdot)$ is an increasing function. Therefore, we conclude that $A_1>0$ when $\lambda_2\geq0$. Next, we consider the case where $\lambda_2<0$. In this case, $A_1>0$ is equivalent to $\lambda_3 (\Phi(\lambda_3\sigma\sqrt{T})-\tfrac{1}{2}) > |\lambda_2| (\tfrac{1}{2} - e^{-rT}\Phi(\lambda_2\sigma\sqrt{T}))$. If $\tfrac{1}{2} - e^{-rT}\Phi(\lambda_2\sigma\sqrt{T}) \leq 0$, this inequality clearly holds, so assume that $\tfrac{1}{2} - e^{-rT}\Phi(\lambda_2\sigma\sqrt{T}) >0$. Since $r,\sigma>0$, we have $\lambda_3>|\lambda_2|$, which implies that $A_1>0$ if $\Phi(\lambda_3\sigma\sqrt{T})+ e^{-rT}\Phi(\lambda_2\sigma\sqrt{T}))-1 \geq 0$. This inequality is equivalent to 
	\begin{align} \label{eq: equivalence in a1 proof}
		e^{-rT}\Phi(-|\lambda_2|\sigma\sqrt{T})) \geq \Phi(-\lambda_3\sigma\sqrt{T}),
	\end{align}
	since $\Phi(-x)=1-\Phi(x)$ for all $x \in \Real$. Using the substitution $s = \sqrt{t^2+2rT}$, we can derive the following identity for any $x>0$, due to $e^{-t^2}$ being symmetric:
	\begin{align*}
		e^{-rT} \Phi(-x) = \tfrac{e^{-rT}}{\sqrt{2\pi}} \displaystyle\int_{-\infty}^{-x} e^{-\frac{t^2}{2}} \diff t = \tfrac{1}{\sqrt{2\pi}} \displaystyle\int_{x}^{\infty} e^{-\frac{1}{2}(t^2+2rT)} \diff t = \tfrac{1}{\sqrt{2\pi}} \displaystyle\int_{\sqrt{x^2+2rT}}^{\infty} e^{-\frac{s^2}{2}} \tfrac{s}{\sqrt{s^2-2rT}} \diff s.
	\end{align*}
	Thus, we have $e^{-rT}\Phi(-|\lambda_2|\sigma\sqrt{T})) = \tfrac{1}{\sqrt{2\pi}} \int_{\sqrt{\lambda_2^2\sigma^2 T+2rT}}^{\infty} e^{-\frac{s^2}{2}} \tfrac{s}{\sqrt{s^2-2rT}} \diff s = \tfrac{1}{\sqrt{2\pi}} \int_{\lambda_3\sigma\sqrt{T}}^{\infty} e^{-\frac{s^2}{2}} \linebreak \tfrac{s}{\sqrt{s^2-2rT}} \diff s$, since $\lambda_2^2\sigma^2 T+2rT = \lambda_3^2 \sigma^2 T$. Indeed, it holds by definition that $\lambda_3^2 \sigma^2 = \tfrac{\lambda_2^2 \sigma^4+2r\sigma^2}{\sigma^4} \sigma^2 = \lambda_2^2 \sigma^2 + 2r$. Multiplying by $T$ yields this intermediate statement. Now, a simple rewriting leads to $\Phi(-\lambda_3\sigma\sqrt{T}) = \tfrac{1}{\sqrt{2\pi}} \int_{\lambda_3\sigma\sqrt{T}}^{\infty} e^{-\frac{s^2}{2}} \diff s$. Hence, \eqref{eq: equivalence in a1 proof} is equivalent to 
	\begin{align*}
		&\hspace{-60pt}&\tfrac{1}{\sqrt{2\pi}} \displaystyle\int_{\lambda_3\sigma\sqrt{T}}^{\infty} e^{-\frac{s^2}{2}} \tfrac{s}{\sqrt{s^2-2rT}} \diff s &\geq \tfrac{1}{\sqrt{2\pi}} \displaystyle\int_{\lambda_3\sigma\sqrt{T}}^{\infty} e^{-\frac{s^2}{2}} \diff s, \\
		&\Leftrightarrow\hspace{-60pt}& \int_{\lambda_3\sigma\sqrt{T}}^{\infty} e^{-\frac{s^2}{2}} (\tfrac{s}{\sqrt{s^2-2rT}}-1) \diff s &\geq 0.
	\end{align*}
	Since $\tfrac{s}{\sqrt{s^2-2rT}} \geq 1$ (due to $s \geq \lambda_3 \sigma \sqrt{T}>0$ and $(\lambda_3\sigma\sqrt{T})^2-2rT = \lambda_2^2 \sigma^2 T >0$), the last inequality is indeed correct. Therefore, $A_1>0$ follows.

	The property that $A_2>0$ is directly implied by the proof of Lemma \ref{lemma: term bigger 0 for vb}, where $B=2A_2$ with $B$ defined as in the proof of Lemma \ref{lemma: term bigger 0 for vb}.

	Next, we show that $A_3, A_4>0$: Using Lemma \ref{lemma: explicit calculation integral} and the fact that $\Big(\tfrac{\lambda_1^2 \sigma}{\nu} + \tfrac{2}{\sigma}\Big) \sqrt{\tfrac{1}{\lambda_1^2\sigma^2+2\nu}} = \tfrac{1}{\sigma \nu} \sqrt{\lambda_1^2 \sigma^2 + 2\nu}$, we have:
	\begin{align}
		A_3 &= \int_0^\infty \Big(e^{-\nu t}(2\lambda_1 \Phi(\lambda_1 \sigma \sqrt{t})+ \tfrac{2\varphi(\lambda_1 \sigma \sqrt{t})}{\sigma \sqrt{t}} )\Big) \diff t, \label{eq: a3 equality integral} \\
		A_4 &= \displaystyle\int_0^T \Big(e^{-\nu t}(2\lambda_1 \Phi(\lambda_1 \sigma \sqrt{t})+ \tfrac{2\varphi(\lambda_1 \sigma \sqrt{t})}{\sigma \sqrt{t}} )\Big) \diff t. \label{eq: a4 equality integral}
	\end{align}
	We now show that $\lambda_1 \Phi(\lambda_1 \sigma \sqrt{t})+ \tfrac{\varphi(\lambda_1 \sigma \sqrt{t})}{\sigma \sqrt{t}}>0$ for all $\lambda_1 \in \Real$, $\sigma>0$, and $t\geq 0$, which directly implies the claim. First, if $\lambda_1 \geq 0$, the result is trivial. If $\lambda_1 < 0$, we obtain: $\lambda_1 \Phi(\lambda_1 \sigma \sqrt{t})+ \tfrac{\varphi(\lambda_1 \sigma \sqrt{t})}{\sigma \sqrt{t}} = \lambda_1 [\Phi(\lambda_1 \sigma \sqrt{t})+ \tfrac{\varphi(\lambda_1 \sigma \sqrt{t})}{\lambda_1\sigma \sqrt{t}}]$. Let $y := \lambda_1 \sigma \sqrt{t} <0$, and define $h(y):= \Phi(y)+\tfrac{\varphi(y)}{y}$. Since $\lambda_1<0$, we only need to show that $h(y)<0$ for all $y \in (-\infty,0]$. First, we obtain that $\lim_{y \to -\infty} h(y) = 0$ and $\lim_{y \to0_-} h(y) =-\infty$. Additionally, $h'(y) = \varphi(y) + \tfrac{-y\varphi(y)y-\varphi(y)}{y^2} = - \tfrac{\varphi(y)}{y^2} < 0$ which yields the claim. 

	Finally, we conclude that $A_3 > A_4$, which follows immediately from the fact that $\lambda_1 \Phi(\lambda_1 \sigma \sqrt{t})+ \tfrac{\varphi(\lambda_1 \sigma \sqrt{t})}{\sigma \sqrt{t}}>0$ and $T<\infty$.
\end{myproof}

\begin{lemma} \label{lemma: long term >0}
	The inequalities $1+\rho(\lambda_2+\lambda_3)+2(1-\rho)A_2>0$ and $\tfrac{2(P-\frac{G}{r})A_1}{rT} + 2 \tfrac{G}{r} A_2 - \tau_1 \frac{G}{r}(\lambda_2+\lambda_3) > 0$ hold, where $\lambda_2,\lambda_3$ are defined in equation \eqref{eq: def lambda23}. 
\end{lemma}

\begin{myproof}%[Proof of Lemma \ref{lemma: long term >0}]
	The first part of the claim has already been established in Lemma \ref{lemma: term bigger 0 for vb} by inserting the definition of $A_2$ from equation \eqref{eq: a2}. The second part of the lemma follows directly from Lemma \ref{lemma: ass reformulation derivative}, with the additional observation that $A_1>0$ as established in Lemma \ref{lemma: a1,a2,a3,a4>0}, and that $P>0$ by definition.
	%the proof of Theorem \ref{th: VB determination}, where we demonstrated in \eqref{eq: h1 v to 0} that $\lim_{V \to 0} h_1(V) = -\infty$ with $h_1$ defined as in equation \eqref{eq: def h1}. Therefore, the definition of $h_1$ along with the limit $\lim_{V \to 0} h_1(V) = -\infty$ directly imply the lemma.
\end{myproof}

\begin{lemma} \label{lem: vb neq 0}
	If a solution $V_B$ to the equation \eqref{eq: formula for vb} exists, then it must satisfy $V_B \neq 0$.
\end{lemma}

\begin{myproof}%[Proof of Lemma \ref{lem: vb neq 0}]
	To prove this lemma, we demonstrate that the absolute value of the right-hand side of equation \eqref{eq: formula for vb} diverges to $\infty$ as $V_B \to 0$. According to Lemma \ref{lemma: long term >0}, this holds if the integrals in equation \eqref{eq: formula for vb} remain bounded as $V_B$ approaches $0$, which is ensured by Lemma \ref{lemma: cdo unif bounded L1} since $\nu>0$. Therefore, the lemma is proved.
\end{myproof}

