\begin{lemma} \label{lemma: dv2 cdo bounded l1}
	It holds that $h(V_B):=\tfrac{\partial c_{do} (V,k,V_B,t)}{\partial V} \big|_{V=V_B}$ is continuously differentiable. Furthermore, for all $k\geq 0$ and $T>0$, there exists a constant $C>0$ such that $0 \leq \tfrac{\partial}{\partial V_B}[\tfrac{\partial c_{do} (V,k,V_B,T)}{\partial V} \big|_{V=V_B}] \leq C (e^{-rT}+e^{-\nu T})$ for all $V_B>0$. 
\end{lemma}

\begin{myproof}%[Proof of Lemma \ref{lemma: dv2 cdo bounded l1}]
	To establish the continuous differentiability of $h$, it suffices to verify that the derivative is continuous at $V=k$, as these properties follow directly for all other points. From equations \eqref{eq: dv cdo< v=vb} and \eqref{eq: dv cdo> v=vb} resp. \eqref{eq: dv cdo v=vb}, we observe using $2-2\lambda_1=-2\lambda_2$:
	\begin{align}
		\tfrac{\partial}{\partial V_B}[\tfrac{\partial}{\partial V} c_{do}^{V_B \leq k} (V,k,V_B,t) \big|_{V=V_B}] =&\, 2e^{-\nu t} \Big(  \tfrac{\lambda_1 \varphi(d_1(\frac{V_B}{k},t))}{\sigma \sqrt{t}V_B}+ \frac{-\varphi(d_1(\frac{V_B}{k},t))d_1(\frac{V_B}{k},t)}{\sigma^2 t V_B} \Big) \notag \\
		&+ \tfrac{2ke^{-rt}}{V_B^2} \Big(\lambda_2  \Phi(d_2(\tfrac{V_B}{k},t)) + \frac{ \varphi(d_2(\frac{V_B}{k},t))}{\sigma \sqrt{t}} \Big) \notag \\
		&- \tfrac{2ke^{-rt}}{V_B} \Big(\tfrac{\lambda_2 \varphi(d_2(\frac{V_B}{k},t))}{\sigma\sqrt{t}V_B} + \frac{ -\varphi(d_2(\frac{V_B}{k},t))d_2(\frac{V_B}{k},t)}{\sigma^2 t V_B} \Big) \notag \\
		=&\, \tfrac{2e^{-\nu t}}{\sigma\sqrt{t}V_B} \Big( \lambda_1 \varphi(d_1(\frac{V_B}{k},t))- \frac{\varphi(d_1(\frac{V_B}{k},t))(\ln(\frac{V_B}{k})+\lambda_1\sigma^2 t)}{\sigma^2 t} \Big) \notag \\
		&+ \tfrac{2ke^{-rt}}{V_B^2} \Big(\lambda_2  \Phi(d_2(\tfrac{V_B}{k},t)) + \frac{ \varphi(d_2(\frac{V_B}{k},t))}{\sigma \sqrt{t}} \Big) \notag \\
		&- \tfrac{2ke^{-rt}}{\sigma \sqrt{t}V_B^2} \Big(\lambda_2 \varphi(d_2(\frac{V_B}{k},t)) - \frac{\varphi(d_2(\frac{V_B}{k},t)) (\ln(\frac{V_B}{k})+\lambda_2\sigma^2 t)}{\sigma^2 t} \Big) \notag \\
		=&\, -\tfrac{2e^{-\nu t} \ln(\frac{V_B}{k})}{\sigma^3 t\sqrt{t}V_B} \varphi(d_1(\frac{V_B}{k},t)) \notag \\
		&+ \tfrac{2ke^{-rt}}{V_B^2} \Big(\lambda_2  \Phi(d_2(\tfrac{V_B}{k},t)) + \frac{ \varphi(d_2(\frac{V_B}{k},t))}{\sigma \sqrt{t}} (1+\tfrac{\ln(\frac{V_B}{k})}{\sigma^2t}) \Big) \notag \\
		=&\, \tfrac{2ke^{-rt}}{V_B^2} \Big(\lambda_2  \Phi(d_2(\tfrac{V_B}{k},t)) + \frac{ \varphi(d_2(\frac{V_B}{k},t))}{\sigma \sqrt{t}} \Big), \label{eq: dv2 cdo<} \\
		\tfrac{\partial}{\partial V_B} [\tfrac{\partial}{\partial V} c_{do}^{V_B \geq k} (V,k,V_B,t) \big|_{V=V_B}] =&\, \tfrac{2ke^{-rt}}{V_B^2} \Big(\lambda_2  \Phi(d_2(1,t)) + \frac{ \varphi(d_2(1,t))}{\sigma \sqrt{t}} \Big). \label{eq: dv2 cdo>}
	\end{align}
	The last step in \eqref{eq: dv2 cdo<} holds since:
	\begin{align*}
		\tfrac{2e^{-\nu t} \ln(\frac{V_B}{k})}{\sigma^3 t\sqrt{t}V_B} \varphi(d_1(\frac{V_B}{k},t)) =&\, \tfrac{2e^{-\nu t} \ln(\frac{V_B}{k})}{\sigma^3 t\sqrt{t}V_B} \cdot \tfrac{1}{\sqrt{2\pi}} e^{-\frac{1}{2 \sigma^2 t} [ \ln(\frac{V_B}{k})^2 + 2 \ln(\frac{V_B}{k}) (r-\nu+\frac{\sigma^2}{2})t+((r-\nu)^2+(r-\nu)\sigma^2+\frac{\sigma^4}{4})t^2 ]} \\
		=&\, \tfrac{2ke^{-r t} \ln(\frac{V_B}{k})}{\sigma^3 t\sqrt{t}V_B^2} \cdot e^{\ln(\frac{V_B}{k})} \cdot  e^{(r-\nu)t} \\
		&\cdot \tfrac{1}{\sqrt{2\pi}}e^{-\frac{1}{2 \sigma^2 t} [ \ln(\frac{V_B}{k})^2 + 2 \ln(\frac{V_B}{k}) (r-\nu-\frac{\sigma^2}{2})t + ((r-\nu)^2-(r-\nu)\sigma^2+\frac{\sigma^4}{4})t^2 ]} \\
		&\cdot e^{-\frac{1}{2 \sigma^2 t} [2\ln(\frac{V_B}{k})\sigma^2t+2(r-\nu)\sigma^2t^2]} \\
		=&\, \tfrac{2ke^{-r t} \ln(\frac{V_B}{k})}{\sigma^3 t\sqrt{t}V_B^2} \cdot e^{\ln(\frac{V_B}{k})+(r-\nu)t} \cdot e^{-\ln(\frac{V_B}{k})-(r-\nu)t} \\
		&\cdot \tfrac{1}{\sqrt{2\pi}} e^{-\frac{1}{2} (\frac{\ln(\frac{V_B}{k})+(r-\nu-\frac{\sigma^2}{2})t}{\sigma \sqrt{t}})^2} \\
		=&\, \tfrac{2ke^{-r t} \ln(\frac{V_B}{k})}{\sigma^3 t\sqrt{t}V_B^2} \varphi(d_2(\frac{V_B}{k},t)).
	\end{align*}
	Now, evaluating \eqref{eq: dv2 cdo<} and \eqref{eq: dv2 cdo>} at $V_B=k \neq 0$ yields:
	\begin{align*}
		\tfrac{\partial}{\partial V_B}[\tfrac{\partial}{\partial V} c_{do}^{V_B \leq k} (V,k,V_B,t) \big|_{V=V_B}] \big|_{V_B=k}
		=&\, \tfrac{2e^{-rt}}{k} \Big(\lambda_2  \Phi(d_2(1,t)) + \frac{ \varphi(d_2(1,t))}{\sigma \sqrt{t}} \Big), \\
		\tfrac{\partial}{\partial V_B} [\tfrac{\partial}{\partial V} c_{do}^{V_B \geq k} (V,k,V_B,t) \big|_{V=V_B}] \big|_{V_B=k}=&\, \tfrac{2e^{-rt}}{k} \Big(\lambda_2  \Phi(d_2(1,t)) + \frac{ \varphi(d_2(1,t))}{\sigma \sqrt{t}} \Big).
	\end{align*}
	If $k=0$, Lemma \ref{lemma: cdo limit of derivative to 0 and infty}\eqref{lemma, item: k=0 limit} implies that $\tfrac{\partial}{\partial V_B}[\tfrac{\partial}{\partial V} c_{do} (V,k,V_B,t) \big|_{V=V_B}] = 0$. This shows that $h$ is continuously differentiable.

	For the second claim, we need to show that the limits of $\tfrac{\partial}{\partial V_B}[\tfrac{\partial c_{do} (V,k,V_B,T)}{\partial V} \big|_{V=V_B}]$ as $V_B \to 0$ and $V_B \to \infty$ are both bounded by $C (e^{-rT}+e^{-\nu T})$ for some constant $C>0$. The continuity then gives us the result. If $k=0$, we already know that $\tfrac{\partial}{\partial V_B}[\tfrac{\partial c_{do} (V,k,V_B,T)}{\partial V} \big|_{V=V_B}] = 0$, which trivially implies the claim. Thus, we assume $k>0$. For the limit when $V_B \to 0$, we only need to consider the case $V_B \leq k$. Each term can be individually analyzed using Lemma \ref{lemma: varphi bounded}, %Lemma \ref{lemma: varphi ln 0},
	and Lemma \ref{lemma: phi bounded} (with $\ln (\tfrac{V_B}{k})=\ln(V_B)-\ln(k)$) to ensure the boundedness of $\tfrac{\partial}{\partial V_B}[\tfrac{\partial c_{do} (V,k,V_B,T)}{\partial V} \big|_{V=V_B}]$ as $V_B \to 0$. For the limit when $V_B \to \infty$, we only need to consider the case $V_B\geq k$. In this case, we have $\lim_{V_B \to \infty} \tfrac{\partial}{\partial V_B}[\tfrac{\partial c_{do} (V,k,V_B,T)}{\partial V} \big|_{V=V_B}] = 0$. Combining these results with the continuity of $\tfrac{\partial}{\partial V_B}[\tfrac{\partial c_{do} (V,k,V_B,T)}{\partial V} \big|_{V=V_B}]$ in $V_B$, we obtain the claim.
\end{myproof}

\begin{lemma} \label{lemma: dcdo dalpha}
	%Let $V_B(0) \neq k$. Then, t
	There exists an $\hat{\alpha}>0$ and a constant $C_{\hat{\alpha}}>0$ such that $|V_B'(\alpha)| \leq C_{\hat{\alpha}}$ and $|\tfrac{\partial c_{do} (V,k,V_B(\alpha),T)}{\partial \alpha}| \leq C_{\hat{\alpha}} (e^{-\nu T}+e^{-rT})$ for all $\alpha \in [0,\hat{\alpha}]$.
\end{lemma}

\begin{myproof}%[Proof of Lemma \ref{lemma: dcdo dalpha}]
	We begin by taking the derivative of $V_B(\alpha)$. For this, we use the expression from equation \eqref{eq: formula for vb}, where we define the right-hand side as $R(\alpha,V_B)$. According to the implicit function theorem (if applicable), we have $V_B'(\alpha) = - \tfrac{R_{\alpha}(\alpha,V_B(\alpha))}{R_{V_B}(\alpha,V_B(\alpha))}$, where $R_x$ denotes the partial derivative with respect to $x$. Next, we evaluate the partial derivatives involved. With $\tfrac{\partial  c_{do} (V,k,V_B,t) }{\partial V} \big|_{V=V_B}$ as in \eqref{eq: dv cdo v=vb} and $\tfrac{\partial}{\partial V_B}[\tfrac{\partial  c_{do} (V,k,V_B,t) }{\partial V} \big|_{V=V_B}]$ as in \eqref{eq: dv2 cdo<} resp. \eqref{eq: dv2 cdo>}, we obtain (where we suppress the dependency of $V_B$ on $\alpha$):
	\begin{align}
		R_\alpha(\alpha,V_B) =&\, \tau_2 \int_0^\infty \tfrac{\partial  c_{do} (V,k,V_B,t) }{\partial V} \big|_{V=V_B} \diff t - \displaystyle\int_0^T \tfrac{\partial c_{do} (V,k,V_B,t)}{\partial V} \big|_{V=V_B} \diff t, \label{eq: ralpha}\\
		R_{V_B}(\alpha,V_B) =&\, \tfrac{1}{V_B^2} \Big( \tfrac{2(P-\frac{G}{r})A_1}{rT} + 2 \tfrac{G}{r} A_2 - \tau_1 \frac{G}{r}(\lambda_2+\lambda_3) \Big) \notag \\
		&+ \tau_2 \alpha \int_0^\infty \tfrac{\partial}{\partial V_B}[\tfrac{\partial  c_{do} (V,k,V_B,t) }{\partial V} \big|_{V=V_B}] \diff t - \alpha \displaystyle\int_0^T \tfrac{\partial}{\partial V_B}[\tfrac{\partial c_{do} (V,k,V_B,t)}{\partial V} \big|_{V=V_B}] \diff t, \label{eq: rvb}
	\end{align}
	where we are allowed to interchange the integral and the derivative due to Lemma \ref{lemma: dv2 cdo bounded l1}. Next, we note that $V_B (0) > 0$ by \eqref{eq: vb alpha=0 main text} (since $\alpha=0$ corresponds to no participation). Hence, using Lemma \ref{lemma: long term >0}, we have that $R_{V_B} (0,V_B(0)) > 0$. (This property also ensures that we can apply the implicit function theorem.) %Since $R_{V_B}(\alpha,V_B)$ is continuous by Lemma \ref{lemma: dv2 cdo bounded l1}, there exists an $\hat{\alpha} >0$ such that $R_{V_B}(s,V_B(s)) > 0$ for all $s \in [0,\hat{\alpha}]$. 
	Consequently, the implicit function theorem guarantees the existence of an $\hat{\alpha} >0$ such that $V_B(\alpha)$ is continuously differentiable in $\alpha$ for $\alpha \in [0,\hat{\alpha}]$. Thus, we have the continuity of $R_{V_B}$ in $\alpha$. As a result, possibly after reducing $\hat{\alpha}>0$, it follows that $R_{V_B}$ is bounded from below by an $\varepsilon>0$ for all $\alpha \in [0,\hat{\alpha}]$. In particular, there exists a $C_{\hat{\alpha}}$ such that $|V_B'(\alpha)| \leq C_{\hat{\alpha}}$ for all $\alpha \in [0,\hat{\alpha}]$. Moreover, we conclude from equations \eqref{eq: cd0 vb<k formula} and \eqref{eq: cd0 vb>k formula} analogously to equations \eqref{eq: derivative cdo vb<k} and \eqref{eq: derivative cdo vb>k} (with the dependence of $V_B$ on $\alpha$ suppressed) that:
	\begin{align}
		\tfrac{\partial}{\partial \alpha} c_{do}^{V_B \leq k} (V,k,V_B,T) =&\, - e^{-\nu T}2\lambda_1 (\textstyle\frac{V_B}{V})^{2\lambda_1-1} V_B'(\alpha) \Phi (d_1 (\textstyle\frac{V_B^2}{V k},T)) \notag \\
		&- V e^{-\nu T} (\textstyle\frac{V_B}{V})^{2\lambda_1} \varphi (d_1 (\textstyle\frac{V_B^2}{V k},T)) \tfrac{2}{\sigma \sqrt{T} V_B} V_B'(\alpha) \notag \\
		&+\tfrac{k}{V}e^{-rT} (2\lambda_1-2) (\textstyle\frac{V_B}{V})^{2\lambda_1-3} V_B'(\alpha) \Phi (d_2 (\textstyle\frac{V_B^2}{V k},T)) \notag \\
		&+ke^{-rT} (\textstyle\frac{V_B}{V})^{2\lambda_1-2} \varphi (d_2 (\textstyle\frac{V_B^2}{V k},T)) \tfrac{2}{\sigma \sqrt{T} V_B} V_B'(\alpha), \label{eq: dalpha cdo<} \\
		\tfrac{\partial}{\partial \alpha} c_{do}^{V_B \geq k} (V,k,V_B,T) =&\, V e^{-\nu T} \varphi (d_1 (\textstyle\frac{V}{V_B},T)) \tfrac{-1}{\sigma \sqrt{T} V_B} V_B'(\alpha) - k e^{-rT} \varphi(d_2 (\textstyle\frac{V}{V_B},T)) \tfrac{-1}{\sigma \sqrt{T} V_B} V_B'(\alpha) \notag \\
		&- e^{-\nu T}2\lambda_1(\textstyle\frac{V_B}{V})^{2\lambda_1-1} V_B'(\alpha) \Phi (d_1 (\textstyle\frac{V_B}{V},T)) \notag \\
		&- V e^{-\nu T}(\textstyle\frac{V_B}{V})^{2\lambda_1} \varphi (d_1 (\textstyle\frac{V_B}{V},T)) \tfrac{1}{\sigma \sqrt{T} V_B} V_B'(\alpha) \notag\\
		&+\tfrac{k}{V}e^{-rT} (2\lambda_1-2) (\textstyle\frac{V_B}{V})^{2\lambda_1-3} V_B'(\alpha) \Phi (d_2 (\textstyle\frac{V_B}{V},T)) \notag\\
		&+ke^{-rT} (\textstyle\frac{V_B}{V})^{2\lambda_1-2} \varphi (d_2 (\textstyle\frac{V_B}{V},T)) \tfrac{1}{\sigma \sqrt{T} V_B} V_B'(\alpha). \label{eq: dalpha cdo>}
	\end{align}
	%Since $V_B(0) \neq k$, it follows that for all $\alpha \in [0,\hat{\alpha}]$, we have either $V_B(\alpha)>k$ or $V_B(\alpha)<k$, by possibly decreasing $\hat{\alpha}>0$. 
	Next, we consider each term in the expression individually. All of these terms are bounded by $C_{\hat{\alpha}} (e^{-\nu T}+e^{-r T})$, since $V_B(\alpha)$ is bounded (by $V$ by definition) and bounded away from zero for all $\alpha \in [0,\hat{\alpha}]$ (using Lemma \ref{lem: vb neq 0} and Proposition \ref{prop: vb monoton alpha g}), with an appropriately chosen constant $C_{\hat{\alpha}}$. Therefore, the claim follows.
\end{myproof}

\begin{remark}
	We observe from equations \eqref{eq: dalpha cdo<} and \eqref{eq: dalpha cdo>} that $\tfrac{\partial c_{do} (V,k,V_B(\alpha),T)}{\partial \alpha}$ is not continuous in $\alpha$ (or alternatively in $V_B$) at $V_B(\alpha)=k$, meaning there could be a discontinuity at any $\alpha$ where $V_B(\alpha)=k$.
\end{remark}



\begin{lemma} \label{lemma: dcdo dg}
	Assume %$V_B(0) \neq k$, and 
	\begin{align*}
		\tfrac{2PA_1}{V_B(0)^2rT} &+ \tau_2 \alpha \displaystyle\int_0^\infty \tfrac{\partial}{\partial V_B}[\tfrac{\partial  c_{do} (V,k,V_B,t) }{\partial V} \big|_{V=V_B}] \big|_{V_B=V_B(0)}\diff t \\
		&- \alpha \displaystyle\int_0^T \tfrac{\partial}{\partial V_B}[\tfrac{\partial c_{do} (V,k,V_B,t)}{\partial V} \big|_{V=V_B}] \big|_{V_B=V_B(0)} \diff t \neq 0,
