\begin{myproof}%[Proof of Lemma \ref{lemma: dcdo dg}]
	This proof follows from an approach similar to the proof of Lemma \ref{lemma: dcdo dalpha}. We begin by differentiating $V_B(g)$. Again, we use \eqref{eq: formula for vb} and define the right-hand side as $R(g,V_B)$. By applying the implicit function theorem (if applicable), we obtain $V_B'(g) = - \tfrac{R_{g}(g,V_B(g))}{R_{V_B}(g,V_B(g))}$, where $R_x$ denotes the partial derivative with respect to $x$. %The term $R_{V_B}(g,V_B)$ is analogous to the expression in \eqref{eq: rvb}. Additionally, we obtain with $g=\tfrac{G}{T}$:
	With $\tfrac{\partial}{\partial V_B}[\tfrac{\partial  c_{do} (V,k,V_B,t) }{\partial V} \big|_{V=V_B}]$ as in \eqref{eq: dv2 cdo<} resp. \eqref{eq: dv2 cdo>}, we obtain (where we suppress the dependency of $V_B$ on $g$):
	\begin{align}
		R_g(g,V_B) =&\, -\tfrac{T}{V_B r} \Big( -\tfrac{2A_1}{rT} + 2A_2 - \tau_1(\lambda_2+\lambda_3) \Big), \label{eq: rg}\\
		R_{V_B}(g,V_B) =&\, \tfrac{1}{V_B^2} \Big( \tfrac{2(P-\frac{G}{r})A_1}{rT} + 2 \tfrac{G}{r} A_2 - \tau_1 \frac{G}{r}(\lambda_2+\lambda_3) \Big) \notag \\
		&+ \tau_2 \alpha \int_0^\infty \tfrac{\partial}{\partial V_B}[\tfrac{\partial  c_{do} (V,k,V_B,t) }{\partial V} \big|_{V=V_B}] \diff t - \alpha \displaystyle\int_0^T \tfrac{\partial}{\partial V_B}[\tfrac{\partial c_{do} (V,k,V_B,t)}{\partial V} \big|_{V=V_B}] \diff t, \label{eq: rvb2}
	\end{align}
	where $A_1$ and $A_2$ are defined as in \eqref{eq: a1} and \eqref{eq: a2}. By Lemma \ref{lem: vb neq 0}% and the continuity of $V_B$ in $g$
	, we know that $V_B(0) \neq 0$. %is bounded away from zero. 
	Therefore, by assumption, we have that $R_{V_B}(0,V_B(0)) \neq 0$, which can be verified by substituting $g=0$ into $R_{V_B}(g,V_B(g))$ and comparing it with the assumption of the lemma. (This property also ensures us that we can apply the implicit function theorem.) %Given the joint continuity of $R_{V_B}(g,V_B)$ and the continuity of $V_B$ in $g$, there exists a $\hat{g} >0$ such that $R_{V_B}(s,V_B(s)) \neq 0$ for all $s \in [0,\hat{g}]$. 
	By the implicit function theorem, we conclude that there exists a $\hat{g} >0$ such that $V_B(g)$ is continuously differentiable in $g$ on $[0,\hat{g}]$. This guarantees the continuity of $R_{V_B}(g,V_B(g))$ in $g$. Furthermore, possibly after reducing $\hat{g}>0$, it follows that $|R_{V_B}(g,V_B(g))|$ is bounded from below for all $g \in [0,\hat{g}]$. In particular, there exists a constant $C_{\hat{g}}$ such that $|V_B'(g)| \leq C_{\hat{g}}$ for all $g \in [0,\hat{g}]$. Additionally, similar to Lemma \ref{lemma: dv2 cdo bounded l1} (where the dependence of $V_B$ on $g$ is omitted), we obtain:
	\begin{align}
		\tfrac{\partial}{\partial g} c_{do}^{V_B \leq k} (V,k,V_B,T) =&\, - e^{-\nu T}2\lambda_1 (\textstyle\frac{V_B}{V})^{2\lambda_1-1} V_B'(g) \Phi (d_1 (\textstyle\frac{V_B^2}{V k},T)) \notag \\
		&- V e^{-\nu T} (\textstyle\frac{V_B}{V})^{2\lambda_1} \varphi (d_1 (\textstyle\frac{V_B^2}{V k},T)) \tfrac{2}{\sigma \sqrt{T} V_B} V_B'(g) \notag \\
		&+\tfrac{k}{V}e^{-rT} (2\lambda_1-2) (\textstyle\frac{V_B}{V})^{2\lambda_1-3} V_B'(g) \Phi (d_2 (\textstyle\frac{V_B^2}{V k},T)) \notag \\
		&+ke^{-rT} (\textstyle\frac{V_B}{V})^{2\lambda_1-2} \varphi (d_2 (\textstyle\frac{V_B^2}{V k},T)) \tfrac{2}{\sigma \sqrt{T} V_B} V_B'(g), \label{eq: dg cdo<} \\
		\tfrac{\partial}{\partial g} c_{do}^{V_B \geq k} (V,k,V_B,T) =&\, V e^{-\nu T} \varphi (d_1 (\textstyle\frac{V}{V_B},T)) \tfrac{-1}{\sigma \sqrt{T} V_B} V_B'(g) - k e^{-rT} \varphi(d_2 (\textstyle\frac{V}{V_B},T)) \tfrac{-1}{\sigma \sqrt{T} V_B} V_B'(g) \notag \\
		&- e^{-\nu T}2\lambda_1(\textstyle\frac{V_B}{V})^{2\lambda_1-1} V_B'(g) \Phi (d_1 (\textstyle\frac{V_B}{V},T)) \notag \\
		&- V e^{-\nu T}(\textstyle\frac{V_B}{V})^{2\lambda_1} \varphi (d_1 (\textstyle\frac{V_B}{V},T)) \tfrac{1}{\sigma \sqrt{T} V_B} V_B'(g) \notag\\
		&+\tfrac{k}{V}e^{-rT} (2\lambda_1-2) (\textstyle\frac{V_B}{V})^{2\lambda_1-3} V_B'(g) \Phi (d_2 (\textstyle\frac{V_B}{V},T)) \notag\\
		&+ke^{-rT} (\textstyle\frac{V_B}{V})^{2\lambda_1-2} \varphi (d_2 (\textstyle\frac{V_B}{V},T)) \tfrac{1}{\sigma \sqrt{T} V_B} V_B'(g). \label{eq: dg cdo>}
