	%Since $V_B(0) \neq k$, it follows that $V_B(g)>k$ or $V_B(g)<k$ for all $g \in [0,\hat{g}]$, by possibly reducing $\hat{g}$. 
	We now consider each term in the expression individually. All of these terms are bounded by $C_{\hat{g}} (e^{-\nu T}+e^{-r T})$, since $V_B$ is bounded (by $V$) and bounded away from zero for all $g \in [0,\hat{g}]$ (using Lemma \ref{lem: vb neq 0} and Proposition \ref{prop: vb monoton alpha g}), with an appropriately chosen constant $C_{\hat{g}}$. Therefore, the claim follows.
\end{myproof}

\begin{remark}
	We observe from \eqref{eq: dg cdo<} and \eqref{eq: dg cdo>} that $\tfrac{\partial c_{do} (V,k,V_B(g),T)}{\partial g}$ is also not continuous in $g$ (or alternatively in $V_B$) at $V_B(g)=k$, meaning that there may be a point of discontinuity for each $g$ such that $V_B(g)=k$.
