\section{Proof of the main results} \label{proofs}
In this section, we present the proofs for all theorems and propositions discussed in the main body of the paper.

\begin{myproof}[Proof of Theorem \ref{th: VB determination}]
	To prove this, we must explicitly calculate \eqref{eq: smooth pasting condition} using equations \eqref{eq: liability value L} and \eqref{eq: firm value v}:
	\begin{align*}
		\tfrac{\partial E(V;V_B,T)}{\partial V} \big|_{V=V_B} =&\, \tfrac{\partial v(V;V_B)}{\partial V} \big|_{V=V_B} - \tfrac{\partial L(V;V_B,T)}{\partial V} \big|_{V=V_B} \\
		=&\, \tfrac{\partial V}{\partial V} \big|_{V=V_B} + \tfrac{\partial \tau_1 \frac{G}{r} (1-(\frac{V_B}{V})^{\lambda_2+\lambda_3})}{\partial V} \big|_{V=V_B} + \tfrac{\partial \tau_2 \alpha \int_0^\infty c_{do} (V,k,V_B,t) \diff t}{\partial V} \big|_{V=V_B} \\
		&- \tfrac{\partial \rho V_B (\frac{V_B}{V})^{\lambda_2+\lambda_3}}{\partial V} \big|_{V=V_B}-\tfrac{\partial \frac{G}{r}}{\partial V} \big|_{V=V_B}-\tfrac{\partial ( P - \frac{G}{r} ) ( \frac{1-e^{-rT}}{rT} - I_1^V(T))}{\partial V} \big|_{V=V_B} \\
		&-\tfrac{\partial ( (1-\rho)V_B - \frac{G}{r} ) I_2^V(T)}{\partial V} \big|_{V=V_B} -\tfrac{\partial \alpha \int_0^T c_{do} (V,k,V_B,t) \diff t}{\partial V} \big|_{V=V_B} \\
		=&\, 1 - \tau_1 \tfrac{G}{r} \tfrac{\partial (\frac{V_B}{V})^{\lambda_2+\lambda_3}}{\partial V} \big|_{V=V_B} + \tau_2 \alpha \int_0^\infty \tfrac{\partial  c_{do} (V,k,V_B,t) }{\partial V} \big|_{V=V_B} \diff t \\
		&- \rho V_B  \tfrac{\partial (\frac{V_B}{V})^{\lambda_2+\lambda_3}}{\partial V} \big|_{V=V_B}-0+( P - \tfrac{G}{r} )\tfrac{\partial I_1^V(T)}{\partial V} \big|_{V=V_B} \\
		&-( (1-\rho)V_B - \tfrac{G}{r} )\tfrac{\partial I_2^V(T)}{\partial V} \big|_{V=V_B} - \alpha \int_0^T \tfrac{\partial c_{do} (V,k,V_B,t)}{\partial V} \big|_{V=V_B} \diff t,
	\end{align*}
	where we used Lemma \ref{lemma: cdo bounded L1} to interchange the integral with the derivative by the Leibniz integral rule (in the measure theoretic version). 

	Now, in a first step, we demonstrate the existence of a solution $V_B$ by setting the previous equation equal to zero. The definitions of $A_1$ and $A_2$ in \eqref{eq: a1} and \eqref{eq: a2}, along with Lemma \ref{lemma: i1 i2 derivative}, imply that $\tfrac{\partial I_1^V(T)}{\partial V} \big|_{V=V_B} = - \tfrac{2A_1}{rTV_B}$ and $\tfrac{\partial I_2^V(T)}{\partial V} \big|_{V=V_B} = - \tfrac{2A_2}{V_B}$. In the initial step, we will disregard the participating part by setting $\alpha=0$. Then, using Lemma \ref{lemma: i1 i2 derivative} and noting that $\tfrac{\partial (\frac{V_B}{V})^{\lambda_2+\lambda_3}}{\partial V} \big|_{V=V_B} = (-\lambda_2-\lambda_3)V_B^{\lambda_2+\lambda_3} V^{-\lambda_2-\lambda_3-1} \big|_{V=V_B} = -\tfrac{(\lambda_2+\lambda_3)}{V_B}$, we have:
	\begin{align}
		0 &= 1 + \tfrac{\tau_1 \frac{G}{r}(\lambda_2+\lambda_3)}{V_B} + \tfrac{\rho V_B(\lambda_2+\lambda_3)}{V_B}-\tfrac{2(P-\frac{G}{r})A_1}{rTV_B} + \tfrac{2((1-\rho)V_B-\frac{G}{r})A_2}{V_B} \notag \\
		&= 1 + \rho(\lambda_2+\lambda_3)+2(1-\rho)A_2 - \tfrac{1}{V_B} \Big( \tfrac{2(P-\frac{G}{r})A_1}{rT} + 2 \tfrac{G}{r} A_2 - \tau_1 \frac{G}{r}(\lambda_2+\lambda_3) \Big) =: h_1(V_B). \label{eq: def h1}
	\end{align}
	Solving this equation for $V_B$ yields:
	\begin{align} \label{eq: vb alpha=0}
		V_B^* = \frac{\tfrac{2(P-\frac{G}{r})A_1}{rT} + 2 \tfrac{G}{r} A_2 - \tau_1 \frac{G}{r}(\lambda_2+\lambda_3)}{1 + \rho(\lambda_2+\lambda_3)+2(1-\rho)A_2},
	\end{align}
	where Lemma \ref{lemma: long term >0} guarantees that the nominator and the denominator are positive, ensuring that $V_B^*$ is positive and well-defined. %Moreover, we can conclude from Lemma \ref{lemma: ass reformulation derivative} that the nominator is positive for $P=0$ and therefore for all $P \geq 0$ since $A_1 >0$ by Lemma \ref{lemma: a1,a2,a3,a4>0}. %This is because the value of the guaranteed payment for both the liabilities and the tax benefit is zero at the bankruptcy-triggering value. Therefore, the assumption implies that the marginal value (for an additional asset value) of the liabilities at $V_B$, arising from the guaranteed payment, $\tfrac{-2\frac{G}{r}A_1}{rT} + 2 \tfrac{G}{r} A_2$, exceeds the marginal value of the tax benefit at $V_B$, which is $\tau_1 \frac{G}{r}(\lambda_2+\lambda_3)$.

	Specifically, we find that $V_B^*>0$ solves $h_1(V_B)=0$. Since $h$ is increasing in $V_B$, we have $h_1(V) < 0$ for all $V<V_B^*$ and $h(V) > 0$ for all $V>V_B^*$. In particular, by Lemma \ref{lemma: term bigger 0 for vb},we obtain:
	\begin{align}
