	\end{align}	
	Next, we incorporate the term with the participation component. Consequently, $\tfrac{\partial E(V;V_B,T)}{\partial V} \big|_{V=V_B}=0$ is equivalent to
	\begin{align} \label{eq: def of h2}
		0 &= h_1(V_B) + \tau_2 \alpha \int_0^\infty \tfrac{\partial  c_{do} (V,k,V_B,t) }{\partial V} \big|_{V=V_B} \diff t - \alpha \displaystyle\int_0^T \tfrac{\partial c_{do} (V,k,V_B,t)}{\partial V} \big|_{V=V_B} \diff t =: h_2(V_B).
