\begin{myproof}[Proof of Proposition \ref{prop: vb monoton tau T}]
	If $\tau_2$ increases, we observe that the right-hand side of \eqref{eq: formula for vb} also increases. From the proof of Theorem \ref{th: VB determination}, we know that the largest solution of \eqref{eq: formula for vb} corresponds to a sign transition from ``$-$'' to ``$+$'' (or to a local minimum, with the function being positive to the right-hand side of the zero root). Therefore, as the graph shifts upwards, the zero root decreases showing that $V_B$ is increasing in $\tau_2$.

	We know that the positive value $\tfrac{2(P-\frac{G}{r})A_1}{rT} + 2 \tfrac{G}{r} A_2 - \tau_1 \frac{G}{r}(\lambda_2+\lambda_3)$ decreases if $\tau_1$ increases. (Note that positivity is ensured by Lemma \ref{lemma: long term >0}.) Therefore, the zero root $V_B$ must also decrease in order to maintain the equality, ensuring that the right-hand side of equation \eqref{eq: formula for vb} remains zero.

	The argument for the contract maturity $T$ follows analogously, but in the opposite direction in both cases. Indeed, an increasing $T$ leads to lower values on the right-hand side of equation \eqref{eq: formula for vb} in the participation component, while simultaneously increasing $\tfrac{2(P-\frac{G}{r})A_1}{rT} + 2 \tfrac{G}{r} A_2 - \tau_1 \frac{G}{r}(\lambda_2+\lambda_3)$ under the assumption that $P - \tfrac{G}{r} \leq 0$. Therefore, as $T$ increases, the bankruptcy-triggering value increases as well.
\end{myproof}

\begin{myproof}[Proof of Proposition \ref{prop: vb monoton alpha g}]
	%We note that the value of the surplus participation is zero for both the tax benefit and the liabilities when the asset value is equal to the bankruptcy-triggering value. Hence, the assumption that the liability value of surplus participation exceeds the associated tax benefit implies that the marginal value (for additional asset value) of liabilities at $V_B$ due to surplus participation, given by $\int_0^T \frac{\partial c_{do} (V,k,V_B,t)}{\partial V} \big|_{V=V_B} \diff t$ exceeds the marginal value of the associated tax benefit at $V_B$, given by $\tau_2 \int_0^\infty \frac{\partial  c_{do} (V,k,V_B,t) }{\partial V} \big|_{V=V_B} \diff t$ for all $V_B$. Here, $\frac{\partial c_{do} (V,k,V_B,t)}{\partial V} \big|_{V=V_B}$ is defined as in \eqref{eq: dv cdo v=vb}.

	To show that $V_B$ is monotonically increasing in $\alpha$, let $0 \leq \alpha_1 < \alpha_2$, and we aim to prove that $V_B(\alpha_1) < V_B(\alpha_2)$. By Theorem \ref{th: VB determination}, we know that:
	\begin{align}
		0 =&\, 1 + \rho(\lambda_2+\lambda_3)+2(1-\rho)A_2 - \tfrac{1}{V_B(\alpha_1)} \Big( \tfrac{2(P-\frac{G}{r})A_1}{rT} + 2 \tfrac{G}{r} A_2 - \tau_1 \frac{G}{r}(\lambda_2+\lambda_3) \Big) \notag \\
		&+ \tau_2 \alpha_1 \int_0^\infty \tfrac{\partial  c_{do} (V,k,V_B(\alpha_1),t) }{\partial V} \big|_{V=V_B(\alpha_1)} \diff t - \alpha_1 \displaystyle\int_0^T \tfrac{\partial c_{do} (V,k,V_B(\alpha_1),t)}{\partial V} \big|_{V=V_B(\alpha_1)} \diff t. \label{eq: solution formula vb(alpha1)}
	\end{align}
	Using Lemma \ref{lemma: ass reformulation derivative}, we get, in particular, that:
	\begin{align*}
		0 >&\, 1 + \rho(\lambda_2+\lambda_3)+2(1-\rho)A_2 - \tfrac{1}{V_B(\alpha_1)} \Big( \tfrac{2(P-\frac{G}{r})A_1}{rT} + 2 \tfrac{G}{r} A_2 - \tau_1 \frac{G}{r}(\lambda_2+\lambda_3) \Big) \notag \\
		&+ \tau_2 \alpha_2 \int_0^\infty \tfrac{\partial  c_{do} (V,k,V_B(\alpha_1),t) }{\partial V} \big|_{V=V_B(\alpha_1)} \diff t - \alpha_2 \displaystyle\int_0^T \tfrac{\partial c_{do} (V,k,V_B(\alpha_1),t)}{\partial V} \big|_{V=V_B(\alpha_1)} \diff t.
	\end{align*}
	Since the right-hand side converges to a positive number (or to $0$ from above) as $V_B \to \infty$ (see \ref{eq: limit h2 inf}) and as $V_B(\alpha_1)$ is the largest solution of \eqref{eq: solution formula vb(alpha1)}, we conclude that $V_B(\alpha_2) > V_B(\alpha_1)$. %This means that the right-hand side of the equation as a function of $V_B$ must intersect the $x$-axis at a point larger than $V_B(\alpha_1)$. This follows from the intermediate value theorem (which applies since the right-hand side is continuous in $V_B$).

	Second, we demonstrate the right-continuity in $\alpha$. Let $f: [0,\infty) \times [0,\infty) \to \Real$ be a jointly continuous function satisfying $\lim_{x \to 0} f(x,v) = -\infty$, $\lim_{x \to \infty} f(x,v) = c(v) \geq 0$, and assume that for all $v \in [0,\infty)$ there exists a $\tilde{x}(v) \in (0,\infty)$ such that $f(\tilde{x}(v),v) = 0$. Since the right-hand side of \eqref{eq: formula for vb} satisfies the properties of $f$, it remains to show that $w(v) := \sup \{y \in [0,\infty): f(y,v)=0 \}$ is right-continuous under the assumption that $w$ is monotonically increasing (which was established in the first part of this proof). Note that the assumption that for all $v \in [0,\infty)$ there exists a $\tilde{x}(v) \in (0,\infty)$ such that $f(\tilde{x}(v),v) = 0$ implies that $\{y \in [0,\infty): f(y,v)=0 \} \neq \emptyset$ for all $v \in [0,\infty)$. %Indeed, we can limit our analysis to $\alpha<\bar{\alpha}$, because for $\alpha>\bar{\alpha}$, it holds that $\lim_{V_B \to \infty} h_2(V_B) <0$ (see \eqref{eq: limit h2 inf} and the definition of $\bar{\alpha}$ in \eqref{eq: baralpha}). This leads to a contradiction with the assumption that $V \to E(V)$ is non-decreasing, as pointed out in the proof of Theorem \ref{th: VB determination}. Consequently, since then the right-continuity in $\bar{\alpha}$ is trivial, we can restrict our attention to the case that $\alpha<\bar{\alpha}$. 
	%Since $w$ is monotonically increasing, $w$ has only countably many points of discontinuity. Let $v_1$ be such a point of discontinuity. First, we observe that there exists a small interval around $v_1$ that contains no other point of discontinuity. We choose $\delta$ sufficiently small such that $v_1+\delta$ is still contained within this interval. 
	Let $v_1 \geq 0$. Since $w$ is increasing, we know that $w(v_1+\delta) \geq w(v_1)$ for all $\delta>0$. Now, suppose that there exists an $\varepsilon>0$ such that $w(v_1+\delta) \geq w(v_1)+\varepsilon$ for all $\delta>0$. Due to the monotonicity of $w$, there exists a bound $\tilde{x}$ with $w(v_1)+\varepsilon \leq \tilde{x} = \lim_{\delta \downarrow 0} w(v_1+\delta)$. By definition of $w$ and the joint continuity of $f$, we have: $0 = f(w(v_1+\delta),v_1+\delta) \xrightarrow{\delta \to 0} f(\tilde{x},v_1)$. In particular, $\tilde{x} > w(v_1)$ is a zero root of $y \to f(y,v_1)$. However, this contradicts the definition of $w(v_1)$ as the supremum of the zero root of $y \to f(y,v_1)$. Therefore, no such $\varepsilon>0$ can exist, and the right-continuity in $\alpha$ follows.
	%Next, if $w(v_1)$ is not a (possibly non-strict) local minimum of $y \to f(y,v_1)$, then by the implicit function theorem, $w$ is continuous in $v_1$. Thus, it remains to check the right-continuity when $w(v_1)$ is a local minimum of $y \to f(y,v_1)$. By the definition of $w(v_1)$ as the supremum of the zero roots, we know that $f(x,v_1)>0$ for all $x>w(v_1)$. Furthermore, since $\lim_{x \to \infty} f(x,v) = c(v)>0$, and by the definition of $w(v_1)$, for any $\delta>0$, there exists an $\varepsilon>0$ such that $f(x,v_1) > \varepsilon$ for all $x \geq w(v_1) + \delta$. Therefore, since $f$ is continuous and there are no discontinuities in an interval around $v_1$, increasing $v_1$ by a sufficiently small amount will not introduce any new intersections with the $x$-axis. Now, since $w$ is monotonically increasing, the zero root(s) near $w(v_1)$ cannot vanish as $v_1$ increases. Hence, by choosing $v_2>v_1$ sufficiently small, the largest zero root of $v_2$ will only be slightly larger than $w(v_1)$, which establishes us the right-continuity of $w$. 

	Third, the existence of the left-limits follows directly from the monotonicity.

	The proof for the guaranteed payment proceeds similarly. We observe that, under the assumption on the value of the guaranteed payments, the term $\tfrac{2(P-\frac{G}{r})A_1}{rT} + 2 \tfrac{G}{r} A_2 - \tau_1 \frac{G}{r}(\lambda_2+\lambda_3)$ is increasing in $G$ (as analyzed in the proof of Theorem \ref{th: VB determination}), while the other terms depend on $G$ only through $V_B$. Therefore, an analogous reasoning leads to the same conclusion about the behavior of $V_B$ with respect to $G$.
\end{myproof}

\begin{remark}
	Note that left-continuity is not shown in Proposition \ref{prop: vb monoton alpha g} for the following two reasons: (i) If an additional intersection of the right-hand side of \eqref{eq: formula for vb} with $0$ occurs when increasing $\alpha$ (resp. $g$), and this intersection becomes the largest zero root, then the zero root will have a left limit in $\alpha$ (resp. $g$), but it will be not left-continuous. Specifically, when a new intersection appears and becomes the largest zero root, the left-continuity of the zero root fails. (ii) If there exists an interval of zero roots that includes the largest zero root, left-continuity can fail as well. However, a left limit still exists, and this limit belongs to this interval of zero roots. By definition, however, we select the largest zero root, which lies on the right-hand side of this interval and thus is not the left limit.
	%
	%In summary, we observe that while left-limits of $V_B$ with respect to $\alpha$ and $g$ exist, these left-limits are still zero roots. However, in certain special cases, these zero roots may no longer be the largest ones, and therefore, left-continuity may fail.
\end{remark}

\begin{myproof}[Proof of Proposition \ref{prop: alpha bar competitive market}]
	As in the previous proof of Theorem \ref{th: VB determination}, we observe that the assumption of $V \to E(V)$ being non-decreasing is implied by $\lim_{V_B \to \infty} h_2(V_B) = \linebreak \lim_{V_B \to \infty} \tfrac{\partial E(V;V_B,T)}{\partial V} \big|_{V=V_B}>0$ with $h_2$ defined as in \eqref{eq: def of h2}. Let $\tau_2 A_3 < A_4$. Then, if $\alpha<\bar{\alpha} = \dfrac{1+\rho(\lambda_2+\lambda_3)+2(1-\rho)A_2}{A_4-\tau_2A_3}$, we have that $\lim_{V_B \to \infty} h_2(V_B)>0$ by \eqref{eq: limit h2 inf}, which implies the claim. On the other hand, if $\tau_2 A_3 \geq A_4$, then $\lim_{V_B \to \infty} h_2(V_B) \geq 0$ for all $\alpha \geq 0$ by \eqref{eq: limit h2 inf} and Lemma \ref{lemma: long term >0}, implying the claim.
\end{myproof}

\begin{remark} \label{rem: alpha bar competitive >}
	In the context of the proof of Proposition \ref{prop: alpha bar competitive market} above, we observe that the assumption of $V \to E(V)$ being non-decreasing fails if $\lim_{V_B \to \infty} h_2(V_B) = \lim_{V_B \to \infty} \tfrac{\partial E(V;V_B,T)}{\partial V} \big|_{V=V_B} < 0$. Analogously to the earlier discussion, this corresponds to the case $\alpha > \bar{\alpha}$. However, if $\lim_{V_B \to \infty} h_2(V_B) = \lim_{V_B \to \infty} \tfrac{\partial E(V;V_B,T)}{\partial V} \big|_{V=V_B} = 0$, the analysis becomes more delicate. In this case, it is essential to distinguish whether the limit is approached from above or below (cf. the discussion in the proof of Theorem \ref{th: VB determination}).
\end{remark}

\begin{myproof}[Proof of Corollary \ref{cor: vb determination}]
	Let us assume that $V_B \geq k$, i.e., $\min\{\tfrac{V_B}{k},1\}=1$. Note that $d_1(1,T) = \lambda_1 \sigma \sqrt{T}$ and $d_2(1,T) = \lambda_2 \sigma \sqrt{T}$. Then, we get, using \eqref{eq: dv cdo v=vb} and Lemma \ref{lemma: explicit calculation integral} (once applied in the original version, and once applied with $\lambda_1$ replaced by $\lambda_2$, and $\nu$ replaced by $r$):
	\begin{align}
		\int_0^\infty \tfrac{\partial  c_{do} (V,k,V_B,t) }{\partial V} \big|_{V=V_B} \diff t =&\, \tfrac{\lambda_1}{\nu} + \tfrac{\lambda_1^2 \sigma}{\nu} \sqrt{\tfrac{1}{\lambda_1^2\sigma^2+2\nu}} + \tfrac{2}{\sigma} \sqrt{\tfrac{1}{\lambda_1^2\sigma^2+2\nu}} \notag \\
		&- \tfrac{k}{V_B} \Big( \tfrac{\lambda_2}{r} + \tfrac{\lambda_2^2 \sigma}{r} \sqrt{\tfrac{1}{\lambda_2^2\sigma^2+2r}} + \tfrac{2}{\sigma} \sqrt{\tfrac{1}{\lambda_2^2\sigma^2+2r}} \Big) \notag \\
		=&\, A_3 - \tfrac{k}{V_B} A_5, \label{eq: integral infty del cdo v=vb}\\
		\int_0^T \tfrac{\partial  c_{do} (V,k,V_B,t) }{\partial V} \big|_{V=V_B} \diff t =&\, \tfrac{\lambda_1}{\nu} - \tfrac{2\lambda_1 e^{-\nu T} \Phi(\lambda_1\sigma\sqrt{T})}{\nu} + \tfrac{\lambda_1^2 \sigma}{\nu} \sqrt{\tfrac{1}{\lambda_1^2\sigma^2+2\nu}} (2\Phi(\sqrt{\lambda_1^2 \sigma^2 + 2\nu}\sqrt{T})-1) \notag \\
		&+ \tfrac{2}{\sigma} \sqrt{\tfrac{1}{\lambda_1^2\sigma^2+2\nu}} (2\Phi(\sqrt{\lambda_1^2 \sigma^2 + 2\nu}\sqrt{T})-1) \notag \\
		&- \tfrac{k}{V_B} \Big( \tfrac{\lambda_2}{r} - \tfrac{2\lambda_2 e^{-r T} \Phi(\lambda_2\sigma\sqrt{T})}{r} + \tfrac{\lambda_2^2 \sigma}{r} \sqrt{\tfrac{1}{\lambda_2^2\sigma^2+2r}} (2\Phi(\sqrt{\lambda_2^2 \sigma^2 + 2r}\sqrt{T})-1) \notag \\
		&\hspace{30pt}+ \tfrac{2}{\sigma} \sqrt{\tfrac{1}{\lambda_2^2\sigma^2+2r}} (2\Phi(\sqrt{\lambda_2^2 \sigma^2 + 2r}\sqrt{T})-1) \Big) \notag \\
		=&\, A_4 - \tfrac{k}{V_B} A_6, \label{eq: integral T del cdo v=vb}
	\end{align}
	where we used that $\Big(\tfrac{\lambda_1^2 \sigma}{\nu} + \tfrac{2}{\sigma}\Big) \sqrt{\tfrac{1}{\lambda_1^2\sigma^2+2\nu}} = \tfrac{1}{\sigma \nu} \sqrt{\lambda_1^2 \sigma^2 + 2\nu}$ and $\Big(\tfrac{\lambda_2^2 \sigma}{r} + \tfrac{2}{\sigma}\Big) \sqrt{\tfrac{1}{\lambda_2^2\sigma^2+2r}} = \tfrac{1}{\sigma r} \sqrt{\lambda_2^2 \sigma^2 + 2r}$. Next, we substitute \eqref{eq: integral infty del cdo v=vb} and \eqref{eq: integral T del cdo v=vb} into \eqref{eq: formula for vb} and solve for $V_B$, yielding the formula for $\hat{V}_B$. In particular, if $\hat{V}_B\geq k$, it is the unique solution to \eqref{eq: formula for vb} that satisfies this condition. Therefore, the claim follows.
\end{myproof}

