\begin{myproof}[Proof of Theorem \ref{th: alpha*}]
	Before we begin the actual proof, we first show the identities used in the theorem: From the proof of Lemma \ref{lemma: dcdo dalpha}, we find that $V_B'(\alpha) = - \tfrac{R_{\alpha}(\alpha,V_B(\alpha))}{R_{V_B}(\alpha,V_B(\alpha))}$ for $\alpha \in [0,\hat{\alpha}]$, where $R_{\alpha}$ is defined as in \eqref{eq: ralpha}, $R_{V_B}$ is defined as in \eqref{eq: rvb}, and $\hat{\alpha}>0$ is defined as in Lemma \ref{lemma: dcdo dalpha}. Substituting $\alpha=0$ gives us \eqref{eq: partial vb0} and \eqref{eq: formula dvb dalpha}. Finally, \eqref{eq: partial cdo} follows immediately from \eqref{eq: dv2 cdo<} and \eqref{eq: dv2 cdo>}.

	For the main claim, we consider the total value $v$ of the insurance company as given in \eqref{eq: firm value v} and take the derivative with respect to $\alpha$. We restrict ourselves to $\alpha \in [0,\hat{\alpha}]$, with $\hat{\alpha}$ defined as in Lemma \ref{lemma: dcdo dalpha}. Under these conditions, we can interchange the integral and the derivative (where we suppress the dependency of $V_B$ on $\alpha$):
	\begin{align}
		\tfrac{\partial}{\partial \alpha} v(V;V_B) =&\, - \tfrac{\tau_1 \frac{G}{r} (\lambda_2+\lambda_3)}{V} (\tfrac{V_B}{V})^{\lambda_2+\lambda_3-1} V_B'(\alpha) - \rho (\lambda_2+\lambda_3+1) (\tfrac{V_B}{V})^{\lambda_2+\lambda_3} V_B'(\alpha) \notag\\
		&+ \tau_2 \int_0^\infty c_{do} (V,k,V_B,t) \diff t + \alpha \tau_2 \int_0^\infty \tfrac{\partial c_{do} (V,k,V_B,T)}{\partial \alpha} \diff t \notag \\
		=&\, -V_B'(\alpha) (\tfrac{V_B}{V})^{\lambda_2+\lambda_3} \left( \tfrac{\tau_1 \frac{G}{r} (\lambda_2+\lambda_3)}{V_B} + \rho (\lambda_2+\lambda_3+1) \right)  \notag\\
		&+ \tau_2 \int_0^\infty c_{do} (V,k,V_B,t) \diff t + \alpha \tau_2 \int_0^\infty \tfrac{\partial c_{do} (V,k,V_B,T)}{\partial \alpha} \diff t. \label{eq: dv dalpha}
	\end{align}
	Setting this equation equal to zero yields \eqref{eq: solution alpha*}. %Moreover, if $\tfrac{\partial}{\partial \alpha} v(V;V_B) > 0$ for all $\alpha \in [0,\min\{1,\bar{\alpha}\}]$, it follows that $\alpha^* = \min\{1,\bar{\alpha}\}$. Conversely, if $\tfrac{\partial}{\partial \alpha} v(V;V_B) < 0$ for all $\alpha \in [0,\min\{1,\bar{\alpha}\}]$, then $\alpha^* = 0$.

	Next, we show the existence of a $\bar{\tau}$ as described in the theorem. To do this, we evaluate the above formula at $\alpha=0$, which gives us:
	\begin{align}
		\tfrac{\partial}{\partial \alpha} v(V;V_B) \big|_{\alpha=0} =&\, -V_B'(0) (\tfrac{V_B(0)}{V})^{\lambda_2+\lambda_3} \left( \tfrac{\tau_1 \frac{G}{r} (\lambda_2+\lambda_3)}{V_B(0)} + \rho (\lambda_2+\lambda_3+1) \right) \notag \\
		&+ \tau_2 \int_0^\infty c_{do} (V,k,V_B(0),t) \diff t. \label{eq: dv dalpha alpha0}
	\end{align}
	Now, it is optimal to offer a surplus participation for the insurance company if $\tfrac{\partial}{\partial \alpha} v(V;V_B) \big|_{\alpha=0}>0$. 

	Therefore, let us analyze equation \eqref{eq: dv dalpha alpha0}: Lemma \ref{lemma: long term >0} implies that $V_B(0)>0$ (see \eqref{eq: vb alpha=0 main text}), and that the denominator of $V_B'(0)$ (see \eqref{eq: partial vb0}) is strictly positive. Moreover, $\Big( \tfrac{\tau_1 \frac{G}{r} (\lambda_2+\lambda_3)}{V_B(0)} + \rho (\lambda_2+\lambda_3+1) \Big)>0$, since $\lambda_3>|\lambda_2|$ by definition, %. %Additionally, 
	the price of a Down-and-Out Call Option, $c_{do}$, is non-negative, $V_B(0)$ (see \eqref{eq: vb alpha=0 main text}) is independent of $\tau_2$, and %, and $\tfrac{\partial}{\partial \tau_2}V_B'(0) \leq 0$ (see \eqref{eq: partial vb0}) by Lemma \ref{lemma: long term >0}, and since the price a Down-and-Out Call Option, $c_{do}$, is non-decreasing in the initial asset value. Thus, we conclude that 
	%\begin{align*}
		%\tfrac{\partial}{\partial \tau_2} \Big(\tfrac{\partial}{\partial \alpha} v(V;V_B) \big|_{\alpha=0}\Big) =&\, - (\tfrac{\partial}{\partial \tau_2}V_B'(0)) (\tfrac{V_B(0)}{V})^{\lambda_2+\lambda_3} \left( \tfrac{\tau_1 \frac{G}{r} (\lambda_2+\lambda_3)}{V_B(0)} + \rho (\lambda_2+\lambda_3+1) \right) \notag \\
		%&+  \int_0^\infty c_{do} (V,k,V_B(0),t) \diff t >0.
	%\end{align*}
	%In particular, for $\tau_2=1$, the term $(-V_B'(0))$ (see \eqref{eq: partial vb0}) is positive, as $T < \infty$, and it is negative for $\tau_2=0$. Thus, we observe that $\tfrac{\partial}{\partial \alpha} v(V;V_B) \big|_{\alpha=0}<0$ for $\tau_2=0$ and $\tfrac{\partial}{\partial \alpha} v(V;V_B) \big|_{\alpha=0}>0$ for $\tau_2=1$. 
	%Furthermore, 
	for $\tau_2=1$ the term $(-V_B'(0))$ (see \eqref{eq: partial vb0}) is positive because $T < \infty$. Consequently, we obtain that $\tfrac{\partial}{\partial \alpha} v(V;V_B) \big|_{\alpha=0}>0$ for $\tau_2=1$, and that $\tfrac{\partial}{\partial \alpha} v(V;V_B) \big|_{\alpha=0}$ is continuous in $\tau_2$. This leads to the existence of a $\bar{\tau} \in (0,1)$ such that $\tfrac{\partial}{\partial \alpha} v(V;V_B) \big|_{\alpha=0}>0$ for $\tau_2 \in (\bar{\tau},1)$, implying the claim.

	 Finally, it remains to demonstrate the existence of $\bar{\bar{\tau}}$. To establish this, we have by \eqref{eq: dv dalpha}:
	 \begin{align*}
	 	\tfrac{\partial}{\partial \alpha} v(V;V_B) \big|_{\tau_2=0} =  -V_B'(\alpha) (\tfrac{V_B}{V})^{\lambda_2+\lambda_3} \left( \tfrac{\tau_1 \frac{G}{r} (\lambda_2+\lambda_3)}{V_B} + \rho (\lambda_2+\lambda_3+1) \right) < 0,
	 \end{align*}
	 since $\lambda_3>|\lambda_2|$ by definition and $V_B'(\alpha)>0$ (since $V_B$ is increasing in $\alpha$ by Proposition \ref{prop: vb monoton alpha g}). Hence, it follows that if $\tau_2=0$, the optimal choice is $\alpha^*=0$. Moreover, the inequality
	 \begin{align*}
	 	-V_B'(\alpha) (\tfrac{V_B}{V})^{\lambda_2+\lambda_3} \left( \tfrac{\tau_1 \frac{G}{r} (\lambda_2+\lambda_3)}{V_B} + \rho (\lambda_2+\lambda_3+1) \right) < 0
	 \end{align*}
	 persists independently of the specific choice of $\tau_2$. Finally, since $\int_0^\infty c_{do} (V,k,V_B,t) \diff t + \linebreak \alpha \int_0^\infty \tfrac{\partial c_{do} (V,k,V_B,T)}{\partial \alpha} \diff t$ in \eqref{eq: dv dalpha} is bounded (by Lemmas \ref{lem: int cdo < infty} and \ref{lemma: dcdo dalpha}), it follows that
	 %Given that $\tfrac{\partial}{\partial \alpha} v(V;V_B)$ is continuous in $\tau_2$,
	 there exists a value $\bar{\bar{\tau}} > 0$ such that $\tfrac{\partial}{\partial \alpha} v(V;V_B)<0$ for all $0 \leq \tau_2 < \bar{\bar{\tau}}$, implying that $\alpha^*=0$ for all $0 \leq \tau_2 < \bar{\bar{\tau}}$. Thus, the claim is established.
