\begin{myproof}[Proof of Proposition \ref{prop: gstar exists}]
	%By Proposition \ref{prop: vb monoton alpha g}, we know that $g \to V_B(g)$ is monotonically increasing and right-continuous and thus upper semi-continuous. 

	Since $v$ is continuous in $g$ (because $V_B$ is continuous in $g$), it suffices to show that the supremum is attained in a compact interval of $g$. First, assume that $-\tfrac{2A_1}{rT} + 2 A_2 - \tau_1 (\lambda_2+\lambda_3) \neq 0$. By Lemma \ref{lemma: cdo unif bounded L1}, it follows that the term $\tau_2 \alpha \int_0^\infty \tfrac{\partial  c_{do} (V,k,V_B,t) }{\partial V} \big|_{V=V_B} \diff t - \alpha \int_0^T \tfrac{\partial c_{do} (V,k,V_B,t)}{\partial V} \big|_{V=V_B} \diff t$ is uniformly bounded in $V_B$, and thus in $g$. From equation \eqref{eq: formula for vb}, we know that $V_B \xrightarrow{g \to \infty} \infty$ (using that $g = \tfrac{G}{T}$). Therefore, by the continuity of $V_B$ in $g$, there exists a $\bar{g} \geq 0$ such that $V_B(g) \geq V_0$ for all $g \geq \bar{g}$. If $V_B \geq V_0$, however, the insurance company declares bankruptcy immediately. In this case, the insurance company's value is given by $v(V;V_B) = V - \rho V$ for all $V_B \geq V_0$, according to the first equation in \eqref{eq: firm value v}, where $TB_1 = TB_2 = 0$ and $BC = \rho V$ (see \eqref{eq: def TB1}, \eqref{eq: def TB2}, and \eqref{eq: def BC}). Therefore, $v$ is constant for $V_B \geq V_0$, and we can consequently set $V_B=V_0$. Hence, we can restrict $g$ to the interval $[0,\bar{g}]$, completing the proof.
\end{myproof}

\begin{myproof}[Proof of Theorem \ref{th: g*}]
	Note that this proof is similar to the proof of Theorem \ref{th: alpha*}.

	We begin by showing the identities stated in the theorem: Equation \eqref{eq: vb0 g} follows directly from \eqref{eq: formula for vb}. Next, from the proof of Lemma \ref{lemma: dcdo dg}, we obtain that $V_B'(g) = - \tfrac{R_{g}}{R_{V_B}}$, where $R_{g}$ is defined in \eqref{eq: rg} and $R_{V_B}$ is defined in \eqref{eq: rvb2}. Evaluating this expression at $g=0$ and inserting $V_B(0)$ gives us the desired results in \eqref{eq: formula dvb dg} and \eqref{eq: partial vb0 g}. Finally, the equations \eqref{eq: partial cdo g} and \eqref{eq: partial cdo g0} are immediate consequences of \eqref{eq: dv2 cdo<} and \eqref{eq: dv2 cdo>}.

	For the main claim \eqref{eq: solution g*}, we again utilize the total value $v$ of the insurance company, as defined in \eqref{eq: firm value v}, and differentiate it with respect to $g$. We consider $g \in [0,\hat{g}]$, where $\hat{g}$ is defined as in Lemma \ref{lemma: dcdo dg}, such that we can interchange the integral and the derivative (where we suppress the dependency of $V_B$ on $g$):
	\begin{align}
		\tfrac{\partial}{\partial g} v(V;V_B) =&\, \tfrac{\tau_1T}{r} (1-(\tfrac{V_B}{V})^{\lambda_2+\lambda_3})  - \tfrac{\tau_1 gT (\lambda_2+\lambda_3)}{Vr} (\tfrac{V_B}{V})^{\lambda_2+\lambda_3-1} V_B'(g) \notag \\ 
		&- \rho (\lambda_2+\lambda_3+1) (\tfrac{V_B}{V})^{\lambda_2+\lambda_3} V_B'(g) + \alpha \tau_2 \int_0^\infty \tfrac{\partial c_{do} (V,k,V_B,T)}{\partial g} \diff t. \label{eq: dv dg}
	\end{align}
	Setting this equation equal to zero results in the equation \eqref{eq: solution g*}.

	It remains to demonstrate that offering a guarantee rate is indeed optimal. To do so, we evaluate this formula at $g=0$, which leads to:
	\begin{align}
		\tfrac{\partial}{\partial g} v(V;V_B) \big|_{g=0} =&\, \tfrac{\tau_1 T}{r} (1-(\tfrac{V_B(0)}{V})^{\lambda_2+\lambda_3}) - \rho (\lambda_2+\lambda_3+1) (\tfrac{V_B(0)}{V})^{\lambda_2+\lambda_3} V_B'(0) \notag \\
		&+ \alpha \tau_2 \int_0^\infty \tfrac{\partial c_{do} (V,k,V_B,T)}{\partial g} \Big|_{g=0} \diff t >0, \label{eq: dv dg0}
	\end{align}
	by assumption. Note that we applied Lemma \ref{lemma: dcdo dg} to move the point estimation inside the integral. Therefore, it follows that $g^*>0$.
\end{myproof}

\begin{myproof}[Proof of Proposition \ref{prop: alphastar and gstar exists}]
	This proposition follows directly from Propositions \ref{prop: alphastar exists} and \ref{prop: gstar exists}. Note that the proof of Proposition \ref{prop: alphastar exists} is independent of $g$, and the proof of Proposition \ref{prop: gstar exists} holds for all $\alpha \leq 1$.
\end{myproof}

\section{Additional results}

In this section, we present additional results that are referenced in the main text.

\begin{proposition} \label{prop: assumption fulfilled}
	If (i) $V_B \geq k$ or (ii) $V_B < k$ and the following condition (with $d_2$ as in \eqref{eq: def d12 lambda1} and $\lambda_2,\lambda_3$ as in \eqref{eq: def lambda23}) holds for all $\alpha \in [0,\min\{\bar{\alpha},1\}]$, then the bankruptcy-triggering value $V_B$ is continuous in $\alpha$:
	\begin{align} \label{eq: assumption fulfilled equation}
		\tfrac{2(P-\frac{G}{r})A_1}{rT} &+ 2 \tfrac{G}{r} A_2 - \tau_1 \frac{G}{r}(\lambda_2+\lambda_3) + \tau_2 \alpha \displaystyle\int_0^\infty 2ke^{-rt} \big(\lambda_2  \Phi(d_2(\tfrac{V_B}{k},t)) + \frac{ \varphi(d_2(\frac{V_B}{k},t))}{\sigma \sqrt{t}} \big) \diff t \notag \\
		&- \alpha \int_0^T 2ke^{-rt} \big(\lambda_2  \Phi(d_2(\tfrac{V_B}{k},t)) + \frac{ \varphi(d_2(\frac{V_B}{k},t))}{\sigma \sqrt{t}} \big) \diff t >0,
	\end{align}
	Moreover, if (i) $V_B \geq k$ or (ii) $V_B < k$ and \eqref{eq: assumption fulfilled equation} holds for all $G \in [0,\infty)$, then the bankruptcy-triggering value $V_B$ is continuous in $g$.
\end{proposition}

\begin{proof}%[Proof of Lemma \ref{lem: assumption fulfilled}]
	We begin with the case (i), meaning that $V_B \geq k$. In this case, Corollary \ref{cor: vb determination} provides an analytical solution that already ensures the continuity of $V_B$ in $\alpha$ resp. $g$.

	Next, we consider case (ii). In particular, we assume $V_B<k$.
	To prove this part of the lemma, we aim to establish that the right hand side of \eqref{eq: formula for vb}, denoted as $R(V_B)$, is strictly increasing in $V_B$ (treated as an independent variable). This strict monotonicity implies that the zero root is unique. Given that the right hand side of \eqref{eq: formula for vb} is smooth in $V_B$ (treated as an independent variable), as well as in $\alpha$ (resp. $g$), the uniqueness of the zero root implies that the conditions of the inverse function theorem are locally satisfied around this root. Consequently, by applying this theorem, we conclude that the bankruptcy-triggering value $V_B$ (the unique zero root) is continuous in $\alpha$ (resp. $g$). \\
	To demonstrate that $R(V_B)$ is increasing in $V_B$, we will show that $R'$ is positive (using \eqref{eq: dv2 cdo<}). Specifically, it holds that:
	\begin{align*}
		R'(V_B) =&\, \tfrac{1}{V_B^2} \Big( \tfrac{2(P-\frac{G}{r})A_1}{rT} + 2 \tfrac{G}{r} A_2 - \tau_1 \frac{G}{r}(\lambda_2+\lambda_3) \Big) \notag \\
		&+ \tau_2 \alpha \int_0^\infty \tfrac{\partial}{\partial V_B} [\tfrac{\partial  c_{do} (V,k,V_B,t) }{\partial V} \big|_{V=V_B}] \diff t - \alpha \displaystyle\int_0^T \tfrac{\partial}{\partial V_B} [\tfrac{\partial c_{do} (V,k,V_B,t)}{\partial V} \big|_{V=V_B}] \diff t \\
		=&\, \tfrac{1}{V_B^2} \Big( \tfrac{2(P-\frac{G}{r})A_1}{rT} + 2 \tfrac{G}{r} A_2 - \tau_1 \frac{G}{r}(\lambda_2+\lambda_3) \Big) \notag \\
		&+ \tau_2 \alpha \int_0^\infty \tfrac{2ke^{-rt}}{V_B^2} \Big(\lambda_2  \Phi(d_2(\tfrac{V_B}{k},t)) + \frac{ \varphi(d_2(\frac{V_B}{k},t))}{\sigma \sqrt{t}} \Big) \diff t \\
		&- \alpha \displaystyle\int_0^T \tfrac{2ke^{-rt}}{V_B^2} \Big(\lambda_2  \Phi(d_2(\tfrac{V_B}{k},t)) + \frac{ \varphi(d_2(\frac{V_B}{k},t))}{\sigma \sqrt{t}} \Big) \diff t > 0,
	\end{align*}
	where the last inequality follows from the assumption of the lemma after factoring $\tfrac{1}{V_B^2}>0$ out.
\end{proof}

\begin{remark}
	Since $\tfrac{2(P-\frac{G}{r})A_1}{rT} + 2 \tfrac{G}{r} A_2 - \tau_1 \frac{G}{r}(\lambda_2+\lambda_3) >0$ (see Lemma \ref{lemma: long term >0}), we can conclude that for sufficiently large $\tau_2$, the assumption in equation \eqref{eq: assumption fulfilled equation} is always satisfied. Economically, this reflects a situation where the tax benefit on surplus participation is sufficiently large that an increase in asset value leads to an increase in equity. In particular, the assumption holds when $\alpha=0$, i.e., in the absence of a surplus participation.
\end{remark}

